window.UNITS=[{"id": "E01", "level": "elem", "num": 1, "title": "A Stranger Next Door", "titleZh": "隔壁的陌生人", "theme": "People", "themeZh": "人物", "article": ["Last Saturday, a young couple moved into the apartment next to ours. My mom said we should be friendly, so she asked me to bring them a box of pineapple cakes. I am a shy teenager, and I do not like talking to strangers. But I knocked on their door anyway.", "A tall man opened the door with a big smile. His name was Mr. Lin, and his wife, Amy, was holding a cute baby girl. They invited me in like a guest and gave me a glass of juice. Mr. Lin was a great host. He told funny stories about his job as a firefighter. In our city, people like him are real heroes.", "Now the Lins are more than neighbors to me. On weekends, Amy teaches me how to bake cookies, and I help them watch the baby. Mr. Lin says I am a genius with kids. I learned something important that day: a stranger is just a friend you have not met yet."], "translation": ["上星期六，一對年輕夫妻搬進了我們隔壁的公寓。我媽媽說我們應該友善一點，所以她要我拿一盒鳳梨酥去送給他們。我是個害羞的青少年，不喜歡和陌生人說話。但我還是去敲了他們的門。", "一個高高的男人帶著大大的笑容打開門。他叫林先生，他的太太 Amy 抱著一個可愛的女寶寶。他們像招待客人一樣請我進去，還給我一杯果汁。林先生是個很棒的主人。他講了許多關於他消防員工作的有趣故事。在我們的城市裡，像他這樣的人是真正的英雄。", "現在林家對我來說不只是鄰居。週末時，Amy 教我怎麼烤餅乾，我則幫他們照顧寶寶。林先生說我是帶小孩的天才。那天我學到一件重要的事：陌生人只是你還沒認識的朋友。"], "vocab": [{"word": "couple", "pos": "n.", "zh": "夫妻；一對", "example": "The couple next door has two dogs.", "exampleZh": "隔壁那對夫妻養了兩隻狗。"}, {"word": "teenager", "pos": "n.", "zh": "青少年", "example": "Many teenagers like to play mobile games.", "exampleZh": "很多青少年喜歡玩手機遊戲。"}, {"word": "stranger", "pos": "n.", "zh": "陌生人", "example": "Do not open the door to a stranger.", "exampleZh": "不要幫陌生人開門。"}, {"word": "guest", "pos": "n.", "zh": "客人；賓客", "example": "We have three guests for dinner tonight.", "exampleZh": "今晚我們有三位客人來吃晚餐。"}, {"word": "host", "pos": "n.", "zh": "主人；主持人", "example": "The host gave everyone a warm welcome.", "exampleZh": "主人熱情地歡迎每一個人。"}, {"word": "hero", "pos": "n.", "zh": "英雄", "example": "The firefighter is a hero to the children.", "exampleZh": "那位消防員是孩子們心中的英雄。"}, {"word": "neighbor", "pos": "n.", "zh": "鄰居", "example": "Our neighbor waters our plants when we travel.", "exampleZh": "我們出門旅行時，鄰居會幫我們澆花。"}, {"word": "genius", "pos": "n.", "zh": "天才", "example": "My cousin is a genius at math.", "exampleZh": "我表哥是數學天才。"}], "phrases": [{"phrase": "move into", "zh": "搬進", "example": "A new family moved into the house across the street.", "exampleZh": "一個新家庭搬進了對街的房子。"}, {"phrase": "knock on", "zh": "敲（門）", "example": "Please knock on the door before you come in.", "exampleZh": "進來之前請先敲門。"}, {"phrase": "more than", "zh": "不只是；超過", "example": "She is more than a teacher to us; she is a friend.", "exampleZh": "她對我們來說不只是老師，更是朋友。"}], "grammar": [{"pattern": "S + ask + O + to + V", "explain": "「要求／請某人做某事」。ask 後面接人，再接不定詞 to + 原形動詞。", "example": "My mom asked me to bring them a gift.", "exampleZh": "我媽媽要我帶禮物給他們。"}, {"pattern": "S + V + O + like + N", "explain": "like 當介系詞，表示「像……一樣」，後面接名詞或代名詞，用來做比喻。", "example": "They treated me like a guest.", "exampleZh": "他們像對待客人一樣對待我。"}], "reading": [{"q": "Why did the writer go to the Lins' apartment?", "options": ["To borrow some sugar", "To bring them a gift", "To ask for help with homework", "To look at their baby"], "answer": 1, "explain": "第一段提到媽媽要作者帶一盒鳳梨酥 (a box of pineapple cakes) 送給新鄰居，故選 (B)。"}, {"q": "What is Mr. Lin's job?", "options": ["A baker", "A doctor", "A firefighter", "A teacher"], "answer": 2, "explain": "第二段提到 his job as a firefighter，林先生是消防員，故選 (C)。"}, {"q": "The word \"host\" in paragraph 2 is closest in meaning to ______.", "options": ["a person who welcomes guests", "a person who sells cakes", "a person who fixes doors", "a person who drives a truck"], "answer": 0, "explain": "host 指「招待客人的主人」。文中林先生請作者進門並給他果汁，是很棒的主人，故選 (A)。"}, {"q": "What can we learn about the writer?", "options": ["He is good at baking cookies.", "He was afraid of talking to new people at first.", "He has a baby sister.", "He wants to be a firefighter."], "answer": 1, "explain": "第一段說作者是害羞的青少年，不喜歡和陌生人說話 (do not like talking to strangers)，故選 (B)。"}, {"q": "What is the main idea of the article?", "options": ["Pineapple cakes are the best gift.", "Firefighters work very hard.", "A stranger can become a good friend.", "Babies need a lot of care."], "answer": 2, "explain": "最後一句點出主旨：陌生人只是你還沒認識的朋友 (a stranger is just a friend you have not met yet)，故選 (C)。"}], "vocabQ": [{"q": "The ____ upstairs plays the piano every night, and it is very noisy.", "options": ["neighbor", "prince", "king", "queen"], "answer": 0, "explain": "句意為「樓上的鄰居每晚彈鋼琴，很吵」，neighbor 鄰居。"}, {"q": "My aunt and uncle are a happy ____. They got married ten years ago.", "options": ["giant", "couple", "visitor", "child"], "answer": 1, "explain": "句意為「我的阿姨和姨丈是一對幸福的夫妻」，couple 夫妻。"}, {"q": "Einstein was a ____. He changed the way we think about time.", "options": ["fool", "stranger", "genius", "guest"], "answer": 2, "explain": "句意為「愛因斯坦是個天才，改變了我們對時間的看法」，genius 天才。"}, {"q": "Every ____ in Taiwan has to take the high school entrance exam at fifteen.", "options": ["baby", "adult", "teenager", "queen"], "answer": 2, "explain": "句意為「台灣每個青少年十五歲時都要參加高中入學考試」，teenager 青少年。"}, {"q": "The ____ of the party asked everyone to sit down for dinner.", "options": ["stranger", "kid", "princess", "host"], "answer": 3, "explain": "句意為「派對的主人請大家坐下來用餐」，host 主人。"}]}, {"id": "E02", "level": "elem", "num": 2, "title": "My Little Brother Is Taller Than Me!", "titleZh": "我弟弟比我高了！", "theme": "Appearance", "themeZh": "外表", "article": ["Dear Diary, Today was Grandpa's birthday, and our whole family took a photo together. When I saw the photo, I was surprised. My little brother Kevin is now taller than me! Two years ago, he was a short, chubby boy with a round face. Now he is tall and slim, and his face looks quite handsome.", "I am still the same. I have short hair, a small nose, and I am a little thin. My mom says I am cute, but I want to look cool, not cute! Kevin laughed and said, \"Don't worry. You are still the pretty one in the family.\" Sometimes he is really nice.", "Grandpa looked at the photo and smiled. He is eighty years old, but his eyes are bright and young. He said, \"Tall or short, fat or thin, you are all beautiful to me.\" I think he is right. Looks change, but family love does not. Good night, Diary!"], "translation": ["親愛的日記：今天是爺爺的生日，我們全家一起拍了一張照片。看到照片時，我嚇了一跳。我的弟弟 Kevin 現在比我高了！兩年前，他還是個矮矮胖胖、圓臉的小男孩。現在他又高又苗條，臉也變得相當帥氣。", "我還是老樣子。短頭髮、小鼻子，而且有一點瘦。媽媽說我很可愛，但我想要看起來很酷，而不是可愛！Kevin 笑著說：「別擔心，妳還是我們家最漂亮的那一個。」有時候他真的很貼心。", "爺爺看著照片微笑。他八十歲了，但眼睛明亮又有活力。他說：「不管高矮胖瘦，在我眼裡你們都很美。」我想他說得對。外表會改變，但家人的愛不會。晚安，日記！"], "vocab": [{"word": "tall", "pos": "adj.", "zh": "高的", "example": "The basketball player is very tall.", "exampleZh": "那位籃球選手非常高。"}, {"word": "short", "pos": "adj.", "zh": "矮的；短的", "example": "I am too short to reach the top shelf.", "exampleZh": "我太矮了，搆不到最上面的架子。"}, {"word": "chubby", "pos": "adj.", "zh": "圓胖的", "example": "The chubby puppy loves to eat.", "exampleZh": "那隻圓滾滾的小狗很愛吃。"}, {"word": "slim", "pos": "adj.", "zh": "苗條的", "example": "She stays slim by jogging every morning.", "exampleZh": "她每天早上慢跑來保持苗條。"}, {"word": "handsome", "pos": "adj.", "zh": "英俊的", "example": "The actor is handsome and funny.", "exampleZh": "那位演員又帥又風趣。"}, {"word": "thin", "pos": "adj.", "zh": "瘦的；薄的", "example": "He became thin after he was sick.", "exampleZh": "他生病後變瘦了。"}, {"word": "cute", "pos": "adj.", "zh": "可愛的", "example": "What a cute kitten!", "exampleZh": "好可愛的小貓！"}, {"word": "young", "pos": "adj.", "zh": "年輕的", "example": "My grandmother looks young for her age.", "exampleZh": "我奶奶看起來比實際年齡年輕。"}], "phrases": [{"phrase": "take a photo", "zh": "拍照", "example": "Let's take a photo in front of Taipei 101.", "exampleZh": "我們在台北 101 前面拍張照吧。"}, {"phrase": "look at", "zh": "看著", "example": "Look at the sky! It's full of stars.", "exampleZh": "看看天空！滿天都是星星。"}, {"phrase": "the same", "zh": "一樣的", "example": "My sister and I wear the same size.", "exampleZh": "我和姊姊穿同樣的尺寸。"}], "grammar": [{"pattern": "S + be + 比較級 + than + N", "explain": "比較級用來比較兩者。短的形容詞字尾加 -er（tall → taller），後面用 than 接比較的對象。", "example": "My brother is taller than me.", "exampleZh": "我弟弟比我高。"}, {"pattern": "S + look + adj.", "explain": "look 是連綴動詞，意思是「看起來……」，後面直接接形容詞，不接副詞。", "example": "His face looks handsome.", "exampleZh": "他的臉看起來很帥。"}], "reading": [{"q": "What kind of writing is this?", "options": ["A letter to a friend", "A news report", "A diary entry", "A school announcement"], "answer": 2, "explain": "文章以 Dear Diary 開頭、Good night, Diary 結尾，是日記，故選 (C)。"}, {"q": "What did Kevin look like two years ago?", "options": ["Tall and slim", "Short and chubby", "Thin and pale", "Old and tired"], "answer": 1, "explain": "第一段提到 Two years ago, he was a short, chubby boy，故選 (B)。"}, {"q": "How does the writer feel about being called \"cute\"?", "options": ["She is happy about it.", "She does not like it.", "She does not care.", "She thinks it is funny."], "answer": 1, "explain": "第二段說 I want to look cool, not cute!，表示作者不喜歡被說可愛，故選 (B)。"}, {"q": "The word \"bright\" in paragraph 3 is closest in meaning to ______.", "options": ["full of light and life", "very large", "dark and sad", "closed"], "answer": 0, "explain": "bright 形容眼睛「明亮有神」，與 young 搭配表示有活力，故選 (A)。"}, {"q": "What does Grandpa want to tell the family?", "options": ["Everyone should take more photos.", "Being tall is better than being short.", "Looks are not the most important thing.", "Kevin is the most handsome person."], "answer": 2, "explain": "爺爺說不論高矮胖瘦，大家在他眼裡都很美，點出外表不是最重要的，故選 (C)。"}], "vocabQ": [{"q": "The model is ____ because she eats healthy food and exercises every day.", "options": ["fat", "heavy", "slim", "chubby"], "answer": 2, "explain": "句意為「那位模特兒很苗條，因為她吃得健康又天天運動」，slim 苗條的。"}, {"q": "Jeremy Lin is very ____, so he can touch the top of the door easily.", "options": ["tall", "short", "thin", "young"], "answer": 0, "explain": "句意為「林書豪很高，所以能輕鬆摸到門的上方」，tall 高的。"}, {"q": "The baby panda is so ____ that everyone wants to take a picture of it.", "options": ["ugly", "cute", "old", "skinny"], "answer": 1, "explain": "句意為「那隻熊貓寶寶太可愛了，大家都想拍牠」，cute 可愛的。"}, {"q": "Mr. Chang is ____, so his students always say he looks like a movie star.", "options": ["blind", "deaf", "handsome", "under-weight"], "answer": 2, "explain": "句意為「張老師很英俊，學生總說他像電影明星」，handsome 英俊的。"}, {"q": "My cousin is only three years old. She is too ____ to go to school.", "options": ["old", "pretty", "tall", "young"], "answer": 3, "explain": "句意為「我表妹才三歲，太小還不能上學」，young 年幼的。"}]}, {"id": "E03", "level": "elem", "num": 3, "title": "An Email About My New Class", "titleZh": "一封關於新班級的電子郵件", "theme": "Personality & Emotions", "themeZh": "個性與情緒", "article": ["Hi Jenny, How are you? I started junior high school in September, and I want to tell you about my new class. At first, I was nervous because I did not know anyone. But my classmates are very friendly, and now I have many new friends.", "My best friend is Peter. He is talkative and humorous, so he always makes everyone laugh. He is also honest. Last week, he found a wallet on the MRT and gave it back to the owner. Another friend, Mei, is shy and quiet, but she is a diligent student. She studies English every night. I was lazy before, but now I study with her.", "Our teacher, Ms. Wang, is kind and patient. When we make mistakes, she never gets angry. She just explains again with a smile. I feel lucky to be in this class. What about your new school? Please write back soon! Your friend, Lily"], "translation": ["嗨，Jenny：妳好嗎？我九月開始上國中了，想跟妳說說我的新班級。一開始我很緊張，因為我誰都不認識。但我的同學們都很友善，現在我已經有很多新朋友了。", "我最好的朋友是 Peter。他很愛講話又很幽默，所以總是逗得大家哈哈大笑。他也很誠實。上星期他在捷運上撿到一個皮夾，把它還給了失主。另一個朋友 Mei 害羞又安靜，但她是個勤奮的學生。她每天晚上都讀英文。我以前很懶，但現在我會跟她一起讀書。", "我們的老師王老師既親切又有耐心。當我們犯錯時，她從來不生氣，只是帶著微笑再解釋一次。能在這個班上，我覺得很幸運。妳的新學校怎麼樣？請快點回信！妳的朋友 Lily"], "vocab": [{"word": "nervous", "pos": "adj.", "zh": "緊張的", "example": "I always feel nervous before a test.", "exampleZh": "考試前我總是很緊張。"}, {"word": "friendly", "pos": "adj.", "zh": "友善的", "example": "The people in this town are very friendly.", "exampleZh": "這個小鎮的人非常友善。"}, {"word": "talkative", "pos": "adj.", "zh": "健談的；多話的", "example": "My talkative uncle can chat for hours.", "exampleZh": "我那健談的叔叔可以聊上好幾個小時。"}, {"word": "humorous", "pos": "adj.", "zh": "幽默的", "example": "Our humorous teacher tells a joke every class.", "exampleZh": "我們幽默的老師每堂課都講一個笑話。"}, {"word": "honest", "pos": "adj.", "zh": "誠實的", "example": "An honest person never tells lies.", "exampleZh": "誠實的人從不說謊。"}, {"word": "shy", "pos": "adj.", "zh": "害羞的", "example": "The shy girl hid behind her mother.", "exampleZh": "那個害羞的女孩躲在媽媽身後。"}, {"word": "diligent", "pos": "adj.", "zh": "勤奮的", "example": "Diligent students review their notes every day.", "exampleZh": "勤奮的學生每天複習筆記。"}, {"word": "patient", "pos": "adj.", "zh": "有耐心的", "example": "Be patient; the bus will come soon.", "exampleZh": "耐心點，公車很快就來了。"}], "phrases": [{"phrase": "at first", "zh": "起初；一開始", "example": "At first, I did not like the city, but now I love it.", "exampleZh": "起初我不喜歡這座城市，但現在我很愛它。"}, {"phrase": "give back", "zh": "歸還", "example": "Please give back the book tomorrow.", "exampleZh": "請明天把書還回來。"}, {"phrase": "write back", "zh": "回信", "example": "I wrote back to my pen pal yesterday.", "exampleZh": "我昨天回信給我的筆友。"}], "grammar": [{"pattern": "S + V ..., so + S + V ...", "explain": "so 是連接詞，表示「所以」，前面是原因，後面是結果。注意 so 與 because 不可同時使用。", "example": "He is humorous, so everyone likes him.", "exampleZh": "他很幽默，所以大家都喜歡他。"}, {"pattern": "S + never + V", "explain": "never「從不」是頻率副詞，放在一般動詞之前、be 動詞之後，句子本身用肯定形式。", "example": "She never gets angry with us.", "exampleZh": "她從不對我們生氣。"}], "reading": [{"q": "Why is Lily writing this email?", "options": ["To ask Jenny for help with English", "To tell Jenny about her new class", "To invite Jenny to a party", "To say sorry to Jenny"], "answer": 1, "explain": "第一段提到 I want to tell you about my new class，寫信目的是分享新班級的事，故選 (B)。"}, {"q": "How did Lily feel on her first day at junior high school?", "options": ["Nervous", "Angry", "Bored", "Proud"], "answer": 0, "explain": "第一段說 At first, I was nervous because I did not know anyone，故選 (A)。"}, {"q": "What did Peter do last week?", "options": ["He made a funny video.", "He lost his wallet on the MRT.", "He returned a wallet to its owner.", "He studied English with Mei."], "answer": 2, "explain": "第二段提到他在捷運上撿到皮夾並還給失主 (gave it back to the owner)，故選 (C)。"}, {"q": "The word \"diligent\" in paragraph 2 is closest in meaning to ______.", "options": ["lazy", "hard-working", "shy", "famous"], "answer": 1, "explain": "diligent 勤奮的，後文說 Mei 每晚讀英文，與 hard-working 意思最接近，故選 (B)。"}, {"q": "What can we learn about Ms. Wang?", "options": ["She gives a lot of homework.", "She is new at the school.", "She is patient with students' mistakes.", "She is Lily's best friend."], "answer": 2, "explain": "第三段提到學生犯錯時她從不生氣，會微笑著再解釋一次，顯示她很有耐心，故選 (C)。"}], "vocabQ": [{"q": "Amy is so ____ that she talks on the phone for two hours every day.", "options": ["lonely", "talkative", "careful", "selfish"], "answer": 1, "explain": "句意為「Amy 非常健談，每天講兩小時電話」，talkative 健談的。"}, {"q": "The ____ boy did not dare to speak in front of the class.", "options": ["shy", "brave", "rude", "proud"], "answer": 0, "explain": "句意為「那個害羞的男孩不敢在全班面前說話」，shy 害羞的。"}, {"q": "Please be ____ with your little sister; she is learning to read.", "options": ["jealous", "greedy", "patient", "cruel"], "answer": 2, "explain": "句意為「請對妹妹有耐心，她正在學認字」，patient 有耐心的。"}, {"q": "Jack is ____. He told the teacher the truth even though it was his mistake.", "options": ["dishonest", "sneaky", "stingy", "honest"], "answer": 3, "explain": "句意為「Jack 很誠實，即使是自己的錯也向老師說實話」，honest 誠實的。"}, {"q": "Everyone laughed at the ____ story the comedian told.", "options": ["humorous", "boring", "sad", "evil"], "answer": 0, "explain": "句意為「大家都被喜劇演員講的幽默故事逗笑了」，humorous 幽默的。"}]}, {"id": "E04", "level": "elem", "num": 4, "title": "Five Minutes for a Happy Body", "titleZh": "五分鐘讓身體更舒服", "theme": "The Body", "themeZh": "身體部位", "article": ["Do you sit in front of a computer or a phone for hours? Many teenagers do, and then their necks and backs hurt. Here are four easy exercises. You can do them in your classroom or at home in just five minutes.", "First, sit up straight and slowly turn your head to the left, then to the right. Do this five times to relax your neck. Second, lift your shoulders up to your ears, hold for three seconds, and let them drop. Third, stand up and raise both arms high. Then bend at the waist and try to touch your toes with your fingers. Keep your knees straight, but do not push too hard.", "Finally, stand on one foot and move your ankle in small circles. Change feet and do it again. These exercises are simple, but they are good for your whole body. Try them every day, and your back will thank you!"], "translation": ["你會連續好幾個小時坐在電腦或手機前面嗎？很多青少年都會，然後脖子和背就開始痛。這裡有四個簡單的運動。你可以在教室或家裡做，只需要五分鐘。", "第一，坐直，慢慢把頭轉向左邊，再轉向右邊。做五次來放鬆你的脖子。第二，把肩膀往上提到耳朵旁，停三秒，再放下來。第三，站起來，把兩隻手臂高高舉起。然後從腰部彎下去，試著用手指碰腳趾。膝蓋保持打直，但不要太用力。", "最後，單腳站立，把腳踝轉小圈圈。換另一隻腳再做一次。這些運動很簡單，但對你的全身都有好處。每天試著做一做，你的背會感謝你的！"], "vocab": [{"word": "neck", "pos": "n.", "zh": "脖子", "example": "The giraffe has a very long neck.", "exampleZh": "長頸鹿的脖子非常長。"}, {"word": "back", "pos": "n.", "zh": "背部", "example": "Grandpa's back hurts when it rains.", "exampleZh": "下雨時爺爺的背會痛。"}, {"word": "shoulder", "pos": "n.", "zh": "肩膀", "example": "He carried the bag on his shoulder.", "exampleZh": "他把袋子扛在肩上。"}, {"word": "arm", "pos": "n.", "zh": "手臂", "example": "She broke her arm in the game.", "exampleZh": "她在比賽中摔斷了手臂。"}, {"word": "waist", "pos": "n.", "zh": "腰", "example": "This belt is too big for my waist.", "exampleZh": "這條皮帶對我的腰來說太大了。"}, {"word": "toe", "pos": "n.", "zh": "腳趾", "example": "Ouch! You stepped on my toe.", "exampleZh": "哎呀！你踩到我的腳趾了。"}, {"word": "knee", "pos": "n.", "zh": "膝蓋", "example": "The boy fell and hurt his knee.", "exampleZh": "男孩跌倒，弄傷了膝蓋。"}, {"word": "ankle", "pos": "n.", "zh": "腳踝", "example": "I twisted my ankle while playing basketball.", "exampleZh": "我打籃球時扭傷了腳踝。"}], "phrases": [{"phrase": "in front of", "zh": "在……前面", "example": "There is a tall tree in front of our school.", "exampleZh": "我們學校前面有一棵大樹。"}, {"phrase": "sit up straight", "zh": "坐直", "example": "Sit up straight when you read.", "exampleZh": "看書時要坐直。"}, {"phrase": "be good for", "zh": "對……有益", "example": "Fruit is good for your health.", "exampleZh": "水果對你的健康有益。"}], "grammar": [{"pattern": "V + O ... / Do not + V ...（祈使句）", "explain": "祈使句用來給指令或建議，直接以原形動詞開頭，主詞 you 省略；否定用 Do not（Don't）+ 原形動詞。", "example": "Keep your knees straight. Do not push too hard.", "exampleZh": "膝蓋保持打直。不要太用力。"}, {"pattern": "V + for + 一段時間", "explain": "for 後面接一段時間（three seconds, two hours），表示動作持續多久。", "example": "Hold your shoulders up for three seconds.", "exampleZh": "把肩膀抬高停三秒。"}], "reading": [{"q": "Who is this article mainly written for?", "options": ["Doctors in a hospital", "Teenagers who sit for a long time", "Parents of small children", "People who run every day"], "answer": 1, "explain": "第一段問讀者是否長時間坐在電腦或手機前，並說 Many teenagers do，故對象是久坐的青少年，選 (B)。"}, {"q": "Which part of the body does the first exercise help?", "options": ["The knees", "The ankles", "The neck", "The fingers"], "answer": 2, "explain": "第二段第一個運動是轉頭，Do this five times to relax your neck，故選 (C)。"}, {"q": "In the third exercise, what should you do after you raise your arms?", "options": ["Bend at the waist", "Sit down slowly", "Turn your head", "Move your ankle"], "answer": 0, "explain": "第二段提到舉起手臂後 Then bend at the waist，故選 (A)。"}, {"q": "The word \"drop\" in paragraph 2 is closest in meaning to ______.", "options": ["lift up", "fall down", "turn around", "hold tight"], "answer": 1, "explain": "let them drop 指把提起的肩膀「放下來」，與 fall down 意思最接近，故選 (B)。"}, {"q": "How long do the four exercises take?", "options": ["Three seconds", "Five minutes", "Five times a day", "Several hours"], "answer": 1, "explain": "第一段說 in just five minutes，故選 (B)。"}], "vocabQ": [{"q": "The soccer player hurt his ____ when he kicked the ball too hard.", "options": ["beard", "ankle", "ear", "lip"], "answer": 1, "explain": "句意為「足球員踢球太用力，傷了腳踝」，ankle 腳踝。"}, {"q": "My ____ hurts after I carried the heavy backpack all day.", "options": ["back", "tongue", "nail", "tooth"], "answer": 0, "explain": "句意為「背了一整天重書包後，我的背很痛」，back 背部。"}, {"q": "The boy put a scarf around his ____ because it was cold.", "options": ["thumb", "neck", "hip", "chin"], "answer": 1, "explain": "句意為「天氣冷，男孩在脖子上圍了圍巾」，neck 脖子。"}, {"q": "She tapped him on the ____ to get his attention.", "options": ["toe", "stomach", "shoulder", "heel"], "answer": 2, "explain": "句意為「她拍拍他的肩膀以引起他的注意」，shoulder 肩膀。"}, {"q": "The nurse put a bandage on his ____ after he fell off the bike.", "options": ["hair", "eye", "knee", "mouth"], "answer": 2, "explain": "句意為「他從腳踏車摔下來後，護士在他的膝蓋上包了繃帶」，knee 膝蓋。"}]}, {"id": "E05", "level": "elem", "num": 5, "title": "Jack Has the Flu", "titleZh": "Jack 得了流感", "theme": "Health & Illness", "themeZh": "健康與疾病", "article": ["On Monday morning, Jack did not get out of bed. His face was pale, and he felt dizzy. \"Mom, I feel sick,\" he said. His mother touched his forehead. \"You have a fever,\" she said. \"Let's go to the clinic.\"", "At the clinic, Dr. Chen looked at Jack's throat and listened to his chest. \"Do you have a cough?\" she asked. \"Yes, and I have a sore throat too,\" Jack said in a weak voice. Dr. Chen smiled. \"Don't worry. It's just the flu. Take this medicine three times a day, drink a lot of water, and get some rest.\"", "Jack stayed home for three days. He slept a lot and ate warm soup. By Thursday, his fever was gone, and he felt strong again. \"I want to stay healthy,\" Jack told his mom. \"From now on, I will wash my hands more often and go to bed early.\" His mom laughed. \"Good idea, but first, finish your homework!\""], "translation": ["星期一早上，Jack 沒有起床。他臉色蒼白，覺得頭暈。「媽，我覺得不舒服。」他說。媽媽摸了摸他的額頭。「你發燒了，」她說，「我們去診所吧。」", "在診所，陳醫師看了 Jack 的喉嚨，又聽了他的胸腔。「你有咳嗽嗎？」她問。「有，我還喉嚨痛。」Jack 用虛弱的聲音說。陳醫師笑了笑。「別擔心，只是流感而已。這個藥一天吃三次，多喝水，好好休息。」", "Jack 在家待了三天。他睡了很多覺，也喝了熱湯。到了星期四，他的燒退了，又覺得有力氣了。「我想要保持健康。」Jack 對媽媽說。「從現在起，我會更常洗手，也會早點睡。」媽媽笑了：「好主意，不過先把功課寫完！」"], "vocab": [{"word": "dizzy", "pos": "adj.", "zh": "頭暈的", "example": "I felt dizzy after the roller coaster ride.", "exampleZh": "坐完雲霄飛車後我覺得頭暈。"}, {"word": "sick", "pos": "adj.", "zh": "生病的", "example": "Three students were sick and stayed home today.", "exampleZh": "今天有三個學生生病待在家。"}, {"word": "fever", "pos": "n.", "zh": "發燒", "example": "The baby has a high fever, so we called the doctor.", "exampleZh": "寶寶發高燒，所以我們打電話給醫生。"}, {"word": "cough", "pos": "n.", "zh": "咳嗽", "example": "His cough kept him awake all night.", "exampleZh": "他的咳嗽讓他整夜睡不著。"}, {"word": "sore throat", "pos": "n.", "zh": "喉嚨痛", "example": "Drink warm water if you have a sore throat.", "exampleZh": "喉嚨痛的話就喝溫開水。"}, {"word": "flu", "pos": "n.", "zh": "流行性感冒", "example": "Many people get the flu in winter.", "exampleZh": "冬天很多人得流感。"}, {"word": "medicine", "pos": "n.", "zh": "藥", "example": "Remember to take your medicine after meals.", "exampleZh": "記得飯後吃藥。"}, {"word": "healthy", "pos": "adj.", "zh": "健康的", "example": "Eating vegetables keeps you healthy.", "exampleZh": "吃蔬菜讓你保持健康。"}], "phrases": [{"phrase": "get out of bed", "zh": "起床", "example": "It is hard to get out of bed on cold mornings.", "exampleZh": "寒冷的早晨很難爬起床。"}, {"phrase": "three times a day", "zh": "一天三次", "example": "Brush your teeth three times a day.", "exampleZh": "一天刷牙三次。"}, {"phrase": "from now on", "zh": "從現在起", "example": "From now on, I will eat breakfast every day.", "exampleZh": "從現在起，我每天都要吃早餐。"}], "grammar": [{"pattern": "S + feel + adj.", "explain": "feel 是連綴動詞，意思是「感覺……」，後面接形容詞（sick, dizzy, strong）來描述身體或心情的狀態。", "example": "I feel dizzy and weak today.", "exampleZh": "我今天覺得頭暈又無力。"}, {"pattern": "Let's + V ...", "explain": "Let's 是 Let us 的縮寫，意思是「我們……吧」，後面接原形動詞，用來提議一起做某事。", "example": "Let's go to the clinic.", "exampleZh": "我們去診所吧。"}], "reading": [{"q": "How did Jack's mother know he had a fever?", "options": ["She looked at his throat.", "She touched his forehead.", "She listened to his chest.", "She called Dr. Chen."], "answer": 1, "explain": "第一段提到 His mother touched his forehead 後說他發燒了，故選 (B)。"}, {"q": "Which of the following was NOT one of Jack's problems?", "options": ["A cough", "A fever", "A sore throat", "A stomachache"], "answer": 3, "explain": "文中提到發燒、咳嗽、喉嚨痛，沒有提到肚子痛，故選 (D)。"}, {"q": "What did Dr. Chen tell Jack to do?", "options": ["Go back to school right away", "Take medicine and rest", "Eat warm soup every morning", "Wash his hands three times a day"], "answer": 1, "explain": "第二段醫師說 Take this medicine three times a day ... and get some rest，故選 (B)。"}, {"q": "The word \"gone\" in paragraph 3 is closest in meaning to ______.", "options": ["higher", "worse", "finished", "stronger"], "answer": 2, "explain": "his fever was gone 指燒「退了、沒有了」，與 finished 意思最接近，故選 (C)。"}, {"q": "What does the ending of the story show about Jack's mom?", "options": ["She is still very worried.", "She has a sense of humor.", "She is angry at Jack.", "She wants Jack to stay in bed."], "answer": 1, "explain": "媽媽笑著說「好主意，但先寫完功課」，是幽默的回應，故選 (B)。"}], "vocabQ": [{"q": "Grandma takes her ____ every morning with a glass of water.", "options": ["medicine", "cancer", "death", "wound"], "answer": 0, "explain": "句意為「奶奶每天早上配一杯水吃藥」，medicine 藥。"}, {"q": "I had a bad ____ last night, so I could not stop making noise in class.", "options": ["headache", "cough", "toothache", "stomachache"], "answer": 1, "explain": "句意為「昨晚我咳得很厲害，所以上課一直發出聲音」，cough 咳嗽。"}, {"q": "Mark felt ____ after standing in the hot sun for an hour.", "options": ["healthy", "comfortable", "dizzy", "strong"], "answer": 2, "explain": "句意為「Mark 在大太陽下站了一小時後覺得頭暈」，dizzy 頭暈的。"}, {"q": "Lisa has a ____ of 39 degrees, so she cannot go to school today.", "options": ["pain", "cold", "cure", "fever"], "answer": 3, "explain": "句意為「Lisa 發燒到 39 度，今天不能上學」，fever 發燒。"}, {"q": "My father exercises every day, so he is very ____ for his age.", "options": ["ill", "healthy", "weak", "pale"], "answer": 1, "explain": "句意為「我爸爸每天運動，以他的年紀來說非常健康」，healthy 健康的。"}]}, {"id": "E06", "level": "elem", "num": 6, "title": "Four Generations, One Big Party", "titleZh": "四代同堂的大派對", "theme": "Titles & Family", "themeZh": "稱謂與家庭", "article": ["Taipei, May 10 - Mrs. Lin Mei-hua turned ninety years old on Sunday, and more than fifty relatives came to Daan Park to celebrate with her. Mrs. Lin was born in Tainan in 1936. She married her husband, Mr. Lin Wen-long, at the age of twenty, and they have four daughters and two sons.", "Her youngest daughter, Ms. Lin Ya-ting, planned the party. \"My mother is the heart of our family,\" she said. \"Every Sunday, she still cooks dinner for all of us.\" Her grandson, Kevin Chen, a university student, made a short film about his grandmother's life. Many cousins who live in different cities watched it together and cried.", "The best moment came at noon. Mrs. Lin's great-granddaughter, two-year-old Emma, gave her a big kiss and said, \"Happy birthday, Grandma!\" Mrs. Lin smiled and said, \"I am a lucky woman. My family is my best gift.\" After lunch, the whole family took a photo with four generations in it."], "translation": ["台北，5 月 10 日訊 — 林美華女士在星期日滿九十歲，超過五十位親戚來到大安森林公園為她慶生。林女士 1936 年出生於台南。她二十歲時嫁給丈夫林文龍先生，兩人育有四個女兒和兩個兒子。", "她的小女兒林雅婷女士籌辦了這場派對。「我媽媽是我們家的核心，」她說，「每個星期天，她還是會為我們全家煮晚餐。」她的孫子陳凱文是大學生，拍了一部關於奶奶一生的短片。許多住在不同城市的表兄弟姊妹一起看了影片，都哭了。", "最棒的時刻在中午到來。林女士的曾孫女、兩歲的 Emma 給了她一個大大的親吻，說：「奶奶生日快樂！」林女士微笑著說：「我是個幸運的女人，家人是我最好的禮物。」午餐後，全家人拍了一張四代同堂的照片。"], "vocab": [{"word": "relative", "pos": "n.", "zh": "親戚", "example": "We visit our relatives during Chinese New Year.", "exampleZh": "農曆新年時我們會去拜訪親戚。"}, {"word": "born", "pos": "adj.", "zh": "出生的（be born 出生）", "example": "My sister was born in Kaohsiung.", "exampleZh": "我妹妹在高雄出生。"}, {"word": "marry", "pos": "v.", "zh": "結婚；嫁；娶", "example": "My uncle married his high school classmate.", "exampleZh": "我叔叔娶了他的高中同學。"}, {"word": "husband", "pos": "n.", "zh": "丈夫", "example": "Her husband works in a bank.", "exampleZh": "她的丈夫在銀行工作。"}, {"word": "daughter", "pos": "n.", "zh": "女兒", "example": "Mr. Wu has one son and two daughters.", "exampleZh": "吳先生有一個兒子和兩個女兒。"}, {"word": "grandson", "pos": "n.", "zh": "孫子", "example": "Grandpa plays chess with his grandson every afternoon.", "exampleZh": "爺爺每天下午跟孫子下棋。"}, {"word": "grandmother", "pos": "n.", "zh": "祖母；外婆", "example": "My grandmother makes the best dumplings.", "exampleZh": "我奶奶包的水餃最好吃。"}, {"word": "cousin", "pos": "n.", "zh": "堂（表）兄弟姊妹", "example": "I play video games with my cousins on weekends.", "exampleZh": "週末我和表兄弟一起打電動。"}], "phrases": [{"phrase": "at the age of", "zh": "在……歲時", "example": "She learned to swim at the age of six.", "exampleZh": "她六歲時學會游泳。"}, {"phrase": "more than", "zh": "超過", "example": "More than two hundred people came to the concert.", "exampleZh": "超過兩百人來聽演唱會。"}, {"phrase": "take a photo", "zh": "拍照", "example": "We took a photo with our teacher on graduation day.", "exampleZh": "畢業那天我們和老師拍了一張照片。"}], "grammar": [{"pattern": "S + be + born + in + 地點／年份", "explain": "「出生於……」用 be born 表示，be 動詞依主詞與時態變化（was / were）。後面接 in + 年份或地點，on + 日期。", "example": "Mrs. Lin was born in Tainan in 1936.", "exampleZh": "林女士 1936 年出生於台南。"}, {"pattern": "the + 最高級 + N", "explain": "三者以上比較用最高級，前面要加 the。短的形容詞加 -est（young → youngest），不規則變化如 good → best。", "example": "Her youngest daughter planned the party.", "exampleZh": "她最小的女兒籌辦了派對。"}], "reading": [{"q": "What is this news report mainly about?", "options": ["A new park in Taipei", "A grandmother's ninetieth birthday party", "A short film by a university student", "A cooking class for families"], "answer": 1, "explain": "全文報導林女士九十歲生日派對，故選 (B)。"}, {"q": "How old was Mrs. Lin when she got married?", "options": ["Twenty", "Thirty-six", "Fifty", "Ninety"], "answer": 0, "explain": "第一段提到 She married her husband ... at the age of twenty，故選 (A)。"}, {"q": "Who made a film about Mrs. Lin's life?", "options": ["Her husband", "Her youngest daughter", "Her grandson", "Her great-granddaughter"], "answer": 2, "explain": "第二段提到 Her grandson, Kevin Chen ... made a short film，故選 (C)。"}, {"q": "The phrase \"the heart of our family\" in paragraph 2 means Mrs. Lin is ______.", "options": ["often sick", "the most important person", "the best cook in Taipei", "the oldest woman in Taiwan"], "answer": 1, "explain": "heart 在此比喻「核心、最重要的人」，後文說她每週為全家煮飯，故選 (B)。"}, {"q": "Which of the following is true about the party?", "options": ["It was held at Mrs. Lin's home.", "Only her children came.", "Emma gave her a kiss at noon.", "The family forgot to take a photo."], "answer": 2, "explain": "第三段提到中午時 Emma gave her a big kiss，其他選項與文章不符，故選 (C)。"}], "vocabQ": [{"q": "My ____ is my aunt's son, and we are in the same class.", "options": ["nephew", "cousin", "niece", "uncle"], "answer": 1, "explain": "句意為「我的表哥是我阿姨的兒子，我們同班」，cousin 表兄弟。"}, {"q": "Mrs. Huang and her ____ have been married for thirty years.", "options": ["husband", "sister", "grandma", "daddy"], "answer": 0, "explain": "句意為「黃太太和她的丈夫結婚三十年了」，husband 丈夫。"}, {"q": "The old man smiled when his ____ ran into his arms and called him Grandpa.", "options": ["wife", "brother", "grandson", "father"], "answer": 2, "explain": "句意為「孫子跑進懷裡叫他爺爺時，老先生笑了」，grandson 孫子。"}, {"q": "Every ____ came to our family dinner on New Year's Eve, even my aunt from Japan.", "options": ["name", "parent", "relative", "mother"], "answer": 2, "explain": "句意為「除夕夜每位親戚都來參加家庭聚餐，連日本的阿姨也來了」，relative 親戚。"}, {"q": "I was ____ on a rainy night in October, so my mom calls me her rain baby.", "options": ["married", "grown", "lived", "born"], "answer": 3, "explain": "句意為「我在十月一個下雨的夜晚出生，所以媽媽叫我雨寶寶」，be born 出生。"}]}, {"id": "E07", "level": "elem", "num": 7, "title": "School Announcement: Charity Bake Sale", "titleZh": "學校公告：愛心義賣會", "theme": "Numbers & Quantity", "themeZh": "數字與數量", "article": ["Attention, all students! Our school's charity bake sale will take place next Friday, from twelve to two in the afternoon, at the basketball court. Last year, more than three hundred students and parents came, and we raised forty thousand dollars for a children's hospital. This year, our goal is fifty thousand dollars.", "Each class will have one table. Please bring a few cookies, cakes, or drinks to sell. Prices should be between ten and fifty dollars, so everyone can buy something. Several teachers will also sell their famous egg tarts. Both the school band and the dance club will perform at one o'clock.", "We need twenty volunteers to help set up tables at eleven thirty. If you want to help, write your name and class number on the sign-up sheet outside the office before Wednesday. At the end of the sale, we will count the total and share the good news on Monday. Let's make this year's number even bigger!"], "translation": ["全體同學請注意！本校的愛心烘焙義賣會將於下星期五下午十二點到兩點在籃球場舉行。去年有超過三百位學生和家長參加，我們為一家兒童醫院募得四萬元。今年我們的目標是五萬元。", "每個班級會有一張桌子。請帶一些餅乾、蛋糕或飲料來販售。價格應該在十元到五十元之間，這樣每個人都買得起。幾位老師也會販售他們有名的蛋塔。學校樂隊和熱舞社都會在一點鐘表演。", "我們需要二十位志工在十一點半幫忙擺桌子。如果你想幫忙，請在星期三之前到辦公室外面的報名表上寫下你的姓名和班級號碼。義賣結束時，我們會計算總金額，並在星期一公布好消息。讓我們把今年的數字變得更大吧！"], "vocab": [{"word": "hundred", "pos": "n.", "zh": "百", "example": "There are about one hundred students in the hall.", "exampleZh": "禮堂裡大約有一百名學生。"}, {"word": "thousand", "pos": "n.", "zh": "千", "example": "The new phone costs twenty thousand dollars.", "exampleZh": "這支新手機要兩萬元。"}, {"word": "a few", "pos": "det.", "zh": "一些；幾個（接可數名詞）", "example": "I have a few questions about the test.", "exampleZh": "關於考試我有幾個問題。"}, {"word": "several", "pos": "adj.", "zh": "幾個；數個", "example": "Several students were late this morning.", "exampleZh": "今天早上有幾個學生遲到。"}, {"word": "both", "pos": "det.", "zh": "兩者都", "example": "Both of my parents are teachers.", "exampleZh": "我的父母都是老師。"}, {"word": "twenty", "pos": "n.", "zh": "二十", "example": "My brother will be twenty next month.", "exampleZh": "我哥哥下個月滿二十歲。"}, {"word": "total", "pos": "n.", "zh": "總數；總計", "example": "The total came to five hundred dollars.", "exampleZh": "總金額是五百元。"}, {"word": "number", "pos": "n.", "zh": "數字；數量", "example": "The number of visitors is growing every year.", "exampleZh": "遊客的數量每年都在增加。"}], "phrases": [{"phrase": "take place", "zh": "舉行；發生", "example": "The sports day will take place in October.", "exampleZh": "運動會將在十月舉行。"}, {"phrase": "set up", "zh": "架設；擺好", "example": "We set up the tent before it got dark.", "exampleZh": "我們在天黑前把帳篷搭好。"}, {"phrase": "at the end of", "zh": "在……的結尾", "example": "We will have a test at the end of the month.", "exampleZh": "我們月底要考試。"}], "grammar": [{"pattern": "If + S + V（現在式）, S + will + V", "explain": "表示未來可能發生的條件。if 子句用現在式代替未來式，主要子句用 will + 原形動詞。", "example": "If you want to help, write your name on the sheet.", "exampleZh": "如果你想幫忙，就在表上寫下名字。"}, {"pattern": "between + A + and + B", "explain": "「在 A 和 B 之間」，可用於數字、時間、地點。注意一定要搭配 and，不可用 to。", "example": "Prices should be between ten and fifty dollars.", "exampleZh": "價格應該在十元到五十元之間。"}], "reading": [{"q": "When will the bake sale begin?", "options": ["At 11:30 a.m.", "At 12:00 p.m.", "At 1:00 p.m.", "At 2:00 p.m."], "answer": 1, "explain": "第一段提到 from twelve to two in the afternoon，中午十二點開始，故選 (B)。"}, {"q": "How much money did the school raise last year?", "options": ["$300", "$20,000", "$40,000", "$50,000"], "answer": 2, "explain": "第一段提到 we raised forty thousand dollars，故選 (C)。"}, {"q": "What will happen at one o'clock?", "options": ["Teachers will sell egg tarts.", "Volunteers will set up tables.", "The band and dance club will perform.", "The school will count the total."], "answer": 2, "explain": "第二段提到 Both the school band and the dance club will perform at one o'clock，故選 (C)。"}, {"q": "What should a student do to become a volunteer?", "options": ["Bring fifty cookies", "Write their name on a sheet", "Call the office", "Pay ten dollars"], "answer": 1, "explain": "第三段說想幫忙的人要在辦公室外的報名表上寫姓名和班級號碼，故選 (B)。"}, {"q": "The word \"raised\" in paragraph 1 is closest in meaning to ______.", "options": ["collected", "lost", "spent", "lifted"], "answer": 0, "explain": "raise money 指「募款」，即收集到的錢，與 collected 意思最接近，故選 (A)。"}], "vocabQ": [{"q": "There are about two ____ pages in this English dictionary.", "options": ["twenty", "thousand", "zero", "first"], "answer": 1, "explain": "句意為「這本英文字典大約有兩千頁」，thousand 千。"}, {"q": "____ of my sisters play the violin, so our house is never quiet.", "options": ["Any", "Little", "Both", "Less"], "answer": 2, "explain": "句意為「我的兩個姊姊都拉小提琴，所以家裡從不安靜」，both 兩者都。"}, {"q": "Add up all the prices, and tell me the ____.", "options": ["number", "total", "second", "third"], "answer": 1, "explain": "句意為「把所有價格加起來，告訴我總數」，total 總數。"}, {"q": "I only have ____ coins left, so I cannot buy a drink.", "options": ["a few", "a little", "much", "all"], "answer": 0, "explain": "coins 是可數名詞，句意為「我只剩幾枚硬幣，買不了飲料」，a few 幾個。"}, {"q": "The ____ of students in our class is thirty-two.", "options": ["total", "hundred", "number", "several"], "answer": 2, "explain": "句意為「我們班的學生人數是三十二人」，the number of 「……的數量」。"}]}, {"id": "E08", "level": "elem", "num": 8, "title": "Four Seasons on My Calendar", "titleZh": "我日曆上的四季", "theme": "Time, Dates & Seasons", "themeZh": "時間、日期與季節", "article": ["Some people say Taiwan has only two seasons: hot and hotter. I don't agree. Each season on my calendar has its own color and taste. Spring starts in March. The weather is warm, but it rains almost every afternoon. On weekends, my family goes to Yangmingshan to see the cherry blossoms.", "Summer comes in June, and it is very hot and wet. In July and August, we have no school, so I wake up late and go swimming with my cousins in the evening. Typhoons sometimes visit in September. When a typhoon comes, we stay home and watch movies all day. Autumn is my favorite season. From October to November, the air is cool and dry. It is the best time to ride a bike along the river.", "Winter in Taiwan is short, but January can be cold and gray. I still love it because of the Lunar New Year. We get red envelopes and eat hot pot with Grandma. Then, in early February, the year begins again. I can't wait for the next spring!"], "translation": ["有些人說台灣只有兩個季節：熱和更熱。我不同意。我日曆上的每一個季節都有自己的顏色和味道。春天從三月開始。天氣溫暖，但幾乎每天下午都會下雨。週末時，我們全家會去陽明山看櫻花。", "夏天在六月到來，又熱又潮溼。七月和八月不用上學，所以我很晚起床，傍晚和表兄弟姊妹一起去游泳。九月有時候會有颱風來訪。颱風來的時候，我們就待在家裡看一整天電影。秋天是我最喜歡的季節。從十月到十一月，空氣涼爽又乾燥，是沿著河邊騎腳踏車最棒的時候。", "台灣的冬天很短，但一月可能又冷又灰暗。我還是很愛冬天，因為有農曆新年。我們會拿紅包，和奶奶一起吃火鍋。然後，在二月初，新的一年又開始了。我等不及下一個春天了！"], "vocab": [{"word": "season", "pos": "n.", "zh": "季節", "example": "Which season do you like best?", "exampleZh": "你最喜歡哪個季節？"}, {"word": "calendar", "pos": "n.", "zh": "日曆；行事曆", "example": "I wrote the test date on my calendar.", "exampleZh": "我把考試日期寫在日曆上。"}, {"word": "spring", "pos": "n.", "zh": "春天", "example": "Flowers bloom everywhere in spring.", "exampleZh": "春天時到處都開滿了花。"}, {"word": "summer", "pos": "n.", "zh": "夏天", "example": "We go to the beach every summer.", "exampleZh": "我們每年夏天都去海邊。"}, {"word": "autumn", "pos": "n.", "zh": "秋天", "example": "The leaves turn red and yellow in autumn.", "exampleZh": "秋天時葉子變成紅色和黃色。"}, {"word": "winter", "pos": "n.", "zh": "冬天", "example": "It sometimes snows on Hehuanshan in winter.", "exampleZh": "冬天合歡山有時會下雪。"}, {"word": "weekend", "pos": "n.", "zh": "週末", "example": "What are you going to do this weekend?", "exampleZh": "你這個週末要做什麼？"}, {"word": "early", "pos": "adj.", "zh": "早的；初期的", "example": "We left in the early morning to catch the train.", "exampleZh": "我們一大早出發去趕火車。"}], "phrases": [{"phrase": "wake up", "zh": "醒來；起床", "example": "I wake up at six thirty every day.", "exampleZh": "我每天六點半起床。"}, {"phrase": "because of", "zh": "因為（後接名詞）", "example": "The game was canceled because of the rain.", "exampleZh": "比賽因為下雨而取消。"}, {"phrase": "can't wait for", "zh": "等不及", "example": "The kids can't wait for the summer vacation.", "exampleZh": "孩子們等不及放暑假了。"}], "grammar": [{"pattern": "When + S + V ..., S + V ...", "explain": "when 引導時間副詞子句，表示「當……的時候」。子句放句首時，後面要加逗號；描述習慣或一般事實時，兩邊都用現在式。", "example": "When a typhoon comes, we stay home all day.", "exampleZh": "颱風來的時候，我們整天待在家裡。"}, {"pattern": "the best + N + to + V", "explain": "「做……最好的（時間／地方／方法）」。最高級 the best 修飾名詞，再用不定詞 to V 說明用途。", "example": "Autumn is the best time to ride a bike.", "exampleZh": "秋天是騎腳踏車最好的時候。"}], "reading": [{"q": "What does the writer think about the seasons in Taiwan?", "options": ["Taiwan only has summer and winter.", "Every season is different and special.", "All seasons are too hot.", "Spring is the only nice season."], "answer": 1, "explain": "第一段作者不同意「台灣只有兩季」，並說每個季節都有自己的顏色和味道，故選 (B)。"}, {"q": "What does the writer's family do in spring?", "options": ["Eat hot pot with Grandma", "Go swimming in the evening", "Watch movies at home", "See cherry blossoms on a mountain"], "answer": 3, "explain": "第一段提到週末全家去陽明山看櫻花 (cherry blossoms)，故選 (D)。"}, {"q": "Why does the writer wake up late in July and August?", "options": ["Because there is no school", "Because of the typhoons", "Because it is too cold", "Because of the Lunar New Year"], "answer": 0, "explain": "第二段提到 we have no school, so I wake up late，故選 (A)。"}, {"q": "Which season is the writer's favorite?", "options": ["Spring", "Summer", "Autumn", "Winter"], "answer": 2, "explain": "第二段明確說 Autumn is my favorite season，故選 (C)。"}, {"q": "The word \"gray\" in paragraph 3 most likely describes ______.", "options": ["a bright, sunny sky", "a dark, cloudy sky", "a warm wind", "a snowy mountain"], "answer": 1, "explain": "gray 灰暗的，與 cold 並列形容一月的天氣，指天空陰暗多雲，故選 (B)。"}], "vocabQ": [{"q": "I circled my birthday on the ____ so that I would not forget it.", "options": ["clock", "calendar", "watch", "minute"], "answer": 1, "explain": "句意為「我在日曆上把生日圈起來，這樣就不會忘記」，calendar 日曆。"}, {"q": "We do not have classes on the ____, so I sleep until ten.", "options": ["weekday", "weekend", "noon", "dawn"], "answer": 1, "explain": "句意為「週末不用上課，所以我睡到十點」，weekend 週末。"}, {"q": "It is so hot in ____ that we eat shaved ice almost every day.", "options": ["summer", "winter", "January", "December"], "answer": 0, "explain": "句意為「夏天太熱了，我們幾乎每天吃剉冰」，summer 夏天。"}, {"q": "My grandpa wears a thick coat in ____ because he is afraid of the cold.", "options": ["spring", "fall", "winter", "July"], "answer": 2, "explain": "句意為「爺爺冬天穿厚外套，因為他怕冷」，winter 冬天。"}, {"q": "Autumn is my favorite ____ because the weather is cool and dry.", "options": ["moment", "season", "month", "week"], "answer": 1, "explain": "句意為「秋天是我最喜歡的季節，因為天氣涼爽乾燥」，season 季節。"}]}, {"id": "E09", "level": "elem", "num": 9, "title": "Tom's Two-Thousand-Dollar Sneakers", "titleZh": "Tom 的兩千元球鞋", "theme": "Money", "themeZh": "金錢", "article": ["Tom wanted a new pair of sneakers. The price was two thousand dollars, but he only had five hundred in his piggy bank. \"Can you lend me some money?\" he asked his older sister, Amy. Amy shook her head. \"I won't lend you money, but I can teach you how to earn it.\"", "For the next month, Tom worked hard. He washed his dad's car, walked the neighbor's dog, and sold his old comic books at a flea market. He also stopped buying bubble tea every day. He put every coin and every bill into a big jar. By the end of the month, he had saved enough cash.", "At the shoe store, Tom paid for the sneakers and counted his change carefully. The shoes were still expensive, but now they felt special. \"When you spend money you earned yourself, you think twice,\" Amy said. Tom smiled. He never borrowed money from anyone again."], "translation": ["Tom 想要一雙新球鞋。價格是兩千元，但他的小豬撲滿裡只有五百元。「妳可以借我一些錢嗎？」他問姊姊 Amy。Amy 搖搖頭：「我不會借你錢，但我可以教你怎麼賺錢。」", "接下來的一個月，Tom 很努力。他幫爸爸洗車、幫鄰居遛狗，還在跳蚤市場賣掉他的舊漫畫。他也不再每天買珍珠奶茶了。他把每一枚硬幣和每一張鈔票都放進一個大罐子裡。到了月底，他已經存夠現金了。", "在鞋店，Tom 付了球鞋的錢，仔細數了找回來的零錢。鞋子還是很貴，但現在它們感覺很特別。「當你花的是自己賺來的錢，你就會三思。」Amy 說。Tom 笑了。他再也沒有向任何人借過錢。"], "vocab": [{"word": "price", "pos": "n.", "zh": "價格", "example": "The price of the bike is too high for me.", "exampleZh": "這台腳踏車的價格對我來說太高了。"}, {"word": "lend", "pos": "v.", "zh": "借（出）", "example": "Can you lend me your pen for a minute?", "exampleZh": "你可以借我一下筆嗎？"}, {"word": "earn", "pos": "v.", "zh": "賺（錢）", "example": "She earns extra money by teaching piano.", "exampleZh": "她靠教鋼琴賺外快。"}, {"word": "coin", "pos": "n.", "zh": "硬幣", "example": "I found a ten-dollar coin under the sofa.", "exampleZh": "我在沙發下找到一枚十元硬幣。"}, {"word": "cash", "pos": "n.", "zh": "現金", "example": "This shop only takes cash.", "exampleZh": "這家店只收現金。"}, {"word": "change", "pos": "n.", "zh": "零錢；找回的錢", "example": "Keep the change, please.", "exampleZh": "零錢不用找了。"}, {"word": "expensive", "pos": "adj.", "zh": "昂貴的", "example": "Eating at that restaurant is very expensive.", "exampleZh": "在那家餐廳吃飯很貴。"}, {"word": "borrow", "pos": "v.", "zh": "借（入）", "example": "May I borrow your umbrella?", "exampleZh": "我可以借你的雨傘嗎？"}], "phrases": [{"phrase": "shake one's head", "zh": "搖頭", "example": "Dad shook his head when I asked for more candy.", "exampleZh": "我要更多糖果時，爸爸搖了搖頭。"}, {"phrase": "pay for", "zh": "付……的錢", "example": "Who will pay for the dinner tonight?", "exampleZh": "今晚誰付晚餐的錢？"}, {"phrase": "think twice", "zh": "三思；再考慮一下", "example": "Think twice before you buy an expensive phone.", "exampleZh": "買昂貴的手機前要三思。"}], "grammar": [{"pattern": "S + teach + O + how + to + V", "explain": "「教某人如何做某事」。how to + 原形動詞是名詞片語，作 teach 的受詞補語。類似用法：show / tell + 人 + how to V。", "example": "Amy taught Tom how to earn money.", "exampleZh": "Amy 教 Tom 怎麼賺錢。"}, {"pattern": "S + stop + V-ing", "explain": "stop 後面接 V-ing 表示「停止做（原本在做的）某事」；若接 to V 則是「停下來去做另一件事」，意思不同。", "example": "He stopped buying bubble tea every day.", "exampleZh": "他不再每天買珍珠奶茶了。"}], "reading": [{"q": "How much more money did Tom need for the sneakers at the beginning?", "options": ["$500", "$1,000", "$1,500", "$2,000"], "answer": 2, "explain": "球鞋兩千元，Tom 只有五百元，還差一千五百元，故選 (C)。"}, {"q": "Why didn't Amy lend Tom the money?", "options": ["She did not have any money.", "She wanted him to learn to earn it.", "She thought the shoes were ugly.", "She was angry at him."], "answer": 1, "explain": "第一段 Amy 說 I can teach you how to earn it，她希望 Tom 學會自己賺錢，故選 (B)。"}, {"q": "Which of the following did Tom NOT do to get money?", "options": ["Wash a car", "Walk a dog", "Sell old comic books", "Deliver newspapers"], "answer": 3, "explain": "第二段列出洗車、遛狗、賣漫畫，沒有提到送報紙，故選 (D)。"}, {"q": "The phrase \"think twice\" in paragraph 3 is closest in meaning to ______.", "options": ["count your money two times", "buy two pairs of shoes", "consider carefully before acting", "change your mind quickly"], "answer": 2, "explain": "think twice 指「三思、仔細考慮後再行動」，故選 (C)。"}, {"q": "What is the lesson of this story?", "options": ["Sneakers are too expensive.", "Flea markets are good places to shop.", "Money you earn yourself means more to you.", "Never ask your sister for help."], "answer": 2, "explain": "第三段 Amy 說自己賺的錢花起來會三思，鞋子也變得特別，點出主旨，故選 (C)。"}], "vocabQ": [{"q": "The ____ of the concert ticket is 3,000 dollars, so I cannot afford it.", "options": ["price", "cent", "coin", "bill"], "answer": 0, "explain": "句意為「演唱會門票的價格是三千元，我負擔不起」，price 價格。"}, {"q": "I forgot my wallet. Could you ____ me fifty dollars for lunch?", "options": ["buy", "cost", "lend", "spend"], "answer": 2, "explain": "句意為「我忘了帶皮夾，你可以借我五十元吃午餐嗎？」lend 借出（主詞是借錢給別人的人）。"}, {"q": "My brother wants to ____ money by selling drinks at the night market this weekend.", "options": ["pay", "earn", "borrow", "charge"], "answer": 1, "explain": "句意為「我哥哥這個週末想在夜市賣飲料賺錢」，earn 賺錢。"}, {"q": "That hotel is too ____; one night costs more than ten thousand dollars.", "options": ["cheap", "expensive", "little", "early"], "answer": 1, "explain": "句意為「那家飯店太貴了，一晚要一萬多元」，expensive 昂貴的。"}, {"q": "The bus driver does not give ____, so please bring the exact amount.", "options": ["change", "cash", "price", "credit"], "answer": 0, "explain": "句意為「公車司機不找零，請自備剛好的金額」，change 找回的零錢。"}]}, {"id": "E10", "level": "elem", "num": 10, "title": "Taiwan, the Kingdom of Fruit", "titleZh": "台灣，水果王國", "theme": "Fruit & Vegetables", "themeZh": "蔬菜與水果", "article": ["Many visitors call Taiwan \"the Kingdom of Fruit,\" and it is easy to see why. Because the island is warm and sunny, fruit grows well all year. In summer, markets are full of sweet mangoes from Tainan and big, juicy watermelons. In winter, people peel tangerines while they watch TV at home.", "Some fruits are easy to find all year. Guava is a favorite snack for students because it is cheap and crunchy. Papaya is often made into papaya milk, a popular drink at night markets. Pineapple is special too. In Taiwanese, its name sounds like \"good luck comes,\" so people put pineapples in their homes during the Lunar New Year.", "Vegetables are also important in Taiwanese kitchens. Cabbage is in almost every stir-fry, and sweet corn is sold on a stick at night markets. Many families even grow their own vegetables on their balconies. So next time you visit, do not just eat fried chicken. Try the fruit and vegetables. They are the real taste of Taiwan!"], "translation": ["許多遊客稱台灣為「水果王國」，原因不難理解。因為這座島嶼溫暖又陽光充足，水果一整年都長得很好。夏天，市場裡滿是台南的香甜芒果和又大又多汁的西瓜。冬天，大家在家一邊看電視一邊剝橘子。", "有些水果一整年都很容易買到。芭樂是學生最愛的零食，因為它便宜又脆。木瓜常被做成木瓜牛奶，是夜市裡很受歡迎的飲料。鳳梨也很特別。在台語裡，它的名字聽起來像「旺來」（好運來），所以農曆新年期間大家會在家裡擺鳳梨。", "蔬菜在台灣的廚房裡也很重要。高麗菜幾乎出現在每一道炒菜裡，而夜市裡有用竹籤串著賣的甜玉米。許多家庭甚至在陽台上自己種菜。所以下次你來訪時，不要只吃炸雞。試試水果和蔬菜吧，它們才是台灣真正的味道！"], "vocab": [{"word": "fruit", "pos": "n.", "zh": "水果", "example": "Eat more fruit and less candy.", "exampleZh": "多吃水果，少吃糖果。"}, {"word": "mango", "pos": "n.", "zh": "芒果", "example": "Mango shaved ice is popular in summer.", "exampleZh": "芒果冰在夏天很受歡迎。"}, {"word": "watermelon", "pos": "n.", "zh": "西瓜", "example": "We shared a big watermelon at the beach.", "exampleZh": "我們在海邊分享了一顆大西瓜。"}, {"word": "guava", "pos": "n.", "zh": "芭樂", "example": "My grandma grows guavas in her garden.", "exampleZh": "我奶奶在花園裡種芭樂。"}, {"word": "papaya", "pos": "n.", "zh": "木瓜", "example": "Papaya milk is my favorite drink at the night market.", "exampleZh": "木瓜牛奶是我在夜市最愛的飲料。"}, {"word": "pineapple", "pos": "n.", "zh": "鳳梨", "example": "Pineapple cakes are a famous gift from Taiwan.", "exampleZh": "鳳梨酥是台灣有名的伴手禮。"}, {"word": "vegetable", "pos": "n.", "zh": "蔬菜", "example": "Carrots and cabbages are vegetables.", "exampleZh": "紅蘿蔔和高麗菜都是蔬菜。"}, {"word": "cabbage", "pos": "n.", "zh": "高麗菜", "example": "Mom fried some cabbage with garlic for dinner.", "exampleZh": "媽媽晚餐炒了蒜香高麗菜。"}], "phrases": [{"phrase": "be full of", "zh": "充滿", "example": "The basket is full of fresh apples.", "exampleZh": "籃子裡裝滿了新鮮的蘋果。"}, {"phrase": "be made into", "zh": "被做成", "example": "Grapes can be made into juice or wine.", "exampleZh": "葡萄可以做成果汁或酒。"}, {"phrase": "next time", "zh": "下次", "example": "Next time, bring your own water bottle.", "exampleZh": "下次請自備水壺。"}], "grammar": [{"pattern": "Because + S + V ..., S + V ...", "explain": "because 引導原因子句，可放句首（後加逗號）或句中。注意 because 與 so 不可同時出現在一句中。", "example": "Because the island is warm, fruit grows well all year.", "exampleZh": "因為這座島很溫暖，水果一整年都長得好。"}, {"pattern": "S + sound like + N", "explain": "sound 是連綴動詞，「聽起來像……」。後面接名詞時要加 like；直接接形容詞時不加 like（sounds good）。", "example": "Its name sounds like \"good luck comes.\"", "exampleZh": "它的名字聽起來像「好運來」。"}], "reading": [{"q": "Why does fruit grow well in Taiwan?", "options": ["Because farmers work at night", "Because the weather is warm and sunny", "Because people eat a lot of fruit", "Because the island is small"], "answer": 1, "explain": "第一段提到 Because the island is warm and sunny, fruit grows well all year，故選 (B)。"}, {"q": "Why do students like guava?", "options": ["It is sweet and soft.", "It is cheap and crunchy.", "It brings good luck.", "It is sold on a stick."], "answer": 1, "explain": "第二段提到 Guava is a favorite snack for students because it is cheap and crunchy，故選 (B)。"}, {"q": "Why do people put pineapples in their homes during the Lunar New Year?", "options": ["Pineapples keep the house cool.", "Pineapples are cheap in winter.", "The name sounds like good luck is coming.", "Pineapples can be made into milk."], "answer": 2, "explain": "第二段說鳳梨的台語名字聽起來像「好運來」，所以過年時擺在家裡，故選 (C)。"}, {"q": "The word \"crunchy\" in paragraph 2 most likely means ______.", "options": ["making a loud sound when you bite it", "very expensive", "soft and juicy", "hard to find"], "answer": 0, "explain": "crunchy 形容芭樂「脆脆的」，咬下去會發出聲音，故選 (A)。"}, {"q": "What does the writer suggest at the end of the article?", "options": ["Visitors should only eat fried chicken.", "Visitors should try local fruit and vegetables.", "Visitors should grow vegetables on balconies.", "Visitors should come in winter."], "answer": 1, "explain": "最後一段說 do not just eat fried chicken. Try the fruit and vegetables，建議遊客品嚐在地蔬果，故選 (B)。"}], "vocabQ": [{"q": "Cut the ____ into pieces and put it in the fridge; it is so sweet and juicy in summer.", "options": ["onion", "watermelon", "potato", "bean"], "answer": 1, "explain": "句意為「把西瓜切塊放冰箱，夏天的西瓜又甜又多汁」，watermelon 西瓜。"}, {"q": "Tainan is famous for its sweet yellow ____ in June and July.", "options": ["mango", "carrot", "pumpkin", "lettuce"], "answer": 0, "explain": "句意為「台南以六、七月香甜的黃色芒果聞名」，mango 芒果。"}, {"q": "Mom always buys a whole ____ and fries it with garlic for dinner.", "options": ["grape", "strawberry", "cabbage", "peach"], "answer": 2, "explain": "句意為「媽媽總是買一整顆高麗菜，晚餐用蒜頭炒」，cabbage 高麗菜。"}, {"q": "The ____ is a symbol of good luck, so you can see it in many shops during the New Year.", "options": ["lemon", "tomato", "corn", "pineapple"], "answer": 3, "explain": "句意為「鳳梨象徵好運，過年時許多店家都擺鳳梨」，pineapple 鳳梨。"}, {"q": "Spinach is a green ____ that is rich in iron.", "options": ["nut", "vegetable", "apple", "pear"], "answer": 1, "explain": "句意為「菠菜是一種富含鐵質的綠色蔬菜」，vegetable 蔬菜。"}]}, {"id": "E11", "level": "elem", "num": 11, "title": "A Day of Delicious Meals", "titleZh": "美味的一天", "theme": "Food", "themeZh": "食物", "article": ["Last Saturday was my cousin Amy's birthday, so my family ate out all day. For breakfast, we went to a small shop near the MRT station. I had an egg sandwich and a bowl of hot soup. My dad ordered a pork bun and some rice. Amy only ate cereal with milk because she wanted to save room for lunch.", "At noon, we had lunch at a noodle shop near the night market. Grandma loves dumplings, so we ordered thirty of them! I ate beef noodles, and my little brother had fried chicken and French fries. Mom said fast food is not healthy, but she still shared a hamburger with him.", "Dinner was the best meal of the day. We went to a seafood restaurant by the river. There were shrimp, fish, and even a big steak for Dad. Amy got a cake with her name on it. I was so full that I did not need any snack before bed. What a tasty day!"], "translation": ["上星期六是我表姊 Amy 的生日，所以我們全家一整天都在外面吃。早餐我們去了捷運站附近的一家小店。我吃了一個蛋三明治和一碗熱湯。爸爸點了一個豬肉包和一些飯。Amy 只吃了麥片加牛奶，因為她想把肚子留給午餐。", "中午，我們在夜市附近的一家麵店吃午餐。奶奶很愛水餃，所以我們點了三十顆！我吃牛肉麵，弟弟則吃炸雞和薯條。媽媽說速食不健康，但她還是和弟弟分享了一個漢堡。", "晚餐是一天中最棒的一餐。我們去了河邊的一家海鮮餐廳。有蝦子、魚，甚至還有給爸爸的一大塊牛排。Amy 收到了一個寫著她名字的蛋糕。我吃得好飽，睡前完全不需要任何點心。真是美味的一天！"], "vocab": [{"word": "sandwich", "pos": "n.", "zh": "三明治", "example": "I usually eat a ham sandwich for breakfast.", "exampleZh": "我早餐通常吃火腿三明治。"}, {"word": "soup", "pos": "n.", "zh": "湯", "example": "Mom makes chicken soup when I am sick.", "exampleZh": "我生病時媽媽會煮雞湯。"}, {"word": "dumpling", "pos": "n.", "zh": "水餃；餃子", "example": "Grandpa can eat forty dumplings at one time.", "exampleZh": "爺爺一次可以吃四十顆水餃。"}, {"word": "noodle", "pos": "n.", "zh": "麵條", "example": "Beef noodles are very famous in Taiwan.", "exampleZh": "牛肉麵在台灣非常有名。"}, {"word": "chicken", "pos": "n.", "zh": "雞肉", "example": "Fried chicken is my brother's favorite food.", "exampleZh": "炸雞是我弟弟最愛的食物。"}, {"word": "seafood", "pos": "n.", "zh": "海鮮", "example": "We ate fresh seafood at the harbor.", "exampleZh": "我們在港口吃了新鮮的海鮮。"}, {"word": "steak", "pos": "n.", "zh": "牛排", "example": "Dad cooked a big steak on the grill.", "exampleZh": "爸爸在烤架上煎了一大塊牛排。"}, {"word": "meal", "pos": "n.", "zh": "一餐", "example": "We eat three meals a day.", "exampleZh": "我們一天吃三餐。"}], "phrases": [{"phrase": "eat out", "zh": "在外面吃飯", "example": "We eat out every Friday night.", "exampleZh": "我們每個星期五晚上都在外面吃。"}, {"phrase": "save room for", "zh": "留肚子吃…", "example": "Don't eat too much bread. Save room for dessert.", "exampleZh": "別吃太多麵包，留點肚子吃甜點。"}, {"phrase": "share ... with", "zh": "和…分享", "example": "She shared her lunch with her friend.", "exampleZh": "她和朋友分享她的午餐。"}], "grammar": [{"pattern": "S + be + so + adj. + that + S + V", "explain": "「如此…以至於…」，前面說明程度，that 後面接造成的結果。", "example": "I was so full that I did not need any snack.", "exampleZh": "我飽到不需要任何點心。"}, {"pattern": "What + a/an + adj. + N (+ S + V)!", "explain": "感嘆句，用來表達強烈的感受，名詞為單數可數名詞時要加 a / an。", "example": "What a tasty day!", "exampleZh": "真是美味的一天！"}], "reading": [{"q": "Why did the writer's family eat out all day?", "options": ["It was the writer's birthday.", "It was Amy's birthday.", "Mom did not want to cook.", "Grandma came to visit."], "answer": 1, "explain": "第一段開頭提到 Last Saturday was my cousin Amy's birthday, so my family ate out all day，故選 (B)。"}, {"q": "What did Amy eat for breakfast?", "options": ["An egg sandwich.", "A pork bun.", "Cereal with milk.", "Hot soup."], "answer": 2, "explain": "第一段最後說 Amy only ate cereal with milk，故選 (C)。"}, {"q": "Which food does Grandma love?", "options": ["Dumplings.", "Beef noodles.", "Fried chicken.", "Hamburgers."], "answer": 0, "explain": "第二段提到 Grandma loves dumplings, so we ordered thirty of them，故選 (A)。"}, {"q": "The word \"full\" in paragraph 3 is closest in meaning to...", "options": ["very happy", "not hungry anymore", "very tired", "very busy"], "answer": 1, "explain": "吃完晚餐後「不需要任何點心」，可知 full 是「吃飽的」，故選 (B)。"}, {"q": "How does the writer feel about the day?", "options": ["Bored.", "Angry.", "Happy.", "Worried."], "answer": 2, "explain": "最後一句 What a tasty day! 表達作者開心的感受，故選 (C)。"}], "vocabQ": [{"q": "Mom made a chicken ____ for my lunch box, with lettuce between two pieces of bread.", "options": ["sandwich", "soup", "steak", "salad"], "answer": 0, "explain": "兩片麵包中間夾生菜和雞肉的是 sandwich 三明治，故選 (A)。"}, {"q": "The ____ is too hot. Wait a minute before you drink it.", "options": ["bread", "soup", "dumpling", "steak"], "answer": 1, "explain": "可以「喝」且很燙的是 soup 湯，故選 (B)。"}, {"q": "Each ____ has a little pork inside, and Grandma makes them by hand.", "options": ["dumpling", "noodle", "sandwich", "steak"], "answer": 0, "explain": "裡面包豬肉、奶奶手工做的是 dumpling 水餃，故選 (A)。"}, {"q": "We ordered a big ____ at the restaurant, and the cook asked how we wanted the beef done.", "options": ["salad", "soup", "steak", "bread"], "answer": 2, "explain": "廚師問牛肉要幾分熟，可知點的是 steak 牛排，故選 (C)。"}, {"q": "Breakfast is the most important ____ of the day, so do not skip it.", "options": ["snack", "meal", "dish", "food"], "answer": 1, "explain": "句意為「早餐是一天中最重要的一餐」，meal 一餐，故選 (B)。"}]}, {"id": "E12", "level": "elem", "num": 12, "title": "A Letter About Drinks in Taiwan", "titleZh": "一封關於台灣飲料的信", "theme": "Drinks", "themeZh": "飲料", "article": ["Dear Lucy, How are you? I am writing to you from Taipei. The weather is very hot here, so people drink a lot. There is a drink shop on almost every street! Today I want to tell you about my favorite drinks in Taiwan.", "First, you must try milk tea with small black balls inside. People call it bubble tea. You can choose the ice and the sugar. I always say 'less ice' because the tea gets too cold. Juice is also popular. My host mom makes fresh orange juice every morning. She never buys soda or cola because she says soft drinks are bad for our teeth.", "Yesterday my host brother took me to a cafe. He ordered a cup of coffee, and I had a chocolate milk shake. It was sweet and thick, like a liquid dessert. Of course, water is still the best drink on a hot day. I carry a bottle everywhere. Please write back soon and tell me about your favorite drink! Love, Mia"], "translation": ["親愛的 Lucy：你好嗎？我正在台北寫信給你。這裡的天氣很熱，所以大家喝很多飲料。幾乎每條街上都有一家飲料店！今天我想跟你說說我在台灣最愛的飲料。", "首先，你一定要試試裡面有黑色小珍珠的奶茶。大家叫它珍珠奶茶。你可以選冰塊和糖的多少。我總是說「少冰」，因為茶會變得太冰。果汁也很受歡迎。我的寄宿媽媽每天早上都榨新鮮的柳橙汁。她從不買汽水或可樂，因為她說碳酸飲料對我們的牙齒不好。", "昨天寄宿家庭的哥哥帶我去一家咖啡館。他點了一杯咖啡，我則喝了巧克力奶昔。它又甜又濃，就像液體的甜點。當然，在炎熱的日子裡，水仍然是最好的飲料。我走到哪裡都帶著一瓶水。請快點回信，告訴我你最愛的飲料！愛你的 Mia"], "vocab": [{"word": "tea", "pos": "n.", "zh": "茶", "example": "My grandpa drinks green tea every afternoon.", "exampleZh": "我爺爺每天下午都喝綠茶。"}, {"word": "juice", "pos": "n.", "zh": "果汁", "example": "Apple juice is good for breakfast.", "exampleZh": "蘋果汁很適合當早餐喝。"}, {"word": "soda", "pos": "n.", "zh": "汽水", "example": "Too much soda is bad for your health.", "exampleZh": "喝太多汽水對健康不好。"}, {"word": "cola", "pos": "n.", "zh": "可樂", "example": "He bought a can of cola at the night market.", "exampleZh": "他在夜市買了一罐可樂。"}, {"word": "coffee", "pos": "n.", "zh": "咖啡", "example": "Mom drinks coffee before work.", "exampleZh": "媽媽上班前會喝咖啡。"}, {"word": "milk shake", "pos": "n.", "zh": "奶昔", "example": "The strawberry milk shake here is very popular.", "exampleZh": "這裡的草莓奶昔非常受歡迎。"}, {"word": "liquid", "pos": "n.", "zh": "液體", "example": "Do not bring any liquid into the museum.", "exampleZh": "不要帶任何液體進博物館。"}, {"word": "water", "pos": "n.", "zh": "水", "example": "Please drink more water in summer.", "exampleZh": "夏天請多喝水。"}], "phrases": [{"phrase": "a lot", "zh": "很多；大量地", "example": "Kids in Taiwan study a lot.", "exampleZh": "台灣的孩子讀很多書。"}, {"phrase": "be bad for", "zh": "對…有害", "example": "Staying up late is bad for your eyes.", "exampleZh": "熬夜對你的眼睛不好。"}, {"phrase": "write back", "zh": "回信", "example": "I hope you can write back soon.", "exampleZh": "希望你能快點回信。"}], "grammar": [{"pattern": "There + is/are + N + 地方", "explain": "「某地有…」，單數名詞用 is，複數名詞用 are。", "example": "There is a drink shop on almost every street.", "exampleZh": "幾乎每條街上都有一家飲料店。"}, {"pattern": "S + must + 原形動詞", "explain": "must 是助動詞，表示「必須、一定要」，後面接原形動詞，沒有三單變化。", "example": "You must try milk tea with small black balls inside.", "exampleZh": "你一定要試試裡面有黑色小珍珠的奶茶。"}], "reading": [{"q": "Why does Mia write this letter?", "options": ["To invite Lucy to Taipei.", "To tell Lucy about drinks in Taiwan.", "To ask Lucy for money.", "To say sorry to Lucy."], "answer": 1, "explain": "第一段最後一句 Today I want to tell you about my favorite drinks in Taiwan 說明寫信目的，故選 (B)。"}, {"q": "What does Mia say when she buys bubble tea?", "options": ["More sugar.", "No tea.", "Less ice.", "More milk."], "answer": 2, "explain": "第二段提到 I always say 'less ice' because the tea gets too cold，故選 (C)。"}, {"q": "Why doesn't the host mom buy soft drinks?", "options": ["They are too expensive.", "They are bad for teeth.", "She does not like the taste.", "The shop is far away."], "answer": 1, "explain": "第二段最後一句說 soft drinks are bad for our teeth，故選 (B)。"}, {"q": "What did Mia drink at the cafe?", "options": ["Coffee.", "Orange juice.", "Water.", "A chocolate milk shake."], "answer": 3, "explain": "第三段說 He ordered a cup of coffee, and I had a chocolate milk shake，故選 (D)。"}, {"q": "The word \"thick\" in paragraph 3 is closest in meaning to...", "options": ["not thin or watery", "very cold", "very expensive", "very big"], "answer": 0, "explain": "奶昔「又甜又濃，像液體甜點」，thick 指「濃稠的」，故選 (A)。"}], "vocabQ": [{"q": "Dad cannot wake up without a cup of hot ____ in the morning.", "options": ["juice", "water", "coffee", "soda"], "answer": 2, "explain": "早上喝一杯熱的、幫助清醒的是 coffee 咖啡，故選 (C)。"}, {"q": "Grandma squeezes fresh orange ____ for us every Sunday.", "options": ["tea", "juice", "milk shake", "cola"], "answer": 1, "explain": "squeeze 榨，榨柳橙得到的是 juice 果汁，故選 (B)。"}, {"q": "Water is a ____, but ice is not.", "options": ["liquid", "drink", "soda", "cup"], "answer": 0, "explain": "水是液體而冰不是，liquid 液體，故選 (A)。"}, {"q": "The doctor told me to drink eight glasses of ____ every day.", "options": ["coffee", "soda", "water", "tea"], "answer": 2, "explain": "醫生建議每天喝八杯的是 water 水，故選 (C)。"}, {"q": "The shop mixes bananas, ice cream, and milk to make a thick ____.", "options": ["juice", "coffee", "tea", "milk shake"], "answer": 3, "explain": "香蕉、冰淇淋和牛奶打成濃稠的飲料是 milk shake 奶昔，故選 (D)。"}]}, {"id": "E13", "level": "elem", "num": 13, "title": "Grandma Lin's Sweet Little Shop", "titleZh": "林奶奶的甜蜜小舖", "theme": "Snacks & Desserts", "themeZh": "點心與甜食", "article": ["Grandma Lin has a small dessert shop near our school. It is not big, but it always smells sweet. Every afternoon, students stand in line outside the door. They want her famous cookies and cakes. Grandma Lin always says, 'Food made with love tastes better.'", "The shop sells many kinds of snacks. There are chocolate doughnuts, cheese pies, and hot toast with butter. In summer, kids love her mango ice cream. In September, she makes moon cakes for the Moon Festival. Her candy jars sit by the window, and the colors shine in the sun.", "Grandma Lin does not do it for money. She gives free cookies to children who get good grades. She also teaches us how to bake on Sundays. Last week, my friends and I made a strawberry cake with her. It was not perfect, but it was the best dessert of my life."], "translation": ["林奶奶在我們學校附近有一家小小的甜點店。店不大，但總是香甜撲鼻。每天下午，學生們都在門口排隊。他們想要她有名的餅乾和蛋糕。林奶奶總是說：「用愛做的食物比較好吃。」", "這家店賣很多種點心。有巧克力甜甜圈、起司派，還有塗了奶油的熱吐司。夏天時，孩子們喜歡她的芒果冰淇淋。九月時，她會為中秋節做月餅。她的糖果罐放在窗邊，各種顏色在陽光下閃閃發亮。", "林奶奶做這些不是為了錢。她送免費餅乾給成績好的孩子。她也在星期天教我們烘焙。上星期，我和朋友們跟她一起做了草莓蛋糕。它不算完美，但那是我這輩子吃過最棒的甜點。"], "vocab": [{"word": "dessert", "pos": "n.", "zh": "甜點", "example": "What is for dessert tonight?", "exampleZh": "今晚的甜點是什麼？"}, {"word": "cookie", "pos": "n.", "zh": "餅乾", "example": "She baked chocolate cookies for the party.", "exampleZh": "她為派對烤了巧克力餅乾。"}, {"word": "doughnut", "pos": "n.", "zh": "甜甜圈", "example": "I bought a box of doughnuts for my class.", "exampleZh": "我買了一盒甜甜圈給全班。"}, {"word": "pie", "pos": "n.", "zh": "派", "example": "Grandma's apple pie smells wonderful.", "exampleZh": "奶奶的蘋果派聞起來好香。"}, {"word": "toast", "pos": "n.", "zh": "吐司", "example": "He eats two pieces of toast every morning.", "exampleZh": "他每天早上吃兩片吐司。"}, {"word": "ice cream", "pos": "n.", "zh": "冰淇淋", "example": "Vanilla ice cream is my favorite.", "exampleZh": "香草冰淇淋是我的最愛。"}, {"word": "moon cake", "pos": "n.", "zh": "月餅", "example": "We eat moon cakes during the Moon Festival.", "exampleZh": "我們在中秋節吃月餅。"}, {"word": "candy", "pos": "n.", "zh": "糖果", "example": "Too much candy is bad for your teeth.", "exampleZh": "太多糖果對牙齒不好。"}], "phrases": [{"phrase": "stand in line", "zh": "排隊", "example": "People stand in line for the famous bubble tea.", "exampleZh": "人們為了那家有名的珍珠奶茶排隊。"}, {"phrase": "many kinds of", "zh": "很多種類的", "example": "The night market has many kinds of snacks.", "exampleZh": "夜市有很多種小吃。"}, {"phrase": "teach sb. how to V", "zh": "教某人如何做…", "example": "My dad taught me how to ride a bike.", "exampleZh": "我爸爸教我如何騎腳踏車。"}], "grammar": [{"pattern": "S + be + not + ..., but + S + V", "explain": "「雖然不…，但是…」，用 but 連接兩個意思相反的句子，表示轉折。", "example": "It is not big, but it always smells sweet.", "exampleZh": "店不大，但總是香甜撲鼻。"}, {"pattern": "N (人) + who + V ...", "explain": "who 引導形容詞子句，用來說明前面的「人」是誰或是怎樣的人。", "example": "She gives free cookies to children who get good grades.", "exampleZh": "她送免費餅乾給成績好的孩子。"}], "reading": [{"q": "What is the article mainly about?", "options": ["A school near a shop.", "A kind grandma and her dessert shop.", "How to make moon cakes.", "A famous bakery in Taipei."], "answer": 1, "explain": "全文介紹林奶奶和她的甜點店，以及她對孩子的愛心，故選 (B)。"}, {"q": "When does Grandma Lin make moon cakes?", "options": ["In summer.", "On Sundays.", "In September.", "Every afternoon."], "answer": 2, "explain": "第二段提到 In September, she makes moon cakes for the Moon Festival，故選 (C)。"}, {"q": "Who gets free cookies?", "options": ["Students who get good grades.", "Children who help in the shop.", "All the students.", "Kids who buy ice cream."], "answer": 0, "explain": "第三段說 She gives free cookies to children who get good grades，故選 (A)。"}, {"q": "The phrase \"stand in line\" in paragraph 1 means...", "options": ["sit on the floor", "wait one behind another", "run around", "look through the window"], "answer": 1, "explain": "學生在門口「排隊」等著買餅乾，stand in line 即一個接一個排著等，故選 (B)。"}, {"q": "What can we learn about Grandma Lin?", "options": ["She is very rich.", "She does not like children.", "She bakes with love.", "She sells only cookies."], "answer": 2, "explain": "她說 Food made with love tastes better，又免費送餅乾、教孩子烘焙，可知她用愛做甜點，故選 (C)。"}], "vocabQ": [{"q": "After dinner, we had chocolate cake for ____.", "options": ["salad", "dessert", "soup", "breakfast"], "answer": 1, "explain": "晚餐後吃的蛋糕是 dessert 甜點，故選 (B)。"}, {"q": "The ____ is round and has a hole in the middle.", "options": ["pie", "cookie", "doughnut", "toast"], "answer": 2, "explain": "圓形、中間有洞的是 doughnut 甜甜圈，故選 (C)。"}, {"q": "On a hot day, nothing is better than a cup of cold ____.", "options": ["ice cream", "toast", "pie", "candy"], "answer": 0, "explain": "炎熱天氣吃「一杯冰涼的」是 ice cream 冰淇淋，故選 (A)。"}, {"q": "We share a ____ with the whole family when we look at the full moon.", "options": ["toast", "cookie", "moon cake", "candy"], "answer": 2, "explain": "賞月時全家分享的是 moon cake 月餅，故選 (C)。"}, {"q": "Mom put butter and honey on a piece of ____ for my breakfast.", "options": ["toast", "candy", "pie", "cookie"], "answer": 0, "explain": "早餐塗奶油和蜂蜜的「一片」是 toast 吐司，故選 (A)。"}]}, {"id": "E14", "level": "elem", "num": 14, "title": "How to Make a Yummy Egg Sandwich", "titleZh": "如何做出美味的蛋三明治", "theme": "Seasonings & Tastes", "themeZh": "調味料與味道", "article": ["Are you hungry after school? Here is an easy way to make a yummy egg sandwich. You only need bread, two eggs, and a few things from the kitchen. The whole thing takes about ten minutes.", "First, heat a little oil in a pan. Break the eggs into it and add a bit of salt and pepper. Do not use too much salt, or the eggs will taste too strong. Next, spread some butter on two pieces of bread. If you like a sweet taste, add a thin layer of jam. If you like a sour taste, put a few drops of vinegar in the eggs. Many kids also love ketchup, but my mom says a small amount is enough.", "Finally, put the eggs between the bread and cut it in half. Eat it while it is still hot. It is delicious with a glass of milk, and you will not feel thirsty. One sandwich usually makes me full, but my brother always eats two. Try it this weekend and share it with your family!"], "translation": ["放學後肚子餓了嗎？這裡有一個簡單的方法可以做出美味的蛋三明治。你只需要麵包、兩顆蛋，和廚房裡的幾樣東西。整個過程大約十分鐘。", "首先，在平底鍋裡熱一點油。把蛋打進去，加一點鹽和胡椒。不要放太多鹽，否則蛋的味道會太重。接著，在兩片麵包上塗一些奶油。如果你喜歡甜味，可以抹上薄薄一層果醬。如果你喜歡酸味，就在蛋裡滴幾滴醋。很多孩子也愛番茄醬，但我媽媽說少量就夠了。", "最後，把蛋夾進麵包中間，再切成兩半。趁熱吃。配上一杯牛奶非常美味，而且你不會覺得口渴。一個三明治通常就能讓我吃飽，但我弟弟總是吃兩個。這個週末試試看，和家人一起分享吧！"], "vocab": [{"word": "hungry", "pos": "adj.", "zh": "飢餓的", "example": "The kids are hungry after the game.", "exampleZh": "比賽後孩子們都餓了。"}, {"word": "salt", "pos": "n.", "zh": "鹽", "example": "This soup needs a little more salt.", "exampleZh": "這碗湯需要再多一點鹽。"}, {"word": "pepper", "pos": "n.", "zh": "胡椒", "example": "He likes black pepper on his steak.", "exampleZh": "他喜歡在牛排上撒黑胡椒。"}, {"word": "butter", "pos": "n.", "zh": "奶油", "example": "Put some butter on the hot bread.", "exampleZh": "在熱麵包上塗一些奶油。"}, {"word": "jam", "pos": "n.", "zh": "果醬", "example": "Strawberry jam is sweet and sticky.", "exampleZh": "草莓果醬又甜又黏。"}, {"word": "vinegar", "pos": "n.", "zh": "醋", "example": "Grandma adds vinegar to the dumpling sauce.", "exampleZh": "奶奶在水餃醬裡加醋。"}, {"word": "sour", "pos": "adj.", "zh": "酸的", "example": "This lemon is really sour.", "exampleZh": "這顆檸檬真的很酸。"}, {"word": "delicious", "pos": "adj.", "zh": "美味的", "example": "The beef noodles at this shop are delicious.", "exampleZh": "這家店的牛肉麵很美味。"}], "phrases": [{"phrase": "a bit of", "zh": "一點點", "example": "Add a bit of sugar to the tea.", "exampleZh": "在茶裡加一點糖。"}, {"phrase": "in half", "zh": "成兩半", "example": "Cut the apple in half and share it.", "exampleZh": "把蘋果切成兩半分著吃。"}, {"phrase": "spread ... on", "zh": "把…塗在…上", "example": "She spread jam on her toast.", "exampleZh": "她把果醬塗在吐司上。"}], "grammar": [{"pattern": "Do not + 原形動詞 ..., or + S + will + V", "explain": "「不要…，否則…」，祈使句後面接 or，表示不照做會發生的結果。", "example": "Do not use too much salt, or the eggs will taste too strong.", "exampleZh": "不要放太多鹽，否則蛋的味道會太重。"}, {"pattern": "If + S + V (現在式), + 祈使句", "explain": "if 引導條件句，表示「如果…，就…」；if 子句用現在式，主要子句可用祈使句。", "example": "If you like a sweet taste, add a thin layer of jam.", "exampleZh": "如果你喜歡甜味，就抹上薄薄一層果醬。"}], "reading": [{"q": "What is the article mainly about?", "options": ["How to make an egg sandwich.", "How to cook rice.", "Why eggs are healthy.", "Where to buy bread."], "answer": 0, "explain": "第一段說 Here is an easy way to make a yummy egg sandwich，全文說明做法，故選 (A)。"}, {"q": "What happens if you use too much salt?", "options": ["The eggs will burn.", "The eggs will taste too strong.", "The bread will get wet.", "The eggs will be sweet."], "answer": 1, "explain": "第二段提到 Do not use too much salt, or the eggs will taste too strong，故選 (B)。"}, {"q": "What should you add if you like a sour taste?", "options": ["Jam.", "Sugar.", "Vinegar.", "Butter."], "answer": 2, "explain": "第二段說 If you like a sour taste, put a few drops of vinegar in the eggs，故選 (C)。"}, {"q": "The word \"amount\" in paragraph 2 is closest in meaning to...", "options": ["taste", "color", "price", "how much of something"], "answer": 3, "explain": "a small amount 指「少量」，amount 是「數量」，故選 (D)。"}, {"q": "How many sandwiches does the writer's brother usually eat?", "options": ["One.", "Two.", "Three.", "Half."], "answer": 1, "explain": "第三段說 my brother always eats two，故選 (B)。"}], "vocabQ": [{"q": "I did not eat lunch, so I am very ____ now.", "options": ["full", "thirsty", "hungry", "sleepy"], "answer": 2, "explain": "沒吃午餐所以很「餓」，hungry 飢餓的，故選 (C)。"}, {"q": "This lemon juice is too ____; please add some sugar.", "options": ["sweet", "sour", "hot", "bitter"], "answer": 1, "explain": "檸檬汁太「酸」所以要加糖，sour 酸的，故選 (B)。"}, {"q": "Spread some ____ on the hot bread, and it will melt right away.", "options": ["salt", "pepper", "butter", "vinegar"], "answer": 2, "explain": "塗在熱麵包上會融化的是 butter 奶油，故選 (C)。"}, {"q": "Grandma's beef noodles are so ____ that I always ask for more.", "options": ["delicious", "hungry", "thirsty", "bitter"], "answer": 0, "explain": "因為很「美味」所以總是想再吃，delicious 美味的，故選 (A)。"}, {"q": "Add a little black ____ to the soup if you like a stronger taste.", "options": ["jam", "sugar", "pepper", "cream"], "answer": 2, "explain": "black pepper 黑胡椒可讓湯的味道更重，故選 (C)。"}]}, {"id": "E15", "level": "elem", "num": 15, "title": "Lily's Birthday Dinner", "titleZh": "Lily 的生日晚餐", "theme": "Cooking & Tableware", "themeZh": "烹飪與餐具", "article": ["Last Friday, Dad took Lily to a new restaurant for her birthday. Lily looked at the menu for a long time. 'Dad, there are so many dishes! What should I order?' she asked. 'Try the baked fish,' Dad said. 'They cook it very well here.'", "The waiter brought a glass of water and a cup of tea. Lily looked for chopsticks, but there were none on the table. 'Use the fork and knife, honey,' Dad laughed. 'This is not a noodle shop.' Lily put a napkin on her lap. Then she cut a slice of bread and spread butter on it. 'Don't eat too much bread, or you won't finish your fish,' Dad said.", "Soon the dishes came. Lily's fish was on a big white plate, and Dad's soup was in a deep bowl. 'The soup is hot, so be careful,' said Dad. 'Did they boil it for a long time?' Lily asked. 'Yes, and they did not burn it,' Dad said with a smile. They ate slowly and talked a lot. Lily said it was the best birthday dinner ever."], "translation": ["上星期五，爸爸帶 Lily 去一家新餐廳慶祝她的生日。Lily 看了菜單好久。「爸爸，菜好多喔！我該點什麼？」她問。「試試烤魚吧，」爸爸說。「這裡的烤魚做得很好。」", "服務生送來一杯水和一杯茶。Lily 找筷子，但桌上一雙也沒有。「用叉子和刀子吧，寶貝，」爸爸笑著說。「這裡可不是麵店。」Lily 把餐巾放在腿上。接著她切了一片麵包，塗上奶油。「別吃太多麵包，不然你會吃不完你的魚，」爸爸說。", "很快餐點就來了。Lily 的魚放在一個白色大盤子上，爸爸的湯則裝在一個深碗裡。「湯很燙，小心點，」爸爸說。「他們煮了很久嗎？」Lily 問。「對，而且沒有煮焦，」爸爸微笑著說。他們慢慢吃，聊了很多。Lily 說這是她有史以來最棒的生日晚餐。"], "vocab": [{"word": "menu", "pos": "n.", "zh": "菜單", "example": "May I see the menu, please?", "exampleZh": "請問可以給我看菜單嗎？"}, {"word": "order", "pos": "v.", "zh": "點（餐）", "example": "We ordered two bowls of beef noodles.", "exampleZh": "我們點了兩碗牛肉麵。"}, {"word": "dish", "pos": "n.", "zh": "菜餚；一道菜", "example": "My favorite dish is fried rice.", "exampleZh": "我最喜歡的一道菜是炒飯。"}, {"word": "chopsticks", "pos": "n.", "zh": "筷子", "example": "Most people in Taiwan eat with chopsticks.", "exampleZh": "台灣大多數人用筷子吃飯。"}, {"word": "napkin", "pos": "n.", "zh": "餐巾", "example": "Please put the napkin on your lap.", "exampleZh": "請把餐巾放在腿上。"}, {"word": "slice", "pos": "n.", "zh": "一片；薄片", "example": "I ate a slice of pizza for lunch.", "exampleZh": "我午餐吃了一片披薩。"}, {"word": "plate", "pos": "n.", "zh": "盤子", "example": "Put the cookies on a clean plate.", "exampleZh": "把餅乾放在乾淨的盤子上。"}, {"word": "boil", "pos": "v.", "zh": "煮沸；水煮", "example": "Boil the eggs for ten minutes.", "exampleZh": "把蛋煮十分鐘。"}], "phrases": [{"phrase": "look for", "zh": "尋找", "example": "I am looking for my spoon.", "exampleZh": "我在找我的湯匙。"}, {"phrase": "be careful", "zh": "小心", "example": "Be careful! The plate is very hot.", "exampleZh": "小心！盤子很燙。"}, {"phrase": "a slice of", "zh": "一片…", "example": "Would you like a slice of cake?", "exampleZh": "你想來一片蛋糕嗎？"}], "grammar": [{"pattern": "What + should + S + 原形動詞?", "explain": "should 表示「應該」，用來徵求建議；疑問句把 should 放在主詞前面。", "example": "What should I order?", "exampleZh": "我該點什麼？"}, {"pattern": "S + V ..., so + S + V", "explain": "so 是連接詞，表示「所以、因此」，前面是原因，後面是結果。", "example": "The soup is hot, so be careful.", "exampleZh": "湯很燙，所以要小心。"}], "reading": [{"q": "Why did Dad take Lily to the restaurant?", "options": ["For her birthday.", "For Dad's birthday.", "Because Mom was busy.", "To meet a friend."], "answer": 0, "explain": "第一段說 Dad took Lily to a new restaurant for her birthday，故選 (A)。"}, {"q": "What did Dad tell Lily to order?", "options": ["Soup.", "Baked fish.", "Noodles.", "Steak."], "answer": 1, "explain": "第一段中爸爸說 Try the baked fish，故選 (B)。"}, {"q": "What did Dad tell Lily to use for her meal?", "options": ["A spoon.", "Chopsticks.", "A fork and knife.", "Her hands."], "answer": 2, "explain": "第二段中爸爸說 Use the fork and knife, honey，故選 (C)。"}, {"q": "Why did Dad tell Lily not to eat too much bread?", "options": ["The bread was cold.", "The bread was expensive.", "She would not finish her fish.", "He wanted the bread himself."], "answer": 2, "explain": "第二段最後說 Don't eat too much bread, or you won't finish your fish，故選 (C)。"}, {"q": "The word \"deep\" in paragraph 3 is closest in meaning to...", "options": ["going far down from the top", "very hot", "very big", "very old"], "answer": 0, "explain": "a deep bowl 指「深碗」，deep 是「深的」，故選 (A)。"}], "vocabQ": [{"q": "The waiter gave us the ____, and we chose our food from it.", "options": ["plate", "menu", "napkin", "bowl"], "answer": 1, "explain": "從上面選餐點的是 menu 菜單，故選 (B)。"}, {"q": "Please ____ the water for five minutes before you make tea.", "options": ["bake", "burn", "boil", "cut"], "answer": 2, "explain": "泡茶前要把水「煮沸」，boil 煮沸，故選 (C)。"}, {"q": "In Taiwan, most people eat rice with ____, not with a fork.", "options": ["spoons", "chopsticks", "knives", "straws"], "answer": 1, "explain": "台灣人吃飯用的是 chopsticks 筷子，故選 (B)。"}, {"q": "Could I have another ____ of pizza? I am still hungry.", "options": ["slice", "cup", "bowl", "glass"], "answer": 0, "explain": "a slice of pizza 一片披薩，故選 (A)。"}, {"q": "Wipe your mouth with a ____ after you eat the burger.", "options": ["plate", "menu", "dish", "napkin"], "answer": 3, "explain": "用來擦嘴的是 napkin 餐巾，故選 (D)。"}]}, {"id": "E16", "level": "elem", "num": 16, "title": "Shopping for Winter Clothes", "titleZh": "採買冬衣", "theme": "Clothing", "themeZh": "服裝", "article": ["Sunday, December 3. Dear Diary, today Mom and I went shopping for winter clothes. My old sweater is too small now, and my jacket has a hole in it. The weather report says a cold front is coming on Tuesday, so we had to hurry.", "The shop was crowded. First, I tried on a thick blue coat. It looked warm, but it was too long for me. Then Mom found a gray sweater and a pair of jeans. I liked them a lot. My sister bought a pink dress and a white blouse for her piano show. Dad does not care about clothes. He just wants a new pair of pajamas and some black pants for work.", "On the way home, I saw a raincoat with cats on it. It was so cute! Mom said no because I already have one. At school, we wear a uniform every day, so new clothes are only for weekends. Still, I cannot wait to wear my new sweater. I hope Tuesday comes soon!"], "translation": ["十二月三日，星期日。親愛的日記：今天媽媽和我去買冬天的衣服。我的舊毛衣現在太小了，而我的夾克破了一個洞。氣象報告說星期二有冷鋒要來，所以我們得趕快。", "店裡很擁擠。首先，我試穿了一件厚厚的藍色大衣。它看起來很暖，但對我來說太長了。接著媽媽找到一件灰色毛衣和一條牛仔褲。我很喜歡。姊姊為了她的鋼琴表演買了一件粉紅色洋裝和一件白色女用襯衫。爸爸不在乎衣服。他只想要一套新睡衣和幾條上班穿的黑色長褲。", "回家的路上，我看到一件有貓咪圖案的雨衣。好可愛！媽媽說不行，因為我已經有一件了。在學校我們每天都穿制服，所以新衣服只有週末才能穿。不過，我還是等不及要穿我的新毛衣。希望星期二快點來！"], "vocab": [{"word": "sweater", "pos": "n.", "zh": "毛衣", "example": "Grandma knitted a red sweater for me.", "exampleZh": "奶奶為我織了一件紅色毛衣。"}, {"word": "jacket", "pos": "n.", "zh": "夾克；外套", "example": "Take your jacket. It is windy outside.", "exampleZh": "帶著你的夾克，外面風很大。"}, {"word": "coat", "pos": "n.", "zh": "大衣", "example": "She wore a long black coat in the snow.", "exampleZh": "她在雪中穿著一件黑色長大衣。"}, {"word": "jeans", "pos": "n.", "zh": "牛仔褲", "example": "These jeans are too tight for me.", "exampleZh": "這條牛仔褲對我來說太緊了。"}, {"word": "blouse", "pos": "n.", "zh": "女用襯衫", "example": "Mom wears a white blouse to work.", "exampleZh": "媽媽穿白色襯衫去上班。"}, {"word": "pajamas", "pos": "n.", "zh": "睡衣", "example": "The baby's pajamas have little stars on them.", "exampleZh": "寶寶的睡衣上有小星星。"}, {"word": "raincoat", "pos": "n.", "zh": "雨衣", "example": "Put on your raincoat before you ride your bike.", "exampleZh": "騎腳踏車前先穿上雨衣。"}, {"word": "uniform", "pos": "n.", "zh": "制服", "example": "Our school uniform is blue and white.", "exampleZh": "我們的校服是藍白色的。"}], "phrases": [{"phrase": "try on", "zh": "試穿", "example": "Can I try on these shoes?", "exampleZh": "我可以試穿這雙鞋嗎？"}, {"phrase": "a pair of", "zh": "一條／一雙／一副…", "example": "He bought a pair of shorts for summer.", "exampleZh": "他買了一條短褲過夏天。"}, {"phrase": "cannot wait to V", "zh": "等不及要…", "example": "I cannot wait to see the movie.", "exampleZh": "我等不及要看這部電影了。"}], "grammar": [{"pattern": "S + be + too + adj. + for + sb.", "explain": "「對某人來說太…」，too 放在形容詞前表示程度過高。", "example": "It was too long for me.", "exampleZh": "它對我來說太長了。"}, {"pattern": "S + had to + 原形動詞", "explain": "have to 表示「必須」，過去式用 had to，後面接原形動詞。", "example": "We had to hurry.", "exampleZh": "我們必須趕快。"}], "reading": [{"q": "Why did the writer and Mom go shopping today?", "options": ["Cold weather is coming.", "It was the writer's birthday.", "The sister had a piano show.", "The shop had a big sale."], "answer": 0, "explain": "第一段說 a cold front is coming on Tuesday, so we had to hurry，故選 (A)。"}, {"q": "Why didn't the writer buy the blue coat?", "options": ["It was too expensive.", "It was too long.", "It was too thin.", "Mom did not like it."], "answer": 1, "explain": "第二段提到 It looked warm, but it was too long for me，故選 (B)。"}, {"q": "What does Dad want?", "options": ["Pajamas and black pants.", "A gray sweater.", "A pink dress.", "A raincoat."], "answer": 0, "explain": "第二段最後說 He just wants a new pair of pajamas and some black pants for work，故選 (A)。"}, {"q": "Why did Mom say no to the raincoat?", "options": ["It was ugly.", "It was too small.", "The writer already has one.", "It was for boys."], "answer": 2, "explain": "第三段說 Mom said no because I already have one，故選 (C)。"}, {"q": "The phrase \"cannot wait to\" in paragraph 3 shows the writer feels...", "options": ["angry", "tired", "excited", "sad"], "answer": 2, "explain": "cannot wait to 表示「等不及」，可見作者很期待、興奮，故選 (C)。"}], "vocabQ": [{"q": "It is cold outside, so put on your warm ____ before you go out.", "options": ["shorts", "sweater", "swimsuit", "skirt"], "answer": 1, "explain": "天冷時穿的保暖衣物是 sweater 毛衣，故選 (B)。"}, {"q": "Every student at our school must wear a ____ on weekdays.", "options": ["uniform", "pajamas", "blouse", "suit"], "answer": 0, "explain": "學生平日必須穿的是 uniform 制服，故選 (A)。"}, {"q": "Take your ____ with you; it will rain this afternoon.", "options": ["jeans", "coat", "raincoat", "sweater"], "answer": 2, "explain": "下午會下雨，要帶的是 raincoat 雨衣，故選 (C)。"}, {"q": "I always change into my ____ before I go to bed.", "options": ["jacket", "uniform", "jeans", "pajamas"], "answer": 3, "explain": "睡前換上的是 pajamas 睡衣，故選 (D)。"}, {"q": "These blue ____ are made of thick cotton, and they are great for hiking.", "options": ["jeans", "coat", "blouse", "dress"], "answer": 0, "explain": "藍色、厚棉布做的且為複數的是 jeans 牛仔褲，故選 (A)。"}]}, {"id": "E17", "level": "elem", "num": 17, "title": "Lost and Found: Is This Yours?", "titleZh": "失物招領：這是你的嗎？", "theme": "Accessories & Materials", "themeZh": "配件與材質", "article": ["Attention, all students! The Lost and Found box in the office is full again. After the sports day last Friday, we found many things on the playground. Please come and check before this Friday. After that, we will give the items to a charity.", "Here is the list. There are three caps, two umbrellas, and one pair of red sneakers. We also have a silver ring, a gold necklace with a small heart, and a pair of earrings. One student left a black wallet with 200 dollars inside! There is also a blue scarf, a cotton T-shirt, and a purse with a broken button. Someone even lost one glove. Where is the other one?", "To get your things back, tell Ms. Chen what they look like. For example, say 'My cap is white with a spot on the side.' Please also write your name on your clothes and bags. Then we can find you quickly. Remember: check your pockets before you leave the playground!"], "translation": ["全體同學請注意！辦公室的失物招領箱又滿了。上星期五運動會之後，我們在操場上撿到很多東西。請在這個星期五之前來查看。之後，我們會把這些物品捐給慈善機構。", "這是清單。有三頂帽子、兩把雨傘和一雙紅色運動鞋。我們還有一枚銀戒指、一條有小愛心的金項鍊，以及一副耳環。有一位同學掉了一個裡面有兩百元的黑色皮夾！還有一條藍色圍巾、一件棉質 T 恤，和一個鈕扣壞掉的小錢包。甚至有人掉了一隻手套。另一隻在哪裡呢？", "要領回你的東西，請告訴陳老師它們長什麼樣子。例如，可以說「我的帽子是白色的，側邊有一個斑點」。也請在你的衣服和包包上寫上名字。這樣我們就能很快找到你。記住：離開操場前先檢查你的口袋！"], "vocab": [{"word": "cap", "pos": "n.", "zh": "（有帽舌的）帽子", "example": "He wears a baseball cap every day.", "exampleZh": "他每天都戴棒球帽。"}, {"word": "umbrella", "pos": "n.", "zh": "雨傘", "example": "I left my umbrella on the MRT.", "exampleZh": "我把雨傘忘在捷運上了。"}, {"word": "sneakers", "pos": "n.", "zh": "運動鞋", "example": "These sneakers are great for running.", "exampleZh": "這雙運動鞋很適合跑步。"}, {"word": "necklace", "pos": "n.", "zh": "項鍊", "example": "Mom got a pearl necklace for her birthday.", "exampleZh": "媽媽生日收到一條珍珠項鍊。"}, {"word": "wallet", "pos": "n.", "zh": "皮夾", "example": "Dad keeps his cards in a brown wallet.", "exampleZh": "爸爸把卡片放在棕色皮夾裡。"}, {"word": "scarf", "pos": "n.", "zh": "圍巾", "example": "She wears a warm scarf in winter.", "exampleZh": "她冬天會圍一條溫暖的圍巾。"}, {"word": "glove", "pos": "n.", "zh": "手套", "example": "The baseball player caught the ball with his glove.", "exampleZh": "棒球選手用手套接住球。"}, {"word": "pocket", "pos": "n.", "zh": "口袋", "example": "There is a coin in my pocket.", "exampleZh": "我的口袋裡有一枚硬幣。"}], "phrases": [{"phrase": "get ... back", "zh": "拿回…", "example": "I want to get my book back.", "exampleZh": "我想拿回我的書。"}, {"phrase": "look like", "zh": "看起來像；長得…", "example": "What does your bag look like?", "exampleZh": "你的包包長什麼樣子？"}, {"phrase": "for example", "zh": "例如", "example": "I like fruit, for example, mangoes and bananas.", "exampleZh": "我喜歡水果，例如芒果和香蕉。"}], "grammar": [{"pattern": "To + 原形動詞 ..., + S + V", "explain": "不定詞放句首表示「為了…」，說明做後面動作的目的。", "example": "To get your things back, tell Ms. Chen what they look like.", "exampleZh": "要領回你的東西，請告訴陳老師它們長什麼樣子。"}, {"pattern": "Please + 原形動詞 ...", "explain": "祈使句用原形動詞開頭，加上 please 可以讓請求更有禮貌。", "example": "Please come and check before this Friday.", "exampleZh": "請在這個星期五之前來查看。"}], "reading": [{"q": "What is the purpose of this notice?", "options": ["To sell old things.", "To ask students to check for lost items.", "To tell students about sports day.", "To collect money for a charity."], "answer": 1, "explain": "第一段請同學 come and check 失物招領箱，故選 (B)。"}, {"q": "What will happen to the items after Friday?", "options": ["They will be thrown away.", "They will be sold.", "They will be kept in the office.", "They will be given to a charity."], "answer": 3, "explain": "第一段最後說 After that, we will give the items to a charity，故選 (D)。"}, {"q": "Which item has money inside?", "options": ["A purse.", "A wallet.", "A bag.", "A pocket."], "answer": 1, "explain": "第二段提到 a black wallet with 200 dollars inside，故選 (B)。"}, {"q": "How can a student get an item back?", "options": ["Pay 200 dollars.", "Write a letter.", "Tell Ms. Chen what it looks like.", "Go to the playground."], "answer": 2, "explain": "第三段說 To get your things back, tell Ms. Chen what they look like，故選 (C)。"}, {"q": "What does the office ask students to do with their clothes and bags?", "options": ["Wash them.", "Write their names on them.", "Give them to a charity.", "Keep them at home."], "answer": 1, "explain": "第三段提到 Please also write your name on your clothes and bags，故選 (B)。"}], "vocabQ": [{"q": "It is raining hard. Did you bring your ____?", "options": ["umbrella", "cap", "scarf", "glove"], "answer": 0, "explain": "下大雨時要帶的是 umbrella 雨傘，故選 (A)。"}, {"q": "Grandpa keeps his money and ID card in his old brown ____.", "options": ["pocket", "wallet", "necklace", "hole"], "answer": 1, "explain": "放錢和證件的是 wallet 皮夾，故選 (B)。"}, {"q": "Wrap a warm ____ around your neck; it is windy today.", "options": ["belt", "cap", "scarf", "tie"], "answer": 2, "explain": "圍在脖子上保暖的是 scarf 圍巾，故選 (C)。"}, {"q": "These ____ have thick bottoms, so they are perfect for running.", "options": ["socks", "gloves", "sneakers", "slippers"], "answer": 2, "explain": "底部厚、適合跑步的是 sneakers 運動鞋，故選 (C)。"}, {"q": "He put the key in his ____ and walked out of the house.", "options": ["pocket", "hole", "spot", "button"], "answer": 0, "explain": "把鑰匙放進「口袋」，pocket 口袋，故選 (A)。"}]}, {"id": "E18", "level": "elem", "num": 18, "title": "The Wall of Colors", "titleZh": "彩色的牆", "theme": "Colors", "themeZh": "顏色", "article": ["Nina's school had an old gray wall by the gate. Nobody liked it. One day, the art teacher, Mr. Wu, asked the class, 'What color should this wall be?' Everyone shouted a different answer. Some said blue like the sea. Some said green like the mountains. Nina said nothing. She was thinking.", "That night, Nina drew a plan at home. She wanted a big sun in golden yellow, an orange sky, and purple hills. On the hills, there would be a brown cat and a little white dog. 'Taiwan is full of colors,' she wrote at the bottom. 'Our wall should be, too.'", "The next week, the whole class painted the wall together. It took three days. Their hands and shoes turned pink, red, and black. When they finished, the old wall looked like a happy picture book. Now visitors stop and take photos. Nina still smiles every time she walks past it."], "translation": ["Nina 的學校大門旁有一面老舊的灰色牆。沒有人喜歡它。有一天，美術老師吳老師問全班：「這面牆應該是什麼顏色？」每個人都喊出不同的答案。有人說藍色，像大海。有人說綠色，像山。Nina 什麼也沒說。她在思考。", "那天晚上，Nina 在家畫了一張設計圖。她想要一個金黃色的大太陽、橘色的天空和紫色的山丘。山丘上會有一隻棕色的貓和一隻小白狗。「台灣充滿了色彩，」她在底下寫著。「我們的牆也應該如此。」", "隔週，全班一起粉刷那面牆。花了三天。他們的手和鞋子都變成粉紅色、紅色和黑色。完成之後，那面老牆看起來就像一本快樂的圖畫書。現在訪客都會停下來拍照。Nina 每次經過時仍然會微笑。"], "vocab": [{"word": "color", "pos": "n.", "zh": "顏色", "example": "What color is your new bag?", "exampleZh": "你的新包包是什麼顏色？"}, {"word": "gray", "pos": "adj.", "zh": "灰色的", "example": "The sky is gray before a storm.", "exampleZh": "暴風雨前天空是灰色的。"}, {"word": "golden", "pos": "adj.", "zh": "金色的", "example": "The rice fields turn golden in autumn.", "exampleZh": "稻田在秋天變成金黃色。"}, {"word": "orange", "pos": "adj.", "zh": "橘色的", "example": "She wore an orange T-shirt to the game.", "exampleZh": "她穿了一件橘色 T 恤去看比賽。"}, {"word": "purple", "pos": "adj.", "zh": "紫色的", "example": "Grapes are often purple.", "exampleZh": "葡萄常常是紫色的。"}, {"word": "brown", "pos": "adj.", "zh": "棕色的", "example": "My dog has brown eyes.", "exampleZh": "我的狗有一雙棕色的眼睛。"}, {"word": "pink", "pos": "adj.", "zh": "粉紅色的", "example": "The cherry blossoms are pink in spring.", "exampleZh": "春天的櫻花是粉紅色的。"}, {"word": "yellow", "pos": "adj.", "zh": "黃色的", "example": "The school bus is yellow.", "exampleZh": "校車是黃色的。"}], "phrases": [{"phrase": "be full of", "zh": "充滿…", "example": "The night market is full of people.", "exampleZh": "夜市裡擠滿了人。"}, {"phrase": "take photos", "zh": "拍照", "example": "We took photos in front of Taipei 101.", "exampleZh": "我們在台北 101 前面拍照。"}, {"phrase": "walk past", "zh": "走過；經過", "example": "I walk past the park every morning.", "exampleZh": "我每天早上都走過那座公園。"}], "grammar": [{"pattern": "S + look like + N", "explain": "look like 表示「看起來像…」，後面接名詞；look 後面接形容詞時則不用 like。", "example": "The old wall looked like a happy picture book.", "exampleZh": "那面老牆看起來像一本快樂的圖畫書。"}, {"pattern": "It + take(s)/took + 時間", "explain": "用虛主詞 it 表示「花了多少時間」，過去式用 took。", "example": "It took three days.", "exampleZh": "花了三天。"}], "reading": [{"q": "What was the problem with the wall at first?", "options": ["It was too short.", "It was old and gray.", "It was broken.", "It was too far from the gate."], "answer": 1, "explain": "第一段說 Nina's school had an old gray wall by the gate. Nobody liked it，故選 (B)。"}, {"q": "What did Nina do that night?", "options": ["She drew a plan.", "She painted the wall.", "She called Mr. Wu.", "She went to the mountains."], "answer": 0, "explain": "第二段開頭說 That night, Nina drew a plan at home，故選 (A)。"}, {"q": "How long did it take to paint the wall?", "options": ["One day.", "Three days.", "One week.", "Three weeks."], "answer": 1, "explain": "第三段提到 It took three days，故選 (B)。"}, {"q": "What color was the sun in Nina's plan?", "options": ["Orange.", "Purple.", "Golden yellow.", "White."], "answer": 2, "explain": "第二段說 She wanted a big sun in golden yellow，故選 (C)。"}, {"q": "The sentence \"Taiwan is full of colors\" in paragraph 2 means...", "options": ["Taiwan has many colorful things.", "Taiwan sells many paints.", "Taiwan has a big sun.", "Taiwan has many walls."], "answer": 0, "explain": "be full of 是「充滿」，Nina 認為台灣到處都有豐富的色彩，故選 (A)。"}], "vocabQ": [{"q": "The sky turns ____ and red when the sun goes down.", "options": ["orange", "gray", "green", "white"], "answer": 0, "explain": "夕陽時天空會變成橘紅色，orange 橘色的，故選 (A)。"}, {"q": "Grapes can be green, red, or ____.", "options": ["brown", "purple", "yellow", "gray"], "answer": 1, "explain": "葡萄常見的顏色是綠、紅或紫，purple 紫色的，故選 (B)。"}, {"q": "The old man's hair is ____ now, not black anymore.", "options": ["pink", "brown", "gray", "golden"], "answer": 2, "explain": "老人的頭髮變灰白，gray 灰色的，故選 (C)。"}, {"q": "What ____ is your new bike? It looks great!", "options": ["color", "size", "shape", "price"], "answer": 0, "explain": "問「什麼顏色」用 What color，故選 (A)。"}, {"q": "Bananas turn from green to ____ when they are ready to eat.", "options": ["purple", "pink", "brown", "yellow"], "answer": 3, "explain": "香蕉成熟後會由綠轉黃，yellow 黃色的，故選 (D)。"}]}, {"id": "E19", "level": "elem", "num": 19, "title": "Green Hill Wins the City Final", "titleZh": "綠丘國中贏得市賽冠軍", "theme": "Sports", "themeZh": "運動", "article": ["Taipei, May 12 - Green Hill Junior High School won the city basketball final yesterday. The team beat Riverside Junior High 58 to 55 in the last ten seconds. Hundreds of students watched the game in the school gym. 'We never gave up,' said the team captain, Jason Lin.", "Basketball is not the only sport at Green Hill. The school also has strong teams in baseball, volleyball, and table tennis. Last month, the girls' badminton team won second place in the north area. The soccer team practices every morning before class. On Sports Day, every class joins a race and a dodge ball game.", "Coach Huang said the key is simple: practice every day and play as a team. 'Sports teach kids how to lose and how to win,' he said. Next week, the basketball team will go to Kaohsiung for the national game. The whole school will cheer for them."], "translation": ["台北，五月十二日──綠丘國中昨天贏得了市籃球決賽。球隊在最後十秒以 58 比 55 擊敗河濱國中。數百名學生在學校體育館觀看比賽。「我們從不放棄，」隊長林傑森說。", "籃球不是綠丘唯一的運動。學校在棒球、排球和桌球方面也有堅強的隊伍。上個月，女子羽球隊在北區贏得第二名。足球隊每天早上上課前練習。運動會那天，每個班級都會參加賽跑和躲避球比賽。", "黃教練說關鍵很簡單：每天練習，並且像一個團隊一樣打球。「運動教孩子如何輸，也教他們如何贏，」他說。下星期，籃球隊將前往高雄參加全國比賽。全校都會為他們加油。"], "vocab": [{"word": "sports", "pos": "n.", "zh": "運動", "example": "Sports are good for your body and mind.", "exampleZh": "運動對身心都有好處。"}, {"word": "basketball", "pos": "n.", "zh": "籃球", "example": "We play basketball after school.", "exampleZh": "我們放學後打籃球。"}, {"word": "baseball", "pos": "n.", "zh": "棒球", "example": "Baseball is very popular in Taiwan.", "exampleZh": "棒球在台灣非常受歡迎。"}, {"word": "volleyball", "pos": "n.", "zh": "排球", "example": "The girls play volleyball on the beach.", "exampleZh": "女孩們在沙灘上打排球。"}, {"word": "table tennis", "pos": "n.", "zh": "桌球", "example": "My uncle is good at table tennis.", "exampleZh": "我叔叔很會打桌球。"}, {"word": "badminton", "pos": "n.", "zh": "羽球", "example": "We played badminton in the park yesterday.", "exampleZh": "我們昨天在公園打羽球。"}, {"word": "soccer", "pos": "n.", "zh": "足球", "example": "He kicked the soccer ball into the goal.", "exampleZh": "他把足球踢進球門。"}, {"word": "race", "pos": "n.", "zh": "賽跑；比賽", "example": "Amy won the 100-meter race.", "exampleZh": "Amy 贏得了一百公尺賽跑。"}], "phrases": [{"phrase": "give up", "zh": "放棄", "example": "Never give up on your dream.", "exampleZh": "永遠不要放棄你的夢想。"}, {"phrase": "win second place", "zh": "贏得第二名", "example": "Our class won second place in the singing contest.", "exampleZh": "我們班在歌唱比賽贏得第二名。"}, {"phrase": "cheer for", "zh": "為…加油", "example": "We cheered for our team all night.", "exampleZh": "我們整晚為我們的隊伍加油。"}], "grammar": [{"pattern": "S + will + 原形動詞", "explain": "will 表示未來「將會…」，後面接原形動詞，常和 next week、tomorrow 等時間連用。", "example": "The basketball team will go to Kaohsiung next week.", "exampleZh": "籃球隊下星期將前往高雄。"}, {"pattern": "S + be + not the only + N", "explain": "「不是唯一的…」，the only 後面接單數名詞，表示還有其他的。", "example": "Basketball is not the only sport at Green Hill.", "exampleZh": "籃球不是綠丘唯一的運動。"}], "reading": [{"q": "What is the news report mainly about?", "options": ["A school's sports and its basketball win.", "A new school gym.", "A trip to Kaohsiung.", "A famous coach."], "answer": 0, "explain": "報導先說綠丘國中贏得籃球決賽，再介紹學校其他運動，故選 (A)。"}, {"q": "What was the final score of the basketball game?", "options": ["56 to 55.", "58 to 55.", "58 to 50.", "50 to 55."], "answer": 1, "explain": "第一段說 The team beat Riverside Junior High 58 to 55，故選 (B)。"}, {"q": "Which team won second place in the north area?", "options": ["The baseball team.", "The soccer team.", "The girls' badminton team.", "The volleyball team."], "answer": 2, "explain": "第二段提到 the girls' badminton team won second place in the north area，故選 (C)。"}, {"q": "According to Coach Huang, what is the key to winning?", "options": ["Having a big gym.", "Having a good captain.", "Cheering loudly.", "Practicing every day and playing as a team."], "answer": 3, "explain": "第三段說 the key is simple: practice every day and play as a team，故選 (D)。"}, {"q": "The phrase \"gave up\" in paragraph 1 is closest in meaning to...", "options": ["stopped trying", "ran fast", "scored a point", "went home"], "answer": 0, "explain": "give up 是「放棄」，也就是停止努力，故選 (A)。"}], "vocabQ": [{"q": "In ____, players hit a light shuttle over a high net with a racket.", "options": ["tennis", "golf", "badminton", "volleyball"], "answer": 2, "explain": "用球拍打羽毛球過高網的運動是 badminton 羽球，故選 (C)。"}, {"q": "Taiwan's ____ teams are famous, and many players hit home runs in Japan and the US.", "options": ["basketball", "soccer", "baseball", "football"], "answer": 2, "explain": "home run 全壘打是 baseball 棒球用語，故選 (C)。"}, {"q": "Kevin loves ____, so he often shoots a round ball at the basket.", "options": ["volleyball", "basketball", "softball", "badminton"], "answer": 1, "explain": "把球投進籃框的是 basketball 籃球，故選 (B)。"}, {"q": "Mia won first place in the 100-meter ____ on Sports Day.", "options": ["race", "game", "team", "ball"], "answer": 0, "explain": "100-meter race 一百公尺賽跑，故選 (A)。"}, {"q": "My favorite ____ are swimming and tennis because they keep me healthy.", "options": ["songs", "classes", "sports", "races"], "answer": 2, "explain": "游泳和網球都是 sports 運動，故選 (C)。"}]}, {"id": "E20", "level": "elem", "num": 20, "title": "Our Class Hobby Survey", "titleZh": "我們班的嗜好調查", "theme": "Leisure & Hobbies", "themeZh": "休閒與嗜好", "article": ["Last week, our class did a survey about hobbies. We asked all thirty students the same question: 'What do you do in your free time?' The answers were fun, and some were surprising. Here is what we found.", "Music was the most popular hobby. Eight students play an instrument. Four play the piano, two play the guitar, and one girl plays the violin. Sam plays the drums in a band with his cousins. Sports came next. Six students swim or jog on weekends, and three go hiking with their parents. Two boys said their hobby is computer games, but they lose a lot and do not want to be losers, so they practice every night!", "Some hobbies were special. Emily collects stamps from different countries. Jack can sail a small boat at the beach near his grandpa's house. Amy loves to draw cartoons, and her comics are famous in our class. I like reading novels and doing puzzles. What is your hobby? Everyone needs one. It makes life more colorful."], "translation": ["上星期，我們班做了一份關於嗜好的調查。我們問全班三十位同學同一個問題：「你空閒時都做什麼？」答案很有趣，有些還很令人驚訝。以下是我們的發現。", "音樂是最受歡迎的嗜好。八位同學會演奏樂器。四位彈鋼琴、兩位彈吉他，還有一位女生拉小提琴。Sam 和他的表兄弟組了一個樂團，他負責打鼓。運動排第二。六位同學週末游泳或慢跑，三位和父母去健行。兩個男生說他們的嗜好是電腦遊戲，但他們常常輸，又不想當輸家，所以每天晚上都在練習！", "有些嗜好很特別。Emily 收集來自不同國家的郵票。Jack 會在他爺爺家附近的海邊駕駛小帆船。Amy 喜歡畫卡通，她的漫畫在我們班很有名。我喜歡讀小說和玩拼圖。你的嗜好是什麼？每個人都需要一個嗜好。它讓生活更多采多姿。"], "vocab": [{"word": "hobby", "pos": "n.", "zh": "嗜好", "example": "My hobby is taking photos.", "exampleZh": "我的嗜好是拍照。"}, {"word": "instrument", "pos": "n.", "zh": "樂器", "example": "The piano is a popular instrument.", "exampleZh": "鋼琴是很受歡迎的樂器。"}, {"word": "violin", "pos": "n.", "zh": "小提琴", "example": "She practices the violin for an hour every day.", "exampleZh": "她每天練習小提琴一小時。"}, {"word": "band", "pos": "n.", "zh": "樂團", "example": "My brother plays in a rock band.", "exampleZh": "我哥哥在一個搖滾樂團裡演奏。"}, {"word": "jog", "pos": "v.", "zh": "慢跑", "example": "Dad jogs in the park every morning.", "exampleZh": "爸爸每天早上在公園慢跑。"}, {"word": "stamp", "pos": "n.", "zh": "郵票", "example": "Grandpa has a book of old stamps.", "exampleZh": "爺爺有一本舊郵票集。"}, {"word": "cartoon", "pos": "n.", "zh": "卡通", "example": "Kids love watching cartoons on Sunday morning.", "exampleZh": "孩子們喜歡在星期天早上看卡通。"}, {"word": "puzzle", "pos": "n.", "zh": "拼圖；謎題", "example": "This puzzle has 500 pieces.", "exampleZh": "這個拼圖有五百片。"}], "phrases": [{"phrase": "do a survey", "zh": "做調查", "example": "The teacher did a survey about our lunch.", "exampleZh": "老師做了一份關於我們午餐的調查。"}, {"phrase": "in one's free time", "zh": "在某人的空閒時間", "example": "I read comics in my free time.", "exampleZh": "我空閒時看漫畫。"}, {"phrase": "come next", "zh": "排在第二；接著是", "example": "Pizza was the favorite food, and fried chicken came next.", "exampleZh": "披薩是最受歡迎的食物，炸雞排第二。"}], "grammar": [{"pattern": "S + be + the most + adj. + N", "explain": "最高級：多音節形容詞前加 the most，表示「最…的」。", "example": "Music was the most popular hobby.", "exampleZh": "音樂是最受歡迎的嗜好。"}, {"pattern": "S + make(s) + O + adj.", "explain": "make 後面接受詞再接形容詞，表示「使…變得…」。", "example": "It makes life more colorful.", "exampleZh": "它讓生活更多采多姿。"}], "reading": [{"q": "What was the survey about?", "options": ["Favorite foods.", "Hobbies.", "Sports teams.", "Music classes."], "answer": 1, "explain": "第一段說 our class did a survey about hobbies，故選 (B)。"}, {"q": "Which hobby was the most popular?", "options": ["Music.", "Sports.", "Computer games.", "Reading."], "answer": 0, "explain": "第二段開頭說 Music was the most popular hobby，故選 (A)。"}, {"q": "How many students play an instrument?", "options": ["Four.", "Six.", "Eight.", "Thirty."], "answer": 2, "explain": "第二段提到 Eight students play an instrument，故選 (C)。"}, {"q": "What does Emily collect?", "options": ["Comics.", "Stamps.", "Dolls.", "Novels."], "answer": 1, "explain": "第三段說 Emily collects stamps from different countries，故選 (B)。"}, {"q": "What does the writer think about hobbies?", "options": ["They waste time.", "Everyone needs one.", "Only music is a real hobby.", "Boys should not play games."], "answer": 1, "explain": "最後說 Everyone needs one. It makes life more colorful，故選 (B)。"}], "vocabQ": [{"q": "My ____ is taking photos of birds in the park.", "options": ["team", "hobby", "toy", "game"], "answer": 1, "explain": "「拍鳥的照片」是一種嗜好，hobby 嗜好，故選 (B)。"}, {"q": "The ____ has a thousand small pieces, and it took me a week to finish.", "options": ["puzzle", "novel", "card", "song"], "answer": 0, "explain": "有一千片、要拼完成的是 puzzle 拼圖，故選 (A)。"}, {"q": "Grandpa likes to ____ around the park every morning to stay healthy.", "options": ["sail", "paint", "jog", "ski"], "answer": 2, "explain": "在公園裡「慢跑」保持健康，jog 慢跑，故選 (C)。"}, {"q": "Lily plays the ____ with a bow, and its sound is soft and beautiful.", "options": ["drum", "guitar", "trumpet", "violin"], "answer": 3, "explain": "用弓（bow）演奏的是 violin 小提琴，故選 (D)。"}, {"q": "Four of my friends started a ____, and they play rock music on weekends.", "options": ["club", "band", "drama", "film"], "answer": 1, "explain": "幾個人一起演奏音樂組成的是 band 樂團，故選 (B)。"}]}, {"id": "E21", "level": "elem", "num": 21, "title": "Our New Apartment", "titleZh": "我們的新公寓", "theme": "Home & Rooms", "themeZh": "住家與房間", "article": ["Last month, my family moved into a new apartment in Banqiao. It is on the fifth floor of a tall building. When I first opened the door, I was so excited. The living room is big and bright, and the kitchen is right next to it. There is a small balcony, too. My mom put some flowers there.", "My bedroom is at the end of the hall. It has a large window, so I can see the park every morning. The walls are light blue, and the ceiling is white. My little brother's room is upstairs, and the bathroom is downstairs. We often run up and down the stairs. Dad says we are too noisy!", "I miss our old house a little. It had a yard and a garden, and my dog could play behind the fence. But the new apartment is close to the MRT station. Now I can get to school in ten minutes. I think I will love my new home."], "translation": ["上個月，我們家搬進了板橋的一間新公寓。它在一棟高樓的五樓。我第一次打開門時，興奮極了。客廳又大又明亮，廚房就在它旁邊。還有一個小陽台。我媽媽在那裡放了一些花。", "我的臥室在走廊的盡頭。它有一扇大窗戶，所以我每天早上都能看到公園。牆壁是淺藍色的，天花板是白色的。我弟弟的房間在樓上，浴室在樓下。我們常常在樓梯上跑上跑下。爸爸說我們太吵了！", "我有一點想念我們的舊房子。它有院子和花園，我的狗可以在圍籬後面玩。但是新公寓離捷運站很近。現在我十分鐘就能到學校。我想我會愛上我的新家。"], "vocab": [{"word": "apartment", "pos": "n.", "zh": "公寓", "example": "They live in a small apartment near the park.", "exampleZh": "他們住在公園附近的一間小公寓。"}, {"word": "building", "pos": "n.", "zh": "建築物；大樓", "example": "The post office is in that tall building.", "exampleZh": "郵局在那棟高樓裡。"}, {"word": "balcony", "pos": "n.", "zh": "陽台", "example": "Grandma likes to drink tea on the balcony.", "exampleZh": "奶奶喜歡在陽台上喝茶。"}, {"word": "bedroom", "pos": "n.", "zh": "臥室", "example": "I share a bedroom with my sister.", "exampleZh": "我和姊姊共用一間臥室。"}, {"word": "window", "pos": "n.", "zh": "窗戶", "example": "Please close the window before it rains.", "exampleZh": "下雨前請把窗戶關上。"}, {"word": "ceiling", "pos": "n.", "zh": "天花板", "example": "There is a big fan on the ceiling.", "exampleZh": "天花板上有一台大電扇。"}, {"word": "stairs", "pos": "n.", "zh": "樓梯", "example": "Be careful when you go down the stairs.", "exampleZh": "下樓梯時要小心。"}, {"word": "yard", "pos": "n.", "zh": "院子", "example": "The kids are playing ball in the yard.", "exampleZh": "孩子們正在院子裡玩球。"}], "phrases": [{"phrase": "move into", "zh": "搬進", "example": "We will move into the new house next week.", "exampleZh": "我們下週會搬進新房子。"}, {"phrase": "next to", "zh": "在…旁邊", "example": "The bank is next to the bookstore.", "exampleZh": "銀行在書店旁邊。"}, {"phrase": "close to", "zh": "靠近", "example": "My school is close to the MRT station.", "exampleZh": "我的學校離捷運站很近。"}], "grammar": [{"pattern": "There is / There are + N + 地方", "explain": "「某處有…」的句型。單數名詞用 There is，複數名詞用 There are。", "example": "There is a small balcony in our apartment.", "exampleZh": "我們的公寓有一個小陽台。"}, {"pattern": "S + V ..., so + S + V ...", "explain": "so 表示「所以」，連接原因和結果，前面的句子是原因，後面是結果。", "example": "It has a large window, so I can see the park.", "exampleZh": "它有一扇大窗戶，所以我看得到公園。"}], "reading": [{"q": "Where is the writer's new apartment?", "options": ["On the first floor of a house", "On the fifth floor of a tall building", "Next to a garden", "Behind a fence"], "answer": 1, "explain": "第一段提到 It is on the fifth floor of a tall building，故選 (B)。"}, {"q": "What can the writer see from the bedroom window?", "options": ["The MRT station", "The kitchen", "The park", "The school"], "answer": 2, "explain": "第二段提到 It has a large window, so I can see the park every morning，故選 (C)。"}, {"q": "Why does Dad say the children are too noisy?", "options": ["They play with the dog.", "They run up and down the stairs.", "They open the windows.", "They sing in the living room."], "answer": 1, "explain": "第二段提到 We often run up and down the stairs. Dad says we are too noisy，故選 (B)。"}, {"q": "What did the old house have that the new apartment does NOT have?", "options": ["A kitchen", "A bedroom", "A balcony", "A yard and a garden"], "answer": 3, "explain": "第三段提到 It had a yard and a garden，這是舊房子才有的，故選 (D)。"}, {"q": "How does the writer feel about the new home at the end?", "options": ["Sad and tired", "Afraid of the noise", "Happy and hopeful", "Angry at Dad"], "answer": 2, "explain": "最後一句 I think I will love my new home 顯示作者對新家充滿期待，故選 (C)。"}], "vocabQ": [{"q": "My uncle lives in a small ____ on the third floor.", "options": ["apartment", "garden", "fence", "gate"], "answer": 0, "explain": "句意為「我叔叔住在三樓的一間小公寓」，apartment 公寓。"}, {"q": "We dry our clothes on the ____ when it is sunny.", "options": ["ceiling", "balcony", "basement", "roof"], "answer": 1, "explain": "句意為「晴天時我們在陽台上曬衣服」，balcony 陽台。"}, {"q": "Walk up the ____ and you will see my room on the right.", "options": ["wall", "floor", "stairs", "door"], "answer": 2, "explain": "句意為「走上樓梯，你會看到我的房間在右邊」，stairs 樓梯。"}, {"q": "The ____ is so high that we need a long ladder to clean the lamp.", "options": ["yard", "window", "hall", "ceiling"], "answer": 3, "explain": "句意為「天花板很高，我們需要長梯子才能清理燈」，ceiling 天花板。"}, {"q": "Open the ____ and let some fresh air into the room.", "options": ["window", "bedroom", "building", "garage"], "answer": 0, "explain": "句意為「打開窗戶，讓新鮮空氣進到房間」，window 窗戶。"}]}, {"id": "E22", "level": "elem", "num": 22, "title": "An Email to Grandma", "titleZh": "寫給奶奶的電子郵件", "theme": "Furniture & Appliances", "themeZh": "家具與家電", "article": ["Dear Grandma, How are you? I am writing to tell you about my new room. Last Sunday, Dad and I went to a furniture store near our home. We bought a desk, a small bookcase, and a soft armchair. Now my room looks like a little office!", "The best thing is my new lamp. It is on the desk next to the window. When I study at night, the light is warm and bright. Mom also bought a new blanket and two pillows for my bed. They are so comfortable that I fall asleep in five minutes. There is a fan on the ceiling and a curtain in front of the window.", "We put the old sofa in the living room, and the closet is still in the hall. Dad wants to buy a new refrigerator next month because the old one is noisy. When you come to visit, you can sleep in my room. I will sleep on the sofa. I can't wait to see you! Love, Mia"], "translation": ["親愛的奶奶：您好嗎？我寫信是想告訴您我的新房間。上星期天，爸爸和我去了我們家附近的一間家具店。我們買了一張書桌、一個小書櫃和一張柔軟的扶手椅。現在我的房間看起來像一間小辦公室！", "最棒的是我的新檯燈。它放在窗戶旁的書桌上。晚上讀書時，燈光溫暖又明亮。媽媽也為我的床買了一條新毯子和兩個枕頭。它們舒服到我五分鐘就睡著了。天花板上有一台電扇，窗前有一片窗簾。", "我們把舊沙發放在客廳，衣櫃還在走廊。爸爸想下個月買一台新冰箱，因為舊的太吵了。您來訪時可以睡在我的房間，我會睡在沙發上。我等不及要見到您了！愛您的 Mia"], "vocab": [{"word": "furniture", "pos": "n.", "zh": "家具", "example": "The new furniture makes the room look nice.", "exampleZh": "新家具讓房間看起來很漂亮。"}, {"word": "bookcase", "pos": "n.", "zh": "書櫃", "example": "Put the dictionary back on the bookcase.", "exampleZh": "把字典放回書櫃上。"}, {"word": "armchair", "pos": "n.", "zh": "扶手椅", "example": "Grandpa reads the newspaper in his armchair.", "exampleZh": "爺爺坐在他的扶手椅上看報紙。"}, {"word": "lamp", "pos": "n.", "zh": "檯燈；燈", "example": "Turn on the lamp; it is too dark to read.", "exampleZh": "把燈打開，太暗了沒辦法閱讀。"}, {"word": "blanket", "pos": "n.", "zh": "毯子", "example": "It is cold tonight, so I need another blanket.", "exampleZh": "今晚很冷，所以我需要再一條毯子。"}, {"word": "pillow", "pos": "n.", "zh": "枕頭", "example": "This pillow is too soft for me.", "exampleZh": "這個枕頭對我來說太軟了。"}, {"word": "curtain", "pos": "n.", "zh": "窗簾", "example": "Mom opens the curtain every morning at six.", "exampleZh": "媽媽每天早上六點拉開窗簾。"}, {"word": "refrigerator", "pos": "n.", "zh": "冰箱", "example": "There is some milk in the refrigerator.", "exampleZh": "冰箱裡有一些牛奶。"}], "phrases": [{"phrase": "look like", "zh": "看起來像", "example": "Your brother looks like a movie star.", "exampleZh": "你哥哥看起來像個電影明星。"}, {"phrase": "fall asleep", "zh": "入睡", "example": "The baby fell asleep in Mom's arms.", "exampleZh": "寶寶在媽媽懷裡睡著了。"}, {"phrase": "can't wait to + V", "zh": "等不及要…", "example": "I can't wait to open my birthday present.", "exampleZh": "我等不及要打開我的生日禮物。"}], "grammar": [{"pattern": "S + be + so + adj. + that + S + V", "explain": "「如此…以至於…」，so 後面接形容詞，that 後面接完整的結果子句。", "example": "They are so comfortable that I fall asleep in five minutes.", "exampleZh": "它們舒服到我五分鐘就睡著了。"}, {"pattern": "When + S + V ..., S + V ...", "explain": "when 引導時間副詞子句，表示「當…的時候」。when 子句放句首時，後面要加逗號。", "example": "When you come to visit, you can sleep in my room.", "exampleZh": "您來訪時，可以睡在我的房間。"}], "reading": [{"q": "Why is Mia writing to Grandma?", "options": ["To ask for a new lamp", "To tell her about the new room", "To invite her to a furniture store", "To say sorry for the noisy refrigerator"], "answer": 1, "explain": "第一段 I am writing to tell you about my new room 說明寫信目的，故選 (B)。"}, {"q": "Which of the following did Mia and Dad NOT buy at the furniture store?", "options": ["A desk", "A bookcase", "An armchair", "A sofa"], "answer": 3, "explain": "第一段提到買了 desk、bookcase、armchair；sofa 是舊的，故選 (D)。"}, {"q": "Where is the new lamp?", "options": ["On the desk next to the window", "On the ceiling", "In the living room", "In the hall"], "answer": 0, "explain": "第二段提到 It is on the desk next to the window，故選 (A)。"}, {"q": "Why does Dad want to buy a new refrigerator?", "options": ["The old one is too small.", "The old one is too old.", "The old one is noisy.", "Grandma needs one."], "answer": 2, "explain": "第三段提到 because the old one is noisy，故選 (C)。"}, {"q": "Where will Mia sleep when Grandma visits?", "options": ["In her own bed", "On the sofa", "In the armchair", "In Grandma's room"], "answer": 1, "explain": "第三段提到 you can sleep in my room. I will sleep on the sofa，故選 (B)。"}], "vocabQ": [{"q": "We need to buy some new ____ for the living room, like a table and chairs.", "options": ["furniture", "housework", "soap", "tape"], "answer": 0, "explain": "句意為「我們需要為客廳買一些新家具，像是桌子和椅子」，furniture 家具。"}, {"q": "Please put the juice back in the ____ so it stays cold.", "options": ["oven", "refrigerator", "heater", "stove"], "answer": 1, "explain": "句意為「請把果汁放回冰箱，這樣才會保持冰涼」，refrigerator 冰箱。"}, {"q": "The sun is too bright. Could you close the ____?", "options": ["carpet", "mirror", "curtain", "drawer"], "answer": 2, "explain": "句意為「太陽太亮了，你可以把窗簾拉上嗎」，curtain 窗簾。"}, {"q": "My cat likes to sleep on my ____ at night, so my head has no place.", "options": ["bucket", "hanger", "toothbrush", "pillow"], "answer": 3, "explain": "句意為「我的貓晚上喜歡睡在我的枕頭上，所以我的頭沒地方放」，pillow 枕頭。"}, {"q": "Grandma covered the baby with a warm ____.", "options": ["blanket", "candle", "shelf", "faucet"], "answer": 0, "explain": "句意為「奶奶用溫暖的毯子蓋住寶寶」，blanket 毯子。"}]}, {"id": "E23", "level": "elem", "num": 23, "title": "How to Make Your Room Shine in One Hour", "titleZh": "如何在一小時內讓房間煥然一新", "theme": "Housework", "themeZh": "家事", "article": ["Is your room always a mess? Don't worry. Here is an easy plan. You can clean your room in one hour, and it is not boring at all. First, open the window and play your favorite music. Then put all the dirty clothes in a basket. You can wash them later.", "Second, sweep the floor from the door to the corner. Don't forget the space under the bed. Next, wash the desk with a wet towel. If a drawer is broken, ask your dad to fix it. My brother tried to repair his chair by himself, and now it has only three legs!", "Finally, it is time to decorate. You can design a poster for the wall, or build a small shelf for your books. Put a plant near the window. Now look around. Your room is clean, bright, and new. Do this every Saturday, and your mom will be very happy."], "translation": ["你的房間總是亂七八糟嗎？別擔心。這裡有一個簡單的計畫。你可以在一小時內打掃好房間，而且一點也不無聊。首先，打開窗戶，播放你最喜歡的音樂。然後把所有髒衣服放進籃子裡。你可以晚點再洗。", "第二，從門口到角落把地板掃一遍。別忘了床底下的空間。接著，用濕毛巾擦拭書桌。如果抽屜壞了，請你爸爸修理。我哥哥試著自己修他的椅子，現在它只剩三隻腳！", "最後，是布置的時候了。你可以為牆壁設計一張海報，或是為你的書做一個小架子。在窗邊放一盆植物。現在環顧四周。你的房間乾淨、明亮又煥然一新。每個星期六都這樣做，你媽媽會非常開心。"], "vocab": [{"word": "clean", "pos": "v.", "zh": "打掃；清潔", "example": "I clean my room every weekend.", "exampleZh": "我每個週末打掃房間。"}, {"word": "wash", "pos": "v.", "zh": "洗", "example": "Wash your hands before dinner.", "exampleZh": "晚餐前要洗手。"}, {"word": "sweep", "pos": "v.", "zh": "掃", "example": "Dad sweeps the yard every morning.", "exampleZh": "爸爸每天早上掃院子。"}, {"word": "fix", "pos": "v.", "zh": "修理", "example": "Can you fix my bike? The wheel is broken.", "exampleZh": "你可以修我的腳踏車嗎？輪子壞了。"}, {"word": "repair", "pos": "v.", "zh": "修理", "example": "The worker came to repair the air conditioner.", "exampleZh": "工人來修理冷氣。"}, {"word": "decorate", "pos": "v.", "zh": "裝飾；布置", "example": "We decorate the classroom before Christmas.", "exampleZh": "我們在聖誕節前布置教室。"}, {"word": "design", "pos": "v.", "zh": "設計", "example": "She designed a cute card for her mother.", "exampleZh": "她為媽媽設計了一張可愛的卡片。"}, {"word": "build", "pos": "v.", "zh": "建造；製作", "example": "They want to build a tree house in the yard.", "exampleZh": "他們想在院子裡建一間樹屋。"}], "phrases": [{"phrase": "a mess", "zh": "一團亂", "example": "After the party, the kitchen was a mess.", "exampleZh": "派對之後，廚房一團亂。"}, {"phrase": "by oneself", "zh": "獨自；靠自己", "example": "My sister made the cake by herself.", "exampleZh": "我姊姊自己做了這個蛋糕。"}, {"phrase": "look around", "zh": "環顧四周", "example": "Look around and tell me what you see.", "exampleZh": "看看四周，告訴我你看到什麼。"}], "grammar": [{"pattern": "祈使句：V + ... / Don't + V + ...", "explain": "祈使句用動詞原形開頭，表示命令、指示或建議；否定用 Don't 開頭。說明步驟時常用。", "example": "Open the window and play your favorite music.", "exampleZh": "打開窗戶，播放你最喜歡的音樂。"}, {"pattern": "If + S + V ..., (please) + V ...", "explain": "if 子句表示條件「如果…」，後面接要做的事。if 子句用現在式。", "example": "If a drawer is broken, ask your dad to fix it.", "exampleZh": "如果抽屜壞了，請你爸爸修理。"}], "reading": [{"q": "What is the main purpose of this article?", "options": ["To tell a funny story about a brother", "To show how to clean a room step by step", "To sell furniture", "To explain why rooms get dirty"], "answer": 1, "explain": "全文以 First、Second、Next、Finally 說明打掃房間的步驟，故選 (B)。"}, {"q": "What should you do with the dirty clothes first?", "options": ["Wash them right away", "Put them under the bed", "Put them in a basket", "Give them to your dad"], "answer": 2, "explain": "第一段提到 put all the dirty clothes in a basket. You can wash them later，故選 (C)。"}, {"q": "What happened to the brother's chair?", "options": ["It has only three legs now.", "It is new and clean.", "Dad fixed it.", "It is under the bed."], "answer": 0, "explain": "第二段提到 now it has only three legs，故選 (A)。"}, {"q": "Which of the following is in the last step?", "options": ["Sweeping the floor", "Washing the desk", "Opening the window", "Designing a poster"], "answer": 3, "explain": "第三段 Finally, it is time to decorate. You can design a poster for the wall，故選 (D)。"}, {"q": "How often does the writer suggest cleaning the room?", "options": ["Every day", "Once a week", "Once a month", "Every hour"], "answer": 1, "explain": "最後一段 Do this every Saturday 表示每週一次，故選 (B)。"}], "vocabQ": [{"q": "The floor is dirty. Please ____ it before Grandma comes.", "options": ["sweep", "build", "design", "decorate"], "answer": 0, "explain": "句意為「地板很髒，請在奶奶來之前掃一掃」，sweep 掃。"}, {"q": "My watch stopped working, so I took it to a shop to ____ it.", "options": ["wash", "clean", "repair", "decorate"], "answer": 2, "explain": "句意為「我的手錶不走了，所以我把它拿到店裡修理」，repair 修理。"}, {"q": "We will ____ the classroom with balloons for the party.", "options": ["sweep", "wash", "fix", "decorate"], "answer": 3, "explain": "句意為「我們會用氣球布置教室來開派對」，decorate 布置。"}, {"q": "The workers will ____ a new bridge over the river next year.", "options": ["clean", "build", "wash", "sweep"], "answer": 1, "explain": "句意為「工人們明年會在河上建一座新橋」，build 建造。"}, {"q": "Mom asked me to ____ the dishes after dinner.", "options": ["wash", "design", "build", "repair"], "answer": 0, "explain": "句意為「媽媽要我晚餐後洗碗」，wash 洗。"}]}, {"id": "E24", "level": "elem", "num": 24, "title": "Where Is the Gym?", "titleZh": "體育館在哪裡？", "theme": "School & Address", "themeZh": "學校與地址", "article": ["It was Kevin's first day at his new junior high school. The campus was very big, and he did not know the way. He walked to the gate and asked the guard, \"Excuse me, where is the gym?\" The guard smiled and said, \"Go past the library and turn left. It is next to the playground.\"", "Kevin thanked him and walked along the road. He saw a classroom with many students inside. A girl came out and said, \"Are you new here? I'm Amy. My class is 7-3.\" Kevin said, \"Me too! Can you show me the gym?\" Amy laughed, \"Of course. We are in the same class.\"", "After the PE class, Amy asked, \"Where do you live?\" Kevin wrote his address on a piece of paper: No. 25, Zhongshan Street. \"That's my street!\" Amy said. \"We can walk to school together.\" Kevin was happy. The big campus did not look so scary anymore."], "translation": ["這是 Kevin 在新國中的第一天。校園很大，他不認得路。他走到大門口問警衛：「不好意思，體育館在哪裡？」警衛微笑著說：「經過圖書館後左轉，它就在操場旁邊。」", "Kevin 向他道謝後沿著路走。他看到一間教室裡有很多學生。一個女孩走出來說：「你是新來的嗎？我是 Amy，我的班級是七年三班。」Kevin 說：「我也是！你可以帶我去體育館嗎？」Amy 笑著說：「當然，我們同班。」", "體育課後，Amy 問：「你住哪裡？」Kevin 把地址寫在一張紙上：中山街 25 號。「那是我住的街！」Amy 說：「我們可以一起走路上學。」Kevin 很開心。大大的校園再也不那麼可怕了。"], "vocab": [{"word": "campus", "pos": "n.", "zh": "校園", "example": "There are many trees on our campus.", "exampleZh": "我們的校園裡有很多樹。"}, {"word": "guard", "pos": "n.", "zh": "警衛", "example": "The guard checks every car at the gate.", "exampleZh": "警衛在大門檢查每一輛車。"}, {"word": "gym", "pos": "n.", "zh": "體育館", "example": "We play basketball in the gym on rainy days.", "exampleZh": "下雨天我們在體育館打籃球。"}, {"word": "library", "pos": "n.", "zh": "圖書館", "example": "Please be quiet in the library.", "exampleZh": "在圖書館裡請保持安靜。"}, {"word": "playground", "pos": "n.", "zh": "操場；遊樂場", "example": "The children are running on the playground.", "exampleZh": "孩子們正在操場上跑步。"}, {"word": "classroom", "pos": "n.", "zh": "教室", "example": "Our classroom is on the second floor.", "exampleZh": "我們的教室在二樓。"}, {"word": "address", "pos": "n.", "zh": "地址", "example": "Write your address on the envelope.", "exampleZh": "把你的地址寫在信封上。"}, {"word": "street", "pos": "n.", "zh": "街道", "example": "There is a night market on this street.", "exampleZh": "這條街上有一個夜市。"}], "phrases": [{"phrase": "know the way", "zh": "認得路", "example": "Do you know the way to the museum?", "exampleZh": "你知道去博物館的路嗎？"}, {"phrase": "turn left / right", "zh": "左轉／右轉", "example": "Turn right at the bank, and you will see the park.", "exampleZh": "在銀行右轉，你就會看到公園。"}, {"phrase": "not ... anymore", "zh": "不再…", "example": "He does not live here anymore.", "exampleZh": "他不再住在這裡了。"}], "grammar": [{"pattern": "Where + be / do + S ...?", "explain": "詢問地點的疑問句。be 動詞直接放 where 後面；一般動詞要用助動詞 do / does。", "example": "Where is the gym? / Where do you live?", "exampleZh": "體育館在哪裡？／你住在哪裡？"}, {"pattern": "Can + S + V ...?", "explain": "can 用來請求幫忙或詢問能力，後面接動詞原形。回答常用 Of course / Sure。", "example": "Can you show me the gym?", "exampleZh": "你可以帶我去體育館嗎？"}], "reading": [{"q": "Why did Kevin ask the guard a question?", "options": ["He lost his bag.", "He did not know where the gym was.", "He wanted to go home.", "He was looking for Amy."], "answer": 1, "explain": "第一段提到他不認得路，問警衛 where is the gym，故選 (B)。"}, {"q": "According to the guard, where is the gym?", "options": ["Next to the gate", "Inside the library", "Next to the playground", "Behind the classroom"], "answer": 2, "explain": "第一段警衛說 It is next to the playground，故選 (C)。"}, {"q": "What do Kevin and Amy have in common?", "options": ["They are in the same class and live on the same street.", "They both like PE.", "They both know the guard.", "They both lost their way."], "answer": 0, "explain": "第二段 We are in the same class，第三段 That's my street，故選 (A)。"}, {"q": "What did Kevin write on the piece of paper?", "options": ["His phone number", "His class", "His name", "His address"], "answer": 3, "explain": "第三段提到 Kevin wrote his address on a piece of paper，故選 (D)。"}, {"q": "How did Kevin feel at the end of the story?", "options": ["Scared", "Tired", "Happy", "Angry"], "answer": 2, "explain": "第三段 Kevin was happy. The big campus did not look so scary anymore，故選 (C)。"}], "vocabQ": [{"q": "The ____ at the gate asked me to show my student card.", "options": ["guard", "class", "college", "slide"], "answer": 0, "explain": "句意為「大門口的警衛要我出示學生證」，guard 警衛。"}, {"q": "I can't send you the gift because I don't have your ____.", "options": ["campus", "address", "playground", "gym"], "answer": 1, "explain": "句意為「我沒辦法寄禮物給你，因為我沒有你的地址」，address 地址。"}, {"q": "You can borrow up to five books from the school ____.", "options": ["classroom", "street", "library", "road"], "answer": 2, "explain": "句意為「你可以從學校圖書館借最多五本書」，library 圖書館。"}, {"q": "It is raining, so the PE class will be in the ____ today.", "options": ["street", "address", "kindergarten", "gym"], "answer": 3, "explain": "句意為「下雨了，所以今天的體育課會在體育館上」，gym 體育館。"}, {"q": "The university ____ is so big that students ride bikes to class.", "options": ["campus", "guard", "classroom", "seesaw"], "answer": 0, "explain": "句意為「大學校園很大，學生騎腳踏車去上課」，campus 校園。"}]}, {"id": "E25", "level": "elem", "num": 25, "title": "Dear Diary: The Lost Pencil Case", "titleZh": "親愛的日記：遺失的鉛筆盒", "theme": "Stationery", "themeZh": "文具與學習用品", "article": ["September 12, Tuesday. Rainy. Today was a bad day at first. I could not find my pencil case this morning. My ruler, my eraser, and three pens were in it. I looked in my backpack and under my desk, but it was not there. I was so worried.", "In English class, I had to borrow a pencil from Lily. Then the teacher asked us to use the dictionary and write new words in our notebook. I did not have a marker, so I could not underline the important words. My page looked so plain.", "After lunch, Mr. Wang came in with a blue pencil case. \"Whose is this?\" he asked. It was mine! I left it in the art room yesterday after we used glue and crayons. I was so happy. Tonight, I will write my name on it. I will also put a picture of my cat inside. Then I will never lose it again."], "translation": ["九月十二日，星期二，雨天。今天一開始是糟糕的一天。早上我找不到我的鉛筆盒。我的尺、橡皮擦和三支筆都在裡面。我找了背包和書桌底下，但它都不在。我好擔心。", "英文課時，我必須向 Lily 借一支鉛筆。然後老師要我們用字典，把新單字寫在筆記本裡。我沒有麥克筆，所以沒辦法在重要的字下面畫線。我的那一頁看起來好單調。", "午餐後，王老師拿著一個藍色鉛筆盒進來。「這是誰的？」他問。是我的！昨天我們用了膠水和蠟筆之後，我把它留在美術教室了。我好開心。今晚我要把名字寫在上面。我也會在裡面放一張我的貓的照片。這樣我就再也不會弄丟它了。"], "vocab": [{"word": "pencil case", "pos": "n.", "zh": "鉛筆盒", "example": "There are five pens in my pencil case.", "exampleZh": "我的鉛筆盒裡有五支筆。"}, {"word": "ruler", "pos": "n.", "zh": "尺", "example": "Use a ruler to draw a straight line.", "exampleZh": "用尺畫一條直線。"}, {"word": "eraser", "pos": "n.", "zh": "橡皮擦", "example": "May I borrow your eraser?", "exampleZh": "我可以借你的橡皮擦嗎？"}, {"word": "backpack", "pos": "n.", "zh": "背包", "example": "His backpack is full of books.", "exampleZh": "他的背包裝滿了書。"}, {"word": "dictionary", "pos": "n.", "zh": "字典", "example": "Look up the word in the dictionary.", "exampleZh": "在字典裡查這個字。"}, {"word": "notebook", "pos": "n.", "zh": "筆記本", "example": "I write down new words in my notebook.", "exampleZh": "我把新單字寫在筆記本裡。"}, {"word": "marker", "pos": "n.", "zh": "麥克筆", "example": "The teacher wrote on the board with a red marker.", "exampleZh": "老師用紅色麥克筆寫在白板上。"}, {"word": "glue", "pos": "n.", "zh": "膠水", "example": "We need some glue to make the paper house.", "exampleZh": "我們需要一些膠水來做紙房子。"}], "phrases": [{"phrase": "at first", "zh": "起初", "example": "At first, I did not like the new school.", "exampleZh": "起初，我不喜歡新學校。"}, {"phrase": "borrow ... from ...", "zh": "向…借…", "example": "I borrowed a pen from my classmate.", "exampleZh": "我向同學借了一支筆。"}, {"phrase": "have to + V", "zh": "必須", "example": "We have to finish the homework tonight.", "exampleZh": "我們今晚必須完成作業。"}], "grammar": [{"pattern": "S + could not + V (過去式否定)", "explain": "could 是 can 的過去式，could not 表示「過去不能、無法」，後面接動詞原形。", "example": "I could not find my pencil case this morning.", "exampleZh": "今天早上我找不到我的鉛筆盒。"}, {"pattern": "S + ask + O + to + V", "explain": "「要求某人做某事」。ask 後面接受詞，再接 to + 動詞原形。", "example": "The teacher asked us to use the dictionary.", "exampleZh": "老師要我們使用字典。"}], "reading": [{"q": "What kind of writing is this?", "options": ["A letter to a teacher", "A diary", "A news report", "A notice"], "answer": 1, "explain": "標題 Dear Diary 與開頭的日期、天氣是日記的寫法，故選 (B)。"}, {"q": "What was NOT in the pencil case?", "options": ["A ruler", "An eraser", "Three pens", "A dictionary"], "answer": 3, "explain": "第一段提到鉛筆盒裡有 ruler、eraser、three pens，沒有 dictionary，故選 (D)。"}, {"q": "Why could the writer not underline the important words?", "options": ["There was no marker.", "The notebook was lost.", "The teacher said no.", "Lily did not help."], "answer": 0, "explain": "第二段 I did not have a marker, so I could not underline the important words，故選 (A)。"}, {"q": "Where did the writer leave the pencil case?", "options": ["Under the desk", "In the backpack", "In the art room", "In the English classroom"], "answer": 2, "explain": "第三段 I left it in the art room yesterday，故選 (C)。"}, {"q": "The word \"plain\" in paragraph 2 is closest in meaning to ____.", "options": ["colorful", "simple and not special", "wet", "full"], "answer": 1, "explain": "前句說沒有麥克筆畫線，所以頁面看起來「單調、沒有特色」，故選 (B)。"}], "vocabQ": [{"q": "I made a mistake, so I used an ____ to clean it.", "options": ["eraser", "envelope", "ink", "glue"], "answer": 0, "explain": "句意為「我寫錯了，所以用橡皮擦擦掉」，eraser 橡皮擦。"}, {"q": "If you don't know a word, you can look it up in the ____.", "options": ["ruler", "dictionary", "postcard", "crayon"], "answer": 1, "explain": "句意為「如果你不認識一個字，可以在字典裡查」，dictionary 字典。"}, {"q": "Use some ____ to stick the picture on the paper.", "options": ["chalk", "paper", "glue", "ink"], "answer": 2, "explain": "句意為「用一些膠水把圖片黏在紙上」，glue 膠水。"}, {"q": "This line is not straight. You should draw it with a ____.", "options": ["marker", "pencil", "eraser", "ruler"], "answer": 3, "explain": "句意為「這條線不直，你應該用尺來畫」，ruler 尺。"}, {"q": "My ____ is heavy because I put all my textbooks in it.", "options": ["backpack", "notebook", "diary", "magazine"], "answer": 0, "explain": "句意為「我的背包很重，因為我把所有課本都放進去了」，backpack 背包。"}]}, {"id": "E26", "level": "elem", "num": 26, "title": "Students Pick Their Favorite Subject", "titleZh": "學生票選最愛的科目", "theme": "School Subjects", "themeZh": "學科", "article": ["Taipei, October 20. Last week, Green Hill Junior High School asked 600 students a simple question: What is your favorite subject? The results came out yesterday, and they surprised many teachers. The winner was not math or English. It was PE!", "Over 200 students chose PE. \"I love running and playing basketball with my classmates,\" said Jack Lin, a student in grade eight. Science was the second choice. Many students said they like doing experiments in chemistry and biology. Music and art came next. History and geography got fewer votes. \"There are too many names and dates to remember,\" one girl said.", "The principal, Ms. Chen, was happy with the results. She said the school will add one more PE class each week. \"A healthy body makes a smart mind,\" she said. However, she also hopes students will give math a chance. \"Every subject is a friend,\" she added. \"You just need time to know it.\""], "translation": ["台北，十月二十日。上週，綠丘國中問了六百名學生一個簡單的問題：你最喜歡的科目是什麼？結果昨天出爐，讓許多老師感到驚訝。贏家不是數學也不是英文，而是體育！", "超過兩百名學生選了體育。「我喜歡和同學一起跑步、打籃球。」八年級學生林傑克說。自然是第二名。許多學生說他們喜歡做化學和生物的實驗。音樂和美術排在後面。歷史和地理得到的票比較少。「要記的人名和日期太多了。」一個女孩說。", "校長陳女士對結果很滿意。她說學校每週會增加一節體育課。「健康的身體造就聰明的頭腦。」她說。不過，她也希望學生給數學一個機會。「每一個科目都是朋友，」她補充說，「你只是需要時間去認識它。」"], "vocab": [{"word": "PE", "pos": "n.", "zh": "體育", "example": "We have PE on Monday and Thursday.", "exampleZh": "我們星期一和星期四有體育課。"}, {"word": "classmate", "pos": "n.", "zh": "同學", "example": "My classmates and I study together after school.", "exampleZh": "我和同學放學後一起讀書。"}, {"word": "science", "pos": "n.", "zh": "科學；自然", "example": "Science is my favorite subject.", "exampleZh": "自然是我最喜歡的科目。"}, {"word": "chemistry", "pos": "n.", "zh": "化學", "example": "We mixed two things in chemistry class today.", "exampleZh": "今天我們在化學課上混合了兩種東西。"}, {"word": "biology", "pos": "n.", "zh": "生物", "example": "In biology, we learn about plants and animals.", "exampleZh": "在生物課，我們學習植物和動物。"}, {"word": "history", "pos": "n.", "zh": "歷史", "example": "My grandfather loves reading about Chinese history.", "exampleZh": "我爺爺喜歡閱讀中國歷史。"}, {"word": "geography", "pos": "n.", "zh": "地理", "example": "We learned about rivers and mountains in geography.", "exampleZh": "我們在地理課學了河流和山脈。"}, {"word": "principal", "pos": "n.", "zh": "校長", "example": "The principal gave a speech this morning.", "exampleZh": "校長今天早上發表了演講。"}], "phrases": [{"phrase": "come out", "zh": "公布；出爐", "example": "The test results will come out on Friday.", "exampleZh": "考試成績將在星期五公布。"}, {"phrase": "give ... a chance", "zh": "給…一個機會", "example": "Please give the new game a chance.", "exampleZh": "請給這個新遊戲一個機會。"}, {"phrase": "be happy with", "zh": "對…滿意", "example": "Mom is happy with my grades this time.", "exampleZh": "媽媽對我這次的成績很滿意。"}], "grammar": [{"pattern": "S + V + O + with + 人", "explain": "with 表示「和…一起」，用來說明和誰一起做某事。", "example": "I love playing basketball with my classmates.", "exampleZh": "我喜歡和同學一起打籃球。"}, {"pattern": "There are + too many + 複數名詞 + to + V", "explain": "「太多…而無法…」，too many 修飾可數名詞，to 後面接動詞原形。", "example": "There are too many names and dates to remember.", "exampleZh": "要記的人名和日期太多了。"}], "reading": [{"q": "What is this news report mainly about?", "options": ["A new PE teacher at a school", "A school vote on students' favorite subject", "How to study history", "A basketball game"], "answer": 1, "explain": "第一段說明學校問學生最喜歡的科目，全文報導結果，故選 (B)。"}, {"q": "Which subject was the most popular?", "options": ["Math", "Science", "PE", "Music"], "answer": 2, "explain": "第一段 The winner was not math or English. It was PE，故選 (C)。"}, {"q": "Why do many students like science?", "options": ["They like doing experiments.", "It has no tests.", "The teacher is funny.", "It is easy to remember."], "answer": 0, "explain": "第二段 they like doing experiments in chemistry and biology，故選 (A)。"}, {"q": "Why did one girl NOT like history and geography?", "options": ["The classes are too long.", "There is too much to remember.", "The books are expensive.", "She likes PE more."], "answer": 1, "explain": "第二段 There are too many names and dates to remember，故選 (B)。"}, {"q": "What will the school do after the vote?", "options": ["Stop teaching math", "Add a music class", "Add one more PE class each week", "Ask the students again"], "answer": 2, "explain": "第三段 the school will add one more PE class each week，故選 (C)。"}], "vocabQ": [{"q": "In ____ class, we learned about the first president of Taiwan.", "options": ["PE", "history", "music", "art"], "answer": 1, "explain": "句意為「在歷史課，我們學了台灣第一任總統」，history 歷史。"}, {"q": "The ____ of our school is a kind woman with gray hair.", "options": ["classmate", "student", "principal", "friend"], "answer": 2, "explain": "句意為「我們學校的校長是一位頭髮灰白的和藹女士」，principal 校長。"}, {"q": "Put on your sports shoes. We have ____ next.", "options": ["Chinese", "history", "geography", "PE"], "answer": 3, "explain": "句意為「穿上運動鞋，我們接下來是體育課」，PE 體育。"}, {"q": "We looked at the map of Japan in ____ class today.", "options": ["geography", "chemistry", "music", "PE"], "answer": 0, "explain": "句意為「今天我們在地理課看了日本的地圖」，geography 地理。"}, {"q": "In ____ class, we looked at a frog's heart under the microscope.", "options": ["math", "biology", "art", "history"], "answer": 1, "explain": "句意為「在生物課，我們用顯微鏡看青蛙的心臟」，biology 生物。"}]}, {"id": "E27", "level": "elem", "num": 27, "title": "Mr. Huang's Magic English Class", "titleZh": "黃老師的魔法英文課", "theme": "Learning Verbs", "themeZh": "學習動詞", "article": ["Many students in Class 8-2 used to be afraid of English. They could not spell long words, and they did not understand the teacher. Then Mr. Huang came. He is a short man with a big smile, and he never punishes anyone for a wrong answer.", "In his class, students practice speaking every day. First, Mr. Huang says a sentence, and the students repeat it. He shows them how to pronounce each sound slowly. Then he asks a question, and everyone has to answer. If a student does not understand, he explains it again in a different way. He also tells them to underline the key words in every reading.", "Before a test, Mr. Huang helps the class review the lessons with games. Students learn new words by singing and drawing. Now most of them pass the test easily. \"I used to fail every quiz,\" says Tina. \"Now English is my favorite subject.\" Mr. Huang says the secret is simple: practice, listen, and never give up."], "translation": ["八年二班的許多學生以前很怕英文。他們不會拼長的單字，也聽不懂老師在說什麼。後來黃老師來了。他是個矮矮的、笑容很大的男人，而且從不因為答錯而處罰任何人。", "在他的課堂上，學生每天練習說英文。首先，黃老師說一個句子，學生跟著重複。他慢慢示範每個音怎麼發。然後他問一個問題，每個人都要回答。如果有學生不懂，他會用不同的方式再解釋一次。他也要學生在每篇閱讀裡的關鍵字下畫線。", "考試前，黃老師用遊戲幫全班複習課文。學生透過唱歌和畫畫學新單字。現在他們大多數都能輕鬆通過考試。「我以前每次小考都不及格，」Tina 說，「現在英文是我最喜歡的科目。」黃老師說祕訣很簡單：練習、聆聽，而且永不放棄。"], "vocab": [{"word": "spell", "pos": "v.", "zh": "拼字", "example": "How do you spell your last name?", "exampleZh": "你的姓怎麼拼？"}, {"word": "punish", "pos": "v.", "zh": "處罰", "example": "Mom punished me for telling a lie.", "exampleZh": "媽媽因為我說謊而處罰我。"}, {"word": "practice", "pos": "v.", "zh": "練習", "example": "She practices the piano for an hour every day.", "exampleZh": "她每天練鋼琴一小時。"}, {"word": "repeat", "pos": "v.", "zh": "重複", "example": "Could you repeat the question, please?", "exampleZh": "可以請你再說一次問題嗎？"}, {"word": "pronounce", "pos": "v.", "zh": "發音", "example": "I don't know how to pronounce this word.", "exampleZh": "我不知道這個字怎麼發音。"}, {"word": "explain", "pos": "v.", "zh": "解釋", "example": "The teacher explained the rule twice.", "exampleZh": "老師把規則解釋了兩次。"}, {"word": "underline", "pos": "v.", "zh": "在…下畫線", "example": "Underline the verbs in each sentence.", "exampleZh": "在每個句子的動詞下面畫線。"}, {"word": "review", "pos": "v.", "zh": "複習", "example": "Let's review Lesson 5 before the quiz.", "exampleZh": "小考前我們來複習第五課。"}], "phrases": [{"phrase": "used to + V", "zh": "以前常常…", "example": "I used to walk to school when I was little.", "exampleZh": "我小時候常常走路上學。"}, {"phrase": "be afraid of", "zh": "害怕", "example": "My little sister is afraid of dogs.", "exampleZh": "我妹妹怕狗。"}, {"phrase": "give up", "zh": "放棄", "example": "Don't give up. You can do it!", "exampleZh": "別放棄，你做得到！"}], "grammar": [{"pattern": "S + used to + V", "explain": "「過去常常…、以前曾經…」，表示過去的習慣或狀態，現在已經不是這樣了。", "example": "I used to fail every quiz.", "exampleZh": "我以前每次小考都不及格。"}, {"pattern": "S + V + by + V-ing", "explain": "by + 動名詞表示「透過…的方式」，說明做某事的方法。", "example": "Students learn new words by singing and drawing.", "exampleZh": "學生透過唱歌和畫畫學新單字。"}], "reading": [{"q": "How did the students in Class 8-2 feel about English before Mr. Huang came?", "options": ["They loved it.", "They were afraid of it.", "They thought it was easy.", "They did not care."], "answer": 1, "explain": "第一段 Many students in Class 8-2 used to be afraid of English，故選 (B)。"}, {"q": "What does Mr. Huang do when a student does not understand?", "options": ["He punishes the student.", "He asks another student.", "He explains it again in a different way.", "He gives a quiz."], "answer": 2, "explain": "第二段 he explains it again in a different way，故選 (C)。"}, {"q": "How does Mr. Huang help students review before a test?", "options": ["With games", "With long readings", "With more homework", "With a video"], "answer": 0, "explain": "第三段 Mr. Huang helps the class review the lessons with games，故選 (A)。"}, {"q": "Which is TRUE about Tina?", "options": ["She is still afraid of English.", "She used to fail every quiz.", "She is Mr. Huang's daughter.", "She never sings in class."], "answer": 1, "explain": "第三段 Tina 說 I used to fail every quiz，故選 (B)。"}, {"q": "What is the best title for the last paragraph?", "options": ["A Hard Test", "The Secret to Learning English", "How to Draw Pictures", "Mr. Huang's Smile"], "answer": 1, "explain": "第三段說明複習方法與成功的祕訣 practice, listen, and never give up，故選 (B)。"}], "vocabQ": [{"q": "Can you ____ the word \"beautiful\"? B-E-A-U-T-I-F-U-L.", "options": ["spell", "punish", "explain", "review"], "answer": 0, "explain": "句意為「你會拼 beautiful 這個字嗎」，後面是字母拼讀，spell 拼字。"}, {"q": "I didn't hear you. Could you ____ that, please?", "options": ["punish", "repeat", "underline", "practice"], "answer": 1, "explain": "句意為「我沒聽到，可以請你再說一次嗎」，repeat 重複。"}, {"q": "The teacher will ____ anyone who cheats on the test.", "options": ["pronounce", "review", "punish", "spell"], "answer": 2, "explain": "句意為「老師會處罰任何考試作弊的人」，punish 處罰。"}, {"q": "Please ____ the important dates in red so you can find them later.", "options": ["pronounce", "repeat", "practice", "underline"], "answer": 3, "explain": "句意為「請用紅筆在重要日期下畫線，這樣之後才找得到」，underline 畫底線。"}, {"q": "Many students ____ the word \"island\" wrong because the \"s\" is silent.", "options": ["pronounce", "underline", "review", "punish"], "answer": 0, "explain": "句意為「許多學生把 island 唸錯，因為 s 不發音」，pronounce 發音。"}]}, {"id": "E28", "level": "elem", "num": 28, "title": "Notice: Final Exam Week Is Coming", "titleZh": "公告：期末考週即將到來", "theme": "School Life", "themeZh": "學校生活", "article": ["Dear students, the final exam of this semester will be held from January 15 to January 17. Please read this notice carefully. The exam will cover Lessons 1 to 9 in every subject. Your teachers will not start any new lesson next week.", "Here are some important rules. First, all homework must be handed in before January 12. Late homework will get a lower grade. Second, there will be a short vocabulary quiz on Monday. The quiz score will be ten percent of your final grade. Third, bring your own pens and an eraser. No phones are allowed in the exam room.", "Teachers will stay at school until 6 p.m. every day. If you have a problem with any question, go and ask them. Do not wait until the last day. Remember, your record for the whole semester is in your hands. Study hard, sleep well, and good luck to everyone! The Teachers' Office"], "translation": ["親愛的同學們，本學期的期末考將於一月十五日至一月十七日舉行。請仔細閱讀這份公告。考試範圍涵蓋每一科的第一課到第九課。下週老師們不會開始任何新課程。", "以下是一些重要規定。第一，所有作業必須在一月十二日前繳交。遲交的作業會得到較低的成績。第二，星期一會有一個簡短的單字小考。小考分數佔期末成績的百分之十。第三，請自備筆和橡皮擦。考場內不可使用手機。", "老師們每天會留在學校到下午六點。如果你有任何問題不懂，就去問他們。不要等到最後一天。記住，你整個學期的紀錄掌握在你自己手中。用功讀書、睡眠充足，祝大家好運！教師辦公室"], "vocab": [{"word": "exam", "pos": "n.", "zh": "考試", "example": "The math exam is next Friday.", "exampleZh": "數學考試在下週五。"}, {"word": "semester", "pos": "n.", "zh": "學期", "example": "This semester, I want to join the music club.", "exampleZh": "這學期我想加入音樂社。"}, {"word": "lesson", "pos": "n.", "zh": "課；課程", "example": "We are on Lesson 6 now.", "exampleZh": "我們現在上到第六課。"}, {"word": "homework", "pos": "n.", "zh": "家庭作業", "example": "I always do my homework after dinner.", "exampleZh": "我總是在晚餐後寫作業。"}, {"word": "grade", "pos": "n.", "zh": "成績；年級", "example": "She got a good grade in English.", "exampleZh": "她英文得到好成績。"}, {"word": "quiz", "pos": "n.", "zh": "小考", "example": "We have a quiz every Monday morning.", "exampleZh": "我們每週一早上都有小考。"}, {"word": "score", "pos": "n.", "zh": "分數", "example": "My score on the test was 95.", "exampleZh": "我這次考試的分數是 95 分。"}, {"word": "vocabulary", "pos": "n.", "zh": "字彙；單字", "example": "Reading is a good way to learn vocabulary.", "exampleZh": "閱讀是學習單字的好方法。"}], "phrases": [{"phrase": "hand in", "zh": "繳交", "example": "Please hand in your papers before the bell rings.", "exampleZh": "請在鐘響前繳交考卷。"}, {"phrase": "be held", "zh": "舉行", "example": "The school fair will be held in May.", "exampleZh": "校慶園遊會將在五月舉行。"}, {"phrase": "in one's hands", "zh": "由某人掌握", "example": "The future is in your hands.", "exampleZh": "未來掌握在你手中。"}], "grammar": [{"pattern": "S + will be + p.p.", "explain": "未來式的被動語態，「將會被…」。公告中常用來說明活動將在何時舉行。", "example": "The final exam will be held from January 15 to January 17.", "exampleZh": "期末考將於一月十五日至十七日舉行。"}, {"pattern": "S + must + V / must be + p.p.", "explain": "must 表示「必須」，語氣比 should 強，常用於規定。被動用 must be + 過去分詞。", "example": "All homework must be handed in before January 12.", "exampleZh": "所有作業必須在一月十二日前繳交。"}], "reading": [{"q": "Who wrote this notice?", "options": ["A student", "The principal", "The Teachers' Office", "A parent"], "answer": 2, "explain": "公告結尾署名 The Teachers' Office，故選 (C)。"}, {"q": "When is the final exam?", "options": ["January 12", "January 15 to 17", "Next Monday", "At 6 p.m."], "answer": 1, "explain": "第一段 will be held from January 15 to January 17，故選 (B)。"}, {"q": "What will happen if a student hands in homework late?", "options": ["The homework will get a lower grade.", "The student cannot take the exam.", "The teacher will call the parents.", "Nothing will happen."], "answer": 0, "explain": "第二段 Late homework will get a lower grade，故選 (A)。"}, {"q": "How much of the final grade does the vocabulary quiz count for?", "options": ["5 percent", "10 percent", "15 percent", "20 percent"], "answer": 1, "explain": "第二段 The quiz score will be ten percent of your final grade，故選 (B)。"}, {"q": "What does the writer want students to do with their questions?", "options": ["Keep them until the exam day", "Ask their classmates", "Ask teachers before the last day", "Write them in the exam"], "answer": 2, "explain": "第三段 go and ask them. Do not wait until the last day，故選 (C)。"}], "vocabQ": [{"q": "I have a lot of ____ tonight, so I can't watch TV.", "options": ["homework", "semester", "score", "grade"], "answer": 0, "explain": "句意為「我今晚有很多作業，所以不能看電視」，homework 作業。"}, {"q": "The teacher said we would have a short ____ on the new words tomorrow.", "options": ["lesson", "quiz", "semester", "story"], "answer": 1, "explain": "句意為「老師說明天會有一個新單字的小考」，quiz 小考。"}, {"q": "The second ____ starts in February and ends in June.", "options": ["exam", "score", "semester", "vocabulary"], "answer": 2, "explain": "句意為「第二學期從二月開始，六月結束」，semester 學期。"}, {"q": "You need to learn more ____ if you want to read English books.", "options": ["grade", "homework", "quiz", "vocabulary"], "answer": 3, "explain": "句意為「如果你想讀英文書，你需要學更多單字」，vocabulary 字彙。"}, {"q": "Lily got the highest ____ in the class, 98 points.", "options": ["score", "lesson", "homework", "semester"], "answer": 0, "explain": "句意為「Lily 得到全班最高分，98 分」，score 分數。"}]}, {"id": "E29", "level": "elem", "num": 29, "title": "A Note from Mom", "titleZh": "媽媽的留言", "theme": "Position & Direction", "themeZh": "位置與方向", "article": ["Jason, I have to work late tonight. Your dinner is in the refrigerator, on the top shelf. Please heat it for three minutes. Before you eat, I need you to do two things. Read this note carefully because I will not be here to help you.", "First, find the gift for Grandpa. It is in the living room. Stand in front of the TV and turn right. Walk forward three steps to the bookcase. The box is in the middle of the second shelf, behind the photos. After you take it out, put the photos back in the same position.", "Second, take the gift to Grandpa's house. From our gate, go north along the street. Then turn left at the 7-Eleven. His house is the one with the red door, on the right side of the road. Please put the box on the table there and come back before eight. Thank you, my dear. Love, Mom"], "translation": ["Jason，我今晚必須加班。你的晚餐在冰箱的最上層。請加熱三分鐘。吃飯前，我需要你做兩件事。請仔細讀這張留言，因為我不在家幫你。", "第一，找出要給爺爺的禮物。它在客廳。站在電視前面，然後向右轉。往前走三步到書櫃。盒子在第二層的中間，照片的後面。拿出來之後，把照片放回原來的位置。", "第二，把禮物拿去爺爺家。從我們家大門出去，沿著街往北走。然後在 7-Eleven 左轉。他家是那間紅色門的房子，在馬路的右邊。請把盒子放在那裡的桌上，八點前回來。謝謝你，親愛的。愛你的媽媽"], "vocab": [{"word": "top", "pos": "n.", "zh": "頂端；最上面", "example": "The cookies are at the top of the cupboard.", "exampleZh": "餅乾在櫥櫃的最上面。"}, {"word": "front", "pos": "n.", "zh": "前面", "example": "Our teacher stands at the front of the classroom.", "exampleZh": "我們的老師站在教室前面。"}, {"word": "right", "pos": "n./adv.", "zh": "右邊；向右", "example": "The bank is on your right.", "exampleZh": "銀行在你的右邊。"}, {"word": "left", "pos": "n./adv.", "zh": "左邊；向左", "example": "Turn left at the second traffic light.", "exampleZh": "在第二個紅綠燈左轉。"}, {"word": "forward", "pos": "adv.", "zh": "向前", "example": "The bus moved forward slowly.", "exampleZh": "公車慢慢向前移動。"}, {"word": "middle", "pos": "n.", "zh": "中間", "example": "There is a big table in the middle of the room.", "exampleZh": "房間中間有一張大桌子。"}, {"word": "position", "pos": "n.", "zh": "位置", "example": "Put the chairs back in their positions after class.", "exampleZh": "下課後把椅子放回原位。"}, {"word": "north", "pos": "n./adv.", "zh": "北方；向北", "example": "Keelung is to the north of Taipei.", "exampleZh": "基隆在台北的北方。"}], "phrases": [{"phrase": "in front of", "zh": "在…前面", "example": "A big dog is sitting in front of the gate.", "exampleZh": "一隻大狗坐在大門前面。"}, {"phrase": "take out", "zh": "拿出來", "example": "Take out your books and turn to page 10.", "exampleZh": "拿出你們的書，翻到第十頁。"}, {"phrase": "come back", "zh": "回來", "example": "Dad will come back from Japan on Sunday.", "exampleZh": "爸爸星期天會從日本回來。"}], "grammar": [{"pattern": "S + need + O + to + V", "explain": "「需要某人做某事」。need 後面接人，再接 to + 動詞原形。", "example": "I need you to do two things.", "exampleZh": "我需要你做兩件事。"}, {"pattern": "方位介系詞：on / in / behind / in front of + N", "explain": "描述物品位置時用介系詞片語：on 在…上、in 在…裡、behind 在…後面、in front of 在…前面。", "example": "The box is in the middle of the second shelf, behind the photos.", "exampleZh": "盒子在第二層的中間，照片的後面。"}], "reading": [{"q": "Why did Mom write this note?", "options": ["She is on a trip.", "She has to work late.", "She is at Grandpa's house.", "She is sick in bed."], "answer": 1, "explain": "第一段 I have to work late tonight，故選 (B)。"}, {"q": "Where is Jason's dinner?", "options": ["On the table", "In the bookcase", "On the top shelf of the refrigerator", "At Grandpa's house"], "answer": 2, "explain": "第一段 Your dinner is in the refrigerator, on the top shelf，故選 (C)。"}, {"q": "Where is the gift box?", "options": ["In front of the TV", "Behind the photos on the bookcase", "Under the table", "Next to the gate"], "answer": 1, "explain": "第二段 The box is in the middle of the second shelf, behind the photos，故選 (B)。"}, {"q": "How can Jason find Grandpa's house?", "options": ["Go north, turn left at the 7-Eleven, and look for a red door on the right.", "Go south and turn right at the park.", "Walk forward three steps from the gate.", "Take a bus to the north."], "answer": 0, "explain": "第三段 go north... turn left at the 7-Eleven... red door, on the right side of the road，故選 (A)。"}, {"q": "What time should Jason be home?", "options": ["Before three", "Before six", "Before seven", "Before eight"], "answer": 3, "explain": "第三段 come back before eight，故選 (D)。"}], "vocabQ": [{"q": "Jenny is the shortest, so she sits in the ____ row of the classroom.", "options": ["front", "top", "north", "middle"], "answer": 0, "explain": "句意為「Jenny 最矮，所以她坐在教室的前排」，front 前面。"}, {"q": "The cat climbed to the ____ of the tree and could not get down.", "options": ["back", "top", "left", "right"], "answer": 1, "explain": "句意為「貓爬到樹頂，下不來了」，top 頂端。"}, {"q": "Most people in Taiwan write with their ____ hand.", "options": ["middle", "north", "right", "forward"], "answer": 2, "explain": "句意為「台灣大多數人用右手寫字」，right 右邊。"}, {"q": "Please move the desk ____ a little. It is too close to the wall.", "options": ["north", "top", "middle", "forward"], "answer": 3, "explain": "句意為「請把桌子向前移一點，它離牆太近了」，forward 向前。"}, {"q": "Taipei is in the ____ of Taiwan, and Kaohsiung is in the south.", "options": ["north", "middle", "left", "front"], "answer": 0, "explain": "句意為「台北在台灣的北部，高雄在南部」，north 北方。"}]}, {"id": "E30", "level": "elem", "num": 30, "title": "A Postcard from Tainan", "titleZh": "來自台南的明信片", "theme": "Places", "themeZh": "場所", "article": ["Hi Peter, Greetings from Tainan! I am here with my family for three days. This city is very different from Taipei. There is no MRT, but the streets are full of old temples and small shops. Our hotel is downtown, near a big park.", "Yesterday morning, we visited a famous temple and a museum about the history of the city. In the afternoon, we went to a market and tried three kinds of local food. My sister bought a cake at a bakery near the market. It was the best cake I have ever eaten!", "Today we will go to the beach in the morning. Then Mom wants to visit a department store. Dad wants to see a farm in a small village near the city. Tomorrow we will drive back to Taipei. I will bring you some candy from a famous local shop. See you at school! Your friend, Emily"], "translation": ["嗨，Peter：來自台南的問候！我和家人在這裡待三天。這個城市和台北很不一樣。這裡沒有捷運，但街道上到處是古老的廟宇和小商店。我們的飯店在市中心，靠近一座大公園。", "昨天早上，我們參觀了一座有名的廟和一間關於這座城市歷史的博物館。下午我們去了市場，嚐了三種當地的食物。我妹妹在市場附近的麵包店買了一個蛋糕。那是我吃過最好吃的蛋糕！", "今天早上我們要去海邊。然後媽媽想去逛百貨公司。爸爸想去看市郊一個小村莊的農場。明天我們就開車回台北。我會帶一些有名的當地商店的糖果給你。學校見！你的朋友 Emily"], "vocab": [{"word": "temple", "pos": "n.", "zh": "廟宇", "example": "Many people go to the temple on New Year's Day.", "exampleZh": "很多人在元旦去廟裡拜拜。"}, {"word": "hotel", "pos": "n.", "zh": "飯店；旅館", "example": "We stayed at a hotel near the airport.", "exampleZh": "我們住在機場附近的一間飯店。"}, {"word": "downtown", "pos": "n./adv.", "zh": "市中心", "example": "Let's go shopping downtown this weekend.", "exampleZh": "這個週末我們去市中心購物吧。"}, {"word": "museum", "pos": "n.", "zh": "博物館", "example": "The museum is closed on Mondays.", "exampleZh": "博物館星期一休館。"}, {"word": "market", "pos": "n.", "zh": "市場", "example": "Grandma buys fresh fish at the market every morning.", "exampleZh": "奶奶每天早上在市場買新鮮的魚。"}, {"word": "bakery", "pos": "n.", "zh": "麵包店", "example": "The bakery sells the best bread in town.", "exampleZh": "這家麵包店賣鎮上最好吃的麵包。"}, {"word": "beach", "pos": "n.", "zh": "海灘", "example": "We built a sand castle on the beach.", "exampleZh": "我們在海灘上堆了一座沙堡。"}, {"word": "village", "pos": "n.", "zh": "村莊", "example": "My grandparents live in a quiet village.", "exampleZh": "我的祖父母住在一個安靜的村莊。"}], "phrases": [{"phrase": "be different from", "zh": "和…不同", "example": "Life in the country is different from life in the city.", "exampleZh": "鄉下的生活和城市的生活不同。"}, {"phrase": "be full of", "zh": "充滿", "example": "The night market is full of people on weekends.", "exampleZh": "週末時夜市擠滿了人。"}, {"phrase": "drive back", "zh": "開車回去", "example": "We drove back home after the party.", "exampleZh": "派對後我們開車回家。"}], "grammar": [{"pattern": "the + 最高級 + N + (that) + S + have ever + p.p.", "explain": "「…是某人至今…過最…的」，用最高級加上現在完成式強調經驗。", "example": "It was the best cake I have ever eaten!", "exampleZh": "那是我吃過最好吃的蛋糕！"}, {"pattern": "S + want(s) + to + V", "explain": "「想要做某事」。want 後面接 to + 動詞原形；主詞是第三人稱單數時用 wants。", "example": "Mom wants to visit a department store.", "exampleZh": "媽媽想去逛百貨公司。"}], "reading": [{"q": "Who is Emily writing to?", "options": ["Her sister", "Her teacher", "Her friend Peter", "Her grandmother"], "answer": 2, "explain": "開頭 Hi Peter 與結尾 Your friend, Emily 可知收信人是朋友 Peter，故選 (C)。"}, {"q": "How is Tainan different from Taipei, according to Emily?", "options": ["It has a bigger MRT.", "It has no MRT but many old temples.", "It has no parks.", "It has more department stores."], "answer": 1, "explain": "第一段 There is no MRT, but the streets are full of old temples，故選 (B)。"}, {"q": "What did Emily's family do yesterday afternoon?", "options": ["They went to the beach.", "They visited a museum.", "They went to a market.", "They drove back to Taipei."], "answer": 2, "explain": "第二段 In the afternoon, we went to a market，故選 (C)。"}, {"q": "Where did Emily's sister buy the cake?", "options": ["At a bakery near the market", "At the hotel", "At a department store", "At the museum"], "answer": 0, "explain": "第二段 My sister bought a cake at a bakery near the market，故選 (A)。"}, {"q": "What will Emily's family do tomorrow?", "options": ["Visit a farm", "Go to the beach", "Stay at the hotel", "Drive back to Taipei"], "answer": 3, "explain": "第三段 Tomorrow we will drive back to Taipei，故選 (D)。"}], "vocabQ": [{"q": "We will stay at a ____ near the train station for two nights.", "options": ["hotel", "temple", "factory", "bank"], "answer": 0, "explain": "句意為「我們會在火車站附近的飯店住兩晚」，hotel 飯店。"}, {"q": "My aunt lives in a small ____ in the mountains, far from the city.", "options": ["mall", "village", "office", "pool"], "answer": 1, "explain": "句意為「我阿姨住在山裡一個離城市很遠的小村莊」，village 村莊。"}, {"q": "Don't forget your swimsuit. We are going to the ____ this afternoon.", "options": ["museum", "bakery", "beach", "church"], "answer": 2, "explain": "句意為「別忘了泳衣，我們今天下午要去海邊」，beach 海灘。"}, {"q": "The ____ has many old paintings and things from a thousand years ago.", "options": ["bakery", "market", "hotel", "museum"], "answer": 3, "explain": "句意為「博物館有很多古老的畫和一千年前的東西」，museum 博物館。"}, {"q": "The ____ is busy this morning because many people are buying vegetables.", "options": ["market", "beach", "temple", "village"], "answer": 0, "explain": "句意為「今天早上市場很忙，因為很多人在買菜」，market 市場。"}]}, {"id": "E31", "level": "elem", "num": 31, "title": "A Day Full of Wheels", "titleZh": "充滿車輪的一天", "theme": "Transportation", "themeZh": "交通工具", "article": ["Last Sunday, my family took Grandpa to the airport. He was flying to Japan to see his old friend. We did not drive our car because the traffic on the highway is always heavy on weekends. Instead, we walked to the bus stop near our house and took a bus to the MRT station.", "On the MRT, Grandpa looked out of the window like a child. We crossed a long bridge over the river. He pointed at a boat, a truck, and even a helicopter in the sky. A young passenger smiled and gave him her seat. When we got off at the train station, we went down to the platform and waited for the airport train.", "At the airport, we saw many airplanes. Grandpa walked slowly to the gate. He turned around and waved to us. On the way home, we took a taxi because we were tired. Our taxi had a flat tire on the bridge, and we had to wait on the sidewalk for twenty minutes! It was a long day, but it was full of wheels and fun."], "translation": ["上星期日，我們全家送爺爺去機場。他要飛去日本看他的老朋友。我們沒有開自己的車，因為週末高速公路上的車流總是很擁擠。我們改成走到家附近的公車站，搭公車到捷運站。", "在捷運上，爺爺像個孩子一樣望著窗外。我們跨過一座橫越河面的長橋。他指著一艘船、一輛卡車，甚至還有天上的一架直升機。一位年輕的乘客微笑著把座位讓給他。我們在火車站下車後，走下月台，等候機場線的列車。", "在機場，我們看到許多飛機。爺爺慢慢地走向登機門。他轉過身來向我們揮手。回家的路上，我們因為累了而搭計程車。我們的計程車在橋上爆胎了，我們只好在人行道上等了二十分鐘！那是漫長的一天，但充滿了車輪和樂趣。"], "vocab": [{"word": "airport", "pos": "n.", "zh": "機場", "example": "We arrived at the airport two hours early.", "exampleZh": "我們提早兩小時到達機場。"}, {"word": "traffic", "pos": "n.", "zh": "交通、車流", "example": "The traffic is heavy at eight in the morning.", "exampleZh": "早上八點的車流很擁擠。"}, {"word": "highway", "pos": "n.", "zh": "公路、高速公路", "example": "Cars drive very fast on the highway.", "exampleZh": "車子在高速公路上開得很快。"}, {"word": "bus stop", "pos": "n.", "zh": "公車站牌", "example": "There is a bus stop in front of the bank.", "exampleZh": "銀行前面有一個公車站牌。"}, {"word": "passenger", "pos": "n.", "zh": "乘客", "example": "Every passenger must wear a seat belt.", "exampleZh": "每位乘客都必須繫安全帶。"}, {"word": "platform", "pos": "n.", "zh": "月台", "example": "The train to Tainan leaves from platform 2.", "exampleZh": "往台南的火車從第二月台發車。"}, {"word": "taxi", "pos": "n.", "zh": "計程車", "example": "Let's take a taxi; it is raining hard.", "exampleZh": "我們搭計程車吧，雨下得很大。"}, {"word": "flat tire", "pos": "n.", "zh": "爆胎、洩氣的輪胎", "example": "My bike has a flat tire, so I walked to school.", "exampleZh": "我的腳踏車爆胎了，所以我走路上學。"}], "phrases": [{"phrase": "take someone to", "zh": "送某人去（某地）", "example": "Dad takes me to school every morning.", "exampleZh": "爸爸每天早上送我去學校。"}, {"phrase": "get off", "zh": "下車", "example": "We get off at the next station.", "exampleZh": "我們在下一站下車。"}, {"phrase": "on the way home", "zh": "在回家的路上", "example": "I bought some bread on the way home.", "exampleZh": "我在回家的路上買了一些麵包。"}], "grammar": [{"pattern": "S + did not + V ... because + S + V", "explain": "because 引導原因子句，說明前面動作的理由。過去式否定用 did not（didn't）加原形動詞。", "example": "We did not go out because it rained.", "exampleZh": "因為下雨，我們沒有出門。"}, {"pattern": "S + had to + V", "explain": "have to 表示「必須」，過去式為 had to，後面接原形動詞，表示因情況所迫不得不做某事。", "example": "The bus was late, so I had to run to school.", "exampleZh": "公車遲到了，所以我必須跑著去學校。"}], "reading": [{"q": "Why did the family take a bus and the MRT instead of driving?", "options": ["Their car had a flat tire.", "The traffic on the highway is heavy on weekends.", "Grandpa does not like cars.", "The airport has no parking lot."], "answer": 1, "explain": "第一段提到「We did not drive our car because the traffic on the highway is always heavy on weekends」，故選 (B)。"}, {"q": "What did the young passenger do on the MRT?", "options": ["She took a picture of Grandpa.", "She pointed at a helicopter.", "She gave Grandpa her seat.", "She showed them the way to the platform."], "answer": 2, "explain": "第二段說「A young passenger smiled and gave him her seat」，故選 (C)。"}, {"q": "Where did the taxi have a flat tire?", "options": ["On the bridge.", "On the highway.", "At the bus stop.", "In the parking lot."], "answer": 0, "explain": "第三段提到「Our taxi had a flat tire on the bridge」，故選 (A)。"}, {"q": "Which of the following did the writer NOT see on the trip?", "options": ["A boat.", "A helicopter.", "A truck.", "An ambulance."], "answer": 3, "explain": "第二段提到看見 boat、truck、helicopter，文中沒有提到救護車，故選 (D)。"}, {"q": "How did the writer feel about the day?", "options": ["It was boring and too long.", "It was tiring but fun.", "It was short and quiet.", "It was scary because of the flat tire."], "answer": 1, "explain": "最後一句「It was a long day, but it was full of wheels and fun」表示雖然漫長但很有趣，故選 (B)。"}], "vocabQ": [{"q": "Please wait on the ____ until the train stops.", "options": ["platform", "wheel", "bridge", "path"], "answer": 0, "explain": "等火車停下來前要在「月台」上等候，platform 月台。"}, {"q": "There was a lot of ____ this morning, so Dad was late for work.", "options": ["air", "traffic", "sidewalk", "weather"], "answer": 1, "explain": "句意為「今早車流很多，所以爸爸上班遲到了」，traffic 交通、車流。"}, {"q": "My aunt lives far away, so we took the ____ to visit her.", "options": ["bus stop", "station", "highway", "overpass"], "answer": 2, "explain": "去遠方拜訪要走「高速公路」，highway。"}, {"q": "The plane was late, so every ____ had to wait at the gate.", "options": ["driver", "passenger", "sailor", "worker"], "answer": 1, "explain": "飛機誤點，在登機門等候的是「乘客」，passenger。"}, {"q": "I can't ride my bike today because it has a ____.", "options": ["ticket", "wheel", "flat tire", "seat"], "answer": 2, "explain": "句意為「今天不能騎腳踏車，因為它爆胎了」，flat tire 爆胎。"}]}, {"id": "E32", "level": "elem", "num": 32, "title": "My First Ride to School", "titleZh": "我第一次騎車上學", "theme": "Transport Verbs & Speed", "themeZh": "交通動詞與速度", "article": ["Tuesday, May 5, Rainy. Dear Diary, today I rode my bicycle to school for the first time. My father usually drives me, but his car was at the repair shop. I was worried because I am a slow rider, and the roads were wet after the rain.", "I left home at seven. First, I had to cross a busy street. Then I turned left at the park and rode along the river. Some cars were driving very fast, so I stayed on the bike path. A quick little dog ran beside me for a minute. Above the river, a white bird flew low and landed on a boat. The boat sailed slowly under the bridge. It was a beautiful morning after all.", "I arrived at school at seven forty. I was not late! My legs were tired, but I felt proud. My friend Tina said, \"You were faster than the school bus today.\" Tomorrow I will ride again. Maybe I am not so slow."], "translation": ["五月五日，星期二，雨天。親愛的日記，今天我第一次騎腳踏車上學。平常都是爸爸開車載我，但他的車送去修車廠了。我很擔心，因為我騎得很慢，而且雨後的路面很濕。", "我七點出門。首先，我得穿過一條繁忙的街道。接著我在公園左轉，沿著河邊騎。有些車開得很快，所以我一直待在自行車道上。一隻動作敏捷的小狗在我旁邊跑了一分鐘。河面上，一隻白鳥低飛，降落在一艘船上。那艘船慢慢地從橋下駛過。這畢竟是個美好的早晨。", "我七點四十分到學校。我沒有遲到！我的腿很累，但我覺得很驕傲。我的朋友 Tina 說：「你今天比校車還快。」明天我還要再騎。也許我沒有那麼慢。"], "vocab": [{"word": "ride", "pos": "v.", "zh": "騎（車、馬）、搭乘", "example": "I ride my scooter to the night market.", "exampleZh": "我騎機車去夜市。"}, {"word": "drive", "pos": "v.", "zh": "開車、駕駛", "example": "My mother drives to work every day.", "exampleZh": "我媽媽每天開車上班。"}, {"word": "cross", "pos": "v.", "zh": "穿越、橫過", "example": "Look both ways before you cross the road.", "exampleZh": "過馬路前要先看兩邊。"}, {"word": "turn", "pos": "v.", "zh": "轉彎、轉向", "example": "Turn right at the second traffic light.", "exampleZh": "在第二個紅綠燈右轉。"}, {"word": "arrive", "pos": "v.", "zh": "到達", "example": "The train will arrive at ten o'clock.", "exampleZh": "火車將在十點到達。"}, {"word": "fast", "pos": "adj./adv.", "zh": "快速的；快速地", "example": "The MRT is fast and clean.", "exampleZh": "捷運又快又乾淨。"}, {"word": "slow", "pos": "adj.", "zh": "慢的", "example": "The old bus is very slow on the hill.", "exampleZh": "那輛舊公車在山坡上非常慢。"}, {"word": "quick", "pos": "adj.", "zh": "迅速的、敏捷的", "example": "She gave me a quick answer.", "exampleZh": "她很快地回答了我。"}], "phrases": [{"phrase": "for the first time", "zh": "第一次", "example": "I saw snow for the first time last winter.", "exampleZh": "去年冬天我第一次看到雪。"}, {"phrase": "after all", "zh": "畢竟、終究", "example": "The test was not hard after all.", "exampleZh": "考試畢竟沒有那麼難。"}, {"phrase": "along the river", "zh": "沿著河邊", "example": "We walked along the river at night.", "exampleZh": "我們晚上沿著河邊散步。"}], "grammar": [{"pattern": "S + be + 比較級 + than + ...", "explain": "形容詞比較級用來比較兩者。短的形容詞加 -er（fast → faster），後面接 than 表示「比…更…」。", "example": "A scooter is faster than a bicycle.", "exampleZh": "機車比腳踏車快。"}, {"pattern": "S + V ..., so + S + V ...", "explain": "so 連接兩個句子，表示「所以」，前面是原因，後面是結果。注意 so 前面要有逗號。", "example": "It was raining, so we stayed at home.", "exampleZh": "當時在下雨，所以我們待在家裡。"}], "reading": [{"q": "Why did the writer ride a bicycle to school today?", "options": ["The school bus was too slow.", "Her father's car was at the repair shop.", "She wanted to be faster than Tina.", "The MRT was closed because of the rain."], "answer": 1, "explain": "第一段說「My father usually drives me, but his car was at the repair shop」，故選 (B)。"}, {"q": "Why did the writer stay on the bike path?", "options": ["The street was too busy to cross.", "A dog was running beside her.", "Some cars were driving very fast.", "The path was shorter."], "answer": 2, "explain": "第二段提到「Some cars were driving very fast, so I stayed on the bike path」，故選 (C)。"}, {"q": "What did the white bird do?", "options": ["It flew over the bridge.", "It landed on a boat.", "It followed the writer.", "It sat on the bike path."], "answer": 1, "explain": "第二段說「a white bird flew low and landed on a boat」，故選 (B)。"}, {"q": "What time did the writer get to school?", "options": ["At seven.", "At seven twenty.", "At seven forty.", "At eight."], "answer": 2, "explain": "第三段開頭「I arrived at school at seven forty」，故選 (C)。"}, {"q": "How does the writer feel at the end of the diary?", "options": ["Tired and sad.", "Proud and hopeful.", "Angry at her father.", "Afraid of the road."], "answer": 1, "explain": "第三段說「I felt proud」以及「Tomorrow I will ride again」，表示驕傲且期待再騎，故選 (B)。"}], "vocabQ": [{"q": "Be careful when you ____ the street; the cars don't always stop.", "options": ["cross", "land", "sail", "turn"], "answer": 0, "explain": "句意為「過街時要小心，車子不一定會停」，cross 穿越。"}, {"q": "If you ____ left here, you will see the post office.", "options": ["fly", "turn", "ride", "arrive"], "answer": 1, "explain": "句意為「在這裡左轉就會看到郵局」，turn 轉彎。"}, {"q": "Our guests will ____ at six, so let's cook dinner now.", "options": ["drive", "cross", "arrive", "sail"], "answer": 2, "explain": "客人六點會「到達」，所以現在開始煮晚餐，arrive。"}, {"q": "The turtle is very ____; it takes an hour to cross the garden.", "options": ["fast", "quick", "slow", "wet"], "answer": 2, "explain": "烏龜要花一小時穿過花園，表示很「慢」，slow。"}, {"q": "My uncle can ____ a truck, a bus, and a taxi.", "options": ["drive", "ride", "fly", "land"], "answer": 0, "explain": "卡車、公車、計程車都是「開」的，drive 駕駛。"}]}, {"id": "E33", "level": "elem", "num": 33, "title": "How to Make Your Own Kite", "titleZh": "如何自己做風箏", "theme": "Measurements", "themeZh": "度量衡", "article": ["Do you want to fly a kite this weekend? You do not need to buy one. Follow these steps and make your own kite in thirty minutes. First, get a large sheet of paper. It should be about 60 centimeters long and 40 centimeters wide. A rectangle shape works best.", "Second, draw a dot in the middle of the top edge and another dot at the bottom. Draw a straight line between the two dots. Then draw a line across the paper, about 20 centimeters from the top. Now you have four triangles on the paper. Cut along the outside lines, and you will get a diamond shape. Third, tape two thin sticks along the lines. Each stick should weigh less than 10 grams, or the kite will be too heavy to fly.", "Finally, tie a string to the point where the two sticks meet. Your string should be at least 30 meters long. Walk to an open field, hold the string, and run! Your kite may fly as high as 50 meters. You cannot measure that with a ruler, so just look up and enjoy the sky."], "translation": ["這個週末你想放風箏嗎？你不需要買一個。照著這些步驟，三十分鐘內就能做出自己的風箏。首先，拿一張大紙。大約 60 公分長、40 公分寬。長方形最合適。", "第二步，在上方邊緣的中間點一個點，底部再點另一個點。在兩點之間畫一條直線。接著在距離上方大約 20 公分的地方，橫著畫一條線。現在紙上有四個三角形了。沿著外側的線剪開，你就會得到一個菱形。第三步，沿著線用膠帶貼上兩根細棒子。每根棒子應該少於 10 公克，否則風箏會太重飛不起來。", "最後，在兩根棒子交會的那一點綁上一條線。你的線至少要 30 公尺長。走到空曠的場地，握住線，然後跑！你的風箏可能飛到 50 公尺高。那無法用尺測量，所以就抬頭享受天空吧。"], "vocab": [{"word": "centimeter", "pos": "n.", "zh": "公分", "example": "This pencil is 15 centimeters long.", "exampleZh": "這枝鉛筆 15 公分長。"}, {"word": "rectangle", "pos": "n.", "zh": "長方形", "example": "A door is usually a rectangle.", "exampleZh": "門通常是長方形的。"}, {"word": "dot", "pos": "n.", "zh": "點、小圓點", "example": "Her dress has little red dots on it.", "exampleZh": "她的洋裝上有小紅點。"}, {"word": "line", "pos": "n.", "zh": "線、直線", "example": "Please draw a line under the new words.", "exampleZh": "請在新單字下面畫線。"}, {"word": "triangle", "pos": "n.", "zh": "三角形", "example": "A triangle has three sides.", "exampleZh": "三角形有三個邊。"}, {"word": "shape", "pos": "n.", "zh": "形狀", "example": "The cookies come in different shapes.", "exampleZh": "這些餅乾有不同的形狀。"}, {"word": "gram", "pos": "n.", "zh": "公克", "example": "This cake needs 200 grams of sugar.", "exampleZh": "這個蛋糕需要 200 公克的糖。"}, {"word": "meter", "pos": "n.", "zh": "公尺", "example": "The swimming pool is 25 meters long.", "exampleZh": "這座游泳池 25 公尺長。"}], "phrases": [{"phrase": "at least", "zh": "至少", "example": "You should sleep at least eight hours.", "exampleZh": "你應該至少睡八小時。"}, {"phrase": "as high as", "zh": "高達、和…一樣高", "example": "The tree is as high as our house.", "exampleZh": "那棵樹和我們的房子一樣高。"}, {"phrase": "in the middle of", "zh": "在…的中間", "example": "There is a table in the middle of the room.", "exampleZh": "房間中間有一張桌子。"}], "grammar": [{"pattern": "S + should + V", "explain": "should 是助動詞，表示「應該」，用來給建議或說明標準，後面接原形動詞。", "example": "The paper should be 40 centimeters wide.", "exampleZh": "紙應該要 40 公分寬。"}, {"pattern": "S + be + too + adj. + to + V", "explain": "「太…而不能…」，表示程度過高，導致無法做某事。to 後面接原形動詞。", "example": "The box is too heavy to carry.", "exampleZh": "這個箱子太重了，搬不動。"}], "reading": [{"q": "What is the article mainly about?", "options": ["Where to buy a cheap kite.", "How to make a kite at home.", "Why kites fly high.", "The history of kites."], "answer": 1, "explain": "全文依步驟說明如何自己做風箏，故選 (B)。"}, {"q": "How wide should the paper be?", "options": ["20 centimeters.", "30 centimeters.", "40 centimeters.", "60 centimeters."], "answer": 2, "explain": "第一段提到「about 60 centimeters long and 40 centimeters wide」，寬是 40 公分，故選 (C)。"}, {"q": "What shape will you get after cutting the paper?", "options": ["A circle.", "A square.", "A triangle.", "A diamond."], "answer": 3, "explain": "第二段說「Cut along the outside lines, and you will get a diamond shape」，故選 (D)。"}, {"q": "Why should each stick weigh less than 10 grams?", "options": ["Light sticks are cheaper.", "A heavy kite cannot fly.", "The tape is not strong.", "The string may break."], "answer": 1, "explain": "第二段說「or the kite will be too heavy to fly」，太重就飛不起來，故選 (B)。"}, {"q": "The word \"point\" in paragraph 3 is closest in meaning to ____.", "options": ["a small place or spot", "a sharp knife", "a score in a game", "an idea"], "answer": 0, "explain": "第三段「the point where the two sticks meet」指兩根棒子交會的「那個位置、點」，故選 (A)。"}], "vocabQ": [{"q": "A ____ is much shorter than a meter; there are 100 of them in one meter.", "options": ["gram", "kilometer", "centimeter", "kilogram"], "answer": 2, "explain": "一公尺有 100 個，比公尺短很多的單位是「公分」，centimeter。"}, {"q": "A door is a ____: it has two long sides and two short sides.", "options": ["circle", "rectangle", "triangle", "dot"], "answer": 1, "explain": "兩個長邊、兩個短邊的形狀是「長方形」，rectangle。"}, {"q": "Stand on the red ____ on the floor and wait for your turn.", "options": ["dot", "row", "shape", "yard"], "answer": 0, "explain": "站在地板上的紅「點」上等候，dot 點。"}, {"q": "One ____ is 100 centimeters long.", "options": ["gram", "meter", "inch", "liter"], "answer": 1, "explain": "一「公尺」等於 100 公分，meter。"}, {"q": "What ____ is the moon tonight? It looks like a banana.", "options": ["shape", "point", "row", "line"], "answer": 0, "explain": "問月亮是什麼「形狀」，shape。"}]}, {"id": "E34", "level": "elem", "num": 34, "title": "Which Backpack Should I Buy?", "titleZh": "我該買哪個背包？", "theme": "Size & Shape", "themeZh": "大小與形狀", "article": ["Subject: Help! Which backpack should I buy? Hi Jenny, I need your help. My old backpack is too small for senior high school, so Mom gave me 1,200 dollars for a new one. I went to three shops yesterday, but I could not choose. Can you give me some advice?", "The first backpack is large and has a wide pocket for a laptop. But it is heavy. Its weight is almost two kilograms before I put anything in it! The second one is a medium size and very light. It has a narrow pocket for a water bottle and a small round pocket for my keys. However, it is a little short, so my long ruler will not fit. The third one is tiny but cute. It is only the size of a loaf of bread.", "I think the second one is the best. I walk a long distance to school every day, so a light bag is important. I can keep my ruler in a package at school. What do you think? Please write back soon! Love, Amy"], "translation": ["主旨：救命！我該買哪個背包？嗨，Jenny，我需要妳的幫忙。我的舊背包對高中來說太小了，所以媽媽給我一千兩百元買新的。我昨天去了三家店，但是沒辦法決定。妳可以給我一些建議嗎？", "第一個背包很大，有一個寬的口袋可以放筆電。但它很重。還沒放任何東西，它的重量就將近兩公斤！第二個是中尺寸，而且非常輕。它有一個窄口袋放水壺，還有一個小圓口袋放我的鑰匙。不過它有點短，所以我的長尺放不進去。第三個很迷你但很可愛。它只有一條麵包那麼大。", "我覺得第二個最好。我每天走很長的距離上學，所以輕的包包很重要。我可以把尺放在學校的一個包裝盒裡。妳覺得呢？請快點回信！愛妳的 Amy"], "vocab": [{"word": "large", "pos": "adj.", "zh": "大的", "example": "We ordered a large pizza for the party.", "exampleZh": "我們為派對訂了一個大披薩。"}, {"word": "wide", "pos": "adj.", "zh": "寬的", "example": "The new road is wide enough for four cars.", "exampleZh": "新的路寬到可以容納四輛車。"}, {"word": "weight", "pos": "n.", "zh": "重量", "example": "The doctor checked my height and weight.", "exampleZh": "醫生檢查了我的身高和體重。"}, {"word": "medium", "pos": "adj.", "zh": "中等的", "example": "I would like a medium coffee, please.", "exampleZh": "請給我一杯中杯咖啡。"}, {"word": "light", "pos": "adj.", "zh": "輕的", "example": "This jacket is light but very warm.", "exampleZh": "這件外套很輕但很保暖。"}, {"word": "narrow", "pos": "adj.", "zh": "窄的", "example": "The old street is too narrow for buses.", "exampleZh": "這條老街太窄，公車進不來。"}, {"word": "bottle", "pos": "n.", "zh": "瓶子", "example": "Bring a bottle of water to the game.", "exampleZh": "帶一瓶水去看比賽。"}, {"word": "distance", "pos": "n.", "zh": "距離", "example": "The distance from my home to school is two kilometers.", "exampleZh": "我家到學校的距離是兩公里。"}], "phrases": [{"phrase": "write back", "zh": "回信", "example": "I hope you can write back this week.", "exampleZh": "希望你這星期能回信。"}, {"phrase": "a little", "zh": "有一點", "example": "The soup is a little salty.", "exampleZh": "這湯有一點鹹。"}, {"phrase": "the size of", "zh": "…的大小", "example": "The phone is the size of my hand.", "exampleZh": "這支手機跟我的手一樣大。"}], "grammar": [{"pattern": "S + be + too + adj. + for + N", "explain": "too 加形容詞表示「太…」，後面用 for 說明對誰或對什麼來說太過。", "example": "These shoes are too big for me.", "exampleZh": "這雙鞋對我來說太大了。"}, {"pattern": "However, + S + V ...", "explain": "however 意思是「然而」，用來轉折語氣，放在句首時後面加逗號，功能類似 but，但語氣較正式。", "example": "The bag is cute. However, it is expensive.", "exampleZh": "這個包包很可愛。然而，它很貴。"}], "reading": [{"q": "Why is Amy writing this email?", "options": ["To ask Jenny to lend her money.", "To ask Jenny for advice about a backpack.", "To invite Jenny to go shopping.", "To tell Jenny about her new school."], "answer": 1, "explain": "第一段「Can you give me some advice?」說明寫信目的是請 Jenny 給建議，故選 (B)。"}, {"q": "What is the problem with the first backpack?", "options": ["It is too small.", "It is too heavy.", "It is too short.", "It has no pocket for a laptop."], "answer": 1, "explain": "第二段提到第一個背包「But it is heavy. Its weight is almost two kilograms」，故選 (B)。"}, {"q": "What will NOT fit in the second backpack?", "options": ["A water bottle.", "A set of keys.", "A long ruler.", "A laptop."], "answer": 2, "explain": "第二段說第二個「it is a little short, so my long ruler will not fit」，故選 (C)。"}, {"q": "Which backpack does Amy like best, and why?", "options": ["The first one, because it is large.", "The second one, because it is light.", "The third one, because it is cute.", "The third one, because it is cheap."], "answer": 1, "explain": "第三段說「I think the second one is the best ... a light bag is important」，故選 (B)。"}, {"q": "The word \"tiny\" in paragraph 2 is closest in meaning to ____.", "options": ["very small", "very heavy", "very wide", "very round"], "answer": 0, "explain": "tiny 意為「極小的」，與文中「It is only the size of a loaf of bread」相呼應，故選 (A)。"}], "vocabQ": [{"q": "The box is very ____, so even a child can carry it.", "options": ["light", "deep", "high", "wide"], "answer": 0, "explain": "連小孩都搬得動，表示箱子很「輕」，light。"}, {"q": "The river is so ____ that we need a long bridge to cross it.", "options": ["narrow", "wide", "short", "low"], "answer": 1, "explain": "需要長橋才能跨過，表示河很「寬」，wide。"}, {"q": "Please tell me the ____ of the package so I can pay for the mail.", "options": ["weight", "size", "shape", "height"], "answer": 0, "explain": "郵資依包裹「重量」計算，weight。"}, {"q": "The ____ between Taipei and Kaohsiung is about 350 kilometers.", "options": ["amount", "height", "distance", "weight"], "answer": 2, "explain": "台北到高雄約 350 公里，這是「距離」，distance。"}, {"q": "This T-shirt comes in small, ____, and large.", "options": ["medium", "extra", "tiny", "straight"], "answer": 0, "explain": "衣服尺寸小、「中」、大，medium 中等的。"}]}, {"id": "E35", "level": "elem", "num": 35, "title": "A New Friend from Far Away", "titleZh": "來自遠方的新朋友", "theme": "Countries", "themeZh": "國家", "article": ["\"Good morning, everyone. This is Ethan. He comes from the U.S.A.,\" said Ms. Lin. Ethan smiled and said hello in Chinese. The whole class laughed and clapped. \"Which part of America are you from?\" asked Kevin. \"Texas,\" Ethan said. \"It is a big state. You can drive for a whole day and still be in Texas!\"", "At lunch, Ethan asked many questions about Taiwan. \"Is Taiwan a country or an island?\" he asked. \"Both,\" Wendy answered. \"Taiwan is an island, and our nation's full name is the Republic of China, or the R.O.C.\" Ethan looked surprised. \"Is that the same as China?\" \"No,\" said Kevin. \"China is across the sea. We have our own government and our own money.\"", "After school, the class took Ethan to a night market. He tried stinky tofu and shouted, \"This is the best food in the world!\" Everyone laughed again. Ethan said he wants to learn more Chinese and visit every country in Asia. \"Now I have friends in Taiwan,\" he said. \"The world feels smaller today.\""], "translation": ["「各位早安。這位是 Ethan。他來自美國。」林老師說。Ethan 微笑著用中文說哈囉。全班都笑了，還鼓掌。「你來自美國的哪一區？」Kevin 問。「德州。」Ethan 說。「那是一個很大的州。你可以開一整天的車，還是在德州裡面！」", "午餐時，Ethan 問了很多關於台灣的問題。「台灣是一個國家還是一座島？」他問。「都是。」Wendy 回答。「台灣是一座島，而我們國家的全名是中華民國，也就是 R.O.C.。」Ethan 看起來很驚訝。「那跟中國一樣嗎？」「不一樣。」Kevin 說。「中國在海的另一邊。我們有自己的政府和自己的貨幣。」", "放學後，全班帶 Ethan 去夜市。他試了臭豆腐，大喊：「這是全世界最好吃的食物！」大家又笑了。Ethan 說他想學更多中文，也想走訪亞洲的每一個國家。「現在我在台灣有朋友了。」他說。「今天世界感覺變小了。」"], "vocab": [{"word": "country", "pos": "n.", "zh": "國家", "example": "Japan is a country in Asia.", "exampleZh": "日本是亞洲的一個國家。"}, {"word": "nation", "pos": "n.", "zh": "國家、民族", "example": "People from many nations came to the game.", "exampleZh": "來自許多國家的人來看這場比賽。"}, {"word": "world", "pos": "n.", "zh": "世界", "example": "Taipei 101 was once the tallest building in the world.", "exampleZh": "台北 101 曾經是世界上最高的建築。"}, {"word": "America", "pos": "n.", "zh": "美國、美洲", "example": "My cousin studies in America.", "exampleZh": "我的表哥在美國讀書。"}, {"word": "U.S.A", "pos": "n.", "zh": "美國（美利堅合眾國）", "example": "New York is a big city in the U.S.A.", "exampleZh": "紐約是美國的一個大城市。"}, {"word": "Taiwan", "pos": "n.", "zh": "台灣", "example": "Taiwan is famous for its night markets.", "exampleZh": "台灣以夜市聞名。"}, {"word": "China", "pos": "n.", "zh": "中國", "example": "The Great Wall is in China.", "exampleZh": "長城在中國。"}, {"word": "Chinese", "pos": "n./adj.", "zh": "中文；中國的、華人的", "example": "Ethan is learning Chinese at school.", "exampleZh": "Ethan 在學校學中文。"}], "phrases": [{"phrase": "come from", "zh": "來自", "example": "My teacher comes from Canada.", "exampleZh": "我的老師來自加拿大。"}, {"phrase": "the same as", "zh": "和…一樣", "example": "Your bag is the same as mine.", "exampleZh": "你的包包和我的一樣。"}, {"phrase": "across the sea", "zh": "在海的另一邊", "example": "Japan is across the sea from Taiwan.", "exampleZh": "日本在台灣隔海的另一邊。"}], "grammar": [{"pattern": "\"...,\" said + S. / \"...,\" + S + said.", "explain": "直接引述說話內容時，引號內放原話，後面用 said 說明是誰說的。主詞是名詞時可寫成 said Ms. Lin 或 Ms. Lin said。", "example": "\"I am from Texas,\" said Ethan.", "exampleZh": "「我來自德州。」Ethan 說。"}, {"pattern": "S + look(s) + adj.", "explain": "look 當連綴動詞，意思是「看起來」，後面直接接形容詞，不接副詞。", "example": "You look tired today.", "exampleZh": "你今天看起來很累。"}], "reading": [{"q": "Where is Ethan from?", "options": ["Taiwan.", "China.", "The U.S.A.", "Japan."], "answer": 2, "explain": "第一段林老師說「He comes from the U.S.A.」，故選 (C)。"}, {"q": "What does Ethan say about Texas?", "options": ["It is very small.", "It is a big state.", "It is across the sea.", "It is the best place for food."], "answer": 1, "explain": "第一段 Ethan 說「It is a big state. You can drive for a whole day and still be in Texas」，故選 (B)。"}, {"q": "According to Wendy, what is the full name of our nation?", "options": ["Taiwan Island.", "The United States.", "The Republic of China.", "The People's Nation."], "answer": 2, "explain": "第二段 Wendy 說「our nation's full name is the Republic of China, or the R.O.C.」，故選 (C)。"}, {"q": "Why did everyone laugh at the night market?", "options": ["Ethan could not eat stinky tofu.", "Ethan said stinky tofu was the best food in the world.", "Kevin told a joke.", "Ethan said hello in Chinese."], "answer": 1, "explain": "第三段寫 Ethan 大喊「This is the best food in the world!」，大家又笑了，故選 (B)。"}, {"q": "What does Ethan mean by \"The world feels smaller today\"?", "options": ["Taiwan is a small island.", "He is tired after a long day.", "Having friends far away makes places feel closer.", "He wants to go home soon."], "answer": 2, "explain": "由前一句「Now I have friends in Taiwan」可推論，有了遠方的朋友，世界感覺變近變小了，故選 (C)。"}], "vocabQ": [{"q": "Japan is a ____ in Asia with its own language and government.", "options": ["country", "city", "world", "island"], "answer": 0, "explain": "有自己語言和政府的是「國家」，country。"}, {"q": "English is spoken in many parts of the ____.", "options": ["nation", "world", "island", "state"], "answer": 1, "explain": "英語在「世界」許多地方都有人說，world。"}, {"q": "Mr. Wang is ____, but he has lived in Canada for twenty years.", "options": ["American", "Chinese", "Japanese", "English"], "answer": 1, "explain": "句意為「王先生是華人，但已在加拿大住了二十年」，Chinese 華人的。"}, {"q": "____ is an island, so you need a plane or a ship to get here.", "options": ["America", "China", "Taiwan", "Texas"], "answer": 2, "explain": "「台灣」是島，所以要搭飛機或船才能來，Taiwan。"}, {"q": "Washington, D.C. is the capital of the ____.", "options": ["R.O.C", "U.S.A", "Chinese", "Taiwan"], "answer": 1, "explain": "華盛頓特區是「美國」的首都，U.S.A。"}]}, {"id": "E36", "level": "elem", "num": 36, "title": "Join Our Festival Night!", "titleZh": "來參加我們的節慶之夜！", "theme": "Festivals & Holidays", "themeZh": "節日與慶祝", "article": ["Dear students and parents, the winter vacation is coming, and Chinese New Year is only two weeks away. Before the holiday, our school will celebrate the season with a special event: Festival Night! It will be held in the school gym on Friday, January 23, from 6 p.m. to 8:30 p.m. Everyone is welcome.", "At Festival Night, you can learn about customs from around the world. Our English teachers will show how people celebrate Christmas in America. Grade 8 students will perform a dragon dance for Chinese New Year. In the art room, you can make your own paper lantern for the Lantern Festival. There will also be a photo wall with pictures from last year's Moon Festival barbecue. Bring your family and make a happy memory together!", "Please remember these rules. Wear your school jacket. Do not bring fireworks. Food and drinks will be sold in the hall, so bring some money. If it rains, the event will still take place. We hope to see you there. Have a wonderful holiday and a great new year! The Student Activity Office"], "translation": ["親愛的同學與家長，寒假即將來臨，距離農曆新年也只剩兩個星期。放假之前，本校將以一場特別的活動來慶祝這個季節：節慶之夜！活動將於一月二十三日（星期五）晚上六點到八點半在學校體育館舉行。歡迎大家參加。", "在節慶之夜，你可以認識來自世界各地的習俗。我們的英文老師會展示美國人如何慶祝聖誕節。八年級的同學將為農曆新年表演舞龍。在美術教室，你可以為元宵節做一個自己的紙燈籠。另外還有一面照片牆，展出去年中秋節烤肉的照片。帶著家人一起來，共同留下快樂的回憶吧！", "請記住以下規定。請穿學校外套。不要攜帶煙火。大廳會販售食物和飲料，所以請帶一些錢。如果下雨，活動仍照常舉行。我們希望在那裡見到你。祝假期愉快，新年快樂！學生活動組"], "vocab": [{"word": "vacation", "pos": "n.", "zh": "假期", "example": "We went to Kenting during the summer vacation.", "exampleZh": "暑假期間我們去了墾丁。"}, {"word": "Chinese New Year", "pos": "n.", "zh": "農曆新年", "example": "Children get red envelopes on Chinese New Year.", "exampleZh": "小孩在農曆新年會拿到紅包。"}, {"word": "holiday", "pos": "n.", "zh": "假日、節日", "example": "Tomorrow is a holiday, so there is no school.", "exampleZh": "明天是假日，所以不用上學。"}, {"word": "celebrate", "pos": "v.", "zh": "慶祝", "example": "How do you celebrate your birthday?", "exampleZh": "你怎麼慶祝你的生日？"}, {"word": "custom", "pos": "n.", "zh": "習俗", "example": "Eating rice dumplings is a custom on Dragon-Boat Festival.", "exampleZh": "吃粽子是端午節的習俗。"}, {"word": "Christmas", "pos": "n.", "zh": "聖誕節", "example": "We put up a tree before Christmas.", "exampleZh": "我們在聖誕節前擺了一棵樹。"}, {"word": "Lantern Festival", "pos": "n.", "zh": "元宵節", "example": "People eat sweet rice balls on the Lantern Festival.", "exampleZh": "人們在元宵節吃湯圓。"}, {"word": "memory", "pos": "n.", "zh": "回憶、記憶", "example": "The trip to Japan is a sweet memory for me.", "exampleZh": "那趟日本之旅對我來說是甜蜜的回憶。"}], "phrases": [{"phrase": "take place", "zh": "舉行、發生", "example": "The game will take place next Sunday.", "exampleZh": "比賽將在下星期日舉行。"}, {"phrase": "from around the world", "zh": "來自世界各地", "example": "Students from around the world study here.", "exampleZh": "來自世界各地的學生在這裡讀書。"}, {"phrase": "two weeks away", "zh": "距離兩週", "example": "The final exam is only two weeks away.", "exampleZh": "期末考只剩兩個星期了。"}], "grammar": [{"pattern": "S + will be + p.p. (未來被動)", "explain": "被動語態表示主詞「被」做某事。未來式被動用 will be 加過去分詞，例如 will be held（將被舉行）、will be sold（將被販售）。", "example": "The party will be held in the gym.", "exampleZh": "派對將在體育館舉行。"}, {"pattern": "If + S + V(現在式), S + will + V", "explain": "條件句：if 子句用現在式表示未來可能的情況，主要子句用 will 說明結果。", "example": "If it rains tomorrow, we will stay inside.", "exampleZh": "如果明天下雨，我們就待在室內。"}], "reading": [{"q": "What is the purpose of this announcement?", "options": ["To tell students the winter vacation is canceled.", "To invite students and parents to a school event.", "To teach students how to make lanterns.", "To sell tickets for a dragon dance show."], "answer": 1, "explain": "第一段說明學校將舉辦 Festival Night 並寫道「Everyone is welcome」，是邀請大家參加活動，故選 (B)。"}, {"q": "When will Festival Night be held?", "options": ["On Chinese New Year's Eve.", "On Friday, January 23.", "Two weeks after the holiday.", "On the Lantern Festival."], "answer": 1, "explain": "第一段提到「on Friday, January 23, from 6 p.m. to 8:30 p.m.」，故選 (B)。"}, {"q": "What can you do in the art room?", "options": ["Watch a dragon dance.", "Learn about Christmas in America.", "Make a paper lantern.", "Look at pictures from last year."], "answer": 2, "explain": "第二段說「In the art room, you can make your own paper lantern」，故選 (C)。"}, {"q": "Which of the following is NOT allowed at Festival Night?", "options": ["Bringing fireworks.", "Bringing money.", "Wearing a school jacket.", "Bringing family members."], "answer": 0, "explain": "第三段的規定「Do not bring fireworks」，故選 (A)。"}, {"q": "What will happen if it rains on January 23?", "options": ["The event will move to another day.", "The event will be held in the gym as planned.", "Only the dragon dance will be canceled.", "Students will go home early."], "answer": 1, "explain": "第三段說「If it rains, the event will still take place」，而地點本來就是體育館，故選 (B)。"}], "vocabQ": [{"q": "We will ____ Grandma's eightieth birthday with a big dinner.", "options": ["celebrate", "remember", "visit", "decorate"], "answer": 0, "explain": "句意為「我們會以豐盛的晚餐慶祝奶奶八十歲生日」，celebrate 慶祝。"}, {"q": "Giving red envelopes is an old Chinese ____.", "options": ["festival", "custom", "memory", "vacation"], "answer": 1, "explain": "發紅包是古老的中國「習俗」，custom。"}, {"q": "Our summer ____ is two months long, from July to August.", "options": ["weekend", "vacation", "culture", "festival"], "answer": 1, "explain": "長達兩個月的暑「假」用 vacation 最合適。"}, {"q": "My first day at junior high school is a happy ____ for me.", "options": ["custom", "holiday", "memory", "culture"], "answer": 2, "explain": "國中第一天是快樂的「回憶」，memory。"}, {"q": "Many stores play songs and put up lights before ____.", "options": ["Teacher's Day", "Mother's Day", "Christmas", "Double Tenth Day"], "answer": 2, "explain": "許多商店在「聖誕節」前播放歌曲並掛上燈飾，Christmas。"}]}, {"id": "E37", "level": "elem", "num": 37, "title": "Job Day Brings Real Workers to School", "titleZh": "職業日把真正的工作者帶進校園", "theme": "Occupations", "themeZh": "職業", "article": ["TAIPEI, May 16. On Friday, Daan Junior High School held its first Job Day. Twelve parents came to school to talk about their work. Students did not need to sit in a classroom all day. Instead, they walked from room to room and met a nurse, a mechanic, a farmer, a lawyer, and even a magician.", "The most popular room belonged to Mr. Chen, a mechanic. He brought a scooter engine and let students take it apart. \"A mechanic uses his hands and his head,\" he said. Next door, Ms. Huang, a reporter, showed how she writes a news story in one hour. In the garden, Mr. Wu, a farmer from Yilan, taught students how to plant rice. Many students said they had never touched mud before.", "The principal said the school will hold Job Day every year. \"Students should see many kinds of jobs before they choose one,\" she said. A ninth grader, Amy Lin, agreed. \"I wanted to be a doctor,\" she said. \"Now I also think about being an engineer. Today changed my mind.\" Next year's Job Day will invite a pilot and a police officer."], "translation": ["台北，五月十六日。星期五，大安國中舉辦了第一屆職業日。十二位家長來到學校談他們的工作。學生不必整天坐在教室裡。他們改為一間一間地走，見到了護理師、技工、農夫、律師，甚至還有魔術師。", "最受歡迎的教室是陳先生的，他是一位技工。他帶來一個機車引擎，讓學生把它拆開。「技工要用手，也要用腦。」他說。隔壁，黃小姐是一位記者，她示範如何在一小時內寫出一則新聞。在花園裡，來自宜蘭的農夫吳先生教學生如何插秧。許多學生說他們以前從來沒有碰過泥巴。", "校長表示學校每年都會舉辦職業日。「學生在選擇工作之前，應該先看看各種不同的工作。」她說。九年級的林小美同意這個說法。「我本來想當醫生，」她說，「現在我也考慮當工程師。今天改變了我的想法。」明年的職業日將邀請一位飛行員和一位警察。"], "vocab": [{"word": "job", "pos": "n.", "zh": "工作、職業", "example": "My sister found a job at a bank.", "exampleZh": "我姊姊在銀行找到一份工作。"}, {"word": "nurse", "pos": "n.", "zh": "護理師", "example": "The nurse took my temperature.", "exampleZh": "護理師幫我量了體溫。"}, {"word": "mechanic", "pos": "n.", "zh": "技工、修車工", "example": "The mechanic fixed our car in two hours.", "exampleZh": "技工兩小時就修好了我們的車。"}, {"word": "farmer", "pos": "n.", "zh": "農夫", "example": "The farmer gets up before the sun.", "exampleZh": "農夫在太陽升起前就起床。"}, {"word": "lawyer", "pos": "n.", "zh": "律師", "example": "You should talk to a lawyer about this problem.", "exampleZh": "關於這個問題你應該找律師談談。"}, {"word": "magician", "pos": "n.", "zh": "魔術師", "example": "The magician pulled a rabbit out of a hat.", "exampleZh": "魔術師從帽子裡變出一隻兔子。"}, {"word": "reporter", "pos": "n.", "zh": "記者", "example": "A reporter asked the singer some questions.", "exampleZh": "一位記者問了歌手幾個問題。"}, {"word": "engineer", "pos": "n.", "zh": "工程師", "example": "My uncle is an engineer at a computer company.", "exampleZh": "我叔叔是電腦公司的工程師。"}], "phrases": [{"phrase": "take apart", "zh": "拆開", "example": "Don't take the clock apart; you can't put it back.", "exampleZh": "別把時鐘拆開，你裝不回去的。"}, {"phrase": "change one's mind", "zh": "改變心意", "example": "He changed his mind and stayed home.", "exampleZh": "他改變心意，留在家裡。"}, {"phrase": "from room to room", "zh": "一間接一間", "example": "The teacher walked from room to room to check the lights.", "exampleZh": "老師一間一間地走，檢查電燈。"}], "grammar": [{"pattern": "S + let + O + V(原形)", "explain": "let 是使役動詞，意思是「讓」，受詞後面接原形動詞，不加 to。", "example": "Mom let me stay up late last night.", "exampleZh": "媽媽昨晚讓我晚睡。"}, {"pattern": "S + think about + V-ing", "explain": "think about 表示「考慮」，後面接名詞或動名詞（V-ing）。", "example": "I am thinking about joining the music club.", "exampleZh": "我在考慮加入音樂社。"}], "reading": [{"q": "What is the news report mainly about?", "options": ["A new school in Taipei.", "A school event where parents talked about their jobs.", "A contest for the best mechanic.", "How to plant rice in Yilan."], "answer": 1, "explain": "第一段說明職業日是家長來校談工作的活動，全文圍繞此事，故選 (B)。"}, {"q": "Who let the students take a scooter engine apart?", "options": ["Ms. Huang.", "Mr. Wu.", "Mr. Chen.", "The principal."], "answer": 2, "explain": "第二段提到「Mr. Chen, a mechanic. He brought a scooter engine and let students take it apart」，故選 (C)。"}, {"q": "What did Mr. Wu teach the students?", "options": ["How to write a news story.", "How to fix a scooter.", "How to do magic.", "How to plant rice."], "answer": 3, "explain": "第二段說「Mr. Wu, a farmer from Yilan, taught students how to plant rice」，故選 (D)。"}, {"q": "What job does Amy Lin think about now?", "options": ["A doctor only.", "A nurse.", "An engineer.", "A pilot."], "answer": 2, "explain": "第三段 Amy 說「Now I also think about being an engineer」，故選 (C)。"}, {"q": "Which person will come to Job Day next year?", "options": ["A magician.", "A police officer.", "A lawyer.", "A reporter."], "answer": 1, "explain": "最後一句「Next year's Job Day will invite a pilot and a police officer」，故選 (B)。"}], "vocabQ": [{"q": "The ____ gave the sick boy some medicine and checked his fever.", "options": ["nurse", "farmer", "mechanic", "reporter"], "answer": 0, "explain": "給病童藥並檢查發燒的是「護理師」，nurse。"}, {"q": "After the typhoon, the ____ lost most of his rice and vegetables.", "options": ["lawyer", "engineer", "farmer", "magician"], "answer": 2, "explain": "颱風過後損失稻米和蔬菜的是「農夫」，farmer。"}, {"q": "The ____ made the coins disappear, and the children shouted \"Wow!\"", "options": ["mechanic", "magician", "nurse", "lawyer"], "answer": 1, "explain": "讓硬幣消失的是「魔術師」，magician。"}, {"q": "A ____ designed this new bridge across the river.", "options": ["reporter", "farmer", "engineer", "nurse"], "answer": 2, "explain": "設計橋梁的是「工程師」，engineer。"}, {"q": "It is hard to find a good ____ in a small town.", "options": ["work", "job", "business", "company"], "answer": 1, "explain": "句意為「在小鎮很難找到一份好工作」，a good job；work 不可數，不能加 a。"}]}, {"id": "E38", "level": "elem", "num": 38, "title": "Four Kinds of Weather in One Day", "titleZh": "一天之中的四種天氣", "theme": "Weather", "themeZh": "天氣", "article": ["People say Taipei has four seasons, but I think it has four kinds of weather in one day. In the morning, the sky is often cloudy and the air is cool. My mother always tells me to bring a jacket. By noon, the sun comes out and the temperature can reach 30 degrees. The weather is hot and humid, and my shirt sticks to my back.", "In the afternoon, dark clouds gather over the mountains. Then comes a shower with loud thunder and bright lightning. The rain is heavy but short. After the rain, the air is fresh, and sometimes a rainbow appears over the river. My classmates and I run to the window to take pictures. In the evening, a cool wind blows, and the sky is clear. You can even see a few stars.", "Summer is also the typhoon season. When a typhoon comes, the wind is so strong that it can break umbrellas and trees. Schools close, and we stay home. Winter is different. It is not snowy, but the wet and windy weather makes 15 degrees feel freezing. Taipei's weather is strange, but I love it. Every day is a surprise."], "translation": ["人們說台北有四季，但我覺得它一天之中就有四種天氣。早上，天空常常多雲，空氣涼涼的。媽媽總是叫我帶件外套。到了中午，太陽出來，氣溫可以達到 30 度。天氣又熱又潮濕，我的襯衫黏在背上。", "下午，烏雲聚集在山上。接著一陣驟雨伴隨著響亮的雷聲和明亮的閃電而來。雨很大但很短。雨後空氣清新，有時河上會出現彩虹。我和同學們跑到窗邊拍照。傍晚，涼風吹來，天空晴朗。你甚至可以看到幾顆星星。", "夏天也是颱風季。颱風來的時候，風強到可以吹壞雨傘和樹木。學校停課，我們待在家裡。冬天就不一樣了。雖然不下雪，但又濕又有風的天氣讓 15 度感覺像結冰一樣冷。台北的天氣很奇怪，但我喜歡。每一天都是驚喜。"], "vocab": [{"word": "cloudy", "pos": "adj.", "zh": "多雲的", "example": "It is cloudy, so we can't see the moon tonight.", "exampleZh": "今晚多雲，所以看不到月亮。"}, {"word": "temperature", "pos": "n.", "zh": "溫度、氣溫", "example": "The temperature will drop to 10 degrees tonight.", "exampleZh": "今晚氣溫將降到 10 度。"}, {"word": "humid", "pos": "adj.", "zh": "潮濕的", "example": "June is hot and humid in Taiwan.", "exampleZh": "台灣的六月又熱又潮濕。"}, {"word": "shower", "pos": "n.", "zh": "陣雨", "example": "There will be showers in the afternoon.", "exampleZh": "下午會有陣雨。"}, {"word": "thunder", "pos": "n.", "zh": "雷、雷聲", "example": "My dog hides under the bed when he hears thunder.", "exampleZh": "我的狗聽到雷聲就躲到床底下。"}, {"word": "lightning", "pos": "n.", "zh": "閃電", "example": "Lightning hit the tall tree in the park.", "exampleZh": "閃電擊中了公園裡的高樹。"}, {"word": "rainbow", "pos": "n.", "zh": "彩虹", "example": "We saw a beautiful rainbow after the storm.", "exampleZh": "暴風雨過後我們看到一道美麗的彩虹。"}, {"word": "typhoon", "pos": "n.", "zh": "颱風", "example": "The typhoon brought strong wind and heavy rain.", "exampleZh": "颱風帶來強風和豪雨。"}], "phrases": [{"phrase": "come out", "zh": "（太陽、月亮）出現、露臉", "example": "The sun came out after lunch.", "exampleZh": "午餐後太陽出來了。"}, {"phrase": "take pictures", "zh": "拍照", "example": "Tourists love to take pictures of Taipei 101.", "exampleZh": "遊客喜歡拍台北 101 的照片。"}, {"phrase": "stay home", "zh": "待在家裡", "example": "We stayed home because of the typhoon.", "exampleZh": "因為颱風，我們待在家裡。"}], "grammar": [{"pattern": "S + be + so + adj. + that + S + V", "explain": "「如此…以至於…」，so 後面接形容詞，that 引導結果子句，說明程度強到造成什麼結果。", "example": "The wind was so strong that my hat flew away.", "exampleZh": "風強到把我的帽子吹走了。"}, {"pattern": "S + tell(s) + O + to + V", "explain": "tell 後面接受詞，再接不定詞 to V，表示「叫某人做某事」。", "example": "The teacher told us to open our books.", "exampleZh": "老師叫我們打開課本。"}], "reading": [{"q": "What is the main idea of the article?", "options": ["Taipei has terrible weather all year.", "Taipei's weather changes a lot, even in one day.", "Typhoons are dangerous.", "Winter in Taipei is colder than in Japan."], "answer": 1, "explain": "第一句「it has four kinds of weather in one day」點出主旨：台北天氣一天內變化很大，故選 (B)。"}, {"q": "What is the weather like in the morning?", "options": ["Hot and humid.", "Cloudy and cool.", "Rainy with thunder.", "Clear with stars."], "answer": 1, "explain": "第一段說「In the morning, the sky is often cloudy and the air is cool」，故選 (B)。"}, {"q": "What do the writer and the classmates do after the afternoon rain?", "options": ["They go home early.", "They take pictures of the rainbow.", "They play in the rain.", "They close the windows."], "answer": 1, "explain": "第二段提到「a rainbow appears ... My classmates and I run to the window to take pictures」，故選 (B)。"}, {"q": "Why do schools close in summer sometimes?", "options": ["Because it is too hot.", "Because of heavy showers.", "Because of typhoons.", "Because the temperature is 30 degrees."], "answer": 2, "explain": "第三段說「When a typhoon comes ... Schools close, and we stay home」，故選 (C)。"}, {"q": "The word \"freezing\" in paragraph 3 is closest in meaning to ____.", "options": ["very cold", "very wet", "very windy", "very dark"], "answer": 0, "explain": "freezing 意為「冰冷的」，文中說 15 度因又濕又有風而感覺極冷，故選 (A)。"}], "vocabQ": [{"q": "The ____ today is 35 degrees, so drink a lot of water.", "options": ["temperature", "weather", "climate", "thunder"], "answer": 0, "explain": "今天 35 度是「氣溫」，temperature。"}, {"q": "After the loud ____, the baby started to cry.", "options": ["rainbow", "thunder", "cloud", "fog"], "answer": 1, "explain": "巨大的「雷聲」讓嬰兒哭了，thunder。"}, {"q": "A strong ____ is coming, so the fishing boats are back in the harbor.", "options": ["shower", "rainbow", "typhoon", "snowman"], "answer": 2, "explain": "強烈「颱風」要來，漁船都回港了，typhoon。"}, {"q": "Look! There is a ____ in the sky with seven colors.", "options": ["rainbow", "lightning", "storm", "wind"], "answer": 0, "explain": "天空中七種顏色的是「彩虹」，rainbow。"}, {"q": "It is so ____ in the bathroom that the mirror is always wet.", "options": ["dry", "humid", "sunny", "windy"], "answer": 1, "explain": "鏡子總是濕的，表示浴室很「潮濕」，humid。"}]}, {"id": "E39", "level": "elem", "num": 39, "title": "Three Days in Hualien", "titleZh": "花蓮三日遊", "theme": "Nature & Geography", "themeZh": "自然與地理", "article": ["Day 1: We arrived in Hualien by train at noon. Our hotel was near the coast, so we walked to the beach first. The sea was deep blue, and the waves were loud. In the afternoon, we drove to Taroko. The road runs through a valley between tall mountains. A clear stream flows beside the road, and the water is so cold that it hurts your hands.", "Day 2: We went to Liyu Lake. It is the biggest lake in eastern Taiwan, and there is a green hill on one side. We rode bikes around the lake and fed fish at a quiet pond. Later, we visited a farm on the plain. The farmer showed us a hot spring behind the forest. We put our feet in the warm water and watched the sunset.", "Day 3: Before we left, we walked along the river bank near the station. The air in Hualien is clean, and the environment is different from Taipei. There are no tall buildings here, only sky, sea, and mountains. I hope to come back next summer and camp in the woods."], "translation": ["第一天：我們中午搭火車抵達花蓮。飯店在海岸附近，所以我們先走路去海灘。海水是深藍色的，海浪聲很大。下午我們開車到太魯閣。道路穿過高山之間的山谷。一條清澈的溪流在路旁流淌，水冷到會讓你的手發疼。", "第二天：我們去了鯉魚潭。它是東台灣最大的湖，一側有座綠色的小山。我們騎腳踏車環湖，在一個安靜的池塘餵魚。之後，我們參觀了平原上的一座農場。農夫帶我們看森林後面的一處溫泉。我們把腳泡在溫熱的水裡，看著夕陽。", "第三天：離開前，我們沿著車站附近的河岸散步。花蓮的空氣很乾淨，環境和台北不一樣。這裡沒有高樓，只有天空、海和山。我希望明年夏天再回來，在樹林裡露營。"], "vocab": [{"word": "coast", "pos": "n.", "zh": "海岸", "example": "Many fishing villages are on the east coast.", "exampleZh": "東海岸有許多漁村。"}, {"word": "beach", "pos": "n.", "zh": "海灘", "example": "We built a sandcastle on the beach.", "exampleZh": "我們在海灘上堆了沙堡。"}, {"word": "valley", "pos": "n.", "zh": "山谷", "example": "A small town lies in the valley.", "exampleZh": "山谷裡有一座小鎮。"}, {"word": "mountain", "pos": "n.", "zh": "山", "example": "Yushan is the highest mountain in Taiwan.", "exampleZh": "玉山是台灣最高的山。"}, {"word": "stream", "pos": "n.", "zh": "溪流、小河", "example": "We caught small fish in the stream.", "exampleZh": "我們在溪裡抓小魚。"}, {"word": "lake", "pos": "n.", "zh": "湖", "example": "Sun Moon Lake is a famous lake in Nantou.", "exampleZh": "日月潭是南投著名的湖。"}, {"word": "pond", "pos": "n.", "zh": "池塘", "example": "There are frogs and lotus flowers in the pond.", "exampleZh": "池塘裡有青蛙和荷花。"}, {"word": "environment", "pos": "n.", "zh": "環境", "example": "We should protect the environment for our children.", "exampleZh": "我們應該為孩子保護環境。"}], "phrases": [{"phrase": "run through", "zh": "穿過、貫穿", "example": "A river runs through the city.", "exampleZh": "一條河穿過這座城市。"}, {"phrase": "be different from", "zh": "與…不同", "example": "Life in the country is different from life in the city.", "exampleZh": "鄉下生活和都市生活不同。"}, {"phrase": "come back", "zh": "回來", "example": "Please come back before dinner.", "exampleZh": "請在晚餐前回來。"}], "grammar": [{"pattern": "There + be + no + N", "explain": "there is / there are 表示「有」，加 no 表示「沒有」，後面接名詞。", "example": "There are no clouds in the sky today.", "exampleZh": "今天天空沒有雲。"}, {"pattern": "S + hope + to + V", "explain": "hope 表示「希望」，後面接不定詞 to V，說明希望做的事。", "example": "I hope to see you again soon.", "exampleZh": "我希望很快再見到你。"}], "reading": [{"q": "How did the writer get to Hualien?", "options": ["By car.", "By bus.", "By train.", "By bike."], "answer": 2, "explain": "第一段「We arrived in Hualien by train at noon」，故選 (C)。"}, {"q": "What did the writer do on Day 1 in the afternoon?", "options": ["Walked on the beach.", "Drove to Taroko.", "Fed fish at a pond.", "Sat in a hot spring."], "answer": 1, "explain": "第一段說「In the afternoon, we drove to Taroko」，故選 (B)。"}, {"q": "Where is the hot spring?", "options": ["Beside the road in Taroko.", "On the beach.", "Behind the forest near the farm.", "Next to the station."], "answer": 2, "explain": "第二段「The farmer showed us a hot spring behind the forest」，農場在平原上，故選 (C)。"}, {"q": "Why does the writer say Hualien is different from Taipei?", "options": ["It has more people.", "It has no tall buildings and the air is clean.", "It is colder.", "It has a bigger station."], "answer": 1, "explain": "第三段「The air in Hualien is clean ... There are no tall buildings here」，故選 (B)。"}, {"q": "What does the writer want to do next summer?", "options": ["Buy a house in Hualien.", "Swim in Liyu Lake.", "Camp in the woods.", "Climb a mountain."], "answer": 2, "explain": "最後一句「I hope to come back next summer and camp in the woods」，故選 (C)。"}], "vocabQ": [{"q": "Kids like to play in the sand and swim at the ____.", "options": ["beach", "valley", "forest", "desert"], "answer": 0, "explain": "玩沙和游泳的地方是「海灘」，beach。"}, {"q": "Yushan is the highest ____ in Taiwan, almost 4,000 meters tall.", "options": ["hill", "island", "mountain", "plain"], "answer": 2, "explain": "近 4,000 公尺高的是「山」，mountain。"}, {"q": "The ducks swim in the small ____ in the park.", "options": ["pond", "ocean", "sea", "coast"], "answer": 0, "explain": "公園裡小小的水域是「池塘」，pond。"}, {"q": "Plastic bags are bad for the ____, so bring your own bag.", "options": ["weather", "environment", "area", "bank"], "answer": 1, "explain": "塑膠袋對「環境」不好，environment。"}, {"q": "The village is in a ____ between two high mountains.", "options": ["beach", "lake", "stream", "valley"], "answer": 3, "explain": "兩座高山之間的地方是「山谷」，valley。"}]}, {"id": "E40", "level": "elem", "num": 40, "title": "A Talk with a Zookeeper", "titleZh": "與動物園管理員的對談", "theme": "Animals", "themeZh": "動物", "article": ["Mr. Lin has worked at Taipei Zoo for fifteen years. Last week, our school newspaper talked to him about his job. Q: What do you do every day? A: I get up at five. First, I feed the elephants and the zebras. Then I clean the home of the pandas. They eat bamboo all day, so there is always a lot to clean!", "Q: Which animal is the most dangerous? A: Many people say the lion or the tiger. But I think the hippo is more dangerous. It looks slow and friendly, but it can run fast and has very strong teeth. We never go into its pool. Q: Which animal is your favorite? A: The koala. It sleeps about twenty hours a day. When it wakes up, it looks at you like a sleepy baby.", "Q: Do you have a pet at home? A: Yes, a dog and two rabbits. My daughter wants a parrot, too. Q: What do you want to tell students? A: Animals are not toys. A kitten or a puppy needs your time for many years. Think carefully before you bring one home. And please do not feed the monkeys at the zoo. Our food makes them sick."], "translation": ["林先生在台北動物園工作了十五年。上星期，我們的校刊和他聊了他的工作。問：你每天都做些什麼？答：我五點起床。首先，我餵大象和斑馬。接著我打掃貓熊的家。牠們整天都在吃竹子，所以總是有很多東西要清！", "問：哪種動物最危險？答：很多人說是獅子或老虎。但我覺得河馬更危險。牠看起來又慢又友善，但牠跑得很快，而且牙齒非常有力。我們從不進牠的水池。問：你最喜歡哪種動物？答：無尾熊。牠一天大約睡二十個小時。牠醒來的時候，看著你的樣子像個想睡的小嬰兒。", "問：你家裡有養寵物嗎？答：有，一隻狗和兩隻兔子。我女兒還想要一隻鸚鵡。問：你想對學生說什麼？答：動物不是玩具。一隻小貓或小狗需要你付出很多年的時間。帶牠回家之前要仔細想清楚。還有，請不要餵動物園的猴子。我們的食物會讓牠們生病。"], "vocab": [{"word": "elephant", "pos": "n.", "zh": "大象", "example": "An elephant drinks a lot of water every day.", "exampleZh": "大象每天喝很多水。"}, {"word": "zebra", "pos": "n.", "zh": "斑馬", "example": "A zebra has black and white stripes.", "exampleZh": "斑馬有黑白相間的條紋。"}, {"word": "panda", "pos": "n.", "zh": "貓熊", "example": "The panda is the most popular animal at the zoo.", "exampleZh": "貓熊是動物園最受歡迎的動物。"}, {"word": "hippo", "pos": "n.", "zh": "河馬", "example": "The hippo stays in the water to keep cool.", "exampleZh": "河馬待在水裡保持涼爽。"}, {"word": "koala", "pos": "n.", "zh": "無尾熊", "example": "The koala holds the tree and sleeps all day.", "exampleZh": "無尾熊抱著樹睡一整天。"}, {"word": "parrot", "pos": "n.", "zh": "鸚鵡", "example": "My parrot can say \"good morning.\"", "exampleZh": "我的鸚鵡會說「早安」。"}, {"word": "kitten", "pos": "n.", "zh": "小貓", "example": "The kitten is playing with a ball of yarn.", "exampleZh": "小貓在玩毛線球。"}, {"word": "puppy", "pos": "n.", "zh": "小狗", "example": "Our puppy follows me everywhere.", "exampleZh": "我們的小狗到哪裡都跟著我。"}], "phrases": [{"phrase": "wake up", "zh": "醒來", "example": "I wake up at six every day.", "exampleZh": "我每天六點醒來。"}, {"phrase": "a lot to + V", "zh": "有很多要…", "example": "There is a lot to learn in this class.", "exampleZh": "這門課有很多東西要學。"}, {"phrase": "make someone sick", "zh": "讓某人生病", "example": "Bad food can make you sick.", "exampleZh": "壞掉的食物會讓你生病。"}], "grammar": [{"pattern": "S + has/have + p.p. + for + 一段時間", "explain": "現在完成式表示從過去持續到現在的動作或狀態，for 後面接一段時間，表示「已經…了多久」。", "example": "She has lived in Taichung for ten years.", "exampleZh": "她已經在台中住了十年。"}, {"pattern": "Which + N + be + the most + adj.?", "explain": "最高級用來在三者以上中比較。長形容詞前加 the most，例如 the most dangerous（最危險的）。", "example": "Which subject is the most difficult for you?", "exampleZh": "哪一科對你來說最難？"}], "reading": [{"q": "How long has Mr. Lin worked at the zoo?", "options": ["Five years.", "Ten years.", "Fifteen years.", "Twenty years."], "answer": 2, "explain": "第一句「Mr. Lin has worked at Taipei Zoo for fifteen years」，故選 (C)。"}, {"q": "Why is there always a lot to clean in the pandas' home?", "options": ["The pandas play in the mud.", "The pandas eat bamboo all day.", "The pandas live with the elephants.", "The pandas are very big."], "answer": 1, "explain": "第一段「They eat bamboo all day, so there is always a lot to clean」，故選 (B)。"}, {"q": "Why does Mr. Lin think the hippo is dangerous?", "options": ["It has sharp claws.", "It is bigger than a lion.", "It can run fast and has strong teeth.", "It does not like water."], "answer": 2, "explain": "第二段說河馬「can run fast and has very strong teeth」，故選 (C)。"}, {"q": "What pets does Mr. Lin have at home?", "options": ["A dog and two rabbits.", "A parrot and a dog.", "Two kittens.", "A puppy and a koala."], "answer": 0, "explain": "第三段「Yes, a dog and two rabbits」，鸚鵡只是女兒想要的，故選 (A)。"}, {"q": "What is Mr. Lin's advice for students?", "options": ["Visit the zoo every weekend.", "Feed the monkeys healthy food.", "Think carefully before getting a pet.", "Buy a koala as a pet."], "answer": 2, "explain": "第三段「Think carefully before you bring one home」，故選 (C)。"}], "vocabQ": [{"q": "The ____ is the biggest animal on land, and it has a long nose.", "options": ["elephant", "hippo", "zebra", "panda"], "answer": 0, "explain": "陸地上最大且有長鼻子的動物是「大象」，elephant。"}, {"q": "A ____ looks like a horse with black and white stripes.", "options": ["koala", "zebra", "parrot", "kitten"], "answer": 1, "explain": "像馬且有黑白條紋的是「斑馬」，zebra。"}, {"q": "The ____ is black and white and loves to eat bamboo.", "options": ["hippo", "puppy", "panda", "parrot"], "answer": 2, "explain": "黑白相間、愛吃竹子的是「貓熊」，panda。"}, {"q": "My ____ learned to say my name after one month.", "options": ["kitten", "zebra", "puppy", "parrot"], "answer": 3, "explain": "會學說人名的是「鸚鵡」，parrot。"}, {"q": "The little ____ cried \"meow\" all night because it missed its mother.", "options": ["puppy", "kitten", "hippo", "koala"], "answer": 1, "explain": "發出「喵」聲的是「小貓」，kitten。"}]}, {"id": "E41", "level": "elem", "num": 41, "title": "Swimming with Sea Turtles", "titleZh": "與海龜共游", "theme": "Insects & Sea Animals", "themeZh": "昆蟲與海洋生物", "article": ["July 20, Sunny. Today my family and I went to Xiaoliuqiu. It is a small island near Pingtung. In the morning, we put on masks and went into the sea. The water was clear and blue. Soon I saw a big sea turtle under me! It moved its tail slowly and ate sea grass. Small fish swam around it. A crab hid under a rock, and a shrimp with long legs sat next to it.", "In the afternoon, we walked on a path by the shore. There were many insects. A butterfly with orange wings landed on my hat. Ants carried food in a long line. A snail climbed up a wet leaf. A mosquito bit my arm, and it became red. My little brother was afraid of a spider on a tree. Dad said, \"Don't worry. It won't bite you.\"", "At night, we sat by the sea and listened to the waves. Dad told us a story about a dolphin. Many years ago, a dolphin saved a fisherman near this island. I don't know if the story is true. But I hope I can see a dolphin or a whale someday. What a wonderful day!"], "translation": ["七月二十日，晴。今天我和家人去了小琉球。它是屏東附近的一座小島。早上，我們戴上面鏡下海。海水又清又藍。很快我就看到一隻大海龜在我下面！牠慢慢地擺動尾巴，吃著海草。小魚在牠身邊游來游去。一隻螃蟹躲在石頭下，一隻長腳的蝦子坐在旁邊。", "下午，我們沿著海岸邊的小路散步。那裡有很多昆蟲。一隻有橘色翅膀的蝴蝶停在我的帽子上。螞蟻排成長長的一列搬運食物。一隻蝸牛爬上濕濕的葉子。一隻蚊子叮了我的手臂，手臂變紅了。弟弟很怕樹上的一隻蜘蛛。爸爸說：「別擔心，牠不會咬你。」", "晚上，我們坐在海邊聽海浪聲。爸爸跟我們說了一個關於海豚的故事。很多年前，一隻海豚在這座島附近救了一位漁夫。我不知道這個故事是不是真的。但我希望有一天能看到海豚或鯨魚。多麼美好的一天啊！"], "vocab": [{"word": "turtle", "pos": "n.", "zh": "海龜；烏龜", "example": "A turtle can live for a very long time.", "exampleZh": "烏龜可以活很久。"}, {"word": "tail", "pos": "n.", "zh": "尾巴", "example": "The dog wagged its tail when it saw me.", "exampleZh": "那隻狗看到我時搖了搖尾巴。"}, {"word": "crab", "pos": "n.", "zh": "螃蟹", "example": "We caught a small crab on the beach.", "exampleZh": "我們在海灘上抓到一隻小螃蟹。"}, {"word": "insect", "pos": "n.", "zh": "昆蟲", "example": "Many insects come out at night in summer.", "exampleZh": "夏天晚上有很多昆蟲跑出來。"}, {"word": "butterfly", "pos": "n.", "zh": "蝴蝶", "example": "A yellow butterfly flew over the flowers.", "exampleZh": "一隻黃色的蝴蝶飛過花叢。"}, {"word": "wing", "pos": "n.", "zh": "翅膀", "example": "The bird hurt its wing and could not fly.", "exampleZh": "那隻鳥翅膀受傷，飛不起來。"}, {"word": "snail", "pos": "n.", "zh": "蝸牛", "example": "A snail moves very slowly on the ground.", "exampleZh": "蝸牛在地上移動得非常慢。"}, {"word": "bite", "pos": "v.", "zh": "咬；叮", "example": "Be careful! That dog may bite you.", "exampleZh": "小心！那隻狗可能會咬你。"}], "phrases": [{"phrase": "put on", "zh": "戴上；穿上", "example": "Put on your jacket. It is cold outside.", "exampleZh": "穿上你的外套，外面很冷。"}, {"phrase": "be afraid of", "zh": "害怕", "example": "My sister is afraid of snakes.", "exampleZh": "我妹妹怕蛇。"}, {"phrase": "listen to", "zh": "聆聽", "example": "I like to listen to music before bed.", "exampleZh": "我喜歡睡前聽音樂。"}], "grammar": [{"pattern": "What + a/an + adj. + N.!", "explain": "感嘆句，用來表達強烈的感受，意思是「多麼…的…啊！」。名詞是單數可數名詞時要加 a/an。", "example": "What a beautiful beach!", "exampleZh": "多麼美麗的海灘啊！"}, {"pattern": "S + don't/doesn't know + if + S + V", "explain": "if 在這裡表示「是否」，引導名詞子句當 know 的受詞，用來表達不確定某件事是否為真。", "example": "I don't know if he will come tomorrow.", "exampleZh": "我不知道他明天會不會來。"}], "reading": [{"q": "What is this passage?", "options": ["A news report about Xiaoliuqiu", "A diary about a family trip", "A letter to a friend", "A science lesson about insects"], "answer": 1, "explain": "文章開頭有日期和天氣，並以第一人稱記錄一天的經過，是日記。故選 (B)。"}, {"q": "What did the writer see under the sea in the morning?", "options": ["A whale and a dolphin", "A snail on a leaf", "A turtle, a crab, and a shrimp", "A snake under a rock"], "answer": 2, "explain": "第一段提到作者在海裡看到海龜、螃蟹和蝦子。故選 (C)。"}, {"q": "What happened to the writer in the afternoon?", "options": ["A mosquito bit the writer.", "A spider climbed on the writer's hat.", "The writer caught a butterfly.", "The writer fell on the path."], "answer": 0, "explain": "第二段說 A mosquito bit my arm, and it became red，蚊子叮了作者的手臂。故選 (A)。"}, {"q": "Why did Dad say \"Don't worry\" to the writer's brother?", "options": ["Because the brother lost his hat.", "Because the brother could not swim.", "Because the brother was hungry.", "Because the brother was afraid of a spider."], "answer": 3, "explain": "第二段提到弟弟怕樹上的蜘蛛，爸爸才安慰他說蜘蛛不會咬人。故選 (D)。"}, {"q": "Which is true about the dolphin story?", "options": ["The writer saw the dolphin at night.", "The writer is not sure if it is true.", "The dolphin ate a fisherman.", "Mom told the story."], "answer": 1, "explain": "第三段作者說 I don't know if the story is true，表示不確定故事是否為真。故選 (B)。"}], "vocabQ": [{"q": "A ____ has a hard shell and walks sideways on the sand.", "options": ["turtle", "crab", "whale", "dolphin"], "answer": 1, "explain": "句意為「有硬殼且在沙上橫著走」，crab 螃蟹。"}, {"q": "The bird hurt one ____ , so it cannot fly now.", "options": ["tail", "leg", "wing", "eye"], "answer": 2, "explain": "句意為「那隻鳥傷了一邊翅膀，所以現在飛不起來」，wing 翅膀。"}, {"q": "A ____ carries its house on its back and moves slowly.", "options": ["bee", "snail", "bird", "bat"], "answer": 1, "explain": "句意為「背著房子且移動緩慢」，snail 蝸牛。"}, {"q": "Don't touch the cat's ____ , or it will get angry.", "options": ["tail", "wing", "shell", "fin"], "answer": 0, "explain": "句意為「別碰貓的尾巴，不然牠會生氣」，tail 尾巴。"}, {"q": "An ant is a small ____ with six legs.", "options": ["fish", "turtle", "shark", "insect"], "answer": 3, "explain": "句意為「螞蟻是有六隻腳的小昆蟲」，insect 昆蟲。"}]}, {"id": "E42", "level": "elem", "num": 42, "title": "A Surprise for Coach Lin", "titleZh": "給林教練的驚喜", "theme": "Common Nouns (1)", "themeZh": "常用名詞（一）", "article": ["Dear Amy, How are you? I have some exciting news. Last Friday, our basketball club had a surprise birthday party for Coach Lin. It was my idea. At the beginning, nobody believed we could do it. Coach Lin pays attention to everything! But we made a decision and worked hard as a group.", "On Friday, I sent Coach Lin an e-mail. I made an excuse and asked him to come to the gym at six. Before that, we put balloons at the entrance and flowers in the corner. Our school band waited in the center of the gym. When the bell rang at six, Coach Lin walked in. The crowd shouted, \"Happy birthday!\" He was so surprised that he dropped his cellphone. Luckily, it did not break.", "We gave him a photo album as a gift. Inside, every member wrote a few words about him. Coach Lin's eyes were wet. He said this was his best birthday. He also said our friendship was the real gift. It took a lot of effort, but it was a lot of fun. Write back soon! Love, Jenny"], "translation": ["親愛的艾咪：你好嗎？我有一個令人興奮的消息。上星期五，我們籃球社幫林教練辦了一場驚喜生日派對。這是我的點子。一開始，沒有人相信我們做得到。林教練什麼事都注意得到！但我們做了決定，全組一起努力。", "星期五，我寄了一封電子郵件給林教練。我找了個藉口，請他六點來體育館。在那之前，我們在入口放氣球，在角落放花。學校樂隊在體育館中央等著。六點鐘聲一響，林教練走了進來。大家大喊：「生日快樂！」他驚訝到手機都掉了。幸好手機沒壞。", "我們送他一本相簿當禮物。裡面每位社員都寫了幾句話給他。林教練的眼眶濕了。他說這是他最棒的生日。他還說我們的友誼才是真正的禮物。這件事花了很多心力，但也非常好玩。快回信喔！愛你的 珍妮"], "vocab": [{"word": "coach", "pos": "n.", "zh": "教練", "example": "Our coach makes us run five laps every day.", "exampleZh": "我們的教練每天要我們跑五圈。"}, {"word": "attention", "pos": "n.", "zh": "注意；專注", "example": "Please pay attention to the teacher.", "exampleZh": "請注意聽老師講話。"}, {"word": "decision", "pos": "n.", "zh": "決定", "example": "It was a hard decision, but I chose the blue one.", "exampleZh": "這是個困難的決定，但我選了藍色的那個。"}, {"word": "excuse", "pos": "n.", "zh": "藉口；理由", "example": "Being late is not a good excuse for missing the test.", "exampleZh": "遲到不是錯過考試的好理由。"}, {"word": "entrance", "pos": "n.", "zh": "入口", "example": "Let's meet at the entrance of the park.", "exampleZh": "我們在公園入口見面吧。"}, {"word": "balloon", "pos": "n.", "zh": "氣球", "example": "The little boy cried when his balloon flew away.", "exampleZh": "小男孩的氣球飛走時，他哭了。"}, {"word": "album", "pos": "n.", "zh": "相簿；專輯", "example": "Grandma keeps old photos in a big album.", "exampleZh": "奶奶把舊照片放在一本大相簿裡。"}, {"word": "effort", "pos": "n.", "zh": "努力；心力", "example": "With a little more effort, you can pass the test.", "exampleZh": "再多努力一點，你就能通過考試。"}], "phrases": [{"phrase": "pay attention to", "zh": "注意", "example": "Drivers should pay attention to the road.", "exampleZh": "駕駛人應該注意路況。"}, {"phrase": "make a decision", "zh": "做決定", "example": "We need to make a decision before Friday.", "exampleZh": "我們必須在星期五之前做決定。"}, {"phrase": "write back", "zh": "回信", "example": "I hope you will write back soon.", "exampleZh": "希望你很快回信。"}], "grammar": [{"pattern": "S + be + so + adj. + that + S + V", "explain": "「如此…以至於…」，so 後面接形容詞，that 子句說明造成的結果。", "example": "She was so tired that she fell asleep on the bus.", "exampleZh": "她累到在公車上睡著了。"}, {"pattern": "S + ask + O + to + V", "explain": "「請某人做某事」，ask 後面接受詞，再接不定詞 to V。", "example": "Mom asked me to buy some eggs.", "exampleZh": "媽媽要我去買一些蛋。"}], "reading": [{"q": "Why did Jenny write this letter?", "options": ["To invite Amy to a party", "To tell Amy about a surprise party", "To ask Amy for help", "To say sorry to Coach Lin"], "answer": 1, "explain": "信的開頭說 I have some exciting news，接著描述驚喜派對的經過，目的是分享這件事。故選 (B)。"}, {"q": "Why did nobody believe the plan at the beginning?", "options": ["Coach Lin notices everything.", "The club had no money.", "Jenny was a new member.", "The gym was closed on Friday."], "answer": 0, "explain": "第一段說 Coach Lin pays attention to everything，所以大家覺得很難瞞過他。故選 (A)。"}, {"q": "How did Jenny get Coach Lin to the gym?", "options": ["She called him on his cellphone.", "She waited for him at the entrance.", "She sent him an e-mail with an excuse.", "She asked the band to bring him."], "answer": 2, "explain": "第二段說 I sent Coach Lin an e-mail. I made an excuse and asked him to come to the gym at six。故選 (C)。"}, {"q": "What happened when Coach Lin walked into the gym?", "options": ["He broke a balloon.", "He left right away.", "He started to sing.", "He dropped his cellphone."], "answer": 3, "explain": "第二段說 He was so surprised that he dropped his cellphone。故選 (D)。"}, {"q": "What did Coach Lin think was the real gift?", "options": ["The photo album", "The flowers", "The friendship of the members", "The music from the band"], "answer": 2, "explain": "第三段說 He also said our friendship was the real gift。故選 (C)。"}], "vocabQ": [{"q": "You can't find the ____ to the museum? It's next to the big red door.", "options": ["corner", "entrance", "center", "bottom"], "answer": 1, "explain": "句意為「找不到博物館的入口嗎？它在大紅門旁邊」，entrance 入口。"}, {"q": "The ____ is angry because the team lost again.", "options": ["coach", "crowd", "captain", "foreigner"], "answer": 0, "explain": "句意為「教練很生氣，因為球隊又輸了」，coach 教練。"}, {"q": "Tom didn't do his homework, and he had no good ____ for it.", "options": ["advice", "effort", "excuse", "chance"], "answer": 2, "explain": "句意為「湯姆沒寫功課，而且沒有好理由」，excuse 藉口。"}, {"q": "Moving to a new city was a big ____ for our family.", "options": ["accident", "beginning", "gesture", "decision"], "answer": 3, "explain": "句意為「搬到新城市對我們家是個重大決定」，decision 決定。"}, {"q": "The red ____ flew up into the sky when the girl let go of it.", "options": ["bell", "album", "balloon", "flag"], "answer": 2, "explain": "句意為「女孩一放手，紅色氣球就飛上天空」，balloon 氣球。"}]}, {"id": "E43", "level": "elem", "num": 43, "title": "Class 802 Builds a Beach-Cleaning Robot", "titleZh": "八年二班打造淨灘機器人", "theme": "Common Nouns (2)", "themeZh": "常用名詞（二）", "article": ["Last Saturday, Class 802 of Linkou Junior High won first prize at the city science fair. Their project was a small robot. The purpose of the robot is simple. It picks up metal cans and plastic bottles on the beach. The class leader, Wang Yu-ting, said the idea came from a trip to the beach last summer.", "\"We saw a pile of garbage on the sand,\" Yu-ting told this newspaper in an interview. \"Pollution is a big problem for our planet. We wanted to do something about it.\" The class held a meeting every Friday during the lunch period. At first, the robot made many mistakes. It picked up rocks and leaves instead of cans. But the members did not give up. They changed the program again and again, and the robot made good progress.", "The result surprised everyone. In the final test, the robot picked up thirty cans in ten minutes. The judges said the project showed the importance of teamwork. The class will use the prize money to build a bigger robot. \"Next, we want a robot that works in the mud,\" Yu-ting said with a smile."], "translation": ["上星期六，林口國中八年二班在市科展中獲得第一名。他們的作品是一台小機器人。這台機器人的目的很簡單：撿起海灘上的金屬罐和塑膠瓶。班長王宇婷說，這個點子來自去年夏天的一次海灘之旅。", "「我們看到沙灘上有一堆垃圾，」宇婷接受本報訪問時說。「污染是我們地球的大問題，我們想為它做點什麼。」全班每星期五午休時間開會。一開始，機器人犯了很多錯誤。它撿起石頭和葉子，而不是罐子。但成員們沒有放棄。他們一次又一次修改程式，機器人有了很大的進步。", "結果讓所有人都很驚訝。在最後的測試中，機器人十分鐘內撿了三十個罐子。評審說這個作品展現了團隊合作的重要性。這個班級將用獎金打造更大的機器人。「接下來，我們想做一台能在泥巴裡工作的機器人，」宇婷微笑著說。"], "vocab": [{"word": "prize", "pos": "n.", "zh": "獎；獎品", "example": "She won a prize in the speech contest.", "exampleZh": "她在演講比賽中得獎。"}, {"word": "project", "pos": "n.", "zh": "專題；計畫", "example": "Our science project is about plants and light.", "exampleZh": "我們的科學專題是關於植物與光。"}, {"word": "purpose", "pos": "n.", "zh": "目的", "example": "The purpose of this meeting is to plan the trip.", "exampleZh": "這次會議的目的是規劃旅行。"}, {"word": "leader", "pos": "n.", "zh": "領導者；班長", "example": "A good leader listens to everyone.", "exampleZh": "好的領導者會傾聽每個人的意見。"}, {"word": "interview", "pos": "n.", "zh": "訪問；面試", "example": "The singer gave an interview on TV last night.", "exampleZh": "那位歌手昨晚在電視上接受訪問。"}, {"word": "pollution", "pos": "n.", "zh": "污染", "example": "Air pollution is getting worse in big cities.", "exampleZh": "大城市的空氣污染越來越嚴重。"}, {"word": "mistake", "pos": "n.", "zh": "錯誤", "example": "Everyone makes mistakes, so don't be too sad.", "exampleZh": "每個人都會犯錯，所以別太難過。"}, {"word": "progress", "pos": "n.", "zh": "進步", "example": "You have made great progress in English this year.", "exampleZh": "你今年的英文進步很多。"}], "phrases": [{"phrase": "pick up", "zh": "撿起", "example": "Please pick up the paper on the floor.", "exampleZh": "請把地上的紙撿起來。"}, {"phrase": "give up", "zh": "放棄", "example": "Never give up on your dreams.", "exampleZh": "永遠不要放棄你的夢想。"}, {"phrase": "again and again", "zh": "一再；反覆", "example": "He read the letter again and again.", "exampleZh": "他把那封信讀了一遍又一遍。"}], "grammar": [{"pattern": "S + V + A + instead of + B", "explain": "「…而不是…」，instead of 後面接名詞或動名詞，表示用前者取代後者。", "example": "I drank tea instead of coffee this morning.", "exampleZh": "我今天早上喝茶，而不是咖啡。"}, {"pattern": "S + said (that) + S + V", "explain": "間接引述別人說的話，said 後面接 that 子句，that 可省略；主要子句是過去式時，子句的動詞通常也用過去式。", "example": "The teacher said that the test was easy.", "exampleZh": "老師說那次考試很簡單。"}], "reading": [{"q": "What is the main idea of this report?", "options": ["A class won a prize with a robot that cleans the beach.", "A teacher took students to the beach.", "Pollution is a big problem in Linkou.", "Students should not throw garbage on the sand."], "answer": 0, "explain": "全文報導八年二班以淨灘機器人獲得科展第一名的經過。故選 (A)。"}, {"q": "Where did the idea for the robot come from?", "options": ["A science book", "A trip to the beach", "A TV program", "A meeting with the judges"], "answer": 1, "explain": "第一段說 the idea came from a trip to the beach last summer。故選 (B)。"}, {"q": "What problem did the robot have at first?", "options": ["It was too slow.", "It could not move on the sand.", "It picked up the wrong things.", "It broke after one day."], "answer": 2, "explain": "第二段說 It picked up rocks and leaves instead of cans，機器人一開始撿錯東西。故選 (C)。"}, {"q": "The word \"progress\" in paragraph 2 is closest in meaning to ____.", "options": ["noise", "money", "trouble", "improvement"], "answer": 3, "explain": "progress 指「進步」，與 improvement 意思最接近。故選 (D)。"}, {"q": "What will the class do with the prize money?", "options": ["Buy new computers", "Clean another beach", "Build a bigger robot", "Have a party"], "answer": 2, "explain": "第三段說 The class will use the prize money to build a bigger robot。故選 (C)。"}], "vocabQ": [{"q": "The river is full of ____ because the factory throws dirty water into it.", "options": ["pollution", "pressure", "peace", "power"], "answer": 0, "explain": "句意為「工廠把髒水排進河裡，所以河裡充滿污染」，pollution 污染。"}, {"q": "What is the ____ of your trip to Japan, study or travel?", "options": ["pattern", "purpose", "period", "prize"], "answer": 1, "explain": "句意為「你去日本的目的是讀書還是旅遊」，purpose 目的。"}, {"q": "I made a ____ on the math test, so I lost five points.", "options": ["method", "message", "mistake", "meeting"], "answer": 2, "explain": "句意為「我數學考試犯了一個錯，所以扣了五分」，mistake 錯誤。"}, {"q": "Amy had a job ____ at a bookstore yesterday, and she was very nervous.", "options": ["invitation", "interest", "information", "interview"], "answer": 3, "explain": "句意為「艾咪昨天在書店面試，她非常緊張」，interview 面試。"}, {"q": "The ____ of the team must make the final decision.", "options": ["leader", "player", "member", "human"], "answer": 0, "explain": "句意為「隊伍的領導者必須做最後的決定」，leader 領導者。"}]}, {"id": "E44", "level": "elem", "num": 44, "title": "Grandpa's Treasure Box", "titleZh": "爺爺的寶盒", "theme": "Common Nouns (3)", "themeZh": "常用名詞（三）", "article": ["Grandpa kept an old wooden box under his bed. It was his secret, and nobody could touch it. One rainy afternoon, Mei was bored. She sat on the floor and looked at the box. \"Is there treasure inside?\" she asked. Grandpa smiled and sat down next to her. \"Yes,\" he said. \"But not the kind you think.\"", "He opened the box slowly. Inside, there was no gold or money. There was an old train ticket, a small stone, and a black-and-white photo. The ticket was from his first trip to Taipei. The stone came from the shore near his old home. In the photo, a young man and a young woman stood under a tree. \"That was our wedding day,\" Grandpa said in a soft voice. \"Your grandma was so beautiful.\"", "Mei looked at each thing for a long time. Every one of them had a story. Then she understood the truth. The real treasure was not the things. It was the memories inside them. That night, Mei found an empty box in her room. She put her first movie ticket inside. It was the first step of her own treasure box."], "translation": ["爺爺在床底下放了一個舊木盒。那是他的祕密，誰都不能碰。一個下雨的午後，小美覺得很無聊。她坐在地板上看著那個盒子。「裡面有寶藏嗎？」她問。爺爺笑了，在她旁邊坐下。「有，」他說，「但不是你想的那種。」", "他慢慢打開盒子。裡面沒有金子，也沒有錢。有一張舊火車票、一顆小石頭和一張黑白照片。那張票是他第一次去台北的車票。石頭來自他老家附近的海岸。照片裡，一個年輕男子和一個年輕女子站在樹下。「那是我們結婚的日子，」爺爺輕聲說，「你奶奶好漂亮。」", "小美把每樣東西看了很久。每一樣都有一個故事。然後她明白了真相。真正的寶藏不是這些東西，而是藏在裡面的回憶。那天晚上，小美在房間找到一個空盒子。她把自己的第一張電影票放進去。那是她自己的寶盒的第一步。"], "vocab": [{"word": "secret", "pos": "n.", "zh": "祕密", "example": "Can you keep a secret? I have a new puppy.", "exampleZh": "你能保守祕密嗎？我有一隻新小狗。"}, {"word": "treasure", "pos": "n.", "zh": "寶藏；珍寶", "example": "The pirates hid their treasure on the island.", "exampleZh": "海盜把寶藏藏在島上。"}, {"word": "ticket", "pos": "n.", "zh": "票", "example": "I bought two tickets for the concert.", "exampleZh": "我買了兩張演唱會的票。"}, {"word": "stone", "pos": "n.", "zh": "石頭", "example": "The boy threw a stone into the river.", "exampleZh": "男孩把一顆石頭丟進河裡。"}, {"word": "shore", "pos": "n.", "zh": "岸；海岸", "example": "We walked along the shore and picked up shells.", "exampleZh": "我們沿著海岸散步，撿貝殼。"}, {"word": "wedding", "pos": "n.", "zh": "婚禮", "example": "My aunt's wedding will be in June.", "exampleZh": "我阿姨的婚禮將在六月舉行。"}, {"word": "truth", "pos": "n.", "zh": "真相；事實", "example": "Please tell me the truth. Did you break the cup?", "exampleZh": "請告訴我真相，杯子是你打破的嗎？"}, {"word": "memory", "pos": "n.", "zh": "回憶；記憶", "example": "I have many happy memories of my childhood.", "exampleZh": "我有很多童年的快樂回憶。"}], "phrases": [{"phrase": "next to", "zh": "在…旁邊", "example": "The post office is next to the bank.", "exampleZh": "郵局在銀行旁邊。"}, {"phrase": "sit down", "zh": "坐下", "example": "Please sit down and have some tea.", "exampleZh": "請坐下來喝點茶。"}, {"phrase": "for a long time", "zh": "很久", "example": "We waited for the bus for a long time.", "exampleZh": "我們等公車等了很久。"}], "grammar": [{"pattern": "There + was/were + N + 地方", "explain": "「某地有…」的過去式，單數或不可數名詞用 was，複數名詞用 were。", "example": "There was a cat under the table.", "exampleZh": "桌子底下有一隻貓。"}, {"pattern": "Every + 單數名詞 + 單數動詞", "explain": "every 後面接單數名詞，整個主詞視為單數，動詞要用單數形。", "example": "Every student has a dream.", "exampleZh": "每個學生都有夢想。"}], "reading": [{"q": "Why did Mei ask about the box?", "options": ["She wanted to sell it.", "Grandpa asked her to open it.", "She was bored on a rainy day.", "She lost her ticket in it."], "answer": 2, "explain": "第一段說 One rainy afternoon, Mei was bored，她因無聊而看著盒子並發問。故選 (C)。"}, {"q": "Which thing was NOT in the box?", "options": ["Gold", "A ticket", "A stone", "A photo"], "answer": 0, "explain": "第二段說 Inside, there was no gold or money，盒子裡沒有金子。故選 (A)。"}, {"q": "Who were the people in the photo?", "options": ["Mei and her mother", "Grandpa and Grandma", "Grandpa and his friend", "Two strangers"], "answer": 1, "explain": "第二段說 That was our wedding day，照片是爺爺和奶奶結婚那天拍的。故選 (B)。"}, {"q": "What did Mei learn from Grandpa's box?", "options": ["Old things can sell for a lot of money.", "Grandpa was a rich man.", "Memories are the real treasure.", "Everyone should keep a secret."], "answer": 2, "explain": "第三段說 The real treasure was not the things. It was the memories inside them。故選 (C)。"}, {"q": "What did Mei do at the end of the story?", "options": ["She gave Grandpa a new box.", "She threw away her movie ticket.", "She asked Grandpa for the stone.", "She started her own treasure box."], "answer": 3, "explain": "第三段最後說小美把第一張電影票放進空盒，開始自己的寶盒。故選 (D)。"}], "vocabQ": [{"q": "Don't tell anyone about the party. It's a ____.", "options": ["symbol", "secret", "step", "story"], "answer": 1, "explain": "句意為「別告訴任何人派對的事，這是個祕密」，secret 祕密。"}, {"q": "We stood on the ____ and watched the boats go by.", "options": ["shore", "tower", "tunnel", "screen"], "answer": 0, "explain": "句意為「我們站在岸邊看船經過」，shore 岸邊。"}, {"q": "You can't get on the train without a ____.", "options": ["seat", "title", "ticket", "term"], "answer": 2, "explain": "句意為「沒有票不能上火車」，ticket 票。"}, {"q": "I have a bad ____ , so I always write things down.", "options": ["voice", "skill", "sense", "memory"], "answer": 3, "explain": "句意為「我的記性不好，所以總是把事情寫下來」，memory 記憶。"}, {"q": "Everyone wore beautiful clothes to my cousin's ____ last Sunday.", "options": ["wedding", "war", "trade", "victory"], "answer": 0, "explain": "句意為「上星期天大家都穿漂亮衣服參加我表姊的婚禮」，wedding 婚禮。"}]}, {"id": "E45", "level": "elem", "num": 45, "title": "Sorry, Kevin", "titleZh": "對不起，凱文", "theme": "Mind & Emotion Verbs", "themeZh": "心智與情感動詞", "article": ["October 3. I still feel bad about what happened today. Kevin and I are best friends. This morning, I forgot to bring our group report to school. It was my job to print it. Kevin was angry and said, \"You always forget things!\" I felt embarrassed in front of everyone. Then I blamed him. I said he never checked anything. We did not talk for the rest of the day.", "After school, I sat on the MRT and thought about it. I realized that I was wrong. Kevin did not forget anything. I did. I worried that he would hate me now. I imagined him sitting with other friends tomorrow. That frightened me more than a bad grade. I wished I could go back to the morning.", "At night, I sent Kevin a message. I wrote, \"I'm sorry. It was my mistake. Please forgive me.\" I doubted that he would reply. But ten minutes later, my phone rang. \"It's OK,\" Kevin said. \"I'm sorry too. I was too loud.\" I guess good friends can survive a bad day. I will remember this lesson. Tomorrow, I will print the report first."], "translation": ["十月三日。我到現在還是對今天發生的事感到難過。凱文和我是最好的朋友。今天早上，我忘了把我們的小組報告帶到學校。印報告是我的工作。凱文很生氣，說：「你老是忘東忘西！」我在大家面前覺得很丟臉。然後我反過來怪他。我說他從來不檢查任何東西。那天剩下的時間我們都沒有說話。", "放學後，我坐在捷運上想著這件事。我發現是我錯了。凱文沒有忘記任何事，是我忘了。我擔心他現在會討厭我。我想像他明天跟別的朋友坐在一起。那比一個爛成績更讓我害怕。我真希望能回到早上。", "晚上，我傳了一則訊息給凱文。我寫道：「對不起，是我的錯，請原諒我。」我懷疑他會不會回覆。但十分鐘後，我的電話響了。「沒關係，」凱文說，「我也很抱歉，我太大聲了。」我想好朋友是可以撐過糟糕的一天的。我會記住這個教訓。明天，我要先把報告印好。"], "vocab": [{"word": "embarrass", "pos": "v.", "zh": "使尷尬；使難為情", "example": "Please don't embarrass me in front of my friends.", "exampleZh": "請不要在我朋友面前讓我難堪。"}, {"word": "blame", "pos": "v.", "zh": "責怪", "example": "Don't blame your sister. It was not her fault.", "exampleZh": "別怪你妹妹，那不是她的錯。"}, {"word": "realize", "pos": "v.", "zh": "領悟；發現", "example": "I realized that I left my keys at home.", "exampleZh": "我發現我把鑰匙忘在家裡了。"}, {"word": "imagine", "pos": "v.", "zh": "想像", "example": "Can you imagine a world without phones?", "exampleZh": "你能想像一個沒有手機的世界嗎？"}, {"word": "frighten", "pos": "v.", "zh": "使害怕", "example": "The loud noise frightened the baby.", "exampleZh": "巨大的聲響嚇到了嬰兒。"}, {"word": "forgive", "pos": "v.", "zh": "原諒", "example": "She forgave him for breaking her cup.", "exampleZh": "她原諒了他打破她的杯子。"}, {"word": "doubt", "pos": "v.", "zh": "懷疑", "example": "I doubt that it will rain today.", "exampleZh": "我懷疑今天會不會下雨。"}, {"word": "survive", "pos": "v.", "zh": "倖存；撐過", "example": "The old tree survived the typhoon.", "exampleZh": "那棵老樹撐過了颱風。"}], "phrases": [{"phrase": "in front of", "zh": "在…前面", "example": "There is a big tree in front of our school.", "exampleZh": "我們學校前面有一棵大樹。"}, {"phrase": "feel bad about", "zh": "對…感到難過", "example": "I feel bad about missing your birthday.", "exampleZh": "我對錯過你的生日感到很抱歉。"}, {"phrase": "the rest of", "zh": "剩下的", "example": "We spent the rest of the day at home.", "exampleZh": "那天剩下的時間我們都待在家裡。"}], "grammar": [{"pattern": "S + wish + (that) + S + could + V", "explain": "wish 表示「但願」，用來說與現在事實相反的願望，子句的動詞要用過去式，所以 can 要改成 could。", "example": "I wish I could fly like a bird.", "exampleZh": "我真希望能像鳥一樣飛。"}, {"pattern": "S + realize + (that) + S + V", "explain": "「發現、領悟到…」，realize 後面接 that 子句，說明領悟到的內容，that 可以省略。", "example": "He realized that he was on the wrong bus.", "exampleZh": "他發現自己搭錯公車了。"}], "reading": [{"q": "What is this passage?", "options": ["A letter to Kevin", "A story in a newspaper", "A diary about a fight with a friend", "An e-mail to a teacher"], "answer": 2, "explain": "文章以日期開頭、第一人稱記錄當天與朋友吵架的心情，是日記。故選 (C)。"}, {"q": "Why was Kevin angry in the morning?", "options": ["The writer forgot the group report.", "The writer was late for school.", "The writer broke Kevin's phone.", "The writer did not do the homework."], "answer": 0, "explain": "第一段說 I forgot to bring our group report to school，凱文因此生氣。故選 (A)。"}, {"q": "What did the writer realize on the MRT?", "options": ["Kevin forgot the report.", "The writer was wrong.", "Kevin had new friends.", "The report was not important."], "answer": 1, "explain": "第二段說 I realized that I was wrong. Kevin did not forget anything. I did。故選 (B)。"}, {"q": "The word \"frightened\" in paragraph 2 is closest in meaning to ____.", "options": ["surprised", "bored", "scared", "pleased"], "answer": 2, "explain": "frightened 是「使害怕」的過去式，與 scared 意思最接近。故選 (C)。"}, {"q": "How did Kevin feel after he read the message?", "options": ["He was still very angry.", "He did not want to talk.", "He was happy and said sorry too.", "He asked the writer to print the report."], "answer": 2, "explain": "第三段凱文回電說 It's OK. I'm sorry too，表示他不再生氣，也道歉了。故選 (C)。"}], "vocabQ": [{"q": "When Mom found out I lied, I asked her to ____ me.", "options": ["forgive", "blame", "doubt", "frighten"], "answer": 0, "explain": "句意為「媽媽發現我說謊時，我請她原諒我」，forgive 原諒。"}, {"q": "Don't ____ me for the broken window. I was not even at home!", "options": ["imagine", "blame", "survive", "realize"], "answer": 1, "explain": "句意為「別為了破掉的窗戶怪我，我根本不在家」，blame 責怪。"}, {"q": "Only a few plants can ____ in the hot desert.", "options": ["embarrass", "doubt", "imagine", "survive"], "answer": 3, "explain": "句意為「只有少數植物能在炎熱的沙漠中存活」，survive 存活。"}, {"q": "Close your eyes and ____ a beach with white sand and blue water.", "options": ["frighten", "forgive", "imagine", "blame"], "answer": 2, "explain": "句意為「閉上眼睛，想像一片有白沙和藍海的海灘」，imagine 想像。"}, {"q": "I ____ that he can finish the work in one day. It's too much.", "options": ["doubt", "survive", "embarrass", "forgive"], "answer": 0, "explain": "句意為「我懷疑他能一天做完，工作太多了」，doubt 懷疑。"}]}, {"id": "E46", "level": "elem", "num": 46, "title": "How to Make Scallion Pancakes at Home", "titleZh": "在家做蔥油餅", "theme": "Action Verbs (1)", "themeZh": "動作動詞（一）", "article": ["Scallion pancakes are a popular snack in Taiwan's night markets. Do you want to make them at home? First, bring these things to the table: two cups of flour, one cup of hot water, some green onions, salt, and oil. Choose fresh green onions. Cut them into small pieces and put them in a bowl.", "Next, mix the flour and the hot water in a big bowl. Use your hands to make a soft ball. Cover the bowl with a towel and let the dough rest for twenty minutes. Then roll the dough into a thin, round piece. Brush some oil on it, and drop the green onions and a little salt on top. Roll it up like a rope, and then roll it into a snail shape. Push it down and roll it flat one more time.", "Finally, heat some oil in a pan. Fry the pancake for two minutes. Then lift it with a spatula and fry the other side. Shake the pan a little, so the pancake does not stick. When both sides are golden, take it out and cut it into pieces. Hand a piece to your family and watch their smiles. Making food is more fun than buying it!"], "translation": ["蔥油餅是台灣夜市裡很受歡迎的小吃。你想在家做做看嗎？首先，把這些東西拿到桌上：兩杯麵粉、一杯熱水、一些蔥、鹽和油。挑選新鮮的蔥。把蔥切成小段，放進碗裡。", "接著，在大碗裡把麵粉和熱水混合。用手揉成一個柔軟的麵團。用毛巾蓋住碗，讓麵團醒二十分鐘。然後把麵團擀成薄薄的圓片。在上面刷一些油，撒上蔥花和一點鹽。像繩子一樣把它捲起來，再捲成蝸牛的形狀。壓平，再擀一次。", "最後，在平底鍋裡把油燒熱。把餅煎兩分鐘。然後用鍋鏟把它翻起來，煎另一面。稍微搖一搖鍋子，餅才不會黏鍋。當兩面都變成金黃色，就拿出來切塊。把一塊遞給家人，看看他們的笑容。自己做食物比用買的更有趣！"], "vocab": [{"word": "choose", "pos": "v.", "zh": "選擇", "example": "You can choose any book you like.", "exampleZh": "你可以選任何你喜歡的書。"}, {"word": "mix", "pos": "v.", "zh": "混合", "example": "Mix the eggs and the milk in a bowl.", "exampleZh": "把蛋和牛奶在碗裡混合。"}, {"word": "cover", "pos": "v.", "zh": "覆蓋；蓋住", "example": "Cover the pot and wait for ten minutes.", "exampleZh": "把鍋子蓋上，等十分鐘。"}, {"word": "roll", "pos": "v.", "zh": "滾動；捲；擀", "example": "The ball rolled under the car.", "exampleZh": "球滾到車子底下了。"}, {"word": "brush", "pos": "v.", "zh": "刷", "example": "Brush your teeth before you go to bed.", "exampleZh": "睡覺前要刷牙。"}, {"word": "fry", "pos": "v.", "zh": "煎；炸", "example": "Dad fried two eggs for breakfast.", "exampleZh": "爸爸煎了兩顆蛋當早餐。"}, {"word": "lift", "pos": "v.", "zh": "舉起；抬起", "example": "The box is too heavy. I can't lift it.", "exampleZh": "箱子太重了，我抬不起來。"}, {"word": "shake", "pos": "v.", "zh": "搖動", "example": "Shake the bottle before you drink the juice.", "exampleZh": "喝果汁前先把瓶子搖一搖。"}], "phrases": [{"phrase": "roll up", "zh": "捲起來", "example": "Roll up the map and put it in your bag.", "exampleZh": "把地圖捲起來放進你的包包。"}, {"phrase": "take out", "zh": "拿出來", "example": "Take out your homework, please.", "exampleZh": "請把你的功課拿出來。"}, {"phrase": "one more time", "zh": "再一次", "example": "Let's sing the song one more time.", "exampleZh": "我們再唱一次這首歌吧。"}], "grammar": [{"pattern": "Let + O + V (原形)", "explain": "「讓某人／某物做某事」，let 後面接受詞，再接原形動詞，不加 to。", "example": "Let the soup cool for a few minutes.", "exampleZh": "讓湯涼幾分鐘。"}, {"pattern": "First, ... Next, ... Then, ... Finally, ... + 祈使句", "explain": "說明步驟時，用 First、Next、Then、Finally 等順序詞加上祈使句（原形動詞開頭），清楚表達先後順序。", "example": "First, wash the rice. Then, add some water.", "exampleZh": "首先，把米洗乾淨。然後，加一些水。"}], "reading": [{"q": "What is the purpose of this passage?", "options": ["To tell a story about a night market", "To teach readers how to make a snack", "To sell scallion pancakes", "To describe a famous cook"], "answer": 1, "explain": "全文一步一步說明蔥油餅的做法，目的是教讀者製作點心。故選 (B)。"}, {"q": "What should you do right after you mix the flour and water?", "options": ["Fry the dough in a pan", "Cut the green onions", "Make a soft ball with your hands", "Brush oil on the dough"], "answer": 2, "explain": "第二段說 mix the flour and the hot water... Use your hands to make a soft ball。故選 (C)。"}, {"q": "How long should the dough rest?", "options": ["Two minutes", "Ten minutes", "Twenty minutes", "One hour"], "answer": 2, "explain": "第二段說 let the dough rest for twenty minutes。故選 (C)。"}, {"q": "Why should you shake the pan?", "options": ["So the pancake does not stick", "So the oil gets hot faster", "So the pancake becomes round", "So the green onions mix well"], "answer": 0, "explain": "第三段說 Shake the pan a little, so the pancake does not stick。故選 (A)。"}, {"q": "What does the writer think about making food?", "options": ["It is harder than buying it.", "It is boring.", "It is more fun than buying it.", "It is only for night markets."], "answer": 2, "explain": "最後一句說 Making food is more fun than buying it!。故選 (C)。"}], "vocabQ": [{"q": "Please ____ the baby's shoes before you go into the house.", "options": ["shake", "brush", "fry", "cover"], "answer": 1, "explain": "句意為「進屋前請把寶寶的鞋子刷乾淨」，brush 刷。"}, {"q": "There are three colors. You can ____ only one.", "options": ["choose", "lift", "mix", "roll"], "answer": 0, "explain": "句意為「有三種顏色，你只能選一種」，choose 選擇。"}, {"q": "Grandma will ____ some fish for dinner tonight.", "options": ["cover", "shake", "fry", "lift"], "answer": 2, "explain": "句意為「奶奶今晚要煎魚當晚餐」，fry 煎。"}, {"q": "It's raining. ____ the bikes with a big plastic sheet.", "options": ["Mix", "Fry", "Choose", "Cover"], "answer": 3, "explain": "句意為「下雨了，用大塑膠布把腳踏車蓋起來」，cover 覆蓋。"}, {"q": "The ground started to ____ , and the lights went out.", "options": ["shake", "brush", "roll", "choose"], "answer": 0, "explain": "句意為「地面開始搖晃，燈都熄了」，shake 搖動。"}]}, {"id": "E47", "level": "elem", "num": 47, "title": "Rain on Picnic Day", "titleZh": "野餐日的雨", "theme": "Action Verbs (2)", "themeZh": "動作動詞（二）", "article": ["\"It's raining!\" Tina shouted on Sunday morning. She called her friend Leo right away. \"Our picnic is ruined. Should we cancel it?\" Leo was quiet for a moment. \"Wait,\" he said. \"Don't decide so fast. Let's discuss it. Maybe we can arrange something else.\"", "Tina complained, \"But I prepared sandwiches for ten people!\" Leo laughed. \"Then we can't waste them. I suggest we have the picnic at my house. My mom will allow it. We can sit on the floor and share the food.\" Tina was not sure. \"Will everyone agree?\" she asked. \"Let's invite them and see,\" Leo said. \"I promise it will be fun.\"", "Tina sent a message to the group. In five minutes, everyone replied \"Yes!\" At noon, ten friends appeared at Leo's door with umbrellas. They ate on the living room floor and played cards. Tina's sandwiches disappeared quickly. \"Thank you for not giving up,\" Tina told Leo. \"Sometimes a problem is just a chance to try something new.\" Leo smiled. \"See? We solved it together.\""], "translation": ["「下雨了！」星期天早上，蒂娜大叫。她立刻打電話給朋友里歐。「我們的野餐泡湯了，要取消嗎？」里歐安靜了一會兒。「等等，」他說，「別這麼快決定。我們討論一下。也許可以安排別的。」", "蒂娜抱怨：「可是我準備了十個人份的三明治！」里歐笑了。「那我們就不能浪費。我建議把野餐改在我家。我媽會答應的。我們可以坐在地板上分享食物。」蒂娜不太確定。「大家都會同意嗎？」她問。「我們邀他們看看，」里歐說，「我保證會很好玩。」", "蒂娜傳了訊息到群組。五分鐘內，每個人都回了「好！」中午，十位朋友撐著雨傘出現在里歐家門口。他們在客廳地板上吃東西、玩牌。蒂娜的三明治很快就被吃光了。「謝謝你沒有放棄，」蒂娜對里歐說，「有時候問題只是嘗試新事物的機會。」里歐笑著說：「看吧？我們一起解決了。」"], "vocab": [{"word": "cancel", "pos": "v.", "zh": "取消", "example": "The school canceled the sports day because of the typhoon.", "exampleZh": "學校因為颱風取消了運動會。"}, {"word": "arrange", "pos": "v.", "zh": "安排", "example": "My mom arranged a trip to Tainan for us.", "exampleZh": "媽媽幫我們安排了一趟台南之旅。"}, {"word": "complain", "pos": "v.", "zh": "抱怨", "example": "He always complains about the hot weather.", "exampleZh": "他老是抱怨天氣太熱。"}, {"word": "suggest", "pos": "v.", "zh": "建議", "example": "I suggest we take the MRT instead of a taxi.", "exampleZh": "我建議我們搭捷運，不要搭計程車。"}, {"word": "allow", "pos": "v.", "zh": "允許", "example": "My parents don't allow me to stay up late.", "exampleZh": "我爸媽不准我熬夜。"}, {"word": "promise", "pos": "v.", "zh": "承諾；保證", "example": "Dad promised to take us to the zoo on Sunday.", "exampleZh": "爸爸答應星期天帶我們去動物園。"}, {"word": "appear", "pos": "v.", "zh": "出現", "example": "A rainbow appeared in the sky after the rain.", "exampleZh": "雨後天空出現一道彩虹。"}, {"word": "solve", "pos": "v.", "zh": "解決", "example": "Can you solve this math problem?", "exampleZh": "你能解這道數學題嗎？"}], "phrases": [{"phrase": "right away", "zh": "立刻", "example": "Call the doctor right away!", "exampleZh": "馬上打電話給醫生！"}, {"phrase": "for a moment", "zh": "一會兒", "example": "She stopped for a moment and then kept walking.", "exampleZh": "她停了一會兒，然後繼續走。"}, {"phrase": "give up", "zh": "放棄", "example": "The game was hard, but we did not give up.", "exampleZh": "比賽很艱難，但我們沒有放棄。"}], "grammar": [{"pattern": "Let's + V (原形)", "explain": "「我們…吧」，用來提議一起做某事，Let's 後面接原形動詞。", "example": "Let's go to the night market tonight.", "exampleZh": "我們今晚去夜市吧。"}, {"pattern": "Thank you for + V-ing / N", "explain": "「謝謝你做了…」，for 是介系詞，後面要接名詞或動名詞。", "example": "Thank you for helping me with my homework.", "exampleZh": "謝謝你幫我做功課。"}], "reading": [{"q": "Why did Tina call Leo in the morning?", "options": ["She wanted to buy sandwiches.", "It was raining on their picnic day.", "Leo forgot the umbrellas.", "She was late for the picnic."], "answer": 1, "explain": "第一段說 It's raining! ... Our picnic is ruined，蒂娜因為下雨而打電話。故選 (B)。"}, {"q": "What did Leo suggest?", "options": ["To cancel the picnic", "To have the picnic next week", "To have the picnic at his house", "To eat at a restaurant"], "answer": 2, "explain": "第二段說 I suggest we have the picnic at my house。故選 (C)。"}, {"q": "How many friends came to Leo's house?", "options": ["Five", "Eight", "Ten", "Twelve"], "answer": 2, "explain": "第三段說 ten friends appeared at Leo's door with umbrellas。故選 (C)。"}, {"q": "The word \"disappeared\" in paragraph 3 is closest in meaning to ____.", "options": ["were all eaten", "were thrown away", "got cold", "were too many"], "answer": 0, "explain": "三明治 disappeared quickly 是指很快被吃光了。故選 (A)。"}, {"q": "What can we learn from this story?", "options": ["Picnics are only fun on sunny days.", "Never make sandwiches for ten people.", "A problem can be a chance to try something new.", "Friends should not call each other in the morning."], "answer": 2, "explain": "第三段蒂娜說 Sometimes a problem is just a chance to try something new，這是故事的啟示。故選 (C)。"}], "vocabQ": [{"q": "The teacher does not ____ us to eat in the classroom.", "options": ["allow", "cancel", "complain", "appear"], "answer": 0, "explain": "句意為「老師不允許我們在教室吃東西」，allow 允許。"}, {"q": "The customers always ____ about the slow service at that restaurant.", "options": ["arrange", "complain", "promise", "solve"], "answer": 1, "explain": "句意為「顧客老是抱怨那家餐廳服務太慢」，complain 抱怨。"}, {"q": "The singer was sick, so they had to ____ the concert.", "options": ["suggest", "appear", "cancel", "allow"], "answer": 2, "explain": "句意為「歌手生病了，所以他們必須取消演唱會」，cancel 取消。"}, {"q": "Dad will ____ a dinner with our new neighbors this weekend.", "options": ["solve", "complain", "promise", "arrange"], "answer": 3, "explain": "句意為「爸爸這週末會安排一頓和新鄰居的晚餐」，arrange 安排。"}, {"q": "I ____ I will never tell your secret to anyone.", "options": ["promise", "appear", "cancel", "suggest"], "answer": 0, "explain": "句意為「我保證絕不把你的祕密告訴任何人」，promise 保證。"}]}, {"id": "E48", "level": "elem", "num": 48, "title": "Welcome to Tamsui", "titleZh": "歡迎來到淡水", "theme": "Adjectives", "themeZh": "形容詞", "article": ["Are you looking for a perfect place for a day trip? Tamsui is a popular town in New Taipei City. It is convenient to get there. Just take the red line of the MRT to the last stop. The town is famous for its old street and its sunset. Both local people and foreign visitors love it.", "The old street is crowded and noisy on weekends, but it is never boring. You can buy traditional snacks like fish balls and iron eggs. The shops are colorful, and the smells are wonderful. If you want a quiet place, walk along the river. The path is broad and safe, and the view is peaceful. You can also rent a bike there. It is cheap and easy.", "In the evening, go to Fisherman's Wharf. The sunset there is fantastic. The sky turns orange, and the water looks bright gold. It is a special moment, and it is free! Many people say it is the most beautiful sunset in northern Taiwan. Are you ready for a day in Tamsui? Bring a camera and a big appetite!"], "translation": ["你在找一日遊的完美地點嗎？淡水是新北市一個很受歡迎的小鎮。到那裡很方便，只要搭捷運紅線到最後一站就可以了。這個小鎮以老街和夕陽聞名。本地人和外國遊客都很喜歡它。", "週末的老街既擁擠又吵鬧，但絕不無聊。你可以買魚丸、鐵蛋等傳統小吃。商店色彩繽紛，香味撲鼻。如果你想找個安靜的地方，可以沿著河邊走。步道寬敞又安全，景色寧靜。你也可以在那裡租腳踏車，又便宜又方便。", "傍晚，到漁人碼頭去。那裡的夕陽美極了。天空變成橘色，水面看起來像明亮的金色。這是個特別的時刻，而且是免費的！很多人說那是北台灣最美的夕陽。你準備好來淡水玩一天了嗎？帶著相機和好胃口來吧！"], "vocab": [{"word": "convenient", "pos": "adj.", "zh": "方便的", "example": "Living near the MRT station is very convenient.", "exampleZh": "住在捷運站附近非常方便。"}, {"word": "popular", "pos": "adj.", "zh": "受歡迎的", "example": "Bubble tea is popular all over the world.", "exampleZh": "珍珠奶茶在全世界都很受歡迎。"}, {"word": "foreign", "pos": "adj.", "zh": "外國的", "example": "Learning a foreign language takes time.", "exampleZh": "學外語需要時間。"}, {"word": "crowded", "pos": "adj.", "zh": "擁擠的", "example": "The MRT is always crowded at eight in the morning.", "exampleZh": "早上八點的捷運總是很擠。"}, {"word": "traditional", "pos": "adj.", "zh": "傳統的", "example": "We eat traditional rice dumplings on Dragon Boat Festival.", "exampleZh": "端午節我們吃傳統的粽子。"}, {"word": "broad", "pos": "adj.", "zh": "寬闊的", "example": "The new road is broad and smooth.", "exampleZh": "新馬路又寬又平。"}, {"word": "peaceful", "pos": "adj.", "zh": "寧靜的；和平的", "example": "The village is peaceful at night.", "exampleZh": "這個村子晚上很寧靜。"}, {"word": "fantastic", "pos": "adj.", "zh": "極好的", "example": "We had a fantastic time at the concert.", "exampleZh": "我們在演唱會玩得非常開心。"}], "phrases": [{"phrase": "look for", "zh": "尋找", "example": "I am looking for my glasses. Have you seen them?", "exampleZh": "我在找我的眼鏡，你有看到嗎？"}, {"phrase": "be famous for", "zh": "以…聞名", "example": "Tainan is famous for its delicious food.", "exampleZh": "台南以美食聞名。"}, {"phrase": "be ready for", "zh": "準備好…", "example": "Are you ready for the big test tomorrow?", "exampleZh": "你準備好明天的大考了嗎？"}], "grammar": [{"pattern": "It + is + adj. + to + V", "explain": "「做某事是…的」，It 是虛主詞，真正的主詞是後面的不定詞 to V。", "example": "It is easy to get lost in a big city.", "exampleZh": "在大城市裡很容易迷路。"}, {"pattern": "the most + adj. + N + in + 範圍", "explain": "最高級，三個音節以上的形容詞前面加 the most，表示「在…之中最…的」。", "example": "This is the most popular night market in Taipei.", "exampleZh": "這是台北最受歡迎的夜市。"}], "reading": [{"q": "What is this passage mainly about?", "options": ["How to take the MRT in Taipei", "A good place for a day trip", "The history of Tamsui", "How to rent a bike"], "answer": 1, "explain": "全文介紹淡水作為一日遊地點的各種好處。故選 (B)。"}, {"q": "How can visitors get to Tamsui?", "options": ["By bike along the river", "By boat from Fisherman's Wharf", "By the red line of the MRT", "By bus from the old street"], "answer": 2, "explain": "第一段說 Just take the red line of the MRT to the last stop。故選 (C)。"}, {"q": "Which is true about the old street?", "options": ["It is quiet on weekends.", "It sells traditional snacks.", "It is far from the MRT.", "Bikes are not allowed there."], "answer": 1, "explain": "第二段說 You can buy traditional snacks like fish balls and iron eggs。故選 (B)。"}, {"q": "The word \"broad\" in paragraph 2 is closest in meaning to ____.", "options": ["wide", "long", "dark", "new"], "answer": 0, "explain": "broad 是「寬闊的」，與 wide 意思最接近。故選 (A)。"}, {"q": "Why does the writer say \"Bring a camera and a big appetite\"?", "options": ["Because the shops sell cameras.", "Because there is nothing to eat.", "Because the sunset is beautiful and the food is good.", "Because the trip is expensive."], "answer": 2, "explain": "相機是為了拍美麗的夕陽，好胃口是為了品嚐老街小吃。故選 (C)。"}], "vocabQ": [{"q": "The park is ____ in the early morning. You can hear only the birds.", "options": ["crowded", "peaceful", "popular", "foreign"], "answer": 1, "explain": "句意為「清晨的公園很寧靜，只聽得到鳥叫」，peaceful 寧靜的。"}, {"q": "The bus was so ____ that I could not find a seat.", "options": ["crowded", "broad", "traditional", "convenient"], "answer": 0, "explain": "句意為「公車太擠了，我找不到座位」，crowded 擁擠的。"}, {"q": "Many ____ students come to Taiwan to study Chinese.", "options": ["fantastic", "peaceful", "foreign", "broad"], "answer": 2, "explain": "句意為「許多外國學生來台灣學中文」，foreign 外國的。"}, {"q": "Online shopping is ____ because you don't have to leave home.", "options": ["traditional", "crowded", "popular", "convenient"], "answer": 3, "explain": "句意為「網購很方便，因為不必出門」，convenient 方便的。"}, {"q": "Grandma still makes rice cakes in the ____ way, without a machine.", "options": ["traditional", "fantastic", "convenient", "foreign"], "answer": 0, "explain": "句意為「奶奶仍然用傳統的方式做年糕，不用機器」，traditional 傳統的。"}]}, {"id": "E49", "level": "elem", "num": 49, "title": "After-School Life in Class 901", "titleZh": "九年一班的課後生活", "theme": "Frequency & Degree Adverbs", "themeZh": "頻率與程度副詞", "article": ["Last week, our class did a survey about after-school life. Thirty students answered ten questions. The results are quite interesting. Almost everyone goes to a cram school at least twice a week. Twelve students go nearly every day. Only three students never go. They usually study at home with their parents.", "Sports are also popular. Half of the class often plays basketball or badminton after dinner. However, girls seldom play ball games. They would rather ride bikes or walk together. Sleep is a big problem. Most students hardly ever sleep before eleven. Actually, five students said they sometimes sleep at one o'clock! They are always tired in the morning.", "Finally, we asked about phones. Nearly all students use their phones for more than two hours a day. Even the top student in our class uses it a lot, especially on weekends. What does this tell us? Perhaps we are all too busy. We need more sleep and less screen time. We will probably do the survey again next term and see if anything changes."], "translation": ["上星期，我們班做了一份關於課後生活的問卷調查。三十位同學回答了十個問題。結果相當有趣。幾乎每個人每週至少上兩次補習班。十二位同學幾乎天天去。只有三位同學從來不去，他們通常在家跟父母一起讀書。", "運動也很受歡迎。班上有一半的人晚餐後常打籃球或羽球。不過，女生很少打球類運動，她們寧願一起騎腳踏車或散步。睡眠是個大問題。大多數同學幾乎從不在十一點前睡覺。事實上，有五位同學說他們有時候一點才睡！他們早上總是很累。", "最後，我們問了手機的問題。幾乎所有同學每天使用手機超過兩小時。就連班上第一名也用很多，特別是週末。這告訴我們什麼？也許我們都太忙了。我們需要更多睡眠、更少的螢幕時間。我們下學期大概會再做一次調查，看看有沒有任何改變。"], "vocab": [{"word": "almost", "pos": "adv.", "zh": "幾乎", "example": "It is almost ten o'clock. Let's go to bed.", "exampleZh": "快十點了，我們去睡覺吧。"}, {"word": "twice", "pos": "adv.", "zh": "兩次", "example": "I brush my teeth twice a day.", "exampleZh": "我一天刷兩次牙。"}, {"word": "seldom", "pos": "adv.", "zh": "很少；不常", "example": "My grandpa seldom watches TV.", "exampleZh": "我爺爺很少看電視。"}, {"word": "rather", "pos": "adv.", "zh": "寧願；相當", "example": "I would rather stay home than go out in the rain.", "exampleZh": "我寧願待在家，也不想在雨中出門。"}, {"word": "hardly", "pos": "adv.", "zh": "幾乎不", "example": "He was so tired that he could hardly walk.", "exampleZh": "他累得幾乎走不動。"}, {"word": "actually", "pos": "adv.", "zh": "事實上", "example": "Actually, I don't like coffee very much.", "exampleZh": "事實上，我不太喜歡咖啡。"}, {"word": "especially", "pos": "adv.", "zh": "特別；尤其", "example": "I love fruit, especially mangoes.", "exampleZh": "我喜歡水果，尤其是芒果。"}, {"word": "probably", "pos": "adv.", "zh": "大概；可能", "example": "It will probably rain this afternoon.", "exampleZh": "今天下午大概會下雨。"}], "phrases": [{"phrase": "at least", "zh": "至少", "example": "You should drink at least six glasses of water a day.", "exampleZh": "你一天至少要喝六杯水。"}, {"phrase": "would rather", "zh": "寧願", "example": "She would rather read than play video games.", "exampleZh": "她寧願看書也不想打電動。"}, {"phrase": "more than", "zh": "超過", "example": "More than fifty people came to the party.", "exampleZh": "超過五十個人來參加派對。"}], "grammar": [{"pattern": "S + hardly ever + V", "explain": "hardly ever 表示「幾乎從不」，本身帶有否定意味，所以句子不再加 not。", "example": "My dad hardly ever cooks dinner.", "exampleZh": "我爸爸幾乎從不煮晚餐。"}, {"pattern": "頻率副詞的位置：be 動詞之後、一般動詞之前", "explain": "always、usually、often、sometimes、seldom、never 等頻率副詞放在 be 動詞後面，或一般動詞前面。", "example": "He is always late. He never takes the bus.", "exampleZh": "他總是遲到。他從不搭公車。"}], "reading": [{"q": "What is this passage?", "options": ["A diary about a busy week", "A report on a class survey", "A letter to parents", "An advertisement for a cram school"], "answer": 1, "explain": "第一段說 our class did a survey，全文報告問卷結果。故選 (B)。"}, {"q": "How many students never go to a cram school?", "options": ["Three", "Five", "Twelve", "Thirty"], "answer": 0, "explain": "第一段說 Only three students never go。故選 (A)。"}, {"q": "What do most girls in the class like to do after school?", "options": ["Play basketball", "Go to a cram school every day", "Ride bikes or walk together", "Study with their parents"], "answer": 2, "explain": "第二段說 girls seldom play ball games. They would rather ride bikes or walk together。故選 (C)。"}, {"q": "Which is true about sleep in Class 901?", "options": ["Most students sleep before eleven.", "Five students sometimes sleep at one o'clock.", "Nobody is tired in the morning.", "The top student sleeps the most."], "answer": 1, "explain": "第二段說 five students said they sometimes sleep at one o'clock。故選 (B)。"}, {"q": "What does the writer think the class needs?", "options": ["More homework and less sports", "More phones and less sleep", "More cram schools", "More sleep and less screen time"], "answer": 3, "explain": "第三段說 We need more sleep and less screen time。故選 (D)。"}], "vocabQ": [{"q": "I like all kinds of music, ____ jazz.", "options": ["seldom", "hardly", "especially", "twice"], "answer": 2, "explain": "句意為「我喜歡各種音樂，尤其是爵士樂」，especially 尤其。"}, {"q": "The movie was so boring that I ____ fell asleep.", "options": ["almost", "seldom", "rather", "twice"], "answer": 0, "explain": "句意為「電影太無聊，我差點睡著」，almost 幾乎。"}, {"q": "Dad ____ ever gets angry. He is a very kind man.", "options": ["twice", "hardly", "probably", "actually"], "answer": 1, "explain": "句意為「爸爸幾乎從不生氣，他是個很和善的人」，hardly ever 幾乎從不。"}, {"q": "We go to Grandma's house ____ a month, on the first and third Sundays.", "options": ["especially", "hardly", "actually", "twice"], "answer": 3, "explain": "句意為「我們一個月去奶奶家兩次，在第一和第三個星期天」，twice 兩次。"}, {"q": "The sky is dark. It will ____ rain soon.", "options": ["seldom", "rather", "probably", "twice"], "answer": 2, "explain": "句意為「天色很暗，大概很快會下雨」，probably 大概。"}]}, {"id": "E50", "level": "elem", "num": 50, "title": "My First Week in Kyoto", "titleZh": "我在京都的第一週", "theme": "Sense Verbs / Other Adverbs & Responses / Articles & Pronouns / Conjunctions", "themeZh": "感官動詞／其他副詞與應答／冠詞、指示詞與代名詞／連接詞", "article": ["Hi, everyone! This is my first blog post from abroad. I am in Kyoto for a two-week homestay. My host family is very kind. Nobody speaks much English, and my Japanese is not good either. However, we understand each other with smiles and hand signs. Everything here looks different, and I love it.", "In the morning, I hear birds outside my window. Breakfast is rice, fish, and soup. It tastes a little strange, but it smells great. My host mother cooks everything herself. After breakfast, I walk to the language school. Temples are everywhere, and the streets feel so quiet. Nobody talks aloud on the bus. At first, I thought that was strange. Now I think it sounds peaceful.", "Yesterday, we watched a tea ceremony. Each step was slow and careful. I listened to the teacher and tried to copy her. Although I made some mistakes, she smiled at me. Besides, the tea tasted wonderful. I feel lucky to be here. Next week, we will go somewhere special. I will tell you all about it then!"], "translation": ["大家好！這是我第一篇來自國外的部落格文章。我在京都進行為期兩週的寄宿家庭生活。我的寄宿家庭非常親切。沒有人會說多少英文，而我的日文也不好。不過，我們用微笑和手勢就能了解彼此。這裡的一切看起來都不一樣，我很喜歡。", "早上，我聽到窗外的鳥叫聲。早餐是白飯、魚和湯。味道有點奇怪，但聞起來很香。寄宿媽媽所有的菜都自己煮。早餐後，我走路去語言學校。到處都是寺廟，街道感覺好安靜。公車上沒有人大聲說話。一開始我覺得那很奇怪，現在我覺得這聽起來很平靜。", "昨天，我們觀看了茶道。每個步驟都緩慢而仔細。我聽老師講解，並試著模仿她。雖然我犯了一些錯，她還是對我微笑。此外，茶的味道非常棒。我覺得能來這裡很幸運。下星期，我們會去一個特別的地方。到時候我再全部告訴你們！"], "vocab": [{"word": "abroad", "pos": "adv.", "zh": "在國外；到國外", "example": "My cousin is studying abroad in Canada.", "exampleZh": "我表哥在加拿大留學。"}, {"word": "hear", "pos": "v.", "zh": "聽到", "example": "Did you hear the phone ring?", "exampleZh": "你有聽到電話響嗎？"}, {"word": "taste", "pos": "v.", "zh": "嚐起來；品嚐", "example": "This soup tastes too salty.", "exampleZh": "這湯嚐起來太鹹了。"}, {"word": "smell", "pos": "v.", "zh": "聞起來；聞", "example": "The flowers smell sweet.", "exampleZh": "這些花聞起來很香。"}, {"word": "everywhere", "pos": "adv.", "zh": "到處", "example": "There were people everywhere at the festival.", "exampleZh": "節慶時到處都是人。"}, {"word": "aloud", "pos": "adv.", "zh": "出聲地；大聲地", "example": "The teacher asked me to read the story aloud.", "exampleZh": "老師要我把故事大聲念出來。"}, {"word": "sound", "pos": "v.", "zh": "聽起來", "example": "Your idea sounds great!", "exampleZh": "你的點子聽起來很棒！"}, {"word": "although", "pos": "conj.", "zh": "雖然", "example": "Although it was cold, we went swimming.", "exampleZh": "雖然天氣很冷，我們還是去游泳了。"}], "phrases": [{"phrase": "each other", "zh": "彼此", "example": "The twins help each other with homework.", "exampleZh": "那對雙胞胎互相幫忙寫功課。"}, {"phrase": "at first", "zh": "起初", "example": "At first, I didn't like the city, but now I love it.", "exampleZh": "起初我不喜歡這座城市，但現在我很愛它。"}, {"phrase": "be lucky to + V", "zh": "很幸運能…", "example": "We are lucky to have such a good teacher.", "exampleZh": "我們很幸運有這麼好的老師。"}], "grammar": [{"pattern": "Although + S + V, S + V", "explain": "「雖然…，但是…」，although 引導的子句表示讓步；注意英文裡 although 和 but 不能同時使用。", "example": "Although he was tired, he finished his homework.", "exampleZh": "雖然他很累，他還是把功課做完了。"}, {"pattern": "感官動詞 look / sound / smell / taste / feel + adj.", "explain": "這些感官動詞後面直接接形容詞，描述事物「看／聽／聞／嚐／感覺起來」如何，不用副詞。", "example": "The cake smells good and tastes sweet.", "exampleZh": "這個蛋糕聞起來很香，嚐起來很甜。"}], "reading": [{"q": "Where is the writer now?", "options": ["In Taiwan", "In Kyoto", "In Canada", "At a language school in Taipei"], "answer": 1, "explain": "第一段說 I am in Kyoto for a two-week homestay。故選 (B)。"}, {"q": "How do the writer and the host family understand each other?", "options": ["They all speak English well.", "The writer speaks good Japanese.", "They use smiles and hand signs.", "They write notes."], "answer": 2, "explain": "第一段說 we understand each other with smiles and hand signs。故選 (C)。"}, {"q": "What did the writer think about the quiet bus at first?", "options": ["It was strange.", "It was peaceful.", "It was boring.", "It was noisy."], "answer": 0, "explain": "第二段說 Nobody talks aloud on the bus. At first, I thought that was strange。故選 (A)。"}, {"q": "Which is true about the tea ceremony?", "options": ["The writer did everything perfectly.", "The teacher was angry at the writer.", "Each step was fast.", "The tea tasted wonderful."], "answer": 3, "explain": "第三段說 Besides, the tea tasted wonderful。故選 (D)。"}, {"q": "How does the writer feel about this trip?", "options": ["Homesick and sad", "Lucky and happy", "Bored and tired", "Afraid and worried"], "answer": 1, "explain": "第三段說 I feel lucky to be here，加上第一段 I love it，可知作者很開心。故選 (B)。"}], "vocabQ": [{"q": "Please read the poem ____ so everyone in the class can hear you.", "options": ["abroad", "aloud", "everywhere", "although"], "answer": 1, "explain": "句意為「請大聲念這首詩，讓全班都聽得到」，aloud 出聲地。"}, {"q": "I can ____ something bad in the kitchen. Did you forget the fish?", "options": ["smell", "sound", "hear", "look"], "answer": 0, "explain": "句意為「我聞到廚房有東西很臭，你忘了魚嗎」，smell 聞到。"}, {"q": "After he finished college, he went ____ to work in Australia.", "options": ["everywhere", "aloud", "abroad", "although"], "answer": 2, "explain": "句意為「大學畢業後，他到國外的澳洲工作」，abroad 到國外。"}, {"q": "I looked ____ for my cat, but I could not find her.", "options": ["abroad", "aloud", "although", "everywhere"], "answer": 3, "explain": "句意為「我到處找我的貓，但找不到她」，everywhere 到處。"}, {"q": "____ the test was hard, Amy got a high score.", "options": ["Although", "Because", "If", "So"], "answer": 0, "explain": "句意為「雖然考試很難，艾咪還是拿到高分」，前後句意相反，用 although 雖然。"}]}, {"id": "I01", "level": "inter", "num": 1, "title": "The Most Energetic Man in Our Alley", "titleZh": "我們巷子裡最有活力的人", "theme": "People & Descriptions", "themeZh": "人物與外貌描述", "article": ["Every morning at five thirty, long before the first MRT train leaves the station, my grandfather is already in the park doing tai chi. He is seventy-eight years old and almost completely bald, but nobody in our alley would ever call him 'old'. Elderly neighbors who are ten years younger than he is often ask him how he stays so energetic. His answer is always the same: 'Keep moving, and keep listening.'", "Grandpa was born into a poor family in Yunlin, a background he never hides. He left school at fourteen and spent forty hard-working years repairing scooters in a tiny shop near the night market. Because he was so dependable, customers who had moved to Taichung still rode back to let him fix their bikes. Although he has become slightly forgetful lately, he never forgets a name or a face. He greets the courteous young clerk at the convenience store, the lively children on their way to school, and even the junior police officer who once gave him a parking ticket.", "What I admire most, however, is his generosity. When a neighbor's son could not afford cram school, Grandpa quietly paid the fee for a whole year. He is considerate in small ways too, always carrying an extra umbrella in case someone is caught in the rain. A gifted storyteller, he can make a crowd of grown-ups laugh with tales of the old days, yet he is also a patient listener who lets even the shyest child finish a sentence.", "In a world where influential people are usually rich or famous, my grandfather has shown me that the most capable leaders are often the ones who interact kindly with everyone around them. I hope that when I am his age, people will still be asking me how I stay so young."], "translation": ["每天早上五點半，在第一班捷運離站之前很久，我的爺爺就已經在公園裡打太極拳了。他七十八歲，頭髮幾乎全禿了，但我們巷子裡沒有人會叫他「老人」。比他小十歲的年長鄰居常問他怎麼能保持這麼有活力。他的答案永遠一樣：「不停地動，也不停地聽。」", "爺爺出生在雲林的一個貧窮家庭，這樣的出身他從不隱瞞。他十四歲離開學校，在夜市附近的一間小店裡辛勤地修了四十年機車。因為他非常可靠，搬到台中的客人還是會騎回來讓他修車。雖然他最近變得有點健忘，卻從不忘記任何一個名字或面孔。他會跟便利商店有禮貌的年輕店員、上學途中活潑的孩子們打招呼，甚至連曾經開他違停罰單的年輕警員也不例外。", "然而，我最佩服的是他的慷慨。當鄰居的兒子付不起補習費時，爺爺默默地替他付了一整年的學費。他在小事上也很體貼，總是多帶一把傘，以防有人被雨淋到。他是個有說故事天分的人，能用往日的故事逗得一群大人哈哈大笑，但他同時也是個有耐心的傾聽者，連最害羞的孩子也能把一句話說完。", "在這個有影響力的人通常不是有錢就是有名的世界裡，爺爺讓我明白，最有能力的領導者往往是那些和身邊每個人都親切互動的人。我希望到了他這個年紀時，人們還會問我是怎麼保持年輕的。"], "vocab": [{"word": "elderly", "pos": "adj.", "zh": "年長的", "example": "The elderly man walks in the park every morning.", "exampleZh": "那位年長的先生每天早上在公園散步。"}, {"word": "bald", "pos": "adj.", "zh": "禿頭的", "example": "My uncle started going bald in his thirties.", "exampleZh": "我叔叔三十幾歲就開始禿頭了。"}, {"word": "energetic", "pos": "adj.", "zh": "精力充沛的", "example": "The energetic puppy ran around the yard for an hour.", "exampleZh": "那隻精力充沛的小狗在院子裡跑了一個小時。"}, {"word": "dependable", "pos": "adj.", "zh": "可靠的", "example": "Lisa is dependable, so she was chosen as class leader.", "exampleZh": "麗莎很可靠，所以被選為班長。"}, {"word": "forgetful", "pos": "adj.", "zh": "健忘的", "example": "I am so forgetful that I left my phone on the bus again.", "exampleZh": "我健忘到又把手機忘在公車上了。"}, {"word": "courteous", "pos": "adj.", "zh": "有禮貌的", "example": "The courteous waiter pulled out the chair for her.", "exampleZh": "那位有禮貌的服務生替她拉開椅子。"}, {"word": "generosity", "pos": "n.", "zh": "慷慨", "example": "Thanks to his generosity, the library got new computers.", "exampleZh": "多虧他的慷慨，圖書館有了新電腦。"}, {"word": "considerate", "pos": "adj.", "zh": "體貼的", "example": "It was considerate of you to save me a seat.", "exampleZh": "你幫我留位子真是體貼。"}, {"word": "gifted", "pos": "adj.", "zh": "有天分的", "example": "The gifted student finished the test in ten minutes.", "exampleZh": "那位有天分的學生十分鐘就寫完考卷。"}, {"word": "influential", "pos": "adj.", "zh": "有影響力的", "example": "She is one of the most influential writers in Taiwan.", "exampleZh": "她是台灣最有影響力的作家之一。"}], "phrases": [{"phrase": "be born into", "zh": "出生於（某種家庭）", "example": "He was born into a family of doctors.", "exampleZh": "他出生在一個醫生世家。"}, {"phrase": "in case", "zh": "以防萬一", "example": "Take a jacket in case it gets cold tonight.", "exampleZh": "帶件外套，以防今晚變冷。"}, {"phrase": "be caught in the rain", "zh": "被雨淋到", "example": "We were caught in the rain on our way home.", "exampleZh": "我們在回家的路上被雨淋到了。"}], "grammar": [{"pattern": "Although + S + V, S + V", "explain": "「雖然…，但是…」。Although 引導讓步子句，注意中文的「但是」在英文裡不能再加 but。", "example": "Although he is eighty, he still rides a scooter.", "exampleZh": "雖然他八十歲了，仍然騎機車。"}, {"pattern": "What + S + V + is + N / 名詞子句", "explain": "What 引導的名詞子句當主詞，意思是「…的事物／事情」，常用來強調重點。", "example": "What I admire most is his generosity.", "exampleZh": "我最佩服的是他的慷慨。"}], "reading": [{"q": "What is the passage mainly about?", "options": ["The history of a scooter repair shop", "How to do tai chi correctly", "Why elderly people should exercise", "The writer's admirable grandfather"], "answer": 3, "explain": "全文從作息、工作、個性到對作者的影響，都在描述作者敬佩的爺爺，故選 (D)。"}, {"q": "Where was the writer's grandfather born?", "options": ["In Yunlin", "In Taichung", "In Taipei", "In Tainan"], "answer": 0, "explain": "第二段提到 Grandpa was born into a poor family in Yunlin，故選 (A)。"}, {"q": "Why did customers who had moved to Taichung still come back to Grandpa's shop?", "options": ["Because the shop was the cheapest", "Because he was so dependable", "Because they liked the night market", "Because the shop was near the MRT"], "answer": 1, "explain": "第二段說 Because he was so dependable, customers who had moved to Taichung still rode back，故選 (B)。"}, {"q": "The word \"considerate\" in paragraph 3 is closest in meaning to ______.", "options": ["forgetful", "wealthy", "thoughtful", "talkative"], "answer": 2, "explain": "considerate 是「體貼的」，後面舉例他多帶一把傘給別人用，與 thoughtful 意思最接近，故選 (C)。"}, {"q": "What can we infer about the writer from the last paragraph?", "options": ["The writer is afraid of growing old", "The writer hopes to be like Grandpa in the future", "The writer thinks Grandpa should retire", "The writer lives far away from Grandpa"], "answer": 1, "explain": "最後一段作者希望自己到了爺爺的年紀，別人也會問他如何保持年輕，可推知他想成為像爺爺一樣的人，故選 (B)。"}], "vocabQ": [{"q": "Although he is nearly eighty, my uncle is so ____ that he hikes every weekend.", "options": ["energetic", "forgetful", "bald", "elderly"], "answer": 0, "explain": "句意為「雖然快八十歲，叔叔還是精力充沛到每個週末都去爬山」，energetic 精力充沛的。"}, {"q": "Her ____ touched everyone; she gave half of her prize money to the children's home.", "options": ["courtesy", "background", "generosity", "coward"], "answer": 2, "explain": "把一半獎金捐給育幼院，顯示的是「慷慨」generosity。"}, {"q": "My grandmother has become so ____ that she often leaves her keys in the fridge.", "options": ["elderly", "forgetful", "dependable", "gifted"], "answer": 1, "explain": "常把鑰匙忘在冰箱裡，表示「健忘的」forgetful。"}, {"q": "You can always count on Jason; he is the most ____ member of the team.", "options": ["courteous", "considerate", "dependable", "influential"], "answer": 2, "explain": "count on 是「依靠」，可以依靠的人就是「可靠的」dependable。"}, {"q": "It was ____ of him to stand up and offer his seat to the pregnant woman.", "options": ["bald", "courteous", "forgetful", "energetic"], "answer": 1, "explain": "讓座給孕婦是有禮貌的行為，courteous 有禮貌的。"}]}, {"id": "I02", "level": "inter", "num": 2, "title": "An Email about the New Kid in Room 302", "titleZh": "一封關於302教室新同學的電子郵件", "theme": "People & Descriptions", "themeZh": "人物與外貌描述", "article": ["Dear Mei-ling, Thank you for your postcard from Hualien! I have exciting news from Taipei. A newcomer named Ryan joined our class two weeks ago, and he has already changed the atmosphere of Room 302. Ryan is Singaporean, so English is his native language, but his Mandarin is surprisingly good. When our homeroom teacher asked about his nationality, he joked that he was 'half kaya toast, half bubble tea', which made even our strict math teacher laugh.", "What I like most about Ryan is his personality. He is sociable without being loud, and he has the kind of youthful energy that makes everyone want to sit near him. He is also modest. Although he is a talented pianist who has performed in concert halls, he never mentions it unless someone asks. Last Friday, when a timid junior student dropped her lunch box in the corridor, Ryan was the first to kneel down and help her clean up. He is thoughtful in a way that few teenage boys are.", "Of course, nobody is perfect. Ryan can be stubborn when he believes he is right, and he once argued with our senior class leader for twenty minutes about a rule for the basketball tournament. Some students who had treated him as a rival at first found him unfriendly, but once they got to know him, they became his most loyal supporters. Even the tolerant residents of our dormitory, who have seen plenty of teenage mischief, say he is one of the most mature youngsters they have ever met.", "I am honestly a little worried that his reputation as 'the perfect new kid' might put too much pressure on him. Anyway, come and visit soon so you can meet him yourself. Write back when you can! Love, Hsiao-wen"], "translation": ["親愛的美玲：謝謝你從花蓮寄來的明信片！我有台北的新鮮事要告訴你。兩週前有一位叫 Ryan 的新同學加入我們班，他已經改變了 302 教室的氣氛。Ryan 是新加坡人，所以英文是他的母語，但他的中文出乎意料地好。當導師問起他的國籍時，他開玩笑說自己是「一半咖椰吐司、一半珍珠奶茶」，連我們嚴格的數學老師都笑了。", "我最喜歡 Ryan 的地方是他的個性。他善於交際卻不吵鬧，而且有一種讓大家都想坐在他旁邊的青春活力。他也很謙虛。雖然他是在音樂廳表演過的天才鋼琴家，除非有人問起，否則他從不提這件事。上週五，一位膽小的學妹在走廊上把便當盒摔在地上，Ryan 第一個蹲下去幫她收拾。他的體貼是很少青少年男生有的。", "當然，沒有人是完美的。Ryan 認定自己是對的時候會很固執，他曾經為了籃球賽的一條規則，和我們的高年級班長爭論了二十分鐘。有些起初把他當對手的同學覺得他不友善，但一旦認識他之後，他們就成了他最忠實的支持者。連我們宿舍裡那些見過不少青少年惡作劇、很寬容的住宿生，都說他是他們見過最成熟的年輕人之一。", "老實說，我有點擔心「完美新同學」這個名聲會給他太大的壓力。總之，快點來玩，這樣你就可以親自見見他。有空就回信喔！愛你的曉雯"], "vocab": [{"word": "newcomer", "pos": "n.", "zh": "新來的人；新手", "example": "The newcomer did not know where the library was.", "exampleZh": "那位新來的人不知道圖書館在哪裡。"}, {"word": "native", "pos": "adj.", "zh": "本地的；母語的", "example": "Her native language is Japanese, but she also speaks Chinese.", "exampleZh": "她的母語是日語，但她也會說中文。"}, {"word": "personality", "pos": "n.", "zh": "個性；人格", "example": "Tom has a warm personality that people like.", "exampleZh": "湯姆有讓人喜歡的溫暖個性。"}, {"word": "sociable", "pos": "adj.", "zh": "善於交際的", "example": "My sister is sociable and makes friends easily.", "exampleZh": "我姊姊善於交際，很容易交到朋友。"}, {"word": "modest", "pos": "adj.", "zh": "謙虛的", "example": "The modest champion thanked her coach instead of herself.", "exampleZh": "那位謙虛的冠軍感謝的是教練而不是自己。"}, {"word": "talented", "pos": "adj.", "zh": "有才華的", "example": "The talented singer wrote all of her own songs.", "exampleZh": "那位有才華的歌手自己寫了所有的歌。"}, {"word": "thoughtful", "pos": "adj.", "zh": "體貼的；深思的", "example": "It was thoughtful of him to bring soup when I was sick.", "exampleZh": "我生病時他帶湯來，真是體貼。"}, {"word": "stubborn", "pos": "adj.", "zh": "固執的", "example": "The stubborn child refused to wear a coat in the snow.", "exampleZh": "那個固執的孩子在雪中拒絕穿外套。"}, {"word": "loyal", "pos": "adj.", "zh": "忠誠的", "example": "A loyal friend stays with you in bad times.", "exampleZh": "忠誠的朋友在你困難時會陪在你身邊。"}, {"word": "reputation", "pos": "n.", "zh": "名聲", "example": "The school has a reputation for excellent teachers.", "exampleZh": "這所學校以優秀的老師聞名。"}], "phrases": [{"phrase": "get to know", "zh": "認識；逐漸了解", "example": "It took me a month to get to know my new classmates.", "exampleZh": "我花了一個月才認識新同學。"}, {"phrase": "put pressure on", "zh": "給…壓力", "example": "Please do not put too much pressure on the young players.", "exampleZh": "請不要給年輕球員太大的壓力。"}, {"phrase": "at first", "zh": "起初", "example": "At first I did not like the city, but now I love it.", "exampleZh": "起初我不喜歡這個城市，但現在我很愛它。"}], "grammar": [{"pattern": "S + V + without + V-ing", "explain": "「沒有…地」。without 是介系詞，後面的動詞要改成動名詞 V-ing。", "example": "He is sociable without being loud.", "exampleZh": "他善於交際卻不吵鬧。"}, {"pattern": "Once + S + V, S + V", "explain": "「一旦…就…」。once 當連接詞用，表示某件事發生後，另一件事就會跟著發生。", "example": "Once they got to know him, they became his loyal supporters.", "exampleZh": "一旦認識他之後，他們就成了他忠實的支持者。"}], "reading": [{"q": "Why did Hsiao-wen write this email?", "options": ["To invite Mei-ling to a piano concert", "To introduce a new classmate to Mei-ling", "To complain about the math teacher", "To ask for advice about a rival"], "answer": 1, "explain": "信中主要在描述新同學 Ryan 的個性與表現，最後還邀美玲來見他，故選 (B)。"}, {"q": "Which of the following is true about Ryan?", "options": ["He was born in Taipei", "He speaks only English", "He plays the piano very well", "He is the senior class leader"], "answer": 2, "explain": "第二段提到 he is a talented pianist who has performed in concert halls，故選 (C)。"}, {"q": "The word \"timid\" in paragraph 2 is closest in meaning to ______.", "options": ["angry", "lazy", "clever", "shy"], "answer": 3, "explain": "timid 是「膽小的、害羞的」，與 shy 意思最接近，故選 (D)。"}, {"q": "Why did some students find Ryan unfriendly at first?", "options": ["They saw him as a competitor", "He refused to speak Mandarin", "He broke dormitory rules", "He ignored the junior students"], "answer": 0, "explain": "第三段說 Some students who had treated him as a rival at first found him unfriendly，rival 即 competitor，故選 (A)。"}, {"q": "What is Hsiao-wen worried about?", "options": ["Ryan might move back to Singapore", "Ryan's reputation might become a burden to him", "Mei-ling might not like Ryan", "Ryan might lose the basketball tournament"], "answer": 1, "explain": "最後一段提到 his reputation as 'the perfect new kid' might put too much pressure on him，故選 (B)。"}], "vocabQ": [{"q": "As a ____ to the city, Lily still gets lost on the MRT sometimes.", "options": ["newcomer", "resident", "rival", "reader"], "answer": 0, "explain": "句意為「身為剛到這個城市的新人，莉莉有時還是會在捷運迷路」，newcomer 新來的人。"}, {"q": "Even though she won first prize, Amy was ____ and said her teammates deserved the credit.", "options": ["stubborn", "modest", "sociable", "loyal"], "answer": 1, "explain": "得了第一名卻把功勞歸給隊友，是「謙虛的」modest。"}, {"q": "My dog is so ____ that he waits by the door every evening until I come home.", "options": ["talented", "thoughtful", "loyal", "strict"], "answer": 2, "explain": "每天在門口等主人回家，表現的是「忠誠的」loyal。"}, {"q": "Once Grandpa makes up his mind, he is too ____ to listen to anyone.", "options": ["modest", "sociable", "native", "stubborn"], "answer": 3, "explain": "下定決心就不聽任何人的話，是「固執的」stubborn。"}, {"q": "The restaurant has a good ____ for fresh seafood, so it is always full.", "options": ["personality", "reputation", "nationality", "maturity"], "answer": 1, "explain": "餐廳以新鮮海產聞名而總是客滿，have a good reputation for 以…聞名。"}]}, {"id": "I03", "level": "inter", "num": 3, "title": "Sixty Years Later, a Second Honeymoon", "titleZh": "六十年後的第二次蜜月", "theme": "Family & Relationships", "themeZh": "家庭與人際關係", "article": ["TAINAN, Oct. 12 - When Lin Chun-mei walked down the aisle in 1966, she was a nineteen-year-old bride wearing a borrowed dress. On Saturday, surrounded by three generations of family at a small restaurant in Anping, she put on a white dress once again. Her husband, Lin Tsai-fu, now eighty-four, had tears in his eyes. 'She is still my darling,' he told reporters, 'and she still argues with me about the rice cooker.'", "The couple's six grandchildren organized the celebration as a surprise. 'They never had a honeymoon because Grandpa had to go back to the fishing boat the day after the wedding,' explained their eldest grandchild, Lin Yu-ting, 26. 'So we booked them a three-day trip to Penghu.' Twin cousins Kai and Kuan, both twelve, had been saving their red envelope money since the Lunar New Year to help pay for it.", "The marriage was not an easy one. Mr. Lin, an orphan who was raised by his uncle, his legal guardian, had inherited nothing but a leaking wooden house from his ancestors. Mrs. Lin's relations warned her that she would become dependent on a poor fisherman. Yet the bond between them grew stronger with every storm. 'A good relationship is built on mutual respect,' Mrs. Lin said. 'He listens to me, and I let him think he wins.'", "Neighbors describe the pair as constant companions who still hold hands at the morning market. Asked for advice for young couples, Mr. Lin laughed. 'Find a mate who can laugh at you,' he said, 'and then make sure you laugh together.'"], "translation": ["台南，10 月 12 日訊：1966 年林春美步入禮堂時，是個穿著借來禮服的十九歲新娘。週六，在安平一家小餐廳裡，她在三代家人的圍繞下，再次穿上了白色禮服。她現年八十四歲的丈夫林財福眼裡含著淚。「她還是我的寶貝，」他告訴記者，「而且她還是會為了電鍋跟我吵架。」", "這對夫妻的六個孫子女把這場慶祝會辦成了驚喜。「他們從來沒有度過蜜月，因為婚禮隔天爺爺就得回漁船上工作，」26 歲的長孫女林育婷解釋，「所以我們幫他們訂了三天的澎湖之旅。」十二歲的雙胞胎表兄弟小凱和小寬，從農曆新年起就一直存紅包錢，來幫忙負擔這趟旅費。", "這段婚姻並不輕鬆。林先生是個孤兒，由身為法定監護人的叔叔撫養長大，從祖先那裡繼承的只有一間會漏水的木屋。林太太的親戚警告她，嫁給窮漁夫會讓她一輩子依賴別人。然而，兩人之間的情感卻隨著每一場風暴越來越堅固。「好的關係是建立在互相尊重之上，」林太太說，「他聽我的，而我讓他以為是他贏了。」", "鄰居形容這對夫妻是形影不離的伴侶，到現在逛早市還會牽手。被問到給年輕夫妻的建議時，林先生笑了。「找一個敢笑你的伴侶，」他說，「然後確定你們能一起笑。」"], "vocab": [{"word": "bride", "pos": "n.", "zh": "新娘", "example": "The bride looked beautiful in her long white dress.", "exampleZh": "新娘穿著白色長禮服看起來很美。"}, {"word": "honeymoon", "pos": "n.", "zh": "蜜月", "example": "They spent their honeymoon in Okinawa.", "exampleZh": "他們在沖繩度蜜月。"}, {"word": "grandchild", "pos": "n.", "zh": "孫子；孫女", "example": "My grandmother has twelve grandchildren.", "exampleZh": "我奶奶有十二個孫子孫女。"}, {"word": "orphan", "pos": "n.", "zh": "孤兒", "example": "The orphan was adopted by a kind family in Tainan.", "exampleZh": "那個孤兒被台南一個善良的家庭收養。"}, {"word": "guardian", "pos": "n.", "zh": "監護人", "example": "Students under eighteen need a guardian's signature.", "exampleZh": "未滿十八歲的學生需要監護人簽名。"}, {"word": "inherit", "pos": "v.", "zh": "繼承", "example": "She inherited the old farmhouse from her grandfather.", "exampleZh": "她從祖父那裡繼承了那間老農舍。"}, {"word": "bond", "pos": "n.", "zh": "情感連結；羈絆", "example": "There is a strong bond between the twins.", "exampleZh": "這對雙胞胎之間有很深的情感連結。"}, {"word": "mutual", "pos": "adj.", "zh": "相互的", "example": "Good teamwork depends on mutual trust.", "exampleZh": "良好的團隊合作仰賴相互信任。"}, {"word": "relationship", "pos": "n.", "zh": "關係", "example": "He has a close relationship with his cousins.", "exampleZh": "他和表兄弟姊妹的關係很親近。"}, {"word": "companion", "pos": "n.", "zh": "伴侶；同伴", "example": "The old dog has been her faithful companion for years.", "exampleZh": "那隻老狗多年來一直是她忠實的伴侶。"}], "phrases": [{"phrase": "walk down the aisle", "zh": "步入禮堂；結婚", "example": "My sister will walk down the aisle next spring.", "exampleZh": "我姊姊明年春天要結婚了。"}, {"phrase": "be built on", "zh": "建立在…之上", "example": "Their friendship is built on years of trust.", "exampleZh": "他們的友誼建立在多年的信任之上。"}, {"phrase": "hold hands", "zh": "牽手", "example": "The children held hands while crossing the street.", "exampleZh": "孩子們過馬路時牽著手。"}], "grammar": [{"pattern": "S + had + p.p. (過去完成式)", "explain": "表示在過去某個時間點之前就已經完成的動作，常與另一個過去式動作一起出現，用來分出先後。", "example": "He had inherited nothing but an old house from his ancestors.", "exampleZh": "他從祖先那裡只繼承了一間老房子。"}, {"pattern": "P.p. + ..., S + V (過去分詞構句)", "explain": "當主詞與分詞的動作是被動關係時，用過去分詞開頭的分詞構句，相當於 When he was asked...。", "example": "Asked for advice, Mr. Lin laughed.", "exampleZh": "被問到建議時，林先生笑了。"}], "reading": [{"q": "What is this news report mainly about?", "options": ["A fishing family in Penghu", "A couple's sixtieth wedding anniversary celebration", "How to plan a honeymoon", "The history of Anping"], "answer": 1, "explain": "報導描述林家夫妻結婚六十年後，由孫子女安排的慶祝與蜜月，故選 (B)。"}, {"q": "Who helped pay for the trip to Penghu?", "options": ["The neighbors", "Mr. Lin's uncle", "The twin cousins", "The restaurant owner"], "answer": 2, "explain": "第二段說雙胞胎表兄弟 had been saving their red envelope money... to help pay for it，故選 (C)。"}, {"q": "Why did the couple not have a honeymoon in 1966?", "options": ["Mr. Lin had to return to work", "They could not afford a dress", "Mrs. Lin's family objected", "There was a big storm"], "answer": 0, "explain": "第二段提到 Grandpa had to go back to the fishing boat the day after the wedding，故選 (A)。"}, {"q": "The word \"bond\" in paragraph 3 is closest in meaning to ______.", "options": ["argument", "distance", "connection", "promise"], "answer": 2, "explain": "bond 指兩人之間的情感連結，與 connection 最接近，故選 (C)。"}, {"q": "How does Mrs. Lin talk about her marriage?", "options": ["With regret", "With anger", "With fear", "With humor"], "answer": 3, "explain": "她說「他聽我的，而我讓他以為是他贏了」，語氣幽默，故選 (D)。"}], "vocabQ": [{"q": "The ____ threw her bouquet into the crowd after the wedding ceremony.", "options": ["bride", "guardian", "orphan", "companion"], "answer": 0, "explain": "婚禮後丟捧花的是「新娘」bride。"}, {"q": "The boy became an ____ when both of his parents died in the accident.", "options": ["guardian", "companion", "orphan", "grandchild"], "answer": 2, "explain": "父母雙亡的孩子是「孤兒」orphan。"}, {"q": "Jenny will ____ the family bakery when her father retires.", "options": ["divorce", "inherit", "borrow", "deliver"], "answer": 1, "explain": "父親退休後接手家族麵包店，是「繼承」inherit。"}, {"q": "The newlyweds spent their ____ on a quiet beach in Kenting.", "options": ["relationship", "cradle", "funeral", "honeymoon"], "answer": 3, "explain": "新婚夫妻在墾丁海灘度過的是「蜜月」honeymoon。"}, {"q": "Trust should be ____; you cannot expect it from others if you never give it.", "options": ["mutual", "intimate", "dependent", "faithful"], "answer": 0, "explain": "信任必須是「相互的」mutual，自己不給就不能期待別人給。"}]}, {"id": "I04", "level": "inter", "num": 4, "title": "Your First Apartment: A Survival Guide", "titleZh": "第一間租屋生存指南", "theme": "Home & Housing", "themeZh": "居家與住宅", "article": ["Moving out of your parents' home is exciting, but finding affordable accommodation in Taipei can be a headache. Housing near MRT stations is expensive, and many students end up renting a room on the fifth storey of a building with no elevator. Before you sign anything, here are a few tips that every first-time tenant should know.", "First, visit the property in person, and never rely only on photos. Check whether the room is already furnished; a bed, a desk, and a small fridge can save you thousands of dollars. Turn on every appliance, including the air-conditioner and the water heater, and look under the basin for signs of a leak. Flip the light switches to make sure no bulb is dead, and run the tap to see how fast the water goes down the drain. If the hallway is covered in dust and the staircase smells of garbage, the landlord probably does not take good care of the building.", "Second, understand what you are paying for. Ask whether household bills such as water, electricity, and internet are included in the rent. Some landlords charge a flat fee; others calculate electricity by the meter, which can be costly in summer. Find out how long the room has been vacant. If it has been empty for months, you may be able to bargain for a lower price.", "Finally, keep a good relationship with your landlady or landlord. Pay the rent on time, keep the corridor clear, and report problems early. A dripping tap that is ignored for weeks can turn into a flooded floor. Remember: a good tenant usually gets the deposit back, while a careless one leaves with nothing but a bag of dirty laundry and regret."], "translation": ["搬離父母家是件令人興奮的事，但在台北找到負擔得起的住處卻可能讓人頭痛。捷運站附近的房子很貴，許多學生最後只能租在沒有電梯的大樓五樓。在簽任何文件之前，這裡有幾個每位第一次租屋的房客都該知道的訣竅。", "第一，親自去看房子，絕不要只靠照片。確認房間是否已附家具；一張床、一張書桌和一台小冰箱可以幫你省下好幾千元。把每一樣電器都打開試試，包括冷氣和熱水器，並檢查洗手台底下有沒有漏水的痕跡。按一下電燈開關，確定沒有燈泡壞掉，再打開水龍頭看看水流進排水孔的速度快不快。如果走廊滿是灰塵、樓梯間有垃圾味，房東大概沒有好好維護這棟大樓。", "第二，弄清楚你付的錢包含什麼。問清楚水費、電費、網路費等家庭帳單是否包含在房租裡。有些房東收固定費用；有些則按電表計算電費，夏天可能很貴。打聽一下這個房間空了多久。如果已經空了好幾個月，你或許可以殺價。", "最後，和房東太太或房東保持良好關係。準時繳房租、保持走廊暢通、及早回報問題。一個被忽略好幾週的滴水水龍頭，可能會變成淹水的地板。記住：好房客通常拿得回押金，而粗心的房客離開時只帶走一袋髒衣服和後悔。"], "vocab": [{"word": "accommodation", "pos": "n.", "zh": "住處；住宿", "example": "The hotel offers cheap accommodation for students.", "exampleZh": "這家旅館提供學生便宜的住宿。"}, {"word": "housing", "pos": "n.", "zh": "住宅；住房", "example": "The city is building more housing for young families.", "exampleZh": "市政府正為年輕家庭興建更多住宅。"}, {"word": "storey", "pos": "n.", "zh": "樓層", "example": "Our office is on the top storey of the building.", "exampleZh": "我們的辦公室在大樓的頂樓。"}, {"word": "tenant", "pos": "n.", "zh": "房客", "example": "The tenant pays the rent on the first day of each month.", "exampleZh": "房客每個月一號付房租。"}, {"word": "property", "pos": "n.", "zh": "房地產；財產", "example": "The old property by the river was sold last week.", "exampleZh": "河邊那棟老房子上週賣掉了。"}, {"word": "furnish", "pos": "v.", "zh": "為…配備家具", "example": "The apartment is furnished with a sofa and two beds.", "exampleZh": "這間公寓附有一張沙發和兩張床。"}, {"word": "appliance", "pos": "n.", "zh": "家電", "example": "A rice cooker is the most important appliance in our kitchen.", "exampleZh": "電鍋是我們廚房裡最重要的家電。"}, {"word": "leak", "pos": "n.", "zh": "漏水；漏洞", "example": "There is a leak in the roof, so the floor is wet.", "exampleZh": "屋頂漏水，所以地板是濕的。"}, {"word": "landlord", "pos": "n.", "zh": "房東", "example": "Our landlord fixed the broken window the next day.", "exampleZh": "我們的房東隔天就修好了破掉的窗戶。"}, {"word": "vacant", "pos": "adj.", "zh": "空著的", "example": "The shop on the corner has been vacant for a year.", "exampleZh": "轉角那間店面已經空了一年。"}], "phrases": [{"phrase": "end up + V-ing", "zh": "最後落得…；結果變成…", "example": "We missed the last bus and ended up walking home.", "exampleZh": "我們錯過末班公車，最後只好走路回家。"}, {"phrase": "in person", "zh": "親自", "example": "You must sign the form in person.", "exampleZh": "你必須親自簽這份表格。"}, {"phrase": "take care of", "zh": "照顧；維護", "example": "Who will take care of the garden while you are away?", "exampleZh": "你不在的時候誰來照顧花園？"}], "grammar": [{"pattern": "S + V + whether + S + V", "explain": "whether 引導名詞子句，意思是「是否…」，常接在 check、ask、know、wonder 等動詞後面。", "example": "Check whether the room is already furnished.", "exampleZh": "確認房間是否已經附家具。"}, {"pattern": "S + V, while + S + V", "explain": "while 在此表示「而；然而」，用來對比兩個相反的情況，不是「當…時」的意思。", "example": "A good tenant gets the deposit back, while a careless one gets nothing.", "exampleZh": "好房客拿得回押金，而粗心的房客什麼都拿不到。"}], "reading": [{"q": "What is the main purpose of this passage?", "options": ["To advertise an apartment near an MRT station", "To complain about a careless landlord", "To give advice to first-time renters", "To explain how to repair a leaking tap"], "answer": 2, "explain": "第一段最後說 here are a few tips that every first-time tenant should know，全文都在給租屋新手建議，故選 (C)。"}, {"q": "According to paragraph 2, why should you look under the basin?", "options": ["To check for a leak", "To find the fridge", "To measure the room", "To test the light bulb"], "answer": 0, "explain": "第二段提到 look under the basin for signs of a leak，故選 (A)。"}, {"q": "The word \"vacant\" in paragraph 3 is closest in meaning to ______.", "options": ["expensive", "clean", "noisy", "empty"], "answer": 3, "explain": "vacant 是「空著的」，下一句就說 If it has been empty for months，故選 (D)。"}, {"q": "Why can a room that has been vacant for months be good news for a renter?", "options": ["The room is probably newly furnished", "The landlord may accept a lower rent", "The electricity will be free", "The building must have an elevator"], "answer": 1, "explain": "第三段說空很久的房間 you may be able to bargain for a lower price，故選 (B)。"}, {"q": "According to the last paragraph, what usually happens to a careful tenant?", "options": ["They must pay a higher rent", "They are likely to get their deposit back", "They can stop paying electricity bills", "They have to clean the staircase"], "answer": 1, "explain": "最後一段提到 a good tenant usually gets the deposit back，故選 (B)。"}], "vocabQ": [{"q": "The school helps foreign students find cheap ____ near the campus.", "options": ["accommodation", "decoration", "appliance", "property"], "answer": 0, "explain": "幫外籍學生找校園附近便宜的「住處」accommodation。"}, {"q": "The ____ raised the rent by two thousand dollars without any warning.", "options": ["tenant", "landlord", "resident", "newcomer"], "answer": 1, "explain": "調漲房租的人是「房東」landlord。"}, {"q": "Our new office is on the twelfth ____, so we always take the elevator.", "options": ["lobby", "corridor", "cabin", "storey"], "answer": 3, "explain": "在十二「樓」所以要搭電梯，storey 樓層。"}, {"q": "The microwave is the most useful ____ in my tiny kitchen.", "options": ["cushion", "stool", "appliance", "kettle"], "answer": 2, "explain": "微波爐是廚房裡最有用的「家電」appliance。"}, {"q": "The parking space has been ____ for weeks, so you can use it.", "options": ["vacant", "domestic", "indoor", "air-conditioned"], "answer": 0, "explain": "停車位空了好幾週可以使用，vacant 空著的。"}]}, {"id": "I05", "level": "inter", "num": 5, "title": "Diary of a Weekend Without Mom", "titleZh": "媽媽不在家的週末日記", "theme": "Daily Life & Routines", "themeZh": "日常生活作息", "article": ["Saturday, March 14. Mom left for a three-day conference in Kaohsiung this morning, and Dad announced that my brother and I would be in charge of the housework. I laughed at first. How hard could it be? By noon, I had stopped laughing. The kitchen was a mess, the laundry basket was overflowing, and my brother had dozed off on the sofa with a bag of chips on his chest.", "We made an arrangement: he would wipe the table and polish the floor while I ran errands. The errands sounded easy, but the queue at the post office was so long that I spent forty minutes standing behind a man who wanted to mail eleven packages. Then I had to buy shampoo, tissues, and detergent at the drugstore, where I discovered that I did not know which brand Mom normally buys.", "Sunday, March 15. I was awake before seven, which never happens on a weekend. Hanging the laundry turned out to be the most relaxing chore of all; the morning sun felt refreshing, and the neighbors' rooster kept me company. In the afternoon, Dad mowed the tiny lawn in front of our building, and I tried to sew a button back onto my school uniform. It took three attempts and one bleeding finger. After a short nap, we began the preparation for dinner. We had never realized how much hassle a simple meal involves: washing, chopping, cooking, and then washing again.", "Monday, March 16. Mom is home. She looked at the clean kitchen and smiled, but then she opened the fridge and asked why there were four bottles of soy sauce. I am becoming accustomed to the everyday work she does without a word, and I think I finally understand why she goes to bed so early. Bedtime for me tonight: nine o'clock."], "translation": ["3 月 14 日，星期六。媽媽今天早上去高雄參加三天的研討會，爸爸宣布由我和弟弟負責家事。我一開始還笑了出來。能有多難？到了中午，我就笑不出來了。廚房一團亂，洗衣籃滿到溢出來，弟弟則抱著一包洋芋片在沙發上睡著了。", "我們做了分工：他負責擦桌子和打亮地板，我負責跑腿。跑腿聽起來很簡單，但郵局的隊伍長到我在一個要寄十一個包裹的男人後面站了四十分鐘。接著我得去藥妝店買洗髮精、面紙和洗衣精，到了那裡我才發現自己根本不知道媽媽平常買哪個牌子。", "3 月 15 日，星期日。我七點前就醒了，這在週末從來沒發生過。晾衣服結果成了所有家事中最放鬆的一件；早晨的陽光讓人神清氣爽，鄰居的公雞還陪著我。下午，爸爸修剪我們大樓前的小草坪，我則試著把一顆鈕扣縫回制服上。總共試了三次，還流血了一根手指。小睡片刻後，我們開始準備晚餐。我們從來沒意識到一頓簡單的飯要花這麼多功夫：洗、切、煮，然後再洗一次。", "3 月 16 日，星期一。媽媽回家了。她看著乾淨的廚房微笑，但接著她打開冰箱，問為什麼有四瓶醬油。我漸漸習慣了她每天默默做的這些工作，我想我終於明白她為什麼這麼早睡了。我今晚的就寢時間：九點。"], "vocab": [{"word": "housework", "pos": "n.", "zh": "家事", "example": "We share the housework equally in my family.", "exampleZh": "我們家的家事是平均分擔的。"}, {"word": "mess", "pos": "n.", "zh": "混亂；一團糟", "example": "Your room is a mess! Put your clothes away.", "exampleZh": "你的房間一團亂！把衣服收好。"}, {"word": "laundry", "pos": "n.", "zh": "待洗或洗好的衣物", "example": "I do the laundry every Sunday morning.", "exampleZh": "我每個星期天早上洗衣服。"}, {"word": "errand", "pos": "n.", "zh": "差事；跑腿", "example": "Mom asked me to run an errand to the post office.", "exampleZh": "媽媽要我跑一趟郵局辦事。"}, {"word": "queue", "pos": "n.", "zh": "隊伍", "example": "There was a long queue outside the new bubble tea shop.", "exampleZh": "新開的珍奶店外排了一條長長的隊伍。"}, {"word": "chore", "pos": "n.", "zh": "家庭雜務", "example": "Washing the dishes is my least favorite chore.", "exampleZh": "洗碗是我最不喜歡的家事。"}, {"word": "nap", "pos": "n.", "zh": "小睡；午睡", "example": "Grandpa takes a nap after lunch every day.", "exampleZh": "爺爺每天午餐後都會小睡一下。"}, {"word": "hassle", "pos": "n.", "zh": "麻煩；困擾", "example": "Changing trains with heavy bags is such a hassle.", "exampleZh": "提著重行李換車真是麻煩。"}, {"word": "accustomed", "pos": "adj.", "zh": "習慣的", "example": "She is accustomed to getting up at five.", "exampleZh": "她習慣五點起床。"}, {"word": "everyday", "pos": "adj.", "zh": "日常的", "example": "Cooking and cleaning are part of everyday life.", "exampleZh": "煮飯和打掃是日常生活的一部分。"}], "phrases": [{"phrase": "in charge of", "zh": "負責", "example": "Ms. Wang is in charge of the school library.", "exampleZh": "王老師負責學校圖書館。"}, {"phrase": "doze off", "zh": "打瞌睡", "example": "I dozed off during the long speech.", "exampleZh": "我在冗長的演講中打起瞌睡來。"}, {"phrase": "turn out to be", "zh": "結果是；原來是", "example": "The stranger turned out to be my mother's old friend.", "exampleZh": "那位陌生人原來是我媽媽的老朋友。"}], "grammar": [{"pattern": "By + 過去時間, S + had + p.p.", "explain": "「到了（過去某時間）時，已經…」。by 後接過去的時間點，主要子句用過去完成式表示在那之前已完成的動作。", "example": "By noon, I had stopped laughing.", "exampleZh": "到了中午，我已經笑不出來了。"}, {"pattern": "V-ing + ... + V (動名詞當主詞)", "explain": "動名詞片語當主詞時，視為單數，動詞要用單數形。", "example": "Hanging the laundry turned out to be the most relaxing chore.", "exampleZh": "晾衣服結果成了最放鬆的家事。"}], "reading": [{"q": "What is the main idea of this diary?", "options": ["The writer learns how much work Mom does every day", "The writer's mother changes jobs", "How to mail packages quickly", "Why younger brothers are lazy"], "answer": 0, "explain": "最後一段作者說終於明白媽媽每天默默做的工作有多辛苦，這是全文的重點，故選 (A)。"}, {"q": "Why did the writer wait forty minutes at the post office?", "options": ["The post office was closed for lunch", "A man in front was mailing many packages", "The writer forgot the address", "The writer bought the wrong shampoo"], "answer": 1, "explain": "第二段說 standing behind a man who wanted to mail eleven packages，故選 (B)。"}, {"q": "Which chore did the writer enjoy most?", "options": ["Sewing a button", "Mowing the lawn", "Hanging the laundry", "Cooking dinner"], "answer": 2, "explain": "第三段提到 Hanging the laundry turned out to be the most relaxing chore of all，故選 (C)。"}, {"q": "The word \"hassle\" in paragraph 3 is closest in meaning to ______.", "options": ["fun", "money", "time", "trouble"], "answer": 3, "explain": "hassle 指「麻煩」，後面列出洗、切、煮等繁瑣的工作，與 trouble 最接近，故選 (D)。"}, {"q": "Why did Mom probably ask about the four bottles of soy sauce?", "options": ["Dad used too much of it for dinner", "The writer bought it more than once by mistake", "The brother hid it in the fridge", "Mom wanted to cook dinner right away"], "answer": 1, "explain": "作者在藥妝店時就不知道媽媽買哪個牌子，可推知跑腿時重複買了醬油，故選 (B)。"}], "vocabQ": [{"q": "Taking out the garbage is the only ____ my little sister is willing to do.", "options": ["chore", "nap", "queue", "mess"], "answer": 0, "explain": "倒垃圾是妹妹唯一願意做的「家事」chore。"}, {"q": "After a twenty-minute ____, I felt fresh enough to study again.", "options": ["mess", "hassle", "nap", "errand"], "answer": 2, "explain": "二十分鐘的「小睡」nap 之後又能讀書。"}, {"q": "We stood in a long ____ outside the bakery for its famous pineapple cakes.", "options": ["laundry", "queue", "chore", "nap"], "answer": 1, "explain": "為了鳳梨酥在店外排長長的「隊伍」queue。"}, {"q": "It took Grandma years to become ____ to city life after leaving her farm.", "options": ["awake", "everyday", "habitual", "accustomed"], "answer": 3, "explain": "become accustomed to 習慣於，奶奶花了好幾年才習慣都市生活。"}, {"q": "Please clean up this ____ before Dad comes home!", "options": ["mess", "errand", "queue", "hassle"], "answer": 0, "explain": "要在爸爸回家前收拾的是「一團亂」mess。"}]}, {"id": "I06", "level": "inter", "num": 6, "title": "A Night Market Feast for Two", "titleZh": "兩人的夜市盛宴", "theme": "Food & Drink", "themeZh": "飲食", "article": ["'I'm not hungry,' said Emma as she stepped out of the Jiantan MRT station. Ten minutes later, her appetite had come back in full force. The smell of garlic and ginger drifting from a hundred stalls was impossible to resist. 'Okay,' she admitted, 'maybe I could eat a little.' Wei-chen grinned. 'A little? Tonight you are going to have a feast.'", "Their first stop was a stall selling fried chicken cutlets bigger than Emma's face. 'Isn't it greasy?' she asked, watching the cook lift the golden cutlet out of the oil. 'Crispy, not greasy,' Wei-chen corrected her. 'The secret is in the ingredients: sweet potato flour and plenty of white pepper.' Emma took a bite. The outside crackled, and the inside was so juicy that she burned her tongue. 'Worth it,' she mumbled, still chewing.", "Next came a mug of cold lemonade, then a plate of oyster omelette covered in sweet red sauce. Emma was less sure about the stinky tofu. 'Is that even edible?' she whispered, holding her nose. 'My grandmother says if you can chew it with your eyes closed, you are officially Taiwanese,' Wei-chen said. She closed her eyes, chewed, and opened them in surprise. 'The flavor is actually... good? Like a strong cheese.' 'Dairy and tofu, same idea,' he laughed.", "By ten o'clock they had shared a coconut milkshake, a cucumber salad, and a cup of grass jelly. 'In America we dine at a table,' Emma said, rubbing her stomach. 'Here, the whole street is the table.' 'Now you understand,' Wei-chen replied. 'Same time next week?' She did not even hesitate."], "translation": ["「我不餓，」艾瑪走出劍潭捷運站時說。十分鐘後，她的食慾全面回歸。從上百個攤位飄來的蒜頭和薑的香味令人無法抗拒。「好吧，」她承認，「也許我可以吃一點點。」偉辰咧嘴一笑。「一點點？今晚你要吃的是一頓大餐。」", "他們的第一站是一個賣比艾瑪的臉還大的炸雞排的攤子。「這不會很油嗎？」她看著老闆把金黃色的雞排從油鍋裡撈起來，問道。「是酥脆，不是油膩，」偉辰糾正她。「祕密在材料裡：地瓜粉和大量的白胡椒。」艾瑪咬了一口。外皮喀滋作響，裡面多汁到燙傷了她的舌頭。「值得，」她一邊嚼一邊含糊地說。", "接著是一杯冰檸檬水，然後是一盤淋著甜甜紅醬的蚵仔煎。對於臭豆腐，艾瑪就沒那麼有把握了。「那個真的能吃嗎？」她捏著鼻子小聲問。「我奶奶說，如果你能閉著眼睛把它嚼下去，你就正式成為台灣人了，」偉辰說。她閉上眼睛，嚼了嚼，然後驚訝地睜開眼。「這味道其實……不錯？像很重口味的起司。」「乳製品和豆腐，道理一樣，」他笑著說。", "到了十點，他們已經分享了一杯椰子奶昔、一盤涼拌小黃瓜和一杯仙草。「在美國我們是在餐桌上用餐，」艾瑪揉著肚子說，「在這裡，整條街就是餐桌。」「現在你懂了，」偉辰回答，「下週同一時間？」她連猶豫都沒有。"], "vocab": [{"word": "appetite", "pos": "n.", "zh": "食慾", "example": "Swimming always gives me a big appetite.", "exampleZh": "游泳總是讓我食慾大開。"}, {"word": "feast", "pos": "n.", "zh": "盛宴；大餐", "example": "Grandma prepared a feast for the whole family on New Year's Eve.", "exampleZh": "奶奶在除夕夜為全家準備了一頓大餐。"}, {"word": "greasy", "pos": "adj.", "zh": "油膩的", "example": "The fried noodles were too greasy for me.", "exampleZh": "那盤炒麵對我來說太油了。"}, {"word": "crispy", "pos": "adj.", "zh": "酥脆的", "example": "I love the crispy skin of roast duck.", "exampleZh": "我喜歡烤鴨酥脆的外皮。"}, {"word": "ingredient", "pos": "n.", "zh": "食材；成分", "example": "Flour and eggs are the main ingredients of this cake.", "exampleZh": "麵粉和蛋是這個蛋糕的主要材料。"}, {"word": "juicy", "pos": "adj.", "zh": "多汁的", "example": "The peaches from Lala Mountain are sweet and juicy.", "exampleZh": "拉拉山的水蜜桃又甜又多汁。"}, {"word": "chew", "pos": "v.", "zh": "咀嚼", "example": "Chew your food well before you swallow it.", "exampleZh": "吞下去之前要把食物嚼碎。"}, {"word": "edible", "pos": "adj.", "zh": "可食用的", "example": "Not every mushroom in the forest is edible.", "exampleZh": "森林裡不是每種菇都能吃。"}, {"word": "flavor", "pos": "n.", "zh": "味道；口味", "example": "Which flavor of ice cream do you want, mango or chocolate?", "exampleZh": "你要哪種口味的冰淇淋，芒果還是巧克力？"}, {"word": "dine", "pos": "v.", "zh": "用餐", "example": "We usually dine out on Friday nights.", "exampleZh": "我們通常星期五晚上外出用餐。"}], "phrases": [{"phrase": "impossible to resist", "zh": "難以抗拒", "example": "The smell of fresh bread was impossible to resist.", "exampleZh": "新鮮麵包的香味令人難以抗拒。"}, {"phrase": "take a bite", "zh": "咬一口", "example": "Take a bite and tell me what you think.", "exampleZh": "咬一口，告訴我你的感想。"}, {"phrase": "worth it", "zh": "值得", "example": "The ticket was expensive, but the concert was worth it.", "exampleZh": "票很貴，但那場演唱會很值得。"}], "grammar": [{"pattern": "S + be + so + adj. + that + S + V", "explain": "「如此…以至於…」。so 後接形容詞或副詞，that 子句說明造成的結果。", "example": "The inside was so juicy that she burned her tongue.", "exampleZh": "裡面多汁到燙傷了她的舌頭。"}, {"pattern": "If + S + V (現在式), S + V (現在式)", "explain": "表示一般事實或規則的條件句，兩個子句都用現在式，意思是「如果…就…」。", "example": "If you can chew it with your eyes closed, you are officially Taiwanese.", "exampleZh": "如果你能閉著眼睛嚼下去，你就正式成為台灣人了。"}], "reading": [{"q": "What changed Emma's mind about eating?", "options": ["The smell of the food", "Wei-chen's grandmother", "The cold weather", "A long MRT ride"], "answer": 0, "explain": "第一段說 The smell of garlic and ginger... was impossible to resist，故選 (A)。"}, {"q": "According to Wei-chen, what makes the chicken cutlet crispy?", "options": ["Cold oil", "Sweet potato flour and white pepper", "Sweet red sauce", "Coconut milk"], "answer": 1, "explain": "第二段提到 The secret is in the ingredients: sweet potato flour and plenty of white pepper，故選 (B)。"}, {"q": "The word \"edible\" in paragraph 3 is closest in meaning to ______.", "options": ["cheap", "spicy", "popular", "safe to eat"], "answer": 3, "explain": "edible 是「可以吃的」，艾瑪捏著鼻子懷疑臭豆腐能不能吃，故選 (D)。"}, {"q": "What does Emma mean by \"the whole street is the table\"?", "options": ["There are not enough chairs at the stalls", "The street is too crowded to walk", "People eat as they walk from stall to stall", "The food is served on the ground"], "answer": 2, "explain": "她比較美國在餐桌用餐與台灣夜市邊走邊吃的差別，故選 (C)。"}, {"q": "How does Emma feel at the end of the evening?", "options": ["Sick from the food", "Homesick for America", "Angry at Wei-chen", "Eager to come back"], "answer": 3, "explain": "被問到下週同一時間時，She did not even hesitate，表示她很想再來，故選 (D)。"}], "vocabQ": [{"q": "After the long hike, we all had a huge ____ and ordered three pizzas.", "options": ["appetite", "feast", "flavor", "ingredient"], "answer": 0, "explain": "爬完山「食慾」大開，點了三個披薩，appetite 食慾。"}, {"q": "Make sure the pork is cooked long enough; otherwise it is not ____.", "options": ["greasy", "edible", "crispy", "juicy"], "answer": 1, "explain": "豬肉沒煮熟就不「能吃」，edible 可食用的。"}, {"q": "I prefer the mango ____ of ice cream to the vanilla one.", "options": ["appetite", "feast", "flavor", "ingredient"], "answer": 2, "explain": "芒果「口味」的冰淇淋，flavor 口味。"}, {"q": "These fries are too ____; my fingers are shiny after touching them.", "options": ["juicy", "crispy", "edible", "greasy"], "answer": 3, "explain": "摸過之後手指油亮亮的，表示薯條太「油膩」greasy。"}, {"q": "Please ____ your food slowly; it helps your stomach digest it.", "options": ["chew", "dine", "feast", "harvest"], "answer": 0, "explain": "慢慢「咀嚼」食物有助消化，chew 咀嚼。"}]}, {"id": "I07", "level": "inter", "num": 7, "title": "Green Kitchen Challenge: Calling All Young Chefs", "titleZh": "綠色廚房挑戰賽：小廚師們集合", "theme": "Food & Drink", "themeZh": "飲食", "article": ["Attention, all students in grades 10 to 12! The Home Economics Club is proud to announce the third annual Green Kitchen Challenge, which will be held in the school cafeteria on Friday, November 20. The theme this year is 'Vegetarian Taiwan'. Every dish must be meat-free, and at least half of the ingredients should be organic produce grown in Taiwan.", "Teams of two or three will have ninety minutes to prepare one main course and one dessert. Each main course must contain a good source of protein, such as soybean products, nuts, or eggs. Spinach, mushrooms, and yams will be provided for free, but teams may bring their own spices and sauces. A reminder from last year: raw vegetables must be washed thoroughly before they are sliced, and anything that has been peeled should be kept in a covered container. Dishes that are too salty or too spicy will lose points, because the judges include two elementary school students.", "Desserts need not be complicated. Last year's winning team simply stirred fresh yogurt into mashed ripe plums and served it with a crispy wheat pancake. The judges called it 'the tastiest thing we have eaten all season'. Portions should be small, since each judge will be sampling more than twenty dishes.", "To enter, submit your team name and recipe to Ms. Huang in Room 207 by October 30. Recipes written in English will receive extra credit for the English Department's Food Writing Award. The winning team will have their dish served in the cafeteria for a whole week. Sharpen your knives and your ideas. We look forward to tasting your creations!"], "translation": ["高一到高三全體同學請注意！家政社很榮幸宣布第三屆「綠色廚房挑戰賽」將於 11 月 20 日星期五在學校餐廳舉行。今年的主題是「蔬食台灣」。每道菜都必須不含肉類，而且至少一半的食材要是台灣種植的有機農產品。", "每隊二到三人，有九十分鐘準備一道主菜和一道甜點。每道主菜必須含有良好的蛋白質來源，例如黃豆製品、堅果或蛋。菠菜、香菇和地瓜會免費提供，但各隊可以自備香料和醬汁。去年的提醒：生的蔬菜切片前必須徹底洗淨，削過皮的東西要放在有蓋的容器裡。太鹹或太辣的菜會被扣分，因為評審裡有兩位國小學生。", "甜點不必複雜。去年的冠軍隊只是把新鮮優格拌進壓碎的熟李子裡，再搭配一片酥脆的全麥鬆餅。評審說那是「我們這一季吃過最好吃的東西」。份量應該要小，因為每位評審要試吃二十多道菜。", "報名請在 10 月 30 日前把隊名和食譜交給 207 教室的黃老師。用英文寫的食譜可以在英文科「美食寫作獎」獲得加分。獲勝隊伍的菜色將在學校餐廳供應一整週。磨利你的刀，也磨利你的點子。我們期待品嚐你們的作品！"], "vocab": [{"word": "vegetarian", "pos": "adj./n.", "zh": "素食的；素食者", "example": "The restaurant has a special vegetarian menu.", "exampleZh": "這家餐廳有特別的素食菜單。"}, {"word": "organic", "pos": "adj.", "zh": "有機的", "example": "Organic vegetables cost more but contain no chemicals.", "exampleZh": "有機蔬菜比較貴，但不含化學藥劑。"}, {"word": "protein", "pos": "n.", "zh": "蛋白質", "example": "Eggs and milk are rich in protein.", "exampleZh": "蛋和牛奶富含蛋白質。"}, {"word": "raw", "pos": "adj.", "zh": "生的；未煮的", "example": "Some people like to eat raw fish with soy sauce.", "exampleZh": "有些人喜歡沾醬油吃生魚片。"}, {"word": "slice", "pos": "v.", "zh": "切片", "example": "Slice the tomatoes and put them on the bread.", "exampleZh": "把番茄切片放在麵包上。"}, {"word": "peel", "pos": "v.", "zh": "削皮；剝皮", "example": "Please peel the apples before you cook them.", "exampleZh": "煮之前請先把蘋果削皮。"}, {"word": "spicy", "pos": "adj.", "zh": "辣的；辛辣的", "example": "This hot pot is too spicy for my little brother.", "exampleZh": "這個火鍋對我弟弟來說太辣了。"}, {"word": "stir", "pos": "v.", "zh": "攪拌", "example": "Stir the soup slowly so that it does not burn.", "exampleZh": "慢慢攪拌湯，才不會燒焦。"}, {"word": "ripe", "pos": "adj.", "zh": "成熟的", "example": "The mangoes are ripe and ready to eat.", "exampleZh": "芒果熟了，可以吃了。"}, {"word": "portion", "pos": "n.", "zh": "一份；份量", "example": "The portions at that restaurant are huge.", "exampleZh": "那家餐廳的份量非常大。"}], "phrases": [{"phrase": "be proud to + V", "zh": "很榮幸…；很自豪…", "example": "We are proud to welcome you to our school.", "exampleZh": "我們很榮幸歡迎你來到我們學校。"}, {"phrase": "for free", "zh": "免費", "example": "Members can use the swimming pool for free.", "exampleZh": "會員可以免費使用游泳池。"}, {"phrase": "look forward to + V-ing", "zh": "期待", "example": "I look forward to seeing you at the party.", "exampleZh": "我期待在派對上見到你。"}], "grammar": [{"pattern": "N, which + V ... (非限定關係子句)", "explain": "which 前有逗號，用來補充說明前面的名詞，不能用 that 取代。", "example": "The contest, which will be held on Friday, is open to all students.", "exampleZh": "這場比賽將於星期五舉行，開放所有學生參加。"}, {"pattern": "S + must + be + p.p. (被動語態)", "explain": "「必須被…」。助動詞 must 後接 be 加過去分詞，表示規定或必要的動作。", "example": "Raw vegetables must be washed before they are sliced.", "exampleZh": "生的蔬菜切片前必須洗乾淨。"}], "reading": [{"q": "What is the purpose of this announcement?", "options": ["To announce a cooking contest", "To sell organic vegetables", "To introduce a new cafeteria menu", "To explain how to make yogurt"], "answer": 0, "explain": "第一段 The Home Economics Club is proud to announce the third annual Green Kitchen Challenge，全文都在說明比賽，故選 (A)。"}, {"q": "Which of the following will the school provide for free?", "options": ["Spices", "Sauces", "Mushrooms", "Eggs"], "answer": 2, "explain": "第二段說 Spinach, mushrooms, and yams will be provided for free，故選 (C)。"}, {"q": "Why will dishes that are too spicy lose points?", "options": ["The cafeteria has no drinking water", "Some of the judges are young children", "Spices are not organic", "The rules ban all sauces"], "answer": 1, "explain": "第二段說明 because the judges include two elementary school students，故選 (B)。"}, {"q": "The word \"portions\" in paragraph 3 is closest in meaning to ______.", "options": ["prices", "recipes", "flavors", "servings"], "answer": 3, "explain": "portion 指「一份的份量」，因評審要吃二十多道菜，所以份量要小，與 servings 最接近，故選 (D)。"}, {"q": "What can a team gain by writing its recipe in English?", "options": ["A chance at another award", "A free pancake", "A later deadline", "A bigger kitchen"], "answer": 0, "explain": "最後一段說英文食譜 will receive extra credit for the English Department's Food Writing Award，故選 (A)。"}], "vocabQ": [{"q": "As a ____, my aunt never eats beef, pork, or chicken.", "options": ["vegetarian", "pioneer", "survivor", "surgeon"], "answer": 0, "explain": "不吃牛、豬、雞的人是「素食者」vegetarian。"}, {"q": "Eating ____ fish can be dangerous if it is not fresh.", "options": ["ripe", "raw", "spicy", "salty"], "answer": 1, "explain": "不新鮮的「生」魚可能有危險，raw 生的。"}, {"q": "Beans and tofu are good sources of ____ for people who do not eat meat.", "options": ["spice", "syrup", "protein", "sauce"], "answer": 2, "explain": "豆類和豆腐是不吃肉者的「蛋白質」來源，protein 蛋白質。"}, {"q": "Please ____ the bread thinly so we can make sandwiches.", "options": ["stir", "peel", "season", "slice"], "answer": 3, "explain": "做三明治要把麵包「切」薄片，slice 切片。"}, {"q": "These bananas are not ____ yet; wait until they turn yellow.", "options": ["ripe", "raw", "salty", "organic"], "answer": 0, "explain": "香蕉還沒變黃表示還不「熟」，ripe 成熟的。"}]}, {"id": "I08", "level": "inter", "num": 8, "title": "The Scar on Jason's Elbow", "titleZh": "傑森手肘上的疤", "theme": "Health & Body", "themeZh": "健康與身體", "article": ["Jason had always believed that a few scratches were nothing to worry about. So when he slipped on the wet court during a basketball game last June and scraped his elbow, he simply wiped away the blood with his jersey and kept playing. His coach shouted at him to stop, but Jason, breathing hard and with his chest pounding, wanted to finish the match. By the time the final whistle blew, the wound had stopped bleeding, and he forgot about it.", "Three days later, his elbow began to ache. The skin around the cut turned red and hot, and it itched so badly that he could not sleep. His mother took one look at it and marched him to the clinic near the MRT station. The doctor explained that bacteria had entered the wound and caused an infection. 'Germs love dirty basketball courts,' she said, cleaning the cut while Jason made a fist and bit his cheek to keep from crying. She gave him an injection, wrapped the elbow in a thick bandage, and prescribed a dose of antibiotics to be taken twice a day.", "The medicine made him drowsy, and for a week he felt exhausted after climbing a single flight of stairs. Worse, he was not allowed to play. Sitting on the bench, Jason finally consulted his coach about what he should have done. 'Wash it, cover it, and let it heal,' the coach said. 'Playing through pain feels brave, but it is actually harmful.'", "The wound healed slowly, leaving a pale scar on his elbow. Jason still plays every weekend, but now a small first-aid kit with a few band-aids and a roll of bandage travels in his backpack. When his younger teammates laugh at it, he just rolls up his sleeve and shows them the scar."], "translation": ["傑森一直認為幾道擦傷沒什麼好擔心的。所以去年六月，當他在籃球比賽中因為球場濕滑而跌倒、擦破手肘時，他只是用球衣抹掉血，繼續打球。教練大喊要他停下來，但喘著氣、心跳劇烈的傑森想把比賽打完。等到終場哨聲響起，傷口已經不流血了，他也就把它忘了。", "三天後，他的手肘開始疼痛。傷口周圍的皮膚又紅又燙，而且癢到他睡不著。媽媽看了一眼，就押著他到捷運站附近的診所。醫生解釋，細菌進入了傷口，造成感染。「病菌最愛髒髒的籃球場，」她一邊清理傷口一邊說，傑森則握緊拳頭、咬著臉頰忍住不哭。她幫他打了一針，用厚厚的繃帶包住手肘，並開了一天服用兩次的抗生素劑量。", "藥讓他昏昏欲睡，整整一週，他光是爬一層樓梯就累壞了。更糟的是，他不能打球。坐在板凳上，傑森終於向教練請教當時應該怎麼做。「洗乾淨、蓋起來，讓它復原，」教練說，「忍痛上場感覺很勇敢，但其實是有害的。」", "傷口慢慢癒合，在手肘上留下一道淡淡的疤。傑森現在每個週末還是會打球，但背包裡多了一個小小的急救包，裝著幾片 OK 繃和一捲繃帶。當年紀較小的隊友取笑他時，他只是捲起袖子，給他們看那道疤。"], "vocab": [{"word": "bleed", "pos": "v.", "zh": "流血", "example": "My nose started to bleed in the dry weather.", "exampleZh": "天氣乾燥，我的鼻子開始流血。"}, {"word": "ache", "pos": "v.", "zh": "疼痛", "example": "My legs ache after running ten kilometers.", "exampleZh": "跑了十公里後我的腿好痛。"}, {"word": "itch", "pos": "v.", "zh": "發癢", "example": "The mosquito bites on my arm itch terribly.", "exampleZh": "我手臂上的蚊子叮痕癢得要命。"}, {"word": "clinic", "pos": "n.", "zh": "診所", "example": "The dental clinic opens at nine in the morning.", "exampleZh": "那家牙醫診所早上九點開門。"}, {"word": "bacteria", "pos": "n.", "zh": "細菌", "example": "Wash your hands to remove harmful bacteria.", "exampleZh": "洗手可以去除有害的細菌。"}, {"word": "infection", "pos": "n.", "zh": "感染", "example": "The doctor gave her medicine for the ear infection.", "exampleZh": "醫生給她治療耳朵感染的藥。"}, {"word": "bandage", "pos": "n.", "zh": "繃帶", "example": "The nurse put a bandage on my cut finger.", "exampleZh": "護士在我割傷的手指上包了繃帶。"}, {"word": "dose", "pos": "n.", "zh": "（藥的）一劑；劑量", "example": "Take one dose of this medicine after each meal.", "exampleZh": "每餐飯後服用一劑這種藥。"}, {"word": "drowsy", "pos": "adj.", "zh": "昏昏欲睡的", "example": "The cold medicine made me drowsy all afternoon.", "exampleZh": "感冒藥讓我整個下午昏昏欲睡。"}, {"word": "harmful", "pos": "adj.", "zh": "有害的", "example": "Too much sugar is harmful to your teeth.", "exampleZh": "太多糖對牙齒有害。"}], "phrases": [{"phrase": "by the time", "zh": "到…的時候", "example": "By the time we arrived, the movie had already started.", "exampleZh": "我們到的時候，電影已經開始了。"}, {"phrase": "keep from + V-ing", "zh": "忍住不…；避免…", "example": "She bit her lip to keep from laughing.", "exampleZh": "她咬著嘴唇忍住不笑。"}, {"phrase": "roll up", "zh": "捲起", "example": "Roll up your sleeves before you wash the dishes.", "exampleZh": "洗碗前先把袖子捲起來。"}], "grammar": [{"pattern": "By the time + S + V (過去式), S + had + p.p.", "explain": "「到…的時候，已經…」。by the time 子句用過去式，主要子句用過去完成式，表示動作在那之前就完成了。", "example": "By the time the whistle blew, the wound had stopped bleeding.", "exampleZh": "哨聲響起時，傷口已經不流血了。"}, {"pattern": "S + should have + p.p.", "explain": "「早該…（但沒做）」，用來表示對過去的責備或後悔。", "example": "He should have washed the wound right away.", "exampleZh": "他早該馬上把傷口洗乾淨。"}], "reading": [{"q": "Why did Jason keep playing after he fell?", "options": ["He did not notice the cut", "He wanted to finish the game", "The coach told him to continue", "The clinic was closed"], "answer": 1, "explain": "第一段說 Jason... wanted to finish the match，教練其實是叫他停下來，故選 (B)。"}, {"q": "What caused the infection in Jason's elbow?", "options": ["Bacteria entering the wound", "The injection at the clinic", "The thick bandage", "The antibiotics"], "answer": 0, "explain": "第二段醫生說 bacteria had entered the wound and caused an infection，故選 (A)。"}, {"q": "The word \"drowsy\" in paragraph 3 is closest in meaning to ______.", "options": ["hungry", "nervous", "cheerful", "sleepy"], "answer": 3, "explain": "drowsy 是「昏昏欲睡的」，後面也說他很容易累，與 sleepy 最接近，故選 (D)。"}, {"q": "What does the coach think of \"playing through pain\"?", "options": ["It helps players heal faster", "It makes the team stronger", "It only looks brave but is harmful", "It is fine for short games"], "answer": 2, "explain": "教練說 Playing through pain feels brave, but it is actually harmful，故選 (C)。"}, {"q": "Why does Jason show his younger teammates the scar?", "options": ["To make them laugh", "To remind them that small wounds can be serious", "To show how brave he was", "To prove he can still play"], "answer": 1, "explain": "隊友取笑他帶急救包時，他給他們看疤，是為了提醒小傷也可能變嚴重，故選 (B)。"}], "vocabQ": [{"q": "My feet ____ after standing all day at the night market.", "options": ["ache", "itch", "bleed", "swell"], "answer": 0, "explain": "站了一整天腳會「痛」，ache 疼痛。"}, {"q": "Deep cuts can ____ for a long time if you do not press on them.", "options": ["itch", "bleed", "ache", "heal"], "answer": 1, "explain": "深的割傷不按壓會一直「流血」，bleed 流血。"}, {"q": "The nurse wrapped a clean ____ around his injured knee.", "options": ["dose", "clinic", "bandage", "aspirin"], "answer": 2, "explain": "包在受傷膝蓋上的是「繃帶」bandage。"}, {"q": "Do not exceed the ____ written on the bottle; too much medicine can be dangerous.", "options": ["infection", "bacteria", "injection", "dose"], "answer": 3, "explain": "藥瓶上寫的是「劑量」dose，不可超過。"}, {"q": "Staying up late every night is ____ to your health.", "options": ["harmful", "drowsy", "fatal", "conscious"], "answer": 0, "explain": "熬夜對健康「有害」，harmful 有害的。"}]}, {"id": "I09", "level": "inter", "num": 9, "title": "A Day in the Ward: An Interview with Nurse Chen", "titleZh": "病房裡的一天：專訪陳護理師", "theme": "Health & Body", "themeZh": "健康與身體", "article": ["Chen Ya-chi has worked in the surgical ward of a Taipei hospital for twelve years. Last week, our school newspaper visited her to find out what nursing is really like.", "Q: What does a typical morning look like? A: It begins at seven with a report from the night shift. Then I check every patient's symptoms: fever, swelling, pain, and how well they slept. Many of them have just had surgery, so the surgeon needs to know immediately if something has changed. After that I hand out pills and vitamins, change dressings, and help patients who are too weak to walk get out of bed. Q: Which patients stay in your memory? A: A man who received a kidney transplant three years ago still sends me a card every Lunar New Year. He had suffered from kidney disease for a decade, and I watched him regain his strength week by week. His recovery was not only physical; the mental side mattered just as much. Patients who believe they will get better usually do.", "Q: What is the hardest part of the job? A: Honestly, the physical demand. I walk about fifteen kilometers a day, and by evening my legs are shaking and my uniform is soaked with sweat. The muscles in my back never fully relax. Q: Do you have any advice for teenagers? A: Prevention is cheaper than therapy. Eat real food, not just snacks; nutrition matters more than any pill. Being overweight at fifteen makes your organs work harder at fifty. And please, do not start smoking. I have seen too many lungs that could have been healthy.", "Q: Why do you keep doing it? A: Because when a patient who could not breathe on his own walks out of the ward, you feel that your tiredness was worth something. That feeling has not worn out in twelve years."], "translation": ["陳雅琪在台北一家醫院的外科病房工作了十二年。上週，我們的校刊去拜訪她，想了解護理工作究竟是什麼樣子。", "問：一個典型的早晨是什麼樣子？答：七點從大夜班的交班報告開始。接著我檢查每位病人的症狀：發燒、腫脹、疼痛，以及睡得好不好。他們很多人剛動完手術，所以一有變化，外科醫師需要馬上知道。之後我發藥和維他命、換藥，並幫虛弱到無法走路的病人下床。問：哪些病人讓你印象深刻？答：三年前接受腎臟移植的一位先生，到現在每年農曆新年都會寄卡片給我。他受腎臟病之苦十年，我看著他一週一週地恢復體力。他的復原不只是身體上的；心理層面同樣重要。相信自己會好起來的病人，通常真的會好起來。", "問：這份工作最辛苦的部分是什麼？答：老實說，是體力的負荷。我一天大約走十五公里，到了傍晚雙腿發抖，制服被汗水浸濕。背部的肌肉從來沒有完全放鬆過。問：對青少年有什麼建議嗎？答：預防比治療便宜。吃真正的食物，不要只吃零食；營養比任何藥丸都重要。十五歲過重，會讓你的器官在五十歲時更辛苦。還有，拜託不要開始抽菸。我看過太多本來可以健康的肺。", "問：你為什麼一直做下去？答：因為當一位原本無法自己呼吸的病人走出病房時，你會覺得自己的疲累是有價值的。這種感覺十二年來從沒消失過。"], "vocab": [{"word": "ward", "pos": "n.", "zh": "病房", "example": "The children's ward is on the fourth floor.", "exampleZh": "兒童病房在四樓。"}, {"word": "symptom", "pos": "n.", "zh": "症狀", "example": "A high fever is a common symptom of the flu.", "exampleZh": "高燒是流感常見的症狀。"}, {"word": "surgery", "pos": "n.", "zh": "手術", "example": "Grandpa needs heart surgery next month.", "exampleZh": "爺爺下個月需要動心臟手術。"}, {"word": "surgeon", "pos": "n.", "zh": "外科醫生", "example": "The surgeon washed her hands carefully before the operation.", "exampleZh": "外科醫生在手術前仔細洗手。"}, {"word": "transplant", "pos": "n.", "zh": "移植", "example": "He has lived a normal life since his liver transplant.", "exampleZh": "自從肝臟移植後，他過著正常的生活。"}, {"word": "recovery", "pos": "n.", "zh": "康復；恢復", "example": "We wish you a quick recovery.", "exampleZh": "祝你早日康復。"}, {"word": "physical", "pos": "adj.", "zh": "身體的", "example": "Regular physical exercise keeps you healthy.", "exampleZh": "規律的體能運動讓你保持健康。"}, {"word": "mental", "pos": "adj.", "zh": "心理的；精神的", "example": "Talking to friends is good for your mental health.", "exampleZh": "和朋友聊天對心理健康有益。"}, {"word": "prevention", "pos": "n.", "zh": "預防", "example": "Wearing a mask is a simple form of prevention.", "exampleZh": "戴口罩是一種簡單的預防方式。"}, {"word": "nutrition", "pos": "n.", "zh": "營養", "example": "Good nutrition is important for growing children.", "exampleZh": "良好的營養對成長中的孩子很重要。"}], "phrases": [{"phrase": "suffer from", "zh": "罹患；受…之苦", "example": "My grandmother suffers from high blood pressure.", "exampleZh": "我奶奶有高血壓。"}, {"phrase": "hand out", "zh": "分發", "example": "The teacher handed out the test papers.", "exampleZh": "老師發下考卷。"}, {"phrase": "week by week", "zh": "一週一週地；逐週", "example": "The baby grew stronger week by week.", "exampleZh": "寶寶一週比一週強壯。"}], "grammar": [{"pattern": "S + be + too + adj. + to + V", "explain": "「太…而不能…」，表示程度過高導致無法做某事；注意句子本身沒有 not，卻含有否定意思。", "example": "Some patients are too weak to walk.", "exampleZh": "有些病人虛弱到無法走路。"}, {"pattern": "S + could have + p.p.", "explain": "「本來可以…（但事實上沒有）」，用來表示過去未實現的可能性，常帶有惋惜的語氣。", "example": "I have seen too many lungs that could have been healthy.", "exampleZh": "我看過太多本來可以健康的肺。"}], "reading": [{"q": "What is the main purpose of this article?", "options": ["To describe the work and views of a nurse", "To warn students about smoking", "To explain how a kidney transplant is done", "To advertise a Taipei hospital"], "answer": 0, "explain": "第一段說校刊去拜訪她 to find out what nursing is really like，全文以問答介紹她的工作與看法，故選 (A)。"}, {"q": "What does Nurse Chen do first each morning?", "options": ["Hand out pills and vitamins", "Listen to the night shift's report", "Change the patients' dressings", "Walk fifteen kilometers"], "answer": 1, "explain": "第二段說早晨 begins at seven with a report from the night shift，故選 (B)。"}, {"q": "According to Nurse Chen, what helps patients recover?", "options": ["Taking more pills", "Walking fifteen kilometers a day", "Believing that they will get better", "Staying in the ward longer"], "answer": 2, "explain": "第二段最後說 Patients who believe they will get better usually do，故選 (C)。"}, {"q": "The word \"soaked\" in paragraph 3 is closest in meaning to ______.", "options": ["torn", "clean", "tight", "very wet"], "answer": 3, "explain": "soaked with sweat 指被汗水「浸濕」，與 very wet 最接近，故選 (D)。"}, {"q": "What can we infer about Nurse Chen's attitude toward her job?", "options": ["She regrets choosing nursing", "She finds the job tiring but meaningful", "She plans to become a surgeon", "She thinks teenagers are lazy"], "answer": 1, "explain": "她說工作很累，但看到病人走出病房會覺得疲累有價值，故選 (B)。"}], "vocabQ": [{"q": "A runny nose is often the first ____ of a cold.", "options": ["symptom", "remedy", "therapy", "virus"], "answer": 0, "explain": "流鼻水是感冒的第一個「症狀」，symptom 症狀。"}, {"q": "After the car accident, the ____ operated on his leg for six hours.", "options": ["physician", "surgeon", "patient", "nurse"], "answer": 1, "explain": "替病人動手術的是「外科醫生」surgeon。"}, {"q": "Washing your hands often is the best ____ against the flu.", "options": ["recovery", "nutrition", "prevention", "surgery"], "answer": 2, "explain": "勤洗手是對抗流感最好的「預防」方法，prevention 預防。"}, {"q": "Doing puzzles keeps your ____ health as sharp as exercise keeps your body fit.", "options": ["physical", "medical", "vigorous", "mental"], "answer": 3, "explain": "動腦解謎有益「心理」健康，mental 心理的。"}, {"q": "The patient was moved to a quiet ____ on the third floor after the operation.", "options": ["ward", "organ", "lotion", "tablet"], "answer": 0, "explain": "手術後病人被移到三樓安靜的「病房」，ward 病房。"}]}, {"id": "I10", "level": "inter", "num": 10, "title": "How a Pair of Sneakers Taught Me to Budget", "titleZh": "一雙球鞋教會我做預算", "theme": "Shopping & Money", "themeZh": "購物與金錢", "article": ["Every month my parents give me an allowance of two thousand dollars. It sounds like a fortune to a sixteen-year-old, yet until last spring I was broke by the twentieth of every month. The reason was simple: I had never kept a budget. Money went out as fast as it came in, mostly on bubble tea, phone games, and anything with a red discount tag.", "The turning point was a pair of limited-edition sneakers. The price tag said 3,600 dollars, a sum I clearly could not afford. A sales clerk at the counter told me it was a bargain because the shoes would 'go up in value'. I had no money, so I borrowed 1,500 from my cousin, used the whole of my allowance, and walked to the checkout feeling like a wealthy investor. Two weeks later the sneakers were on sale for 2,400, and I owed my cousin money I did not have.", "That was when my mother sat me down with a notebook. We wrote down every expense of the previous month, from the grocery store snacks to the bookstore manga. Then we made a plan: forty percent for daily spending, thirty percent for saving in my bank account, twenty percent to pay back my cousin, and ten percent to donate to the animal shelter near our school. I was told to keep every receipt and to wait three days before buying anything that cost more than five hundred dollars.", "Six months later, my savings have grown to nine thousand dollars, my debt is gone, and I can finally tell a real bargain from a clever sales pitch. I still love sneakers. The difference is that now I buy them with money I actually have, and I no longer need to exchange my peace of mind for a pair of shoes."], "translation": ["每個月父母給我兩千元零用錢。對一個十六歲的人來說這聽起來像一筆財富，但直到去年春天，我每個月二十號就花光了。原因很簡單：我從來沒有做過預算。錢進來多快就出去多快，大多花在珍珠奶茶、手機遊戲，還有任何貼著紅色折扣標籤的東西上。", "轉捩點是一雙限量版球鞋。標價寫著 3,600 元，那是我顯然負擔不起的數目。櫃檯的店員告訴我這很划算，因為這雙鞋會「增值」。我沒有錢，所以向表哥借了 1,500 元，用掉全部的零用錢，然後走向結帳櫃檯，感覺自己像個有錢的投資客。兩週後，這雙球鞋特價 2,400 元，而我欠表哥的錢根本還不出來。", "就在那時，媽媽拿著一本筆記本讓我坐下來。我們寫下前一個月的每一筆開銷，從雜貨店的零食到書店的漫畫。接著我們訂了一個計畫：百分之四十用於日常花費，百分之三十存進我的銀行帳戶，百分之二十還表哥，百分之十捐給學校附近的動物收容所。我被要求保留每一張收據，而且買任何超過五百元的東西之前要先等三天。", "六個月後，我的存款已經增加到九千元，債也還清了，我終於能分辨真正的划算和巧妙的推銷話術。我還是很愛球鞋。不同的是，現在我用真正擁有的錢買鞋，再也不必用內心的平靜去換一雙鞋。"], "vocab": [{"word": "allowance", "pos": "n.", "zh": "零用錢", "example": "I get a weekly allowance of five hundred dollars.", "exampleZh": "我每週有五百元零用錢。"}, {"word": "broke", "pos": "adj.", "zh": "沒錢的；破產的", "example": "I am broke until payday, so I cannot go out tonight.", "exampleZh": "發薪日前我都沒錢，所以今晚不能出去。"}, {"word": "budget", "pos": "n.", "zh": "預算", "example": "Our family keeps a strict budget for food each month.", "exampleZh": "我們家每個月的伙食費有嚴格的預算。"}, {"word": "tag", "pos": "n.", "zh": "標籤", "example": "The price on the tag was wrong, so I asked the clerk.", "exampleZh": "標籤上的價格錯了，所以我問了店員。"}, {"word": "afford", "pos": "v.", "zh": "負擔得起", "example": "We cannot afford a trip abroad this year.", "exampleZh": "我們今年負擔不起出國旅行。"}, {"word": "bargain", "pos": "n.", "zh": "划算的交易；便宜貨", "example": "This jacket was a real bargain at only three hundred dollars.", "exampleZh": "這件外套只要三百元，真是便宜。"}, {"word": "checkout", "pos": "n.", "zh": "結帳櫃檯", "example": "There was a long line at the checkout.", "exampleZh": "結帳櫃檯排了長長的隊伍。"}, {"word": "owe", "pos": "v.", "zh": "欠（錢、人情）", "example": "I owe my brother two hundred dollars for lunch.", "exampleZh": "午餐的錢我欠我哥哥兩百元。"}, {"word": "expense", "pos": "n.", "zh": "開銷；費用", "example": "Rent is our biggest monthly expense.", "exampleZh": "房租是我們每個月最大的開銷。"}, {"word": "receipt", "pos": "n.", "zh": "收據", "example": "Keep the receipt in case you want to return the shirt.", "exampleZh": "把收據留著，以防你想退這件襯衫。"}], "phrases": [{"phrase": "go up in value", "zh": "增值", "example": "Old comic books sometimes go up in value.", "exampleZh": "舊漫畫書有時候會增值。"}, {"phrase": "pay back", "zh": "還錢", "example": "I will pay you back next Monday.", "exampleZh": "我下週一還你錢。"}, {"phrase": "tell A from B", "zh": "分辨 A 與 B", "example": "Can you tell a real diamond from a fake one?", "exampleZh": "你能分辨真鑽和假鑽嗎？"}], "grammar": [{"pattern": "S + V, yet + S + V", "explain": "yet 當連接詞時意思是「但是；然而」，語氣比 but 稍微正式，用來連接兩個意思相反的子句。", "example": "It sounds like a lot of money, yet I was always broke.", "exampleZh": "這聽起來是很多錢，但我總是沒錢。"}, {"pattern": "S + be + told + to + V", "explain": "「被告知要…；被要求…」。tell sb. to V 的被動語態，動作者常省略。", "example": "I was told to keep every receipt.", "exampleZh": "我被要求保留每一張收據。"}], "reading": [{"q": "What is the passage mainly about?", "options": ["How the writer learned to manage money after a bad purchase", "Why sneakers are a good investment", "Why parents should give larger allowances", "How to borrow money from relatives"], "answer": 0, "explain": "全文描述作者買球鞋欠債後，在媽媽幫助下學會做預算，故選 (A)。"}, {"q": "Why did the writer decide to buy the sneakers?", "options": ["They were on sale for 2,400 dollars", "A clerk said their value would rise", "The cousin recommended them", "The writer needed shoes for school"], "answer": 1, "explain": "第二段說店員 told me it was a bargain because the shoes would 'go up in value'，故選 (B)。"}, {"q": "What percentage of the allowance goes to the animal shelter?", "options": ["Forty percent", "Thirty percent", "Twenty percent", "Ten percent"], "answer": 3, "explain": "第三段的計畫是 ten percent to donate to the animal shelter，故選 (D)。"}, {"q": "The word \"broke\" in paragraph 1 is closest in meaning to ______.", "options": ["injured", "bored", "without money", "lazy"], "answer": 2, "explain": "broke 在此是形容詞，指「沒錢的」，故選 (C)。"}, {"q": "Why does the writer wait three days before an expensive purchase?", "options": ["To get a bigger discount", "To avoid buying on impulse", "To compare shop locations", "To collect more receipts"], "answer": 1, "explain": "等三天是為了冷靜思考，避免像買球鞋那樣衝動消費，故選 (B)。"}], "vocabQ": [{"q": "My parents raised my monthly ____ after I started senior high school.", "options": ["allowance", "budget", "receipt", "expense"], "answer": 0, "explain": "父母調高每月「零用錢」，allowance 零用錢。"}, {"q": "I cannot ____ a new phone this year because I am saving for a trip.", "options": ["owe", "afford", "donate", "invest"], "answer": 1, "explain": "為了存旅費而「負擔不起」新手機，afford 負擔得起。"}, {"q": "Keep the ____ in case you need to return the jacket.", "options": ["budget", "checkout", "receipt", "loan"], "answer": 2, "explain": "退貨需要「收據」，receipt 收據。"}, {"q": "I still ____ my sister two hundred dollars for the concert ticket.", "options": ["afford", "donate", "deposit", "owe"], "answer": 3, "explain": "演唱會的票錢還「欠」姊姊兩百元，owe 欠。"}, {"q": "The price ____ on the jacket says 1,200, but there is a 20 percent discount today.", "options": ["tag", "bid", "dime", "counter"], "answer": 0, "explain": "外套上的價格「標籤」，tag 標籤。"}]}, {"id": "I11", "level": "inter", "num": 11, "title": "Three Weeks on a Construction Site", "titleZh": "工地上的三個星期", "theme": "Work & Jobs", "themeZh": "工作與職業", "article": ["Last July, instead of sleeping until noon like most of my classmates, I spent three weeks working at a construction site in Linkou that my uncle manages. He is the deputy manager of a small company that builds apartment buildings, and he thought a sixteen-year-old applicant with no experience could at least carry tools and learn something. My application was accepted on the spot, which tells you how badly they needed extra labor.", "On the first morning, I was introduced to the crew: two carpenters, an electrician who hummed old Taiwanese songs all day, and a young architect who had designed the lobby. My uncle, who was also my employer, explained that the building had to be finished before a strict deadline in September, so everyone was expected to cooperate and work with efficiency. I quickly discovered that being an employee is very different from being a student. If you forget a tool, you cannot say you will bring it tomorrow.", "The hardest day came when a government inspector arrived to check the wiring. The electrician, my most patient colleague, had implemented a new safety plan the week before, but one cable was still not labeled. The inspector frowned, and for a moment I thought someone would be dismissed. Instead, my uncle calmly promised that the problem would be fixed within an hour, and it was.", "By the end of August, the walls were standing and the lobby looked exactly like the architect's drawings. My wages were small, but the real achievement was learning how many different people it takes to raise a single building. Now, whenever I pass a construction site on the way to school, I no longer see a noisy mess. I see a team that must cooperate to turn a drawing into a home."], "translation": ["去年七月，我沒有像大多數同學一樣睡到中午，而是花了三個星期在林口一個由我舅舅管理的建築工地工作。他是一家小型公司的副經理，這家公司專門蓋公寓大樓，他認為一個毫無經驗的十六歲應徵者至少可以搬搬工具、學點東西。我的申請當場就被接受了，這說明了他們有多麼需要額外的人力。", "第一天早上，我被介紹給整個工作團隊：兩位木匠、一位整天哼著台語老歌的電工，以及一位設計了大廳的年輕建築師。我舅舅同時也是我的雇主，他說明這棟大樓必須在九月一個嚴格的期限前完工，因此每個人都被要求互相合作並有效率地工作。我很快就發現，當員工和當學生非常不同。如果你忘了帶工具，你不能說明天再帶來。", "最難熬的一天，是政府的檢查員來檢查電線配置的那天。那位電工是我最有耐心的同事，他前一週才實施了一套新的安全計畫，但有一條電纜還沒貼上標籤。檢查員皺起眉頭，有那麼一瞬間我以為有人會被解雇。結果，我舅舅冷靜地承諾問題會在一小時內解決，而事情也真的做到了。", "到了八月底，牆壁已經立起來，大廳看起來和建築師的圖紙一模一樣。我的工資不多，但真正的成就是明白了蓋一棟大樓需要多少不同的人。現在，每當我上學途中經過工地，我看到的不再是一團吵雜的混亂，而是一個必須合作才能把圖紙變成家園的團隊。"], "vocab": [{"word": "construction", "pos": "n.", "zh": "建築；建造", "example": "The construction of the new bridge will take two years.", "exampleZh": "新橋的建造將花費兩年。"}, {"word": "deputy", "pos": "n.", "zh": "副手；代理人", "example": "The deputy mayor gave a speech at the opening ceremony.", "exampleZh": "副市長在開幕典禮上致詞。"}, {"word": "applicant", "pos": "n.", "zh": "申請人；應徵者", "example": "Over fifty applicants applied for the position.", "exampleZh": "超過五十位應徵者申請了這個職位。"}, {"word": "crew", "pos": "n.", "zh": "（一組）工作人員", "example": "The film crew worked through the night to finish the scene.", "exampleZh": "電影工作人員徹夜工作以完成那一幕。"}, {"word": "carpenter", "pos": "n.", "zh": "木匠", "example": "The carpenter made a wooden table for our kitchen.", "exampleZh": "木匠為我們的廚房做了一張木桌。"}, {"word": "electrician", "pos": "n.", "zh": "電工", "example": "We called an electrician to fix the broken light switch.", "exampleZh": "我們請電工來修理壞掉的電燈開關。"}, {"word": "deadline", "pos": "n.", "zh": "截止期限", "example": "The deadline for the essay contest is next Friday.", "exampleZh": "作文比賽的截止日期是下週五。"}, {"word": "cooperate", "pos": "v.", "zh": "合作", "example": "The two schools cooperated to hold a science fair.", "exampleZh": "這兩所學校合作舉辦了科學展。"}, {"word": "inspector", "pos": "n.", "zh": "檢查員；督察", "example": "A health inspector visited the restaurant this morning.", "exampleZh": "一位衛生檢查員今天早上造訪了這家餐廳。"}, {"word": "achievement", "pos": "n.", "zh": "成就", "example": "Winning the national contest was her greatest achievement.", "exampleZh": "贏得全國比賽是她最大的成就。"}], "phrases": [{"phrase": "on the spot", "zh": "當場", "example": "The manager hired her on the spot after the interview.", "exampleZh": "經理面試後當場就錄用了她。"}, {"phrase": "be introduced to", "zh": "被介紹給…", "example": "On my first day, I was introduced to all my teammates.", "exampleZh": "第一天我被介紹給所有隊友。"}, {"phrase": "by the end of", "zh": "到…結束時", "example": "By the end of the week, we had finished the report.", "exampleZh": "到週末時，我們已經完成了報告。"}], "grammar": [{"pattern": "Instead of + V-ing, S + V", "explain": "「不…而…」，instead of 後接動名詞，表示用另一個行動取代原本的行動。文章第一段：Instead of sleeping until noon..., I spent three weeks working...", "example": "Instead of taking the bus, she walked to school.", "exampleZh": "她沒有搭公車，而是走路上學。"}, {"pattern": "N, who/which + V..., V（非限定關係子句）", "explain": "用逗號隔開的關係子句補充說明前面的名詞，刪去也不影響句子主要意思。文章第二段：My uncle, who was also my employer, explained that...", "example": "Mr. Lee, who teaches physics, is also our basketball coach.", "exampleZh": "李老師教物理，他同時也是我們的籃球教練。"}], "reading": [{"q": "What is the article mainly about?", "options": ["How to apply for a job at a construction company", "A student's experience working at a construction site", "The life of a deputy manager in Linkou", "Why apartment buildings take so long to build"], "answer": 1, "explain": "全文描述作者暑假在舅舅管理的工地打工三週的經歷與心得，故選 (B)。"}, {"q": "Which of the following was NOT a member of the crew the writer met?", "options": ["An electrician", "A carpenter", "An architect", "A consultant"], "answer": 3, "explain": "第二段列出木匠、電工與建築師，並未提到顧問 (consultant)，故選 (D)。"}, {"q": "What can we infer about the company from paragraph 1?", "options": ["It had more workers than it needed.", "It only hired people with experience.", "It was short of workers.", "It refused the writer's application at first."], "answer": 2, "explain": "第一段最後說作者的申請當場被接受，「這說明了他們有多需要額外人力」，可推知公司缺人，故選 (C)。"}, {"q": "The word \"dismissed\" in paragraph 3 is closest in meaning to ____.", "options": ["fired", "praised", "promoted", "injured"], "answer": 0, "explain": "dismiss 意為「解雇」，與 fire 同義，故選 (A)。"}, {"q": "How did the writer's attitude toward construction sites change?", "options": ["He now thinks they are too noisy.", "He now sees them as the work of a cooperating team.", "He decided to become an architect.", "He is afraid of government inspectors."], "answer": 1, "explain": "第四段說作者現在經過工地時，看到的不再是吵雜的混亂，而是一個合作的團隊，故選 (B)。"}], "vocabQ": [{"q": "The road was closed for three months because of ____ work.", "options": ["construction", "education", "celebration", "competition"], "answer": 0, "explain": "句意為「道路因施工關閉三個月」，construction 建築、施工。"}, {"q": "Each ____ for the scholarship must hand in two recommendation letters.", "options": ["instructor", "applicant", "inspector", "historian"], "answer": 1, "explain": "句意為「每位獎學金申請者必須繳交兩封推薦信」，applicant 申請人。"}, {"q": "If we do not ____ with each other, the project will never be finished on time.", "options": ["compete", "complain", "cooperate", "compare"], "answer": 2, "explain": "句意為「如果我們不互相合作，計畫永遠無法準時完成」，cooperate 合作。"}, {"q": "The teacher extended the ____ for the report because of the typhoon.", "options": ["headline", "outline", "pipeline", "deadline"], "answer": 3, "explain": "句意為「老師因颱風延長了報告的截止期限」，deadline 截止期限。"}, {"q": "The fire ____ found that the building did not have enough exits.", "options": ["inspector", "carpenter", "electrician", "gardener"], "answer": 0, "explain": "句意為「消防檢查員發現這棟大樓的出口不足」，inspector 檢查員。"}]}, {"id": "I12", "level": "inter", "num": 12, "title": "Big News from the Front Desk", "titleZh": "櫃台傳來的大消息", "theme": "Work & Jobs", "themeZh": "工作與職業", "article": ["Dear Kevin, Sorry for the slow reply. Since I started working at the reception desk of a hotel in Tainan's Anping district, my life has become busier than it was during exam season. The hotel has a staff of about sixty, and new employees must complete two weeks of training before they are allowed to greet a single guest. We even attended a workshop on handling angry customers, which turned out to be surprisingly useful.", "My supervisor, Ms. Lin, is strict but fair. She has worked in the hotel profession for twenty years, and she expects everyone to look professional at all times, even at six in the morning. Last month she told me I had been the most productive member of the team, and yesterday I was promoted to senior receptionist. The promotion comes with a slightly higher salary and a new mission: managing the night shift twice a week. I am not sure I am qualified yet, but Ms. Lin says that confidence is also a qualification.", "Not everything has been cheerful. Our technician, Mr. Chen, who had fixed every broken air conditioner for fifteen years, resigned in August. His resignation surprised the whole staff, because he always said he would never retire. It seems his doctor advised him to find a less tiring occupation. On his last day, he gave a short presentation about the strangest things he had ever repaired, and we laughed until we cried.", "Anyway, how is your translator course going? Are you still volunteering at the library on weekends? Write soon and tell me everything. Yours, Vivian"], "translation": ["親愛的凱文：抱歉這麼晚才回信。自從我開始在台南安平區一家飯店的櫃台工作以來，我的生活變得比考試季還要忙碌。這家飯店大約有六十名員工，新進人員必須完成兩週的訓練，才被允許接待任何一位客人。我們甚至參加了一場關於如何應對生氣顧客的研習會，結果出乎意料地實用。", "我的主管林小姐嚴格但公正。她在飯店業工作了二十年，要求每個人隨時都要看起來專業，就算是早上六點也一樣。上個月她告訴我，我是團隊裡最有生產力的成員，而昨天我被升為資深櫃台人員。這次升遷帶來稍高一點的薪水和一項新任務：每週兩次負責管理夜班。我不確定自己是否已經夠資格，但林小姐說，自信也是一種資格。", "並不是每件事都令人開心。我們的技術人員陳先生十五年來修好了每一台壞掉的冷氣，卻在八月辭職了。他的辭職讓全體員工都很驚訝，因為他總是說自己永遠不會退休。聽說是他的醫生建議他找一份比較不累的職業。離職那天，他做了一場簡短的簡報，介紹他修過最奇怪的東西，我們笑到流眼淚。", "對了，你的翻譯課程進行得如何？你週末還在圖書館當志工嗎？快點回信，把一切都告訴我。薇薇安 敬上"], "vocab": [{"word": "reception", "pos": "n.", "zh": "接待處；櫃台", "example": "Please leave your key at the reception when you check out.", "exampleZh": "退房時請把鑰匙留在櫃台。"}, {"word": "staff", "pos": "n.", "zh": "全體員工", "example": "The restaurant staff were friendly and quick.", "exampleZh": "餐廳的員工友善又動作迅速。"}, {"word": "training", "pos": "n.", "zh": "訓練", "example": "New pilots receive months of training before their first flight.", "exampleZh": "新飛行員在首次飛行前要接受數月的訓練。"}, {"word": "workshop", "pos": "n.", "zh": "研習會；工作坊", "example": "The school held a workshop on public speaking.", "exampleZh": "學校舉辦了一場公開演說的研習會。"}, {"word": "supervisor", "pos": "n.", "zh": "主管；監督者", "example": "Ask your supervisor before leaving early.", "exampleZh": "提早離開前要先問過你的主管。"}, {"word": "productive", "pos": "adj.", "zh": "有生產力的；有效率的", "example": "I am most productive in the early morning.", "exampleZh": "我在清晨時最有效率。"}, {"word": "promotion", "pos": "n.", "zh": "升遷", "example": "She received a promotion after only one year.", "exampleZh": "她工作一年後就獲得升遷。"}, {"word": "qualified", "pos": "adj.", "zh": "合格的；有資格的", "example": "Only qualified nurses can give this injection.", "exampleZh": "只有合格的護理師才能施打這種針劑。"}, {"word": "resign", "pos": "v.", "zh": "辭職", "example": "The coach resigned after the team lost ten games in a row.", "exampleZh": "球隊連輸十場後，教練辭職了。"}, {"word": "occupation", "pos": "n.", "zh": "職業", "example": "Please write your occupation on the form.", "exampleZh": "請在表格上填寫你的職業。"}], "phrases": [{"phrase": "turn out (to be)", "zh": "結果是；原來是", "example": "The stranger turned out to be my cousin's friend.", "exampleZh": "那位陌生人原來是我表哥的朋友。"}, {"phrase": "at all times", "zh": "隨時；永遠", "example": "Keep your ticket with you at all times.", "exampleZh": "隨時把票帶在身上。"}, {"phrase": "come with", "zh": "附有；伴隨", "example": "The phone comes with a free case.", "exampleZh": "這支手機附贈一個免費保護殼。"}], "grammar": [{"pattern": "Since + S + V-ed（過去式）, S + have/has + p.p.", "explain": "since 引導的子句用過去式表示起點，主要子句用現在完成式，表示從過去某時持續到現在。文章第一段：Since I started working..., my life has become busier...", "example": "Since he moved to Kaohsiung, he has made many new friends.", "exampleZh": "自從他搬到高雄後，就交了許多新朋友。"}, {"pattern": "S + be + V-ed + to + N/V（被動語態）", "explain": "主詞是動作的承受者時用被動語態 be + 過去分詞。文章中 new employees ... are allowed to greet（被允許）、I was promoted to（被升為）都是這種用法。", "example": "The students were asked to hand in their phones.", "exampleZh": "學生們被要求交出手機。"}], "reading": [{"q": "Why did Vivian write this email?", "options": ["To ask Kevin for a job", "To tell Kevin about her new job and life", "To invite Kevin to visit Tainan", "To complain about her supervisor"], "answer": 1, "explain": "信中主要分享薇薇安在飯店工作的近況，包括訓練、升遷和同事離職，故選 (B)。"}, {"q": "What must new employees do before they can greet guests?", "options": ["Pass a test on English", "Work the night shift", "Finish two weeks of training", "Meet Ms. Lin"], "answer": 2, "explain": "第一段提到新進人員必須完成兩週訓練才能接待客人，故選 (C)。"}, {"q": "What is Vivian's new responsibility after her promotion?", "options": ["Managing the night shift twice a week", "Repairing air conditioners", "Training new employees", "Handling angry customers"], "answer": 0, "explain": "第二段說升遷帶來新任務：每週兩次管理夜班，故選 (A)。"}, {"q": "Why did Mr. Chen resign?", "options": ["He wanted a higher salary.", "His doctor told him to find a less tiring job.", "He was dismissed by Ms. Lin.", "He wanted to become a translator."], "answer": 1, "explain": "第三段提到他的醫生建議他找一份比較不累的職業，故選 (B)。"}, {"q": "The word \"productive\" in paragraph 2 is closest in meaning to ____.", "options": ["polite", "nervous", "efficient", "lazy"], "answer": 2, "explain": "productive 意為「有生產力的、有效率的」，與 efficient 最接近，故選 (C)。"}], "vocabQ": [{"q": "Every ____ member must wear a name tag while on duty.", "options": ["staff", "guest", "client", "customer"], "answer": 0, "explain": "句意為「每位員工值班時都必須配戴名牌」，staff 員工。"}, {"q": "After a year of hard work, Mark finally got the ____ he had hoped for.", "options": ["resignation", "promotion", "reception", "occupation"], "answer": 1, "explain": "句意為「經過一年努力，馬克終於獲得了期待已久的升遷」，promotion 升遷。"}, {"q": "You need to be ____ to teach at this school; a college degree is not enough.", "options": ["retired", "voluntary", "specialized", "qualified"], "answer": 3, "explain": "句意為「在這所學校教書需要具備資格，大學學位還不夠」，qualified 合格的。"}, {"q": "The manager decided to ____ after the company lost its biggest customer.", "options": ["resign", "promote", "manage", "qualify"], "answer": 0, "explain": "句意為「公司失去最大客戶後，經理決定辭職」，resign 辭職。"}, {"q": "My ____ told me to finish the report before lunch.", "options": ["messenger", "typist", "supervisor", "porter"], "answer": 2, "explain": "句意為「我的主管要我在午餐前完成報告」，supervisor 主管。"}]}, {"id": "I13", "level": "inter", "num": 13, "title": "From Night Market Stall to Stock Market", "titleZh": "從夜市攤位到股票市場", "theme": "Business & Economy", "themeZh": "商業與經濟", "article": ["TAICHUNG, Nov. 2 — Twelve years ago, brothers Chen Wei-ting and Chen Wei-lun were selling brown sugar milk tea from a tiny stall at Fengjia Night Market. Today their company, Sugar Bear, has 140 shops across Asia, and on Monday its stock was traded on the Taipei exchange for the first time.", "The founders say the secret was never the tea itself. \"Every stall in Taichung sells good tea,\" Wei-ting told reporters. \"What we built was a brand.\" In 2016, the brothers registered a trademark, hired a small agency to advertise on social media, and began to manufacture their own cups instead of buying them from a supplier. These strategies made Sugar Bear more competitive, and demand grew so quickly that the shop was often sold out by 8 p.m.", "The road was not always smooth. During the 2020 recession, consumers stayed home, and the company nearly went bankrupt. An investor from Singapore agreed to provide funds, but only after weeks of negotiation. \"We had to negotiate every detail, from profit sharing to who would pay the taxes,\" Wei-lun recalled. The venture survived, and when the economy recovered, Sugar Bear was ready to expand.", "Economists say the story reflects a wider change in Taiwan, where small family enterprises are increasingly being turned into modern corporations. The company now sponsors a youth basketball league, and the brothers insist that profit matters less than people. \"Our first client was a tired student who wanted something sweet after cram school,\" Wei-ting said. \"We still make the tea for her.\""], "translation": ["【台中十一月二日報導】十二年前，陳偉廷與陳偉倫兩兄弟在逢甲夜市的一個小攤位賣黑糖珍珠奶茶。如今他們的公司「糖熊」在亞洲各地擁有一百四十家門市，而本週一，該公司的股票首次在台北證券交易所掛牌交易。", "兩位創辦人表示，祕訣從來不在茶本身。「台中每個攤位的茶都很好喝，」偉廷告訴記者，「我們建立的是一個品牌。」二〇一六年，兄弟倆註冊了商標，聘請一家小型代理商在社群媒體上打廣告，並開始自行製造杯子，而不再向供應商購買。這些策略讓糖熊更有競爭力，需求成長得如此迅速，店裡常常在晚上八點前就賣光了。", "這條路並非一直平順。二〇二〇年經濟衰退期間，消費者待在家裡，公司幾乎破產。一位新加坡投資人同意提供資金，但那是經過數週談判之後的事。「我們必須談妥每一個細節，從利潤分配到誰來繳稅，」偉倫回憶道。這項事業撐了下來，當經濟復甦時，糖熊已準備好擴張。", "經濟學家表示，這個故事反映了台灣更廣泛的變化：小型家族企業正越來越多地轉型為現代企業。這家公司現在贊助一個青年籃球聯盟，而兄弟倆堅持，利潤沒有人重要。「我們的第一位顧客是一個補習班下課後想吃點甜食的疲憊學生，」偉廷說，「我們到現在還在為她做茶。」"], "vocab": [{"word": "brand", "pos": "n.", "zh": "品牌", "example": "This brand of sneakers is popular with teenagers.", "exampleZh": "這個運動鞋品牌很受青少年歡迎。"}, {"word": "trademark", "pos": "n.", "zh": "商標", "example": "The company's trademark is a small blue bird.", "exampleZh": "這家公司的商標是一隻小藍鳥。"}, {"word": "advertise", "pos": "v.", "zh": "登廣告；宣傳", "example": "The store advertised its sale in the newspaper.", "exampleZh": "這家店在報紙上刊登特賣廣告。"}, {"word": "manufacture", "pos": "v.", "zh": "製造", "example": "The factory manufactures bicycles for export.", "exampleZh": "這家工廠製造外銷用的腳踏車。"}, {"word": "competitive", "pos": "adj.", "zh": "有競爭力的；競爭激烈的", "example": "The price of this laptop is very competitive.", "exampleZh": "這台筆電的價格很有競爭力。"}, {"word": "demand", "pos": "n.", "zh": "需求", "example": "There is a high demand for electric scooters in Taiwan.", "exampleZh": "台灣對電動機車的需求很高。"}, {"word": "recession", "pos": "n.", "zh": "經濟衰退", "example": "Many people lost their jobs during the recession.", "exampleZh": "經濟衰退期間許多人失業。"}, {"word": "consumer", "pos": "n.", "zh": "消費者", "example": "Consumers are paying more attention to food safety.", "exampleZh": "消費者越來越重視食品安全。"}, {"word": "bankrupt", "pos": "adj.", "zh": "破產的", "example": "The airline went bankrupt after the pandemic.", "exampleZh": "這家航空公司在疫情後破產了。"}, {"word": "negotiate", "pos": "v.", "zh": "談判；協商", "example": "The workers negotiated with the company for higher pay.", "exampleZh": "工人與公司協商以爭取更高的薪資。"}], "phrases": [{"phrase": "for the first time", "zh": "第一次", "example": "I rode the high-speed rail for the first time last year.", "exampleZh": "我去年第一次搭高鐵。"}, {"phrase": "be sold out", "zh": "賣完；售罄", "example": "The concert tickets were sold out in ten minutes.", "exampleZh": "演唱會門票十分鐘內就賣完了。"}, {"phrase": "be ready to + V", "zh": "準備好做…", "example": "After months of practice, the team was ready to compete.", "exampleZh": "經過幾個月的練習，球隊已準備好參賽。"}], "grammar": [{"pattern": "S + V + so + adj./adv. + that + S + V", "explain": "「如此…以致於…」，so 後接形容詞或副詞，that 子句說明結果。文章第二段：demand grew so quickly that the shop was often sold out by 8 p.m.", "example": "The movie was so boring that half the audience fell asleep.", "exampleZh": "這部電影無聊到一半的觀眾都睡著了。"}, {"pattern": "N（地方）, where + S + V", "explain": "關係副詞 where 引導的非限定關係子句，用來補充說明前面的地方名詞，相當於 in which。文章第四段：a wider change in Taiwan, where small family enterprises are...", "example": "We visited Lukang, where many old temples still stand.", "exampleZh": "我們造訪了鹿港，那裡還保留著許多古老的廟宇。"}], "reading": [{"q": "What is the main purpose of this news report?", "options": ["To warn readers about the risks of starting a business", "To describe how a night market stall grew into a large company", "To explain how the stock market works", "To advertise a new kind of milk tea"], "answer": 1, "explain": "本報導介紹糖熊從夜市小攤成長為上市公司的過程，故選 (B)。"}, {"q": "According to the founders, what was the key to their success?", "options": ["The quality of their tea", "Low prices", "Building a brand", "Opening shops in Singapore"], "answer": 2, "explain": "第二段偉廷說「我們建立的是一個品牌」，故選 (C)。"}, {"q": "What happened to Sugar Bear in 2020?", "options": ["It opened its 140th shop.", "It nearly went bankrupt.", "It began to make its own cups.", "It started sponsoring a basketball league."], "answer": 1, "explain": "第三段提到 2020 年經濟衰退期間，公司幾乎破產，故選 (B)。"}, {"q": "The word \"funds\" in paragraph 3 is closest in meaning to ____.", "options": ["money", "advice", "cups", "workers"], "answer": 0, "explain": "funds 意為「資金」，與 money 最接近，故選 (A)。"}, {"q": "What can be inferred from the last paragraph?", "options": ["The brothers care only about making money.", "Sugar Bear has stopped selling tea to students.", "The brothers still value their customers more than profit.", "Taiwan's family businesses are disappearing."], "answer": 2, "explain": "最後一段兄弟倆堅持「利潤沒有人重要」，並說仍為第一位顧客做茶，可推知他們重視顧客甚於利潤，故選 (C)。"}], "vocabQ": [{"q": "The toy company decided to ____ its new robot on YouTube.", "options": ["advertise", "negotiate", "manufacture", "consume"], "answer": 0, "explain": "句意為「玩具公司決定在 YouTube 上宣傳新機器人」，advertise 登廣告。"}, {"q": "During the ____, many shops in the city closed because people stopped spending.", "options": ["prosperity", "recession", "commission", "distribution"], "answer": 1, "explain": "句意為「經濟衰退期間，因人們停止消費，許多商店關門」，recession 經濟衰退。"}, {"q": "A smart ____ compares prices online before buying anything expensive.", "options": ["investor", "founder", "consumer", "economist"], "answer": 2, "explain": "句意為「聰明的消費者在購買昂貴物品前會先上網比價」，consumer 消費者。"}, {"q": "The two countries will ____ a new trade agreement next month.", "options": ["prosper", "establish", "exploit", "negotiate"], "answer": 3, "explain": "句意為「兩國下個月將協商新的貿易協定」，negotiate 談判。"}, {"q": "The ____ for face masks rose sharply during the flu season.", "options": ["output", "deficit", "demand", "asset"], "answer": 2, "explain": "句意為「流感季節口罩的需求急劇上升」，demand 需求。"}]}, {"id": "I14", "level": "inter", "num": 14, "title": "Small Government, Big Lessons", "titleZh": "小小政府，大大啟示", "theme": "Government, Law & Society", "themeZh": "政府、法律與社會", "article": ["Every October, something that looks very much like a national election takes place at Minsheng Senior High School in Taipei. Posters cover the hallways, candidates give speeches in the cafeteria, and for one week every student becomes a voter. The student council, which has governed school activities since 1998, is more than a club. It has its own constitution, an elected president, and a committee for almost everything, from the school festival to the lunch menu.", "The council's authority is real, though limited. It can propose rules, but any new rule needs the approval of the school administration before it can be enforced. Two years ago, for example, the council tried to ban homework during the week of the music festival. The teachers rejected the idea, so the students organized a polite boycott of the cafeteria instead. In the end, both sides reached an agreement: homework stayed, but the festival was extended by one day.", "What makes the system work, according to the civics teacher who serves as its adviser, is the idea of equality. Every class sends one delegate, regardless of grades, and every delegate has one vote. When a dispute arises, a five-member committee listens to the evidence like a small jury and gives a judgment that both sides have promised to accept. \"Justice in a school is not about punishment,\" the teacher says. \"It is about being heard.\"", "This year's president is Nguyen Mei-lan, the daughter of immigrants from Vietnam. In her declaration of candidacy, she promised to make the council a bridge between the school and the local community, starting with a charity drive for the elderly. Whether or not she succeeds, her classmates have already learned something no textbook can teach: governing people is harder than complaining about them."], "translation": ["每年十月，一場看起來很像全國大選的活動會在台北市民生高中舉行。海報貼滿走廊，候選人在餐廳發表演說，而在這一週裡，每個學生都成為選民。學生自治會自一九九八年以來一直管理學校的各項活動，它不只是一個社團。它有自己的章程、一位民選的會長，以及幾乎涵蓋所有事務的委員會，從校慶到午餐菜單都有。", "自治會的權力是真實的，但有限。它可以提出規定，但任何新規定都需要學校行政單位的批准才能執行。舉例來說，兩年前自治會想在音樂祭那一週禁止回家作業。老師們否決了這個想法，於是學生改為發起一場有禮貌的餐廳抵制行動。最後雙方達成協議：作業保留，但音樂祭延長一天。", "擔任自治會顧問的公民老師表示，讓這個制度運作的關鍵是平等的觀念。每個班級不論成績都派出一名代表，而每位代表都有一票。當發生爭議時，一個五人委員會會像小型陪審團一樣聽取證據，並做出雙方事先承諾接受的裁決。「學校裡的正義不是關於懲罰，」這位老師說，「而是關於被傾聽。」", "今年的會長是阮美蘭，她是越南移民的女兒。在她的參選宣言中，她承諾讓自治會成為學校與當地社區之間的橋樑，首先從為長者舉辦的慈善募款活動開始。無論她是否成功，她的同學們已經學到了課本教不了的一件事：治理人比抱怨人困難多了。"], "vocab": [{"word": "candidate", "pos": "n.", "zh": "候選人", "example": "Three candidates are running for class leader.", "exampleZh": "有三位候選人競選班長。"}, {"word": "council", "pos": "n.", "zh": "議會；委員會", "example": "The city council will vote on the new park next week.", "exampleZh": "市議會下週將對新公園進行表決。"}, {"word": "constitution", "pos": "n.", "zh": "憲法；章程", "example": "The constitution protects every citizen's right to vote.", "exampleZh": "憲法保障每位公民的投票權。"}, {"word": "authority", "pos": "n.", "zh": "權力；權威", "example": "The principal has the authority to cancel classes.", "exampleZh": "校長有權取消課程。"}, {"word": "approval", "pos": "n.", "zh": "批准；同意", "example": "The plan needs the approval of the whole committee.", "exampleZh": "這項計畫需要整個委員會的批准。"}, {"word": "enforce", "pos": "v.", "zh": "執行；實施", "example": "The police will enforce the new traffic law from Monday.", "exampleZh": "警方將從週一開始執行新的交通法規。"}, {"word": "boycott", "pos": "n.", "zh": "抵制", "example": "The students organized a boycott of the cafeteria's plastic cups.", "exampleZh": "學生發起抵制餐廳塑膠杯的行動。"}, {"word": "delegate", "pos": "n.", "zh": "代表", "example": "Each country sent a delegate to the climate meeting.", "exampleZh": "每個國家都派出一名代表參加氣候會議。"}, {"word": "jury", "pos": "n.", "zh": "陪審團", "example": "The jury found the man not guilty.", "exampleZh": "陪審團判定這名男子無罪。"}, {"word": "immigrant", "pos": "n.", "zh": "移民（移入者）", "example": "Many immigrants from Southeast Asia now live in Taoyuan.", "exampleZh": "許多來自東南亞的移民現在住在桃園。"}], "phrases": [{"phrase": "take place", "zh": "舉行；發生", "example": "The school festival takes place every December.", "exampleZh": "校慶每年十二月舉行。"}, {"phrase": "in the end", "zh": "最後", "example": "In the end, we decided to take the train.", "exampleZh": "最後我們決定搭火車。"}, {"phrase": "regardless of", "zh": "不論；不管", "example": "Everyone can join the club, regardless of age.", "exampleZh": "不論年齡，每個人都可以加入社團。"}], "grammar": [{"pattern": "What + S + V + be + N（名詞子句當主詞）", "explain": "what 引導的名詞子句可以當句子的主詞，意思是「…的事物」。文章第三段：What makes the system work ... is the idea of equality.", "example": "What she said at the meeting surprised everyone.", "exampleZh": "她在會議上所說的話讓每個人都很驚訝。"}, {"pattern": "Whether or not + S + V, S + V", "explain": "「無論是否…」，表示不管條件如何，主要子句的結果都成立。文章第四段：Whether or not she succeeds, her classmates have already learned...", "example": "Whether or not it rains, the game will go on.", "exampleZh": "無論下不下雨，比賽都會照常進行。"}], "reading": [{"q": "What is the passage mainly about?", "options": ["How a high school's student council works like a small government", "The history of elections in Taiwan", "A student who wants to become a politician", "Why homework should be banned during festivals"], "answer": 0, "explain": "全文描述民生高中學生自治會如何像小型政府一樣運作，故選 (A)。"}, {"q": "What must happen before a council rule can be enforced?", "options": ["The president must sign it.", "The school administration must approve it.", "Every class must vote on it.", "The civics teacher must rewrite it."], "answer": 1, "explain": "第二段提到任何新規定都需要學校行政單位的批准才能執行，故選 (B)。"}, {"q": "What was the result of the council's attempt to ban homework?", "options": ["Homework was banned for a week.", "The council was closed down.", "The festival was made one day longer.", "The cafeteria was closed."], "answer": 2, "explain": "第二段最後說雙方達成協議：作業保留，但音樂祭延長一天，故選 (C)。"}, {"q": "The word \"dispute\" in paragraph 3 is closest in meaning to ____.", "options": ["celebration", "election", "lesson", "argument"], "answer": 3, "explain": "dispute 意為「爭議、爭執」，與 argument 最接近，故選 (D)。"}, {"q": "What does the writer suggest in the last sentence?", "options": ["Students should complain more about the school.", "Governing is more difficult than criticizing.", "Textbooks are more useful than experience.", "Mei-lan will probably fail as president."], "answer": 1, "explain": "最後一句說「治理人比抱怨人困難多了」，表示管理比批評更難，故選 (B)。"}], "vocabQ": [{"q": "The ____ who wins the most votes will become the new mayor.", "options": ["candidate", "delegate", "ambassador", "governor"], "answer": 0, "explain": "句意為「得票最多的候選人將成為新市長」，candidate 候選人。"}, {"q": "You cannot build a house here without the ____ of the city government.", "options": ["equality", "approval", "emergency", "evidence"], "answer": 1, "explain": "句意為「沒有市政府的批准，你不能在這裡蓋房子」，approval 批准。"}, {"q": "It is one thing to make a rule and another to ____ it.", "options": ["forbid", "impose", "enforce", "govern"], "answer": 2, "explain": "句意為「制定規則是一回事，執行規則又是另一回事」，enforce 執行。"}, {"q": "Our class chose Amy as its ____ to the school meeting.", "options": ["jury", "council", "constitution", "delegate"], "answer": 3, "explain": "句意為「我們班選艾美作為參加校務會議的代表」，delegate 代表。"}, {"q": "The ____ listened to both lawyers before making its decision.", "options": ["jury", "crown", "colony", "dynasty"], "answer": 0, "explain": "句意為「陪審團在做出決定前聽取了兩位律師的陳述」，jury 陪審團。"}]}, {"id": "I15", "level": "inter", "num": 15, "title": "Three Days That Changed My Mind About Politics", "titleZh": "改變我對政治看法的三天", "theme": "Government, Law & Society", "themeZh": "政府、法律與社會", "article": ["Monday. Until this week, I thought politics was something that only happened on the TV news. Then the mayor announced a new regulation that will prohibit scooters on Dihua Street, where my family has run a tea shop for thirty years. Dad was furious. \"They need a permit to repaint a wall, but a politician can change our whole street in one afternoon?\" he shouted. A group of shopkeepers has decided to hold a protest on Wednesday, and Dad is one of its loudest supporters.", "Wednesday. The protest was not what I expected. About two hundred people gathered outside the city hall holding signs, but nobody was violent. A city representative came out to listen, and she explained that the restriction was part of a wider reform to make the old district safer for pedestrians. A recent poll showed that 60 percent of residents supported it. Dad still opposed the plan, but I noticed that the opposition was not united. Some shopkeepers only wanted longer delivery hours; others wanted the whole rule cancelled.", "Friday. Tonight Dad and I read the full text of the regulation online. It turns out that delivery scooters with a special license will still be permitted before ten in the morning. The city will also use part of its welfare budget to help elderly shop owners move their goods. Dad admitted the plan was not as unfair as he had thought, although he still believes the mayor should have asked the shopkeepers first. I used to think political arguments were just noise. Now I understand that behind every regulation are real people, each with a different idea of what liberty means. Maybe I will study political science after all."], "translation": ["星期一。直到這個星期之前，我一直以為政治是只會出現在電視新聞裡的事。然後市長宣布了一項新規定，將禁止機車進入迪化街，而我家在那裡經營茶行已經三十年了。爸爸氣壞了。「他們重新粉刷一面牆都要許可證，一個政治人物卻可以在一個下午改變我們整條街？」他大吼。一群店家決定在星期三舉行抗議，而爸爸是其中最大聲的支持者之一。", "星期三。這場抗議和我想的不一樣。大約兩百人聚集在市政府外舉著標語，但沒有人訴諸暴力。一位市民代表出來聽取意見，她解釋說這項限制是更大範圍改革的一部分，目的是讓老街區對行人更安全。最近一項民調顯示，百分之六十的居民支持它。爸爸仍然反對這項計畫，但我注意到反對方並不團結。有些店家只想要更長的送貨時間；另一些則希望整條規定取消。", "星期五。今晚爸爸和我上網讀了這項規定的全文。原來，持有特殊牌照的送貨機車在早上十點之前仍然被允許通行。市政府也會動用部分社會福利預算，協助年長的店主搬運貨物。爸爸承認這項計畫沒有他原本想的那麼不公平，雖然他仍然認為市長應該先問過店家。我以前覺得政治上的爭論只是噪音。現在我明白，每一項規定背後都是真實的人，每個人對自由的意義都有不同的看法。也許我終究會去讀政治學。"], "vocab": [{"word": "regulation", "pos": "n.", "zh": "規定；法規", "example": "The new regulation limits the use of plastic bags.", "exampleZh": "新規定限制塑膠袋的使用。"}, {"word": "prohibit", "pos": "v.", "zh": "禁止", "example": "Smoking is prohibited in all MRT stations.", "exampleZh": "所有捷運站都禁止吸菸。"}, {"word": "politician", "pos": "n.", "zh": "政治人物", "example": "The politician promised to build more parks.", "exampleZh": "這位政治人物承諾興建更多公園。"}, {"word": "protest", "pos": "n.", "zh": "抗議", "example": "Hundreds of farmers joined the protest against the new tax.", "exampleZh": "數百名農民加入了反對新稅的抗議。"}, {"word": "supporter", "pos": "n.", "zh": "支持者", "example": "Thousands of supporters cheered for the team at the airport.", "exampleZh": "數千名支持者在機場為球隊歡呼。"}, {"word": "representative", "pos": "n.", "zh": "代表", "example": "A representative of the company answered our questions.", "exampleZh": "一位公司代表回答了我們的問題。"}, {"word": "reform", "pos": "n.", "zh": "改革", "example": "The education reform changed how students are tested.", "exampleZh": "這項教育改革改變了學生的評量方式。"}, {"word": "poll", "pos": "n.", "zh": "民意調查", "example": "The poll shows most people want a new library.", "exampleZh": "民調顯示大多數人想要一座新圖書館。"}, {"word": "opposition", "pos": "n.", "zh": "反對；反對者", "example": "The plan met with strong opposition from local residents.", "exampleZh": "這項計畫遭到當地居民強烈反對。"}, {"word": "welfare", "pos": "n.", "zh": "福利", "example": "The government spends billions on social welfare every year.", "exampleZh": "政府每年花費數十億在社會福利上。"}], "phrases": [{"phrase": "turn out (that)", "zh": "結果發現；原來", "example": "It turned out that the test had been cancelled.", "exampleZh": "結果發現考試已經取消了。"}, {"phrase": "be part of", "zh": "是…的一部分", "example": "Cleaning the classroom is part of our daily routine.", "exampleZh": "打掃教室是我們每日例行事務的一部分。"}, {"phrase": "after all", "zh": "畢竟；終究", "example": "I decided to go to the party after all.", "exampleZh": "我終究還是決定去參加派對。"}], "grammar": [{"pattern": "S + be + not as + adj. + as + S + had thought", "explain": "「不如…原本以為的那麼…」，as...as 表示同等比較，否定時表示程度不及；had thought 用過去完成式表示「先前以為」。文章第三段：the plan was not as unfair as he had thought.", "example": "The exam was not as difficult as I had thought.", "exampleZh": "考試沒有我原本以為的那麼難。"}, {"pattern": "S + should have + p.p.", "explain": "「當時應該…（但沒有）」，用來表示對過去行為的批評或遺憾。文章第三段：the mayor should have asked the shopkeepers first.", "example": "You should have told me about the meeting earlier.", "exampleZh": "你當時應該早點告訴我開會的事。"}], "reading": [{"q": "What is the diary mainly about?", "options": ["A family's decision to close its tea shop", "How a new rule about scooters changed the writer's view of politics", "The history of Dihua Street", "A fight between the writer and her father"], "answer": 1, "explain": "日記記錄作者因機車禁令事件而改變對政治的看法，故選 (B)。"}, {"q": "Why was the writer's father angry on Monday?", "options": ["The mayor had raised taxes on tea.", "His shop had been closed by the city.", "A new regulation would ban scooters on his street.", "He had lost his permit to repaint the wall."], "answer": 2, "explain": "第一段提到市長宣布的新規定將禁止機車進入迪化街，爸爸因此生氣，故選 (C)。"}, {"q": "What did the writer notice about the protesters on Wednesday?", "options": ["They were all violent.", "They did not all want the same thing.", "They were mostly students.", "They refused to listen to the representative."], "answer": 1, "explain": "第二段作者注意到反對方並不團結，有人只想要更長的送貨時間，有人想取消整條規定，故選 (B)。"}, {"q": "According to paragraph 3, which scooters will still be allowed on Dihua Street?", "options": ["Delivery scooters with a special license before 10 a.m.", "All scooters owned by shopkeepers", "Scooters ridden by elderly people", "None at all"], "answer": 0, "explain": "第三段說持有特殊牌照的送貨機車在早上十點前仍被允許通行，故選 (A)。"}, {"q": "What does the writer mean by \"political arguments were just noise\"?", "options": ["Politicians always shout too loudly.", "Protests are too loud for the old street.", "The TV news was hard to hear.", "She thought political debates were meaningless."], "answer": 3, "explain": "作者說以前覺得政治爭論「只是噪音」，意指她以為那些辯論沒有意義，故選 (D)。"}], "vocabQ": [{"q": "The school's new ____ requires all students to turn off their phones during class.", "options": ["regulation", "republic", "privilege", "territory"], "answer": 0, "explain": "句意為「學校的新規定要求所有學生上課時關閉手機」，regulation 規定。"}, {"q": "Many countries ____ the sale of alcohol to anyone under eighteen.", "options": ["permit", "prohibit", "unite", "violate"], "answer": 1, "explain": "句意為「許多國家禁止向十八歲以下的人販售酒類」，prohibit 禁止。"}, {"q": "Every ____ of the team waved a flag as the players arrived at the airport.", "options": ["minister", "refugee", "supporter", "politician"], "answer": 2, "explain": "句意為「球員抵達機場時，球隊的每位支持者都揮舞著旗幟」，supporter 支持者。"}, {"q": "According to the latest ____, most voters have not yet decided whom to support.", "options": ["treaty", "poll", "status", "sanction"], "answer": 1, "explain": "句意為「根據最新民調，大多數選民尚未決定支持誰」，poll 民意調查。"}, {"q": "The ____ of the elderly is one of the city's main concerns.", "options": ["welfare", "liberty", "minority", "permission"], "answer": 0, "explain": "句意為「長者的福利是本市主要關注的事項之一」，welfare 福利。"}]}, {"id": "I16", "level": "inter", "num": 16, "title": "The Mystery of the Missing Class Fund", "titleZh": "班費失蹤之謎", "theme": "Crime & Conflict", "themeZh": "犯罪與衝突", "article": ["\"Someone has stolen the class fund,\" Amy announced on Monday morning, holding up an empty envelope. Two thousand dollars, collected for the graduation trip, had disappeared from her desk over the weekend. The classroom fell silent. Then Jason, who sat behind her, pointed at Ken. \"He stayed late on Friday. He's the suspect.\" Ken turned red. \"Are you accusing me? I was cleaning the board! I'm innocent!\" Within seconds, the two boys were in the middle of a loud quarrel.", "Mr. Huang, our homeroom teacher, walked in before the argument turned into something worse. \"Nobody is guilty until we have proof,\" he said calmly, sounding like a detective in a TV drama. \"A theft is a serious offense, and so is a false accusation. Who was the last person to see the envelope?\" A quiet girl named Lily raised her hand. \"I'm a witness,\" she said. \"On Friday afternoon, I saw Amy put the envelope in her bag, not her desk.\"", "Amy's face changed. She opened her bag, dug through a pile of textbooks, and pulled out the envelope, slightly bent but full. \"I must have forgotten,\" she whispered. The classroom exploded with laughter, but Mr. Huang did not smile. \"Jason, you confronted a classmate with no evidence and threatened his reputation. The penalty is a written apology.\" Jason nodded, and so did Ken, who had been ready to defend himself all morning.", "That afternoon, the two boys walked home together as if nothing had happened. Still, I learned something I will not forget. In real life, there is rarely a criminal hiding in the shadows. More often, the \"crime\" is just a mistake, and the real victim is the person we are too quick to accuse."], "translation": ["「有人偷了班費，」星期一早上，艾咪舉著一個空信封宣布。為畢業旅行收的兩千元，在週末期間從她的桌子裡消失了。教室一片寂靜。接著，坐在她後面的傑森指著肯。「他星期五留到很晚。他就是嫌疑犯。」肯的臉漲紅了。「你在指控我嗎？我當時在擦黑板！我是無辜的！」不到幾秒鐘，兩個男孩就陷入了激烈的爭吵。", "我們的導師黃老師在爭吵變得更糟之前走了進來。「在有證據之前，沒有人是有罪的，」他冷靜地說，聽起來像電視劇裡的偵探。「偷竊是嚴重的罪行，誣告也是。最後一個看到信封的人是誰？」一個安靜的女孩莉莉舉起手。「我是目擊者，」她說，「星期五下午，我看到艾咪把信封放進她的書包，而不是桌子裡。」", "艾咪的臉色變了。她打開書包，在一疊課本裡翻找，拿出了那個信封，有點折到但完好無缺。「我一定是忘了，」她小聲說。教室裡爆出一陣大笑，但黃老師沒有笑。「傑森，你在沒有證據的情況下當面指責同學，還威脅到他的名譽。處罰是寫一封道歉信。」傑森點點頭，一整個早上都準備為自己辯護的肯也點了頭。", "那天下午，兩個男孩像什麼事都沒發生一樣一起走路回家。不過，我學到了一件不會忘記的事。在現實生活中，很少有罪犯躲在陰影裡。更多時候，所謂的「犯罪」只是一個錯誤，而真正的受害者，是那個我們太快就去指控的人。"], "vocab": [{"word": "suspect", "pos": "n.", "zh": "嫌疑犯", "example": "The police questioned two suspects about the robbery.", "exampleZh": "警方就搶案偵訊了兩名嫌疑犯。"}, {"word": "accuse", "pos": "v.", "zh": "指控；控告", "example": "She accused her brother of breaking her phone.", "exampleZh": "她指控弟弟弄壞了她的手機。"}, {"word": "innocent", "pos": "adj.", "zh": "無辜的；無罪的", "example": "The man insisted that he was innocent.", "exampleZh": "這名男子堅稱自己是無辜的。"}, {"word": "quarrel", "pos": "n.", "zh": "爭吵", "example": "The two sisters had a quarrel over the remote control.", "exampleZh": "兩姊妹為了遙控器吵了一架。"}, {"word": "guilty", "pos": "adj.", "zh": "有罪的；內疚的", "example": "The court found him guilty of stealing.", "exampleZh": "法院判定他犯了竊盜罪。"}, {"word": "theft", "pos": "n.", "zh": "偷竊", "example": "Bicycle theft is common near the train station.", "exampleZh": "火車站附近腳踏車失竊很常見。"}, {"word": "offense", "pos": "n.", "zh": "罪行；違法行為", "example": "Driving without a license is a serious offense.", "exampleZh": "無照駕駛是嚴重的違法行為。"}, {"word": "witness", "pos": "n.", "zh": "目擊者；證人", "example": "A witness told the police what she had seen.", "exampleZh": "一位目擊者告訴警方她所看到的事。"}, {"word": "confront", "pos": "v.", "zh": "當面對質；面對", "example": "He finally confronted his friend about the lie.", "exampleZh": "他終於就那個謊言和朋友當面對質。"}, {"word": "penalty", "pos": "n.", "zh": "處罰；罰款", "example": "The penalty for parking here is 900 dollars.", "exampleZh": "在這裡停車的罰款是九百元。"}], "phrases": [{"phrase": "fall silent", "zh": "陷入沉默", "example": "The crowd fell silent when the singer walked on stage.", "exampleZh": "歌手走上舞台時，群眾安靜了下來。"}, {"phrase": "turn into", "zh": "變成", "example": "The small argument turned into a big fight.", "exampleZh": "小爭執變成了大吵架。"}, {"phrase": "as if nothing had happened", "zh": "彷彿什麼事都沒發生", "example": "She smiled and kept talking as if nothing had happened.", "exampleZh": "她微笑著繼續說話，彷彿什麼事都沒發生過。"}], "grammar": [{"pattern": "Nobody / No one + V + until + S + V", "explain": "「直到…之前，沒有人…」，until 引導時間子句，說明某狀態持續到某個時間點才改變。文章第二段：Nobody is guilty until we have proof.", "example": "Nobody may leave the room until the test is over.", "exampleZh": "考試結束前，任何人都不得離開教室。"}, {"pattern": "S + must have + p.p.", "explain": "「一定是…了」，用來表示對過去事情的肯定推測。文章第三段：I must have forgotten.", "example": "The ground is wet. It must have rained last night.", "exampleZh": "地面是濕的，昨晚一定下過雨。"}], "reading": [{"q": "What is the best title for this story?", "options": ["How to Catch a Thief", "The Class Fund That Was Never Stolen", "Mr. Huang's Favorite TV Drama", "Why Ken Stayed Late on Friday"], "answer": 1, "explain": "故事的重點是班費其實沒有被偷，只是艾咪忘了放在書包裡，故選 (B)。"}, {"q": "Why did Jason think Ken was the suspect?", "options": ["Ken had been seen with the envelope.", "Ken had a lot of money on Monday.", "Ken had stayed late on Friday.", "Ken had quarreled with Amy before."], "answer": 2, "explain": "第一段傑森說「他星期五留到很晚」，因此懷疑肯，故選 (C)。"}, {"q": "Where was the class fund finally found?", "options": ["In Amy's desk", "In Ken's bag", "On the teacher's table", "In Amy's bag"], "answer": 3, "explain": "第三段艾咪打開書包，從一疊課本裡拿出信封，故選 (D)。"}, {"q": "The word \"reputation\" in paragraph 3 is closest in meaning to ____.", "options": ["the way others think of a person", "a person's health", "a person's money", "a person's grades"], "answer": 0, "explain": "reputation 意為「名譽、名聲」，即他人對一個人的看法，故選 (A)。"}, {"q": "What lesson does the writer draw from the event?", "options": ["Teachers should act more like detectives.", "Students should not collect money for trips.", "People should not accuse others too quickly.", "Real criminals usually hide in the shadows."], "answer": 2, "explain": "最後一段說真正的受害者是「我們太快去指控的人」，提醒讀者不要輕易指控他人，故選 (C)。"}], "vocabQ": [{"q": "The police arrested a ____ near the bank an hour after the robbery.", "options": ["suspect", "witness", "victim", "detective"], "answer": 0, "explain": "句意為「搶案發生一小時後，警方在銀行附近逮捕了一名嫌疑犯」，suspect 嫌疑犯。"}, {"q": "After hearing all the evidence, the judge decided that the woman was ____.", "options": ["violent", "innocent", "armed", "illegal"], "answer": 1, "explain": "句意為「聽完所有證據後，法官判定這名女子無罪」，innocent 無辜的。"}, {"q": "The ____ of a laptop from the library was reported to the police.", "options": ["penalty", "revenge", "theft", "defense"], "answer": 2, "explain": "句意為「圖書館筆電的失竊案已向警方報案」，theft 偷竊。"}, {"q": "The only ____ to the accident was an old man walking his dog.", "options": ["hostage", "pirate", "rebel", "witness"], "answer": 3, "explain": "句意為「這起意外唯一的目擊者是一位遛狗的老先生」，witness 目擊者。"}, {"q": "The ____ for littering in the park is a fine of 1,200 dollars.", "options": ["offense", "penalty", "threat", "bullet"], "answer": 1, "explain": "句意為「在公園亂丟垃圾的處罰是罰款一千兩百元」，penalty 處罰。"}]}, {"id": "I17", "level": "inter", "num": 17, "title": "Two Days in Tainan: A Walker's Guide", "titleZh": "台南兩日：步行者指南", "theme": "The City & Places", "themeZh": "城市與場所", "article": ["Tainan was Taiwan's capital for more than two hundred years, and it remains the best place on the island to see how a small settlement grows into a modern city. The following guide will help you explore it in two days without a tour bus.", "Step one: begin at Fort Zeelandia in the Anping district, the oldest European site in Taiwan. The Dutch built it in 1624, and although only part of the original walls survives, the fort is still the city's most famous landmark. Nearby, a canal that once carried trading ships now carries tourists in small boats. Step two: walk, do not ride. Tainan's charm hides in its alleys, where old houses, temples, and tiny coffee shops stand side by side. Many lanes are paved with red bricks, and some are so narrow that two people cannot pass without turning sideways.", "Step three: talk to the inhabitants. Unlike people in a busy urban center such as Taipei, Tainan residents are rarely in a hurry, and the owner of a noodle stand may tell you more about the neighborhood than any guidebook. Step four: visit the Chimei Museum in the southern suburb of Rende. Its white building, with a wide avenue and a fountain in front, looks like a European palace, and its collection includes everything from ancient weapons to violins.", "Finally, end your trip by the seaside. Watch the sunset from Anping harbor, then return to the city center for a bowl of beef soup. By then, you will understand why visitors call Tainan a food lover's paradise, and why its location, far from the skyscrapers of the north, is exactly what makes it worth the trip."], "translation": ["台南曾是台灣的首府超過兩百年，至今仍是島上觀察一個小聚落如何發展成現代城市的最佳地點。以下的指南將幫助你不用搭遊覽車，就能在兩天內探索這座城市。", "第一步：從安平區的熱蘭遮城開始，這是台灣最古老的歐洲遺址。荷蘭人於一六二四年建造了它，雖然原有的城牆只剩下一部分，這座堡壘仍是台南最著名的地標。附近有一條運河，曾經載著貿易船隻，如今則載著觀光客乘坐小船。第二步：用走的，不要騎車。台南的魅力藏在巷弄裡，老房子、廟宇和小咖啡店並肩而立。許多巷子鋪著紅磚，有些窄到兩個人要側身才能錯身而過。", "第三步：和當地居民聊天。和台北這類忙碌都市中心的人不同，台南居民很少匆匆忙忙，一位麵攤老闆告訴你的街坊故事，可能比任何旅遊書都多。第四步：造訪位於南邊近郊仁德的奇美博物館。它的白色建築前方有寬闊的大道和噴泉，看起來像歐洲的宮殿，館藏從古代兵器到小提琴應有盡有。", "最後，在海邊結束你的旅程。在安平港欣賞日落，然後回到市中心喝一碗牛肉湯。到那時，你就會明白為什麼遊客稱台南為美食愛好者的天堂，也會明白為什麼它遠離北部摩天大樓的地理位置，正是讓它值得一遊的原因。"], "vocab": [{"word": "capital", "pos": "n.", "zh": "首都；首府", "example": "Taipei is the capital of Taiwan.", "exampleZh": "台北是台灣的首都。"}, {"word": "settlement", "pos": "n.", "zh": "聚落；殖民地", "example": "The first settlement on the island was built near the river.", "exampleZh": "島上第一個聚落建在河邊。"}, {"word": "fort", "pos": "n.", "zh": "堡壘；要塞", "example": "The old fort on the hill now serves as a museum.", "exampleZh": "山丘上的古堡現在是一座博物館。"}, {"word": "landmark", "pos": "n.", "zh": "地標", "example": "Taipei 101 is the most famous landmark in the city.", "exampleZh": "台北101是這座城市最著名的地標。"}, {"word": "canal", "pos": "n.", "zh": "運河", "example": "Boats carry goods along the canal every day.", "exampleZh": "船隻每天沿著運河運送貨物。"}, {"word": "alley", "pos": "n.", "zh": "小巷；窄巷", "example": "There is a tiny bookstore hidden in the alley behind the temple.", "exampleZh": "廟後面的小巷裡藏著一家小書店。"}, {"word": "inhabitant", "pos": "n.", "zh": "居民", "example": "The village has fewer than 300 inhabitants.", "exampleZh": "這個村莊的居民不到三百人。"}, {"word": "urban", "pos": "adj.", "zh": "都市的", "example": "Urban life can be exciting but stressful.", "exampleZh": "都市生活可能很刺激，但也充滿壓力。"}, {"word": "suburb", "pos": "n.", "zh": "郊區", "example": "My grandparents live in a quiet suburb of Taichung.", "exampleZh": "我的祖父母住在台中一個安靜的郊區。"}, {"word": "paradise", "pos": "n.", "zh": "天堂；樂園", "example": "Kenting is a paradise for people who love the beach.", "exampleZh": "墾丁是熱愛海灘的人的天堂。"}], "phrases": [{"phrase": "side by side", "zh": "並肩；並排", "example": "The two friends sat side by side on the bench.", "exampleZh": "兩位朋友並肩坐在長椅上。"}, {"phrase": "in a hurry", "zh": "匆忙", "example": "He left in a hurry and forgot his umbrella.", "exampleZh": "他匆忙離開，忘了帶雨傘。"}, {"phrase": "be worth + N / V-ing", "zh": "值得…", "example": "The museum is worth a visit.", "exampleZh": "這座博物館值得一遊。"}], "grammar": [{"pattern": "Although + S + V, S + V", "explain": "「雖然…，但是…」，although 引導讓步子句，注意英文中 although 和 but 不可同時使用。文章第二段：although only part of the original walls survives, the fort is still...", "example": "Although it was raining, we still went hiking.", "exampleZh": "雖然下著雨，我們還是去健行了。"}, {"pattern": "Unlike + N, S + V", "explain": "「和…不同，…」，unlike 是介系詞，後面接名詞，用來對比兩者的差異。文章第三段：Unlike people in a busy urban center such as Taipei, Tainan residents are rarely in a hurry.", "example": "Unlike his brother, Tom hates spicy food.", "exampleZh": "和他哥哥不同，湯姆討厭辣的食物。"}], "reading": [{"q": "What is the purpose of this passage?", "options": ["To describe the history of the Dutch in Taiwan", "To give advice on how to explore Tainan", "To compare Tainan with Taipei", "To advertise the Chimei Museum"], "answer": 1, "explain": "文章以步驟方式教讀者如何用兩天探索台南，故選 (B)。"}, {"q": "According to the passage, what is Tainan's most famous landmark?", "options": ["The Chimei Museum", "Anping harbor", "Fort Zeelandia", "The canal"], "answer": 2, "explain": "第二段提到熱蘭遮城仍是台南最著名的地標，故選 (C)。"}, {"q": "Why does the writer suggest walking instead of riding?", "options": ["Tainan has no buses.", "The city's charm is hidden in its narrow alleys.", "Riding a scooter is illegal in the old district.", "Walking is good for health."], "answer": 1, "explain": "第二段說台南的魅力藏在巷弄裡，有些窄到兩人要側身才能通過，故選 (B)。"}, {"q": "The word \"inhabitants\" in paragraph 3 is closest in meaning to ____.", "options": ["tourists", "guidebooks", "owners", "residents"], "answer": 3, "explain": "inhabitants 意為「居民」，與 residents 同義，故選 (D)。"}, {"q": "What can we infer about the Chimei Museum?", "options": ["It is located in the center of Tainan.", "It only displays musical instruments.", "It looks different from a traditional Taiwanese building.", "It was built by the Dutch."], "answer": 2, "explain": "第三段說博物館的白色建築有大道和噴泉，看起來像歐洲的宮殿，可推知它與傳統台灣建築不同，故選 (C)。"}], "vocabQ": [{"q": "Canberra, not Sydney, is the ____ of Australia.", "options": ["capital", "province", "district", "zone"], "answer": 0, "explain": "句意為「澳洲的首都是坎培拉，而不是雪梨」，capital 首都。"}, {"q": "The Eiffel Tower is the most famous ____ in Paris.", "options": ["avenue", "landmark", "facility", "settlement"], "answer": 1, "explain": "句意為「艾菲爾鐵塔是巴黎最著名的地標」，landmark 地標。"}, {"q": "Boats travel slowly through the ____ that runs across the old town.", "options": ["arch", "fountain", "canal", "fort"], "answer": 2, "explain": "句意為「船隻緩慢地穿過橫貫老城的運河」，canal 運河。"}, {"q": "My family moved to a quiet ____ because houses there are cheaper than in the city.", "options": ["globe", "homeland", "mainland", "suburb"], "answer": 3, "explain": "句意為「我家搬到一個安靜的郊區，因為那裡的房子比市區便宜」，suburb 郊區。"}, {"q": "Traffic jams are a common problem in large ____ areas.", "options": ["urban", "remote", "regional", "nearby"], "answer": 0, "explain": "句意為「塞車是大型都市地區常見的問題」，urban 都市的。"}]}, {"id": "I18", "level": "inter", "num": 18, "title": "Notice: Sunrise Hike Rescheduled", "titleZh": "公告：日出健行改期", "theme": "Weather & Environment", "themeZh": "天氣與環境", "article": ["To all members of the Outdoor Club: Because of the weather forecast, this Saturday's sunrise hike to the summit of Mt. Qixing has been moved to Saturday, November 15. The Central Weather Administration expects heavy rainfall and thunderstorms over northern Taiwan this weekend, and the mountain trail, which was damaged by a landslide in September, becomes dangerous when it is muddy. The safety of our members comes first.", "Please note the following for the new date. We will meet at Jiantan MRT Station at 3:30 a.m. The air at the top is often freezing before dawn, even when the city feels mild, so bring a warm jacket in addition to your raincoat. Humidity is high in the mountains, and a thick mist frequently covers the path until the sun rises, so a headlamp is required. If the sky is clear, we will watch the sunrise from the summit and see the skyscrapers of Taipei appear on the horizon.", "The club also reminds everyone of our environmental rules. Yangmingshan is a national park, and its volcanic hills, hot springs, and wildlife must be preserved for future hikers. Do not leave litter anywhere, not even fruit peel. Stay on the paved trail, since stepping on the grass damages the plants that hold the damp soil together. Finally, please respect the quiet surroundings; the animals that live there are not used to loud music.", "Members who cannot attend on the new date may receive a refund from Ms. Kao in the student affairs office before November 10. We apologize for the inconvenience and hope to enjoy a chilly but beautiful morning with you on the 15th. The Outdoor Club Committee"], "translation": ["致戶外社全體社員：由於天氣預報的關係，本週六前往七星山山頂的日出健行活動已改期至十一月十五日（星期六）。中央氣象署預計本週末台灣北部將有大雨和雷雨，而登山步道在九月曾受山崩損壞，泥濘時會變得危險。社員的安全是第一優先。", "新日期的注意事項如下。我們將於凌晨三點三十分在劍潭捷運站集合。即使市區感覺溫和，山頂的空氣在黎明前常常冰冷刺骨，所以除了雨衣之外，請再帶一件保暖外套。山區濕度很高，日出之前步道常被濃霧籠罩，因此必須攜帶頭燈。如果天空晴朗，我們將在山頂觀賞日出，並看到台北的摩天大樓在地平線上浮現。", "本社也提醒各位我們的環保規範。陽明山是國家公園，它的火山丘陵、溫泉和野生動物必須為未來的登山者保存下來。不要在任何地方留下垃圾，連果皮也不行。請留在鋪設好的步道上，因為踩踏草地會傷害將潮濕土壤固定在一起的植物。最後，請尊重這裡寧靜的環境；住在那裡的動物不習慣吵鬧的音樂。", "無法於新日期參加的社員，可在十一月十日前向學務處的高老師辦理退費。我們為造成的不便致歉，並期待在十五日與各位共度一個寒冷但美麗的早晨。戶外社委員會"], "vocab": [{"word": "forecast", "pos": "n.", "zh": "預報", "example": "The weather forecast says it will snow tomorrow.", "exampleZh": "天氣預報說明天會下雪。"}, {"word": "summit", "pos": "n.", "zh": "山頂；頂峰", "example": "It took us six hours to reach the summit.", "exampleZh": "我們花了六小時才到達山頂。"}, {"word": "rainfall", "pos": "n.", "zh": "降雨量", "example": "The rainfall this spring was much lower than usual.", "exampleZh": "今年春天的降雨量比往年少很多。"}, {"word": "thunderstorm", "pos": "n.", "zh": "雷雨", "example": "The baseball game was stopped because of a thunderstorm.", "exampleZh": "棒球賽因雷雨而暫停。"}, {"word": "landslide", "pos": "n.", "zh": "山崩；土石流", "example": "The highway was blocked by a landslide after the typhoon.", "exampleZh": "颱風過後，公路被山崩阻斷了。"}, {"word": "humidity", "pos": "n.", "zh": "濕度", "example": "The humidity in Taipei makes summer feel even hotter.", "exampleZh": "台北的濕度讓夏天感覺更熱。"}, {"word": "mist", "pos": "n.", "zh": "薄霧", "example": "A light mist covered the lake in the early morning.", "exampleZh": "清晨一層薄霧籠罩著湖面。"}, {"word": "horizon", "pos": "n.", "zh": "地平線", "example": "The ship slowly disappeared over the horizon.", "exampleZh": "那艘船慢慢消失在地平線上。"}, {"word": "preserve", "pos": "v.", "zh": "保存；保護", "example": "We must preserve the forest for our children.", "exampleZh": "我們必須為孩子保護這片森林。"}, {"word": "litter", "pos": "n.", "zh": "垃圾（亂丟的）", "example": "Volunteers picked up litter along the beach.", "exampleZh": "志工沿著海灘撿拾垃圾。"}], "phrases": [{"phrase": "come first", "zh": "最重要；優先", "example": "For our coach, safety always comes first.", "exampleZh": "對我們的教練而言，安全永遠最重要。"}, {"phrase": "in addition to", "zh": "除了…之外（還）", "example": "In addition to English, she speaks Japanese.", "exampleZh": "除了英語之外，她還會說日語。"}, {"phrase": "be used to + N / V-ing", "zh": "習慣於", "example": "I am not used to getting up so early.", "exampleZh": "我不習慣這麼早起床。"}], "grammar": [{"pattern": "Because of + N, S + V", "explain": "because of 是介系詞片語，後面接名詞或動名詞；because 則接完整子句。文章第一段：Because of the weather forecast, this Saturday's hike has been moved...", "example": "Because of the heavy rain, the picnic was cancelled.", "exampleZh": "由於大雨，野餐取消了。"}, {"pattern": "S + must / may + be + p.p.（助動詞 + 被動語態）", "explain": "助動詞後面接 be + 過去分詞，表示「必須被…／可以被…」。文章第三段：its hills, hot springs, and wildlife must be preserved for future hikers.", "example": "All bags must be checked before you enter the stadium.", "exampleZh": "進入體育場前，所有袋子都必須接受檢查。"}], "reading": [{"q": "What is the main purpose of this notice?", "options": ["To cancel the Outdoor Club for the year", "To announce that the hike has been rescheduled and give details", "To describe the history of Yangmingshan", "To ask members to pay more money"], "answer": 1, "explain": "公告主要說明日出健行改期，並說明新日期的注意事項，故選 (B)。"}, {"q": "Why was the hike postponed?", "options": ["The MRT does not run early enough.", "Not enough members signed up.", "Heavy rain and thunderstorms are expected.", "The trail is closed for repairs."], "answer": 2, "explain": "第一段提到氣象署預計本週末有大雨和雷雨，步道泥濘時很危險，故選 (C)。"}, {"q": "What should members bring according to the notice?", "options": ["A warm jacket, a raincoat, and a headlamp", "A tent and food for two days", "Loud music to keep animals away", "A map of the national park"], "answer": 0, "explain": "第二段提到要帶保暖外套、雨衣，並且必須攜帶頭燈，故選 (A)。"}, {"q": "The word \"mild\" in paragraph 2 is closest in meaning to ____.", "options": ["windy", "dark", "crowded", "warm"], "answer": 3, "explain": "mild 形容天氣「溫和的」，與 warm 最接近，故選 (D)。"}, {"q": "Why are members told to stay on the paved trail?", "options": ["Because the grass is poisonous", "Because the animals might attack them", "Because walking on the grass harms plants that hold the soil", "Because the trail is faster"], "answer": 2, "explain": "第三段說踩踏草地會傷害將潮濕土壤固定在一起的植物，故選 (C)。"}], "vocabQ": [{"q": "According to the ____, a typhoon will hit the east coast on Friday.", "options": ["forecast", "drought", "frost", "shade"], "answer": 0, "explain": "句意為「根據預報，颱風將於週五侵襲東海岸」，forecast 預報。"}, {"q": "Heavy rain caused a ____ that buried part of the mountain road.", "options": ["breeze", "landslide", "sunrise", "snowman"], "answer": 1, "explain": "句意為「大雨引發山崩，掩埋了部分山路」，landslide 山崩。"}, {"q": "The climbers took a photo together when they reached the ____.", "options": ["gulf", "tide", "summit", "iceberg"], "answer": 2, "explain": "句意為「登山者到達山頂時一起拍了照」，summit 山頂。"}, {"q": "Please throw your ____ in the trash can, not on the ground.", "options": ["moisture", "smog", "litter", "mist"], "answer": 2, "explain": "句意為「請把垃圾丟進垃圾桶，不要丟在地上」，litter 垃圾。"}, {"q": "The government has promised to ____ the old temple for future generations.", "options": ["freeze", "preserve", "flood", "chill"], "answer": 1, "explain": "句意為「政府承諾為後代子孫保存這座古廟」，preserve 保存。"}]}, {"id": "I19", "level": "inter", "num": 19, "title": "The Summer the Eggs Hatched", "titleZh": "雞蛋孵化的那個夏天", "theme": "Nature & Animals", "themeZh": "自然與動物", "article": ["When twelve-year-old Hsiao-yu was sent to her grandparents' farm in Yilan for the summer, she expected to be bored within a day. There was no convenience store, no Wi-Fi, and the nearest bus stop was a twenty-minute walk past a bamboo grove. On the first evening, she sat outside the old barn, listening to crickets in the dark, and counted the days until school started.", "Her grandfather, who had spent fifty years in agriculture, had other plans. At dawn, he led her to the henhouse, where a dozen eggs were about to hatch. \"Each chick will need a name,\" he said. By noon, three wet, tired creatures with yellow feathers had broken out of their shells, and Hsiao-yu had forgotten about her phone. Over the following weeks, she learned to feed the cattle, spread fertilizer on the rice fields, and tell a dragonfly from a damselfly. The soil in Yilan is fertile because of the rain, her grandfather explained, but a crop still fails if nobody cares for it.", "One afternoon, a hawk circled above the yard, and the hens hid their chicks under the bushes. Hsiao-yu grabbed a broom, ready to fight the fierce bird, but her grandmother laughed. \"The hawk is hungry, too,\" she said. \"Every creature here is trying to live.\" Later, walking along the brook behind the farm, Hsiao-yu noticed a caterpillar on a blossom and, for the first time, did not scream.", "When her parents arrived in late August, they found a daughter with brown arms, muddy shoes, and a notebook full of drawings of ducklings. Hsiao-yu is now in senior high school, and she has already decided to study agriculture. Her three chicks, by the way, grew into very loud hens."], "translation": ["當十二歲的小宇被送到宜蘭的祖父母農場過暑假時，她以為自己不到一天就會無聊死。那裡沒有便利商店、沒有 Wi-Fi，最近的公車站要走二十分鐘，還得穿過一片竹林。第一天晚上，她坐在老穀倉外面，聽著黑暗中的蟋蟀聲，數著離開學還有幾天。", "她的祖父在農業領域耕耘了五十年，有別的打算。天一亮，他就帶她到雞舍，那裡有一打雞蛋正要孵化。「每隻小雞都需要一個名字，」他說。到了中午，三隻濕濕的、疲倦的、長著黃色羽毛的小生物破殼而出，小宇也忘了她的手機。接下來幾週，她學會了餵牛、在稻田裡撒肥料，還學會分辨蜻蜓和豆娘。祖父解釋，宜蘭的土壤因為雨水而肥沃，但如果沒有人照顧，作物還是會歉收。", "一天下午，一隻老鷹在院子上空盤旋，母雞們把小雞藏到灌木叢下。小宇抓起掃帚，準備和那隻凶猛的鳥搏鬥，但祖母笑了。「老鷹也餓了，」她說，「這裡的每一個生物都在努力活下去。」後來，沿著農場後面的小溪散步時，小宇注意到花朵上有一隻毛毛蟲，而她第一次沒有尖叫。", "八月底父母來接她時，他們看到的是一個手臂曬成褐色、鞋子沾滿泥巴、筆記本裡畫滿小鴨子的女兒。小宇現在念高中了，她已經決定要讀農業。順帶一提，她的三隻小雞長成了叫聲非常大的母雞。"], "vocab": [{"word": "agriculture", "pos": "n.", "zh": "農業", "example": "Agriculture is still important to the economy of Yunlin.", "exampleZh": "農業對雲林的經濟仍然很重要。"}, {"word": "barn", "pos": "n.", "zh": "穀倉；牲口棚", "example": "The farmer keeps his tractor in the barn.", "exampleZh": "農夫把他的曳引機停在穀倉裡。"}, {"word": "hatch", "pos": "v.", "zh": "孵化", "example": "The eggs will hatch in about three weeks.", "exampleZh": "這些蛋大約三週後會孵化。"}, {"word": "chick", "pos": "n.", "zh": "小雞", "example": "The chicks followed their mother around the yard.", "exampleZh": "小雞跟著母雞在院子裡走來走去。"}, {"word": "creature", "pos": "n.", "zh": "生物；動物", "example": "The deep sea is home to many strange creatures.", "exampleZh": "深海是許多奇特生物的家。"}, {"word": "feather", "pos": "n.", "zh": "羽毛", "example": "The peacock spread its colorful feathers.", "exampleZh": "孔雀展開牠色彩繽紛的羽毛。"}, {"word": "fertilizer", "pos": "n.", "zh": "肥料", "example": "Too much fertilizer can harm the river.", "exampleZh": "過多的肥料可能會傷害河川。"}, {"word": "fertile", "pos": "adj.", "zh": "肥沃的", "example": "The land near the river is fertile and good for rice.", "exampleZh": "河邊的土地肥沃，適合種稻。"}, {"word": "hawk", "pos": "n.", "zh": "老鷹；鷹", "example": "A hawk can spot a mouse from high in the sky.", "exampleZh": "老鷹能從高空中發現一隻老鼠。"}, {"word": "fierce", "pos": "adj.", "zh": "凶猛的；激烈的", "example": "The dog looked fierce, but it was actually friendly.", "exampleZh": "那隻狗看起來很凶，其實很友善。"}], "phrases": [{"phrase": "be about to + V", "zh": "即將；正要", "example": "The train is about to leave, so hurry up.", "exampleZh": "火車就要開了，快一點。"}, {"phrase": "break out of", "zh": "從…破出；逃出", "example": "The baby turtles broke out of their shells on the beach.", "exampleZh": "小海龜在沙灘上破殼而出。"}, {"phrase": "tell A from B", "zh": "分辨 A 與 B", "example": "Can you tell a frog from a toad?", "exampleZh": "你能分辨青蛙和蟾蜍嗎？"}], "grammar": [{"pattern": "S + be + about to + V", "explain": "「即將、正要…」，表示動作馬上就要發生。文章第二段：a dozen eggs were about to hatch.", "example": "The movie is about to start, so please turn off your phone.", "exampleZh": "電影即將開始，請關掉手機。"}, {"pattern": "S + had + p.p.（過去完成式）", "explain": "表示在過去某個時間點之前就已完成的動作，常與另一個過去的時間或動作對照。文章第二段：By noon, three creatures had broken out of their shells, and Hsiao-yu had forgotten about her phone.", "example": "By the time we arrived, the show had already begun.", "exampleZh": "我們到達時，表演已經開始了。"}], "reading": [{"q": "What is the story mainly about?", "options": ["How to raise chickens on a farm", "A girl who learned to love farm life during a summer in Yilan", "The dangers of hawks to farm animals", "Why young people should leave the city"], "answer": 1, "explain": "故事描述小宇在宜蘭農場度過暑假，從無聊到愛上農場生活的轉變，故選 (B)。"}, {"q": "How did Hsiao-yu feel on her first evening at the farm?", "options": ["Excited", "Afraid", "Bored", "Angry"], "answer": 2, "explain": "第一段說她數著離開學還有幾天，可見她覺得無聊，故選 (C)。"}, {"q": "Which of the following did Hsiao-yu NOT learn to do on the farm?", "options": ["Feed the cattle", "Spread fertilizer", "Tell a dragonfly from a damselfly", "Drive a tractor"], "answer": 3, "explain": "第二段列出餵牛、撒肥料、分辨蜻蜓和豆娘，並未提到開曳引機，故選 (D)。"}, {"q": "What did the grandmother mean when she said \"The hawk is hungry, too\"?", "options": ["Hsiao-yu should feed the hawk.", "The hawk is also part of nature and needs to survive.", "The chicks are not worth protecting.", "Hawks are more important than hens."], "answer": 1, "explain": "祖母接著說「這裡的每一個生物都在努力活下去」，表示老鷹也是自然的一部分，故選 (B)。"}, {"q": "What can we infer from the last paragraph?", "options": ["Hsiao-yu never returned to the farm.", "Hsiao-yu's parents were angry about her muddy shoes.", "The summer changed Hsiao-yu's plans for the future.", "The three chicks died soon after."], "answer": 2, "explain": "最後一段說小宇已決定讀農業，可推知這個暑假改變了她對未來的規劃，故選 (C)。"}], "vocabQ": [{"q": "Modern ____ uses machines to plant and harvest crops faster.", "options": ["agriculture", "aquarium", "continent", "canyon"], "answer": 0, "explain": "句意為「現代農業使用機器來更快地種植與收割作物」，agriculture 農業。"}, {"q": "The farmer stores hay for the winter in the ____.", "options": ["cave", "barn", "ditch", "bay"], "answer": 1, "explain": "句意為「農夫把冬天用的乾草儲存在穀倉裡」，barn 穀倉。"}, {"q": "Rivers bring rich mud that makes the land ____.", "options": ["extinct", "fierce", "fertile", "endangered"], "answer": 2, "explain": "句意為「河流帶來肥沃的泥土，讓土地變得肥沃」，fertile 肥沃的。"}, {"q": "Scientists discovered a strange ____ living deep in the cave.", "options": ["feather", "claw", "crop", "creature"], "answer": 3, "explain": "句意為「科學家發現一種奇特的生物生活在洞穴深處」，creature 生物。"}, {"q": "The ____ dived from the sky and caught a small bird.", "options": ["hawk", "duckling", "chick", "dove"], "answer": 0, "explain": "句意為「老鷹從空中俯衝，抓住了一隻小鳥」，hawk 老鷹。"}]}, {"id": "I20", "level": "inter", "num": 20, "title": "Where the Pines Meet the Stars", "titleZh": "松樹與星星相遇之處", "theme": "Nature & Animals", "themeZh": "自然與動物", "article": ["Few places in Taiwan feel as far from the city as the Hehuanshan area after dark. By day, the slopes are crowded with hikers taking photos of the scenery; by night, the trail belongs to the wildlife. The pines stand black against a sky in which thousands of stars twinkle, and the only sounds are the wind and, now and then, the call of an owl hunting from a high branch.", "The wilderness here is home to more species than most visitors imagine. Sambar deer wander across the meadows in small herds, their eyes shining in the moonlight. A squirrel may dart up a trunk at the sound of footsteps, and moths as large as a child's palm gather around any headlamp left on too long. Scientists have recorded over two hundred kinds of birds in the region, including the rare Mikado pheasant, which is found nowhere else on Earth.", "Walking the trail at night requires care. The path is covered with loose pebbles, and the soil on the steeper slopes turns slippery after rain. Some plants with pretty purple petals are poisonous, and the thick webs stretched between the trees belong to spiders that hikers are advised not to touch. Guides remind visitors to follow their map rather than their instinct, because every ridge looks the same in the dark.", "Yet those who make the effort are rewarded at dawn. As the sun rises over the eastern peaks, the Pacific appears as a thin silver line beyond the mountains, and the whole valley fills with birdsong. For a few minutes, before the first tour bus arrives, the mountain seems to belong to no one, or perhaps to everyone. It is a reminder that Taiwan's wildest places are only a few hours from its busiest streets, and that they survive only as long as we leave them untamed."], "translation": ["台灣很少有地方像天黑後的合歡山一帶那樣，感覺離城市如此遙遠。白天，山坡上擠滿拍攝風景的登山客；夜晚，步道則屬於野生動物。松樹在數千顆星星閃爍的天空下顯得一片漆黑，唯一的聲音是風聲，以及不時從高枝上傳來的貓頭鷹獵食的叫聲。", "這片荒野是許多物種的家，數量超乎大多數遊客的想像。水鹿成群結隊地漫步穿過草地，眼睛在月光下閃閃發亮。一隻松鼠可能一聽到腳步聲就竄上樹幹，而像小孩手掌一樣大的飛蛾，會聚集在任何開太久的頭燈周圍。科學家在這個區域記錄了超過兩百種鳥類，包括稀有的帝雉，牠在地球上其他地方都找不到。", "夜晚走這條步道需要小心。路面布滿鬆動的小石子，較陡的山坡上的土壤在雨後會變得濕滑。有些開著漂亮紫色花瓣的植物是有毒的，而樹木之間拉起的厚實蜘蛛網，屬於登山客被建議不要碰的蜘蛛。嚮導提醒遊客要跟著地圖走，而不是憑直覺，因為在黑暗中每一道山脊看起來都一樣。", "然而，願意付出努力的人會在黎明時獲得回報。當太陽從東邊的山峰升起，太平洋在群山之外化為一條細細的銀線，整個山谷充滿了鳥鳴。在第一輛遊覽車抵達之前的那幾分鐘，這座山彷彿不屬於任何人，或許也屬於每一個人。它提醒我們，台灣最荒野的地方離最繁忙的街道只有幾小時的路程，而這些地方只有在我們不去馴服它們的情況下，才能繼續存在。"], "vocab": [{"word": "slope", "pos": "n.", "zh": "斜坡；山坡", "example": "The children rolled down the grassy slope laughing.", "exampleZh": "孩子們笑著從草坡上滾下來。"}, {"word": "scenery", "pos": "n.", "zh": "風景", "example": "The scenery along the Suhua Highway is breathtaking.", "exampleZh": "蘇花公路沿途的風景美得令人屏息。"}, {"word": "wildlife", "pos": "n.", "zh": "野生動物", "example": "The park protects the wildlife that lives in the forest.", "exampleZh": "這座公園保護住在森林裡的野生動物。"}, {"word": "twinkle", "pos": "v.", "zh": "閃爍", "example": "The lights of the city twinkled below us.", "exampleZh": "城市的燈光在我們下方閃爍。"}, {"word": "owl", "pos": "n.", "zh": "貓頭鷹", "example": "An owl hooted somewhere in the dark forest.", "exampleZh": "一隻貓頭鷹在黑暗森林的某處鳴叫。"}, {"word": "wilderness", "pos": "n.", "zh": "荒野", "example": "They spent a week camping in the wilderness without a phone.", "exampleZh": "他們在荒野露營了一週，沒有帶手機。"}, {"word": "species", "pos": "n.", "zh": "物種", "example": "This species of butterfly is found only in Taiwan.", "exampleZh": "這種蝴蝶只在台灣才看得到。"}, {"word": "meadow", "pos": "n.", "zh": "草地；牧草地", "example": "Cows were eating grass quietly in the meadow.", "exampleZh": "牛群在草地上安靜地吃草。"}, {"word": "instinct", "pos": "n.", "zh": "本能；直覺", "example": "Birds fly south in winter by instinct.", "exampleZh": "鳥類憑本能在冬天飛往南方。"}, {"word": "poisonous", "pos": "adj.", "zh": "有毒的", "example": "Do not touch that snake; it is poisonous.", "exampleZh": "不要碰那條蛇，牠有毒。"}], "phrases": [{"phrase": "now and then", "zh": "偶爾；不時", "example": "We still meet for coffee now and then.", "exampleZh": "我們偶爾還會見面喝咖啡。"}, {"phrase": "be home to", "zh": "是…的家；有…棲息", "example": "Taiwan is home to many kinds of butterflies.", "exampleZh": "台灣是許多種蝴蝶的家。"}, {"phrase": "make the effort", "zh": "付出努力", "example": "If you make the effort, you will see the difference.", "exampleZh": "如果你付出努力，你就會看到差別。"}], "grammar": [{"pattern": "S + V + as + adj./adv. + as + N", "explain": "同等比較「和…一樣…」，as 與 as 中間放形容詞或副詞原級。文章第一段：Few places feel as far from the city as the Hehuanshan area；第二段：moths as large as a child's palm.", "example": "This lake is as beautiful as Sun Moon Lake.", "exampleZh": "這座湖和日月潭一樣美。"}, {"pattern": "S + V + as long as + S + V", "explain": "「只要…」，as long as 引導條件子句，表示主要子句的結果必須在此條件下才成立。文章第四段：they survive only as long as we leave them untamed.", "example": "You can borrow my bike as long as you return it by six.", "exampleZh": "只要你六點前還我，就可以借我的腳踏車。"}], "reading": [{"q": "What is the passage mainly about?", "options": ["How to climb Hehuanshan safely in winter", "The beauty and wildlife of Hehuanshan at night", "Why tour buses should be banned from the mountains", "The history of the Mikado pheasant"], "answer": 1, "explain": "全文描述合歡山夜晚的景色與野生動物，並提醒讀者珍惜荒野，故選 (B)。"}, {"q": "According to paragraph 2, which animal is found only in Taiwan?", "options": ["The sambar deer", "The squirrel", "The Mikado pheasant", "The moth"], "answer": 2, "explain": "第二段說稀有的帝雉「在地球上其他地方都找不到」，故選 (C)。"}, {"q": "Why are hikers told to follow their map rather than their instinct?", "options": ["Because the map shows where the spiders are", "Because every ridge looks the same in the dark", "Because the trail is closed at night", "Because their phones do not work"], "answer": 1, "explain": "第三段說「因為在黑暗中每一道山脊看起來都一樣」，故選 (B)。"}, {"q": "The word \"dart\" in paragraph 2 is closest in meaning to ____.", "options": ["sleep", "fall", "hide", "move quickly"], "answer": 3, "explain": "dart 意為「飛奔、急衝」，與 move quickly 最接近，故選 (D)。"}, {"q": "What does the writer suggest in the last sentence?", "options": ["Wild places should be developed for tourists.", "Taiwan's cities are too far from the mountains.", "Wild places survive only if people do not try to control them.", "Tour buses should arrive earlier."], "answer": 2, "explain": "最後一句說這些地方只有在我們不去馴服它們時才能存在，故選 (C)。"}], "vocabQ": [{"q": "The house was built on a steep ____ overlooking the sea.", "options": ["slope", "pit", "shell", "pebble"], "answer": 0, "explain": "句意為「這棟房子建在一個俯瞰大海的陡坡上」，slope 斜坡。"}, {"q": "Tourists come to Taroko for its amazing ____.", "options": ["soil", "scenery", "stem", "web"], "answer": 1, "explain": "句意為「遊客來太魯閣是為了它令人驚嘆的風景」，scenery 風景。"}, {"q": "Some mushrooms are ____, so never eat one you cannot identify.", "options": ["tame", "underwater", "poisonous", "virgin"], "answer": 2, "explain": "句意為「有些蘑菇有毒，所以絕對不要吃你無法辨認的蘑菇」，poisonous 有毒的。"}, {"q": "More than fifty ____ of birds live in this small wetland.", "options": ["species", "herds", "hives", "trails"], "answer": 0, "explain": "句意為「超過五十種鳥類生活在這片小濕地」，species 物種。"}, {"q": "Salmon return to the river where they were born by ____.", "options": ["moonlight", "instinct", "scenery", "wilderness"], "answer": 1, "explain": "句意為「鮭魚憑本能回到牠們出生的河流」，instinct 本能。"}]}, {"id": "I21", "level": "inter", "num": 21, "title": "The Day Our Experiment Went Wrong", "titleZh": "實驗出錯的那一天", "theme": "Science & Measurement", "themeZh": "科學與度量", "article": ["Last Friday, our chemistry class moved from the classroom to the school laboratory for the first time this semester. Ms. Lin, who had worked as a chemist before becoming a teacher, told us that we would test how quickly different powders dissolve in water. Each group was given a small bottle of weak acid, three white compounds, and a worksheet with a formula for calculating the speed of the reaction.", "My partner Kevin and I were confident at first. We had read the chapter twice, and we knew that an accurate result depended on measuring every gram carefully. However, Kevin poured too much powder into the beaker before I had finished weighing it. The mixture bubbled over the edge, and a sweet smell filled the room. Ms. Lin hurried over, but instead of being angry, she laughed and asked us what we thought had happened.", "Through the lens of a magnifying glass, she showed us tiny bubbles that were still forming. The powder contained carbon, she explained, and when it met the acid, it released a gas that we could not see. Every bubble was made of atoms that had been rearranged. Our mistake had actually turned into a small discovery about how fast a reaction can happen when the amounts are wrong.", "By the end of the lesson, we had redone the experiment three times and recorded the results with much greater accuracy. Walking home past the night market, I kept thinking about how electricity, gravity, and even the rice in my dinner are all made of the same tiny building blocks. Science, I realized, is not only something in a textbook; it is happening in every beaker, and in every kitchen, all the time."], "translation": ["上週五，我們的化學課第一次從教室移到學校實驗室上課。林老師在當老師之前曾是一名化學家，她告訴我們，這堂課要測試不同的粉末在水中溶解的速度有多快。每一組都拿到一小瓶弱酸、三種白色化合物，以及一張附有計算反應速率公式的學習單。", "我和搭檔 Kevin 一開始很有信心。我們把那一章讀了兩遍，也知道準確的結果取決於仔細測量每一公克。然而，我還沒秤完，Kevin 就把太多粉末倒進燒杯裡。混合物冒泡溢出杯緣，一股甜甜的味道充滿整間教室。林老師急忙走過來，但她非但沒有生氣，反而笑著問我們覺得發生了什麼事。", "她透過放大鏡的鏡片，讓我們看到仍在不斷形成的微小氣泡。她解釋，粉末裡含有碳，碰到酸的時候，會釋放出一種我們看不見的氣體。每一顆氣泡都是由重新排列過的原子組成的。我們的失誤，竟然變成了一個小小的發現：當用量錯誤時，反應可以發生得多快。", "到了下課前，我們已經把實驗重做了三次，並以高出許多的準確度記錄結果。走路回家經過夜市時，我一直在想，電、重力，甚至我晚餐裡的米飯，全都是由同樣微小的建構單元組成的。我明白了，科學不只是課本裡的東西；它隨時都在每一個燒杯裡、每一間廚房裡發生。"], "vocab": [{"word": "laboratory", "pos": "n.", "zh": "實驗室", "example": "The students put on goggles before entering the laboratory.", "exampleZh": "學生們進實驗室前先戴上護目鏡。"}, {"word": "experiment", "pos": "n.", "zh": "實驗", "example": "The experiment proved that plants need light to grow.", "exampleZh": "這個實驗證明植物需要光才能生長。"}, {"word": "chemist", "pos": "n.", "zh": "化學家", "example": "The chemist mixed two liquids and watched the color change.", "exampleZh": "那位化學家把兩種液體混合，觀察顏色的變化。"}, {"word": "dissolve", "pos": "v.", "zh": "溶解", "example": "Sugar dissolves faster in hot tea than in cold tea.", "exampleZh": "糖在熱茶裡比在冷茶裡溶解得更快。"}, {"word": "acid", "pos": "n.", "zh": "酸", "example": "Lemon juice contains a mild acid that can clean metal.", "exampleZh": "檸檬汁含有一種能清潔金屬的弱酸。"}, {"word": "compound", "pos": "n.", "zh": "化合物", "example": "Water is a compound made of hydrogen and oxygen.", "exampleZh": "水是由氫和氧組成的化合物。"}, {"word": "formula", "pos": "n.", "zh": "公式；配方", "example": "Use this formula to find the area of a circle.", "exampleZh": "用這個公式來求圓的面積。"}, {"word": "accurate", "pos": "adj.", "zh": "準確的", "example": "The weather report was surprisingly accurate this week.", "exampleZh": "這週的天氣預報出乎意料地準確。"}, {"word": "carbon", "pos": "n.", "zh": "碳", "example": "Diamonds and pencil lead are both made of carbon.", "exampleZh": "鑽石和鉛筆芯都是由碳構成的。"}, {"word": "discovery", "pos": "n.", "zh": "發現", "example": "The discovery of penicillin saved millions of lives.", "exampleZh": "青黴素的發現拯救了數百萬人的生命。"}], "phrases": [{"phrase": "at first", "zh": "起初；一開始", "example": "At first I did not like the song, but now I love it.", "exampleZh": "起初我不喜歡這首歌，但現在我很愛。"}, {"phrase": "depend on", "zh": "取決於；依賴", "example": "Whether we go hiking depends on the weather.", "exampleZh": "我們去不去健行取決於天氣。"}, {"phrase": "turn into", "zh": "變成", "example": "The small argument turned into a big fight.", "exampleZh": "小小的爭執變成了一場大吵。"}], "grammar": [{"pattern": "S + had + p.p. ... before + S + V-ed", "explain": "過去完成式（had + 過去分詞）表示在過去某個動作之前已經發生或完成的事。文中 Kevin poured too much powder before I had finished weighing it，強調「我還沒秤完」這件事在倒粉末之前仍在進行。", "example": "The movie had already started before we found our seats.", "exampleZh": "我們找到座位之前，電影就已經開始了。"}, {"pattern": "instead of + V-ing / N", "explain": "instead of 意思是「而不是…」，後面接名詞或動名詞，用來表示「沒有做 A，反而做了 B」。文中 instead of being angry, she laughed 表示老師沒有生氣，反而笑了。", "example": "Instead of taking the bus, we walked to the MRT station.", "exampleZh": "我們沒有搭公車，而是走路到捷運站。"}], "reading": [{"q": "What is the main purpose of the lesson described in the article?", "options": ["To teach students how to use a magnifying glass", "To test how fast different powders dissolve in water", "To show students how electricity is produced", "To compare the weight of three kinds of acid"], "answer": 1, "explain": "第一段提到老師說 we would test how quickly different powders dissolve in water，故選 (B)。"}, {"q": "What mistake did Kevin make during the experiment?", "options": ["He forgot to bring the worksheet.", "He used the wrong formula.", "He added too much powder too early.", "He dropped the bottle of acid."], "answer": 2, "explain": "第二段說 Kevin poured too much powder into the beaker before I had finished weighing it，故選 (C)。"}, {"q": "How did Ms. Lin react when the mixture bubbled over?", "options": ["She became angry and stopped the class.", "She laughed and asked the students to think.", "She told the students to leave the laboratory.", "She redid the experiment by herself."], "answer": 1, "explain": "第二段提到 instead of being angry, she laughed and asked us what we thought had happened，故選 (B)。"}, {"q": "The word \"released\" in paragraph 3 is closest in meaning to ______.", "options": ["gave off", "took in", "measured", "cooled"], "answer": 0, "explain": "released 在文中指粉末碰到酸「釋放出」氣體，與 gave off（發出、釋放）意思最接近，故選 (A)。"}, {"q": "What can be inferred about the writer at the end of the article?", "options": ["He thinks science is boring outside the classroom.", "He plans to become a chemist like Ms. Lin.", "He now sees science as part of everyday life.", "He is still upset about the mistake."], "answer": 2, "explain": "最後一段寫到 Science is not only something in a textbook; it is happening in every beaker, and in every kitchen，可推知作者體會到科學存在於日常生活中，故選 (C)。"}], "vocabQ": [{"q": "Scientists wear special gloves when they work with a strong ____ that can burn the skin.", "options": ["acid", "carbon", "formula", "discovery"], "answer": 0, "explain": "句意為「科學家處理會灼傷皮膚的強酸時要戴特殊手套」，acid 酸。"}, {"q": "Please give me the ____ address of the museum so that I can find it on the map.", "options": ["chemical", "accurate", "nuclear", "experimental"], "answer": 1, "explain": "句意為「請給我博物館準確的地址，好讓我在地圖上找到它」，accurate 準確的。"}, {"q": "The salt will ____ completely if you keep stirring the soup.", "options": ["calculate", "classify", "dissolve", "absorb"], "answer": 2, "explain": "句意為「如果你繼續攪拌，鹽會完全溶解在湯裡」，dissolve 溶解。"}, {"q": "The ____ of a new planet made the headlines around the world.", "options": ["laboratory", "compound", "chemist", "discovery"], "answer": 3, "explain": "句意為「發現一顆新行星的消息登上了全球頭條」，discovery 發現。"}, {"q": "Our teacher asked us to repeat the ____ at home and write down the results.", "options": ["experiment", "gravity", "atom", "digit"], "answer": 0, "explain": "句意為「老師要我們在家重做這個實驗並記錄結果」，experiment 實驗。"}]}, {"id": "I22", "level": "inter", "num": 22, "title": "Students Catch a Red Moon from the School Roof", "titleZh": "學生在學校屋頂捕捉紅月亮", "theme": "Science & Measurement", "themeZh": "科學與度量", "article": ["TAIPEI - More than eighty students stayed at school until midnight last Saturday, but not to study for exams. The astronomy club of Linkou Senior High School had set up three telescopes on the roof so that members could watch a total lunar eclipse, a phenomenon that will not be visible again from Taiwan for another two years.", "According to club adviser Mr. Chen, a former physicist who now teaches earth science, the eclipse happens when the Earth moves directly between the Sun and the Moon. 'The Moon does not produce its own light; it only reflects solar rays,' he explained to the crowd. 'When our planet blocks that light, the Moon slowly turns a deep red.' Students recorded the color every ten minutes, and their observation sheets will be sent to a research team at National Central University.", "For many members, the night was their first chance to use scientific equipment outside a classroom. Second-year student Amy Wu said she had always believed the theory that the Moon's orbit was a perfect circle. 'Mr. Chen showed us that it is actually slightly oval, and that is why the Moon sometimes looks bigger,' she said. Another student attached a smartphone to the telescope to photograph the surface structure of the Moon, including craters several hundred meters deep.", "The club plans to hold a similar event in December, when a spacecraft launched by Japan is expected to pass close to the Moon. Mr. Chen hopes the activities will stimulate more interest in science. 'A cold roof at midnight may not sound exciting,' he said, 'but once you have seen the sky through a telescope, you never look at it the same way again.'"], "translation": ["臺北訊－上週六，八十多名學生在學校待到午夜，但不是為了準備考試。林口高中天文社在屋頂架設了三架望遠鏡，讓社員能觀賞月全食；這種現象要再過兩年才會再次在臺灣看得到。", "社團指導老師陳老師曾是物理學家，現在教地球科學。據他表示，月食發生在地球剛好移動到太陽與月球之間的時候。他向群眾解釋：「月球本身不會發光，它只是反射太陽光線。當我們的星球擋住那道光，月球就會慢慢變成深紅色。」學生每十分鐘記錄一次顏色，而他們的觀測紀錄表將寄給國立中央大學的研究團隊。", "對許多社員來說，那一晚是他們第一次在教室以外使用科學儀器。高二學生吳艾咪說，她一直相信月球軌道是完美圓形的理論。她說：「陳老師讓我們看到它其實略呈橢圓，這就是為什麼月亮有時看起來比較大。」另一名學生把智慧型手機接在望遠鏡上，拍下月球的表面構造，包括好幾百公尺深的隕石坑。", "天文社計畫在十二月舉辦類似活動，屆時日本發射的太空船預計會近距離飛越月球。陳老師希望這些活動能激發更多人對科學的興趣。他說：「午夜冰冷的屋頂聽起來也許不刺激，但一旦你透過望遠鏡看過天空，你就再也不會用同樣的眼光看它了。」"], "vocab": [{"word": "lunar", "pos": "adj.", "zh": "月亮的", "example": "The Lunar New Year is the most important holiday in Taiwan.", "exampleZh": "農曆新年是臺灣最重要的節日。"}, {"word": "telescope", "pos": "n.", "zh": "望遠鏡", "example": "With a telescope, you can see the rings of Saturn.", "exampleZh": "用望遠鏡可以看到土星的環。"}, {"word": "phenomenon", "pos": "n.", "zh": "現象", "example": "A rainbow is a natural phenomenon caused by sunlight and rain.", "exampleZh": "彩虹是由陽光和雨水造成的自然現象。"}, {"word": "physicist", "pos": "n.", "zh": "物理學家", "example": "The physicist explained how a roller coaster stays on its track.", "exampleZh": "那位物理學家解釋雲霄飛車如何停留在軌道上。"}, {"word": "reflect", "pos": "v.", "zh": "反射", "example": "The calm lake reflected the mountains perfectly.", "exampleZh": "平靜的湖面完美地倒映出群山。"}, {"word": "solar", "pos": "adj.", "zh": "太陽的", "example": "Many houses in Tainan now use solar panels on their roofs.", "exampleZh": "臺南現在有很多房子在屋頂裝太陽能板。"}, {"word": "observation", "pos": "n.", "zh": "觀察；觀測", "example": "Careful observation helped the nurse notice the problem early.", "exampleZh": "仔細的觀察幫助護理師及早發現問題。"}, {"word": "orbit", "pos": "n.", "zh": "軌道", "example": "The satellite will stay in orbit for about ten years.", "exampleZh": "這顆衛星將在軌道上停留約十年。"}, {"word": "structure", "pos": "n.", "zh": "結構；構造", "example": "The structure of the bridge was checked after the earthquake.", "exampleZh": "地震後，橋梁的結構接受了檢查。"}, {"word": "stimulate", "pos": "v.", "zh": "刺激；激發", "example": "Reading stories can stimulate a child's imagination.", "exampleZh": "閱讀故事可以激發孩子的想像力。"}], "phrases": [{"phrase": "set up", "zh": "架設；設立", "example": "The volunteers set up tents before the typhoon arrived.", "exampleZh": "志工們在颱風來臨前架好了帳篷。"}, {"phrase": "according to", "zh": "根據", "example": "According to the news, the MRT will close early tonight.", "exampleZh": "根據新聞報導，捷運今晚會提早收班。"}, {"phrase": "the same way", "zh": "同樣的方式", "example": "After the trip, I never looked at the ocean the same way.", "exampleZh": "那次旅行之後，我再也不用同樣的眼光看海洋了。"}], "grammar": [{"pattern": "S + V ... so that + S + can / could + V", "explain": "so that 引導目的副詞子句，表示「以便、為了讓…」，子句中常搭配 can、could、will、would 等助動詞。文中 had set up three telescopes so that members could watch 說明架設望遠鏡的目的。", "example": "She saved money so that she could buy a new bike.", "exampleZh": "她存錢是為了能買一輛新腳踏車。"}, {"pattern": "once + S + V, S + V", "explain": "once 當連接詞時意思是「一旦…就…」，引導時間或條件副詞子句，後面的主要子句說明結果。文中 once you have seen the sky through a telescope, you never look at it the same way 即為此用法。", "example": "Once you learn to ride a bike, you never forget how.", "exampleZh": "一旦你學會騎腳踏車，就永遠不會忘記。"}], "reading": [{"q": "What is this article mainly about?", "options": ["A new science building at a senior high school", "A school club watching a lunar eclipse together", "A spacecraft that will be launched by Japan", "The career of a physicist who became a teacher"], "answer": 1, "explain": "全文報導林口高中天文社在屋頂觀賞月全食的活動，故選 (B)。"}, {"q": "According to Mr. Chen, why does the Moon turn red during an eclipse?", "options": ["The Moon produces red light of its own.", "The Sun moves between the Earth and the Moon.", "The Earth blocks the sunlight the Moon normally reflects.", "The telescope changes the color of the image."], "answer": 2, "explain": "第二段說 When our planet blocks that light, the Moon slowly turns a deep red，故選 (C)。"}, {"q": "What did Amy Wu learn during the event?", "options": ["The Moon's orbit is not a perfect circle.", "The Moon is several hundred meters wide.", "The eclipse happens every two years.", "A smartphone can replace a telescope."], "answer": 0, "explain": "第三段 Amy 說 Mr. Chen showed us that it is actually slightly oval，說明月球軌道並非正圓，故選 (A)。"}, {"q": "The word \"stimulate\" in paragraph 4 is closest in meaning to ______.", "options": ["reduce", "measure", "encourage", "record"], "answer": 2, "explain": "stimulate 在文中指「激發」學生對科學的興趣，與 encourage（鼓勵、促進）意思最接近，故選 (C)。"}, {"q": "What will happen to the students' observation sheets?", "options": ["They will be displayed on the school roof.", "They will be sent to a university research team.", "They will be printed in a Japanese magazine.", "They will be used in the December exam."], "answer": 1, "explain": "第二段提到 their observation sheets will be sent to a research team at National Central University，故選 (B)。"}], "vocabQ": [{"q": "The ____ calendar is based on the movements of the Moon rather than the Sun.", "options": ["solar", "lunar", "nuclear", "magnetic"], "answer": 1, "explain": "句意為「陰曆是根據月亮而非太陽的運行」，lunar 月亮的。"}, {"q": "A mirror can ____ light, which is why a dark room looks brighter with one.", "options": ["weigh", "multiply", "subtract", "reflect"], "answer": 3, "explain": "句意為「鏡子能反射光線，所以暗房間有鏡子會顯得亮一些」，reflect 反射。"}, {"q": "Thousands of people gathered to watch the rare ____ of a double rainbow.", "options": ["phenomenon", "structure", "mixture", "substance"], "answer": 0, "explain": "句意為「數千人聚集觀看雙彩虹這種罕見現象」，phenomenon 現象。"}, {"q": "Coffee can ____ the brain, so many students drink it before an exam.", "options": ["survey", "stimulate", "orbit", "research"], "answer": 1, "explain": "句意為「咖啡能刺激大腦，所以很多學生考前會喝」，stimulate 刺激。"}, {"q": "The young ____ won a prize for her study of how light bends around stars.", "options": ["naturalist", "psychologist", "physicist", "chemist"], "answer": 2, "explain": "句意為「這位年輕物理學家以光線如何在恆星周圍彎曲的研究獲獎」，physicist 物理學家。"}]}, {"id": "I23", "level": "inter", "num": 23, "title": "An Email to Grandpa about His Old Typewriter", "titleZh": "寫給爺爺的一封信：關於他的老打字機", "theme": "Technology & Communication", "themeZh": "科技與通訊", "article": ["Dear Grandpa, thank you for the old typewriter you sent me last week. When the parcel arrived, Mom could not stop smiling, because it was the same machine she used to write her college essays on. I have cleaned every key, and it still works perfectly. Pressing the keys feels completely different from tapping on a keyboard; each letter makes a satisfying click, and there is no delete button, so I have to think before I type!", "You asked how my new laptop is going. Honestly, it took me a whole afternoon to install the software I needed for school. The Wi-Fi connection in my room is weak, so I had to sit next to the router in the living room, plugged into the wall socket because the battery runs out so quickly. The school now puts every assignment on a digital platform, and we are expected to upload a file before midnight. If the signal drops at 11:59, the version you were working on is simply gone. That has happened to me twice.", "Still, I know technology has made many things easier. I can browse the library catalog from my phone, attach a photo of my homework to a message, and connect with my cousins in Canada through a video call. Dad says you once sent a telegram to Grandma to ask her out, and it cost you a week's pocket money. These days a text costs nothing, but maybe that is why people do not choose their words as carefully.", "I have attached a photo of the typewriter sitting next to my laptop. The old and the new look good together, don't they? I will bring it with me when we visit during the Mid-Autumn Festival, and you can teach me how to change the ribbon. Love, Yu-ting"], "translation": ["親愛的爺爺，謝謝您上週寄給我的老打字機。包裹送到的時候，媽媽笑得合不攏嘴，因為那正是她大學時用來寫報告的同一台機器。我把每一個按鍵都清乾淨了，它還是運作得很好。按打字機的鍵，感覺跟敲鍵盤完全不一樣；每打一個字母都會發出令人滿足的喀噠聲，而且沒有刪除鍵，所以我打字之前必須先想清楚！", "您問我的新筆電用得怎麼樣。老實說，光是安裝學校需要的軟體就花了我一整個下午。我房間的 Wi-Fi 連線很弱，所以我得坐在客廳的路由器旁邊，還要插著牆上的插座，因為電池耗電太快了。學校現在把每一份作業都放在數位平台上，要求我們在午夜前上傳檔案。要是訊號在 11 點 59 分斷掉，你正在編輯的版本就直接不見了。這種事我已經遇過兩次。", "不過，我知道科技讓很多事情變得更容易。我可以用手機瀏覽圖書館的目錄、把作業的照片附在訊息裡、透過視訊和加拿大的表哥表姊聯繫。爸爸說您以前曾發電報約奶奶出去，花掉了您一整個星期的零用錢。現在傳一則訊息不用錢，但也許正因如此，人們才不會那麼謹慎地挑選用字。", "我附上了一張打字機和筆電並排的照片。新舊放在一起看起來很搭，不是嗎？中秋節回去看您的時候我會把它帶著，您可以教我怎麼換色帶。愛您的 郁婷"], "vocab": [{"word": "typewriter", "pos": "n.", "zh": "打字機", "example": "My grandmother still keeps her typewriter in the study.", "exampleZh": "我奶奶還把她的打字機放在書房裡。"}, {"word": "parcel", "pos": "n.", "zh": "包裹", "example": "The post office called to say my parcel had arrived.", "exampleZh": "郵局打電話來說我的包裹到了。"}, {"word": "keyboard", "pos": "n.", "zh": "鍵盤", "example": "Some keys on my keyboard stopped working after I spilled tea on it.", "exampleZh": "我把茶灑在鍵盤上之後，有幾個鍵就壞了。"}, {"word": "delete", "pos": "v.", "zh": "刪除", "example": "Be careful not to delete the wrong file.", "exampleZh": "小心不要刪錯檔案。"}, {"word": "install", "pos": "v.", "zh": "安裝", "example": "It only takes a minute to install the app on your phone.", "exampleZh": "在手機上安裝這個應用程式只要一分鐘。"}, {"word": "software", "pos": "n.", "zh": "軟體", "example": "The school bought new software for teaching math.", "exampleZh": "學校買了新的數學教學軟體。"}, {"word": "connection", "pos": "n.", "zh": "連線；連接", "example": "The video kept stopping because of the poor connection.", "exampleZh": "因為連線不好，影片一直停頓。"}, {"word": "socket", "pos": "n.", "zh": "插座", "example": "There is no free socket in this cafe to charge my phone.", "exampleZh": "這間咖啡店沒有空的插座可以幫我的手機充電。"}, {"word": "digital", "pos": "adj.", "zh": "數位的", "example": "Most students now read digital textbooks on tablets.", "exampleZh": "現在大多數學生都在平板上閱讀數位教科書。"}, {"word": "signal", "pos": "n.", "zh": "訊號", "example": "There is no phone signal inside the mountain tunnel.", "exampleZh": "山區隧道裡沒有手機訊號。"}], "phrases": [{"phrase": "run out", "zh": "用完；耗盡", "example": "My phone battery always runs out before lunch.", "exampleZh": "我的手機電池總是在午餐前就沒電。"}, {"phrase": "used to + V", "zh": "過去常常…", "example": "We used to play basketball every Sunday morning.", "exampleZh": "我們以前每個星期天早上都會打籃球。"}, {"phrase": "ask (someone) out", "zh": "邀請某人約會", "example": "He finally found the courage to ask her out.", "exampleZh": "他終於鼓起勇氣約她出去。"}], "grammar": [{"pattern": "It + takes / took + sb + 時間 + to + V", "explain": "此句型表示「某人花了多少時間做某事」，it 是虛主詞，真正的主詞是後面的不定詞片語。文中 it took me a whole afternoon to install the software 即為此用法。", "example": "It took us two hours to finish the puzzle.", "exampleZh": "我們花了兩個小時才完成這幅拼圖。"}, {"pattern": "S + be + expected + to + V", "explain": "be expected to 是被動語態，意思是「被要求、被期望做某事」，常用於說明規定或他人的期待。文中 we are expected to upload a file before midnight 表示學校規定必須在午夜前上傳。", "example": "All students are expected to wear uniforms on Monday.", "exampleZh": "所有學生星期一都必須穿制服。"}], "reading": [{"q": "Why did Mom smile when the parcel arrived?", "options": ["She had been waiting for a new laptop.", "The typewriter was the one she used in college.", "Grandpa had sent her favorite snacks.", "Yu-ting had finally cleaned her room."], "answer": 1, "explain": "第一段提到 it was the same machine she used to write her college essays on，故選 (B)。"}, {"q": "Which of the following is a problem Yu-ting has with her laptop?", "options": ["The screen is too small to read.", "It does not have a delete button.", "The battery does not last long.", "The keyboard makes too much noise."], "answer": 2, "explain": "第二段說 the battery runs out so quickly，故選 (C)。"}, {"q": "The word \"drops\" in paragraph 2 is closest in meaning to ______.", "options": ["falls to the floor", "is cut off", "becomes stronger", "gets louder"], "answer": 1, "explain": "the signal drops 指網路「訊號中斷」，與 is cut off 意思最接近，故選 (B)。"}, {"q": "What does Yu-ting suggest about text messages today?", "options": ["They are more expensive than telegrams.", "People write them more carefully than before.", "They are free, so people may choose words less carefully.", "They take a week to arrive."], "answer": 2, "explain": "第三段末 a text costs nothing, but maybe that is why people do not choose their words as carefully，故選 (C)。"}, {"q": "What will Yu-ting do during the Mid-Autumn Festival?", "options": ["Send Grandpa a photo of her laptop", "Buy a new ribbon online", "Learn from Grandpa how to change the ribbon", "Write a college essay on the typewriter"], "answer": 2, "explain": "最後一段提到 you can teach me how to change the ribbon，故選 (C)。"}], "vocabQ": [{"q": "I accidentally pressed the wrong key and had to ____ half of my report.", "options": ["browse", "delete", "install", "connect"], "answer": 1, "explain": "句意為「我不小心按錯鍵，結果得刪掉半份報告」，delete 刪除。"}, {"q": "The hikers lost the phone ____ as soon as they entered the valley.", "options": ["signal", "socket", "panel", "motor"], "answer": 0, "explain": "句意為「登山客一進入山谷就失去了手機訊號」，signal 訊號。"}, {"q": "Please plug the printer into the ____ behind the desk.", "options": ["keyboard", "software", "socket", "parcel"], "answer": 2, "explain": "句意為「請把印表機插到書桌後面的插座」，socket 插座。"}, {"q": "My cousin mailed me a ____ full of dried mangoes from Tainan.", "options": ["parcel", "leaflet", "telegram", "receiver"], "answer": 0, "explain": "句意為「我表姊從臺南寄給我一個裝滿芒果乾的包裹」，parcel 包裹。"}, {"q": "The ____ camera lets you see your photos right away instead of waiting for film.", "options": ["mechanical", "manual", "postal", "digital"], "answer": 3, "explain": "句意為「數位相機讓你立刻看到照片，不必等底片」，digital 數位的。"}]}, {"id": "I24", "level": "inter", "num": 24, "title": "Diary of a Penghu Summer", "titleZh": "澎湖夏日日記", "theme": "Travel & Transport", "themeZh": "旅遊與交通", "article": ["July 12, Sunday. Our family finally began the journey to Penghu that Dad had been promising since Lunar New Year. We left home at five in the morning, dragging two heavy suitcases down the stairs because the elevator was being repaired. At Budai harbor, the ferry terminal was already crowded with tourists checking the timetable on a big screen. Dad had made a reservation online, so we only had to show our ID cards and climb aboard.", "The crossing took about ninety minutes. My little brother spent the whole time on the upper deck, pointing at every fishing vessel we passed, while Mom stayed inside because the waves made her dizzy. When we reached the dock in Magong, a shuttle bus was waiting to take us to our hostel. The fare was only fifty dollars, and the driver told us which beaches were worth visiting.", "July 13, Monday. Today we rented bikes to explore the island. Wearing helmets in the heat was uncomfortable, but after an hour of pedaling along the coast, I forgot about it. We stopped at a white lighthouse that has guided ships for more than a hundred years. From the top, the sea looked like a sheet of blue glass, and I understood why so many cyclists choose this road.", "Tomorrow is our last day, and our main destination is the morning market, where Mom wants to buy dried squid as souvenirs for our neighbors. Dad says the best part of traveling is not the sightseeing but the moments nobody plans. I think he is right. I will never forget the sunset on the deck tonight, with the whole family quiet for once."], "translation": ["7 月 12 日，星期日。我們一家終於展開了爸爸從農曆新年就一直答應要去的澎湖之旅。我們早上五點出門，因為電梯正在維修，只好拖著兩個沉重的行李箱走樓梯。到了布袋港，渡輪航站已經擠滿了對著大螢幕查看時刻表的遊客。爸爸事先在網路上訂了位，所以我們只需要出示身分證就能上船。", "航程大約九十分鐘。弟弟整段時間都待在上層甲板，指著我們經過的每一艘漁船；媽媽則待在船艙裡，因為海浪讓她頭暈。抵達馬公碼頭時，一輛接駁車正等著載我們去青年旅館。車資只要五十元，司機還告訴我們哪些海灘值得一去。", "7 月 13 日，星期一。今天我們租了腳踏車探索這座島。大熱天戴安全帽很不舒服，但沿著海岸踩了一個小時之後，我就忘了這回事。我們在一座已經為船隻指引方向超過一百年的白色燈塔停下來。從塔頂望出去，大海像一片藍色的玻璃，我終於明白為什麼這麼多自行車騎士選擇這條路。", "明天是最後一天，我們的主要目的地是早市，媽媽想在那裡買魷魚乾當伴手禮送給鄰居。爸爸說旅行最棒的部分不是觀光，而是那些沒有人計畫的時刻。我覺得他說得對。我永遠不會忘記今晚甲板上的夕陽，還有全家人難得一次的安靜。"], "vocab": [{"word": "journey", "pos": "n.", "zh": "旅程", "example": "The journey from Taipei to Kenting takes about six hours by bus.", "exampleZh": "從臺北到墾丁的旅程搭客運大約要六小時。"}, {"word": "suitcase", "pos": "n.", "zh": "行李箱", "example": "She packed her suitcase the night before the flight.", "exampleZh": "她在班機前一晚就把行李箱收拾好了。"}, {"word": "harbor", "pos": "n.", "zh": "港口", "example": "Fishing boats return to the harbor every evening.", "exampleZh": "漁船每天傍晚回到港口。"}, {"word": "timetable", "pos": "n.", "zh": "時刻表", "example": "Check the train timetable before you leave for the station.", "exampleZh": "出發去車站前先查一下火車時刻表。"}, {"word": "reservation", "pos": "n.", "zh": "預訂", "example": "We made a reservation at the hot spring hotel for Saturday.", "exampleZh": "我們預訂了星期六的溫泉飯店。"}, {"word": "deck", "pos": "n.", "zh": "甲板", "example": "Passengers gathered on the deck to watch the dolphins.", "exampleZh": "乘客聚集在甲板上看海豚。"}, {"word": "vessel", "pos": "n.", "zh": "船隻", "example": "A large cargo vessel was waiting outside the port.", "exampleZh": "一艘大型貨船正在港外等候。"}, {"word": "shuttle", "pos": "n.", "zh": "接駁車", "example": "A free shuttle runs between the airport and the hotel.", "exampleZh": "機場和飯店之間有免費接駁車。"}, {"word": "lighthouse", "pos": "n.", "zh": "燈塔", "example": "The old lighthouse on the cliff is now a small museum.", "exampleZh": "懸崖上的老燈塔現在是一間小博物館。"}, {"word": "destination", "pos": "n.", "zh": "目的地", "example": "After a long flight, we finally reached our destination.", "exampleZh": "經過漫長的飛行，我們終於抵達目的地。"}], "phrases": [{"phrase": "be worth + V-ing", "zh": "值得…", "example": "The night market in Keelung is worth visiting.", "exampleZh": "基隆的夜市值得一遊。"}, {"phrase": "point at", "zh": "指著", "example": "The child pointed at the airplane in the sky.", "exampleZh": "小孩指著天空中的飛機。"}, {"phrase": "for once", "zh": "難得一次", "example": "For once, my brother did the dishes without being asked.", "exampleZh": "我弟弟難得一次沒人叫就主動洗碗。"}], "grammar": [{"pattern": "S + had been + V-ing + since / for ...", "explain": "過去完成進行式表示某個動作從過去某時開始，一直持續到過去另一個時間點。文中 the journey that Dad had been promising since Lunar New Year 表示爸爸從農曆新年起就一直承諾要去，直到出發那天。", "example": "They had been waiting for an hour before the bus came.", "exampleZh": "公車來之前，他們已經等了一個小時。"}, {"pattern": "not A but B", "explain": "not A but B 意思是「不是 A，而是 B」，A 與 B 必須是對等的詞性或結構。文中 not the sightseeing but the moments nobody plans，兩者都是名詞片語。", "example": "What matters is not the price but the quality.", "exampleZh": "重要的不是價格，而是品質。"}], "reading": [{"q": "Why did the family carry their suitcases down the stairs?", "options": ["The hotel had no elevator.", "The elevator was being repaired.", "They wanted to exercise before the trip.", "The ferry was about to leave."], "answer": 1, "explain": "第一段提到 because the elevator was being repaired，故選 (B)。"}, {"q": "How did Mom spend the ferry crossing?", "options": ["She stayed inside because she felt dizzy.", "She pointed at fishing boats from the deck.", "She checked the timetable on a screen.", "She talked with the shuttle bus driver."], "answer": 0, "explain": "第二段說 Mom stayed inside because the waves made her dizzy，故選 (A)。"}, {"q": "What is true about the lighthouse?", "options": ["It was built last year.", "It is painted blue.", "It has guided ships for over a century.", "It is closed to cyclists."], "answer": 2, "explain": "第三段提到 a white lighthouse that has guided ships for more than a hundred years，故選 (C)。"}, {"q": "The word \"crossing\" in paragraph 2 refers to ______.", "options": ["the bike ride along the coast", "the trip across the sea by ferry", "the walk through the morning market", "the bus ride to the hostel"], "answer": 1, "explain": "crossing 在此指搭渡輪橫越海面的航程，前文剛提到 climb aboard 上船，故選 (B)。"}, {"q": "According to Dad, what is the best part of traveling?", "options": ["Buying souvenirs for neighbors", "Visiting famous sights", "Riding bikes in the heat", "Unplanned moments with family"], "answer": 3, "explain": "最後一段 Dad says the best part of traveling is not the sightseeing but the moments nobody plans，故選 (D)。"}], "vocabQ": [{"q": "The hotel ____ picks up guests at the high-speed rail station every half hour.", "options": ["shuttle", "lighthouse", "harbor", "deck"], "answer": 0, "explain": "句意為「飯店接駁車每半小時到高鐵站接客人」，shuttle 接駁車。"}, {"q": "Our final ____ was a small village high in the mountains.", "options": ["timetable", "reservation", "destination", "suitcase"], "answer": 2, "explain": "句意為「我們的最終目的地是山上的一個小村莊」，destination 目的地。"}, {"q": "Because of the storm, every ____ in the harbor stayed tied to the dock.", "options": ["journey", "vessel", "passport", "souvenir"], "answer": 1, "explain": "句意為「因為暴風雨，港內每艘船都繫在碼頭上」，vessel 船隻。"}, {"q": "The restaurant is so popular that you need a ____ at least a week ahead.", "options": ["timetable", "lighthouse", "harbor", "reservation"], "answer": 3, "explain": "句意為「這家餐廳太受歡迎，至少要提前一週預訂」，reservation 預訂。"}, {"q": "The new ____ shows that the last train now leaves at 11:30 p.m.", "options": ["timetable", "suitcase", "deck", "journey"], "answer": 0, "explain": "句意為「新的時刻表顯示末班車現在是晚上 11 點 30 分發車」，timetable 時刻表。"}]}, {"id": "I25", "level": "inter", "num": 25, "title": "Ten Minutes Before the Speech", "titleZh": "上台前的十分鐘", "theme": "Feelings & Emotions", "themeZh": "情緒與感受", "article": ["Ten minutes before the English speech contest, Jia-hao was sitting alone behind the school auditorium, staring at his cue cards. His hands were shaking, and the anxiety in his stomach felt like a stone. 'I can't do this,' he whispered when his teacher, Ms. Huang, found him. 'Everyone will laugh when I forget a line.'", "Ms. Huang sat down beside him. 'Do you remember the first time you read aloud in my class?' she asked. 'You blushed so hard that your ears turned red, and you were ashamed for a week. But you didn't stop. You came to every practice, even when the other students were discouraged by the long passages.' Jia-hao looked up. 'That was different. Nobody was watching then.' 'Nobody is watching now,' she said with a cheerful smile. 'They are listening. There is a difference.'", "He was not sure he believed her, but her calm voice was a comfort. When his name was called, he walked onto the stage with more determination than confidence. The first sentence came out too fast. The second was better. By the third paragraph, he noticed a boy in the front row nodding with real curiosity, and something inside him relaxed.", "He did not win. A girl from another class took first prize with a story about her grandmother's night-market stall, and Jia-hao felt a surprising admiration for her rather than envy. Backstage, Ms. Huang handed him a bottle of water. 'Still think you can't do it?' she asked. Jia-hao grinned. For the first time that day, he felt genuinely content."], "translation": ["英語演講比賽開始前十分鐘，家豪獨自坐在學校禮堂後面，盯著他的提示卡。他的手在發抖，胃裡的焦慮感像一塊石頭。老師黃老師找到他時，他低聲說：「我做不到。我一忘詞，大家就會笑我。」", "黃老師在他身旁坐下。她問：「你記得第一次在我課堂上朗讀的情景嗎？你臉紅到連耳朵都紅了，還難為情了一個星期。但你沒有放棄。即使其他同學被長篇文章嚇得失去信心，你還是來參加每一次練習。」家豪抬起頭：「那不一樣，那時候沒有人在看。」「現在也沒有人在看，」她帶著開朗的笑容說，「他們是在聽。這是有差別的。」", "他不確定自己相不相信她，但她平靜的聲音讓他安心。被叫到名字時，他走上舞台，帶著的決心多過信心。第一句講得太快，第二句好一些。到了第三段，他注意到前排有個男孩帶著真正的好奇心點頭，他心裡有什麼東西放鬆了下來。", "他沒有得獎。另一班的一個女生以她奶奶的夜市攤位為題的故事拿下第一名，而家豪對她竟感到一股出乎意料的欽佩，而不是嫉妒。後台，黃老師遞給他一瓶水。「還覺得自己做不到嗎？」她問。家豪咧嘴一笑。那一天，他第一次真正感到心滿意足。"], "vocab": [{"word": "anxiety", "pos": "n.", "zh": "焦慮", "example": "Many students feel anxiety before a big test.", "exampleZh": "很多學生在大考前會感到焦慮。"}, {"word": "blush", "pos": "v.", "zh": "臉紅", "example": "She blushed when the teacher praised her in front of the class.", "exampleZh": "老師在全班面前稱讚她時，她臉紅了。"}, {"word": "ashamed", "pos": "adj.", "zh": "羞愧的；難為情的", "example": "He was ashamed of lying to his parents.", "exampleZh": "他為自己對父母說謊感到羞愧。"}, {"word": "discourage", "pos": "v.", "zh": "使氣餒", "example": "Don't let one bad grade discourage you.", "exampleZh": "別讓一次不好的成績使你氣餒。"}, {"word": "cheerful", "pos": "adj.", "zh": "開朗的；愉快的", "example": "The cheerful nurse made the children laugh.", "exampleZh": "那位開朗的護理師逗得孩子們大笑。"}, {"word": "comfort", "pos": "n.", "zh": "安慰", "example": "Her kind words were a great comfort to me.", "exampleZh": "她親切的話語對我是莫大的安慰。"}, {"word": "determination", "pos": "n.", "zh": "決心", "example": "With determination, she finished the marathon despite the pain.", "exampleZh": "憑著決心，她忍著疼痛跑完了馬拉松。"}, {"word": "confidence", "pos": "n.", "zh": "信心", "example": "Practice gave him the confidence to speak in public.", "exampleZh": "練習讓他有信心在公開場合說話。"}, {"word": "curiosity", "pos": "n.", "zh": "好奇心", "example": "Out of curiosity, the boy opened the old box.", "exampleZh": "出於好奇，那個男孩打開了舊箱子。"}, {"word": "admiration", "pos": "n.", "zh": "欽佩", "example": "The firefighters earned the admiration of the whole town.", "exampleZh": "消防員贏得了全鎮的欽佩。"}], "phrases": [{"phrase": "read aloud", "zh": "朗讀", "example": "The teacher asked me to read the poem aloud.", "exampleZh": "老師要我把那首詩朗讀出來。"}, {"phrase": "come out", "zh": "說出；出來", "example": "The words came out before I could stop them.", "exampleZh": "我還來不及停下來，話就已經說出口了。"}, {"phrase": "rather than", "zh": "而不是", "example": "I would take the MRT rather than drive in the rain.", "exampleZh": "我寧願搭捷運，也不要在雨中開車。"}], "grammar": [{"pattern": "S + V + so + adj. / adv. + that + S + V", "explain": "so ... that 表示「如此…以至於…」，so 後面接形容詞或副詞，that 引導結果子句。文中 You blushed so hard that your ears turned red 說明臉紅的程度和結果。", "example": "The soup was so hot that I burned my tongue.", "exampleZh": "湯太燙了，我燙到了舌頭。"}, {"pattern": "with + more + N + than + N", "explain": "用 with 加名詞片語描述伴隨的狀態，more A than B 表示「A 多於 B」。文中 with more determination than confidence 表示「決心多過信心」，是描寫人物心情的常見寫法。", "example": "She answered the question with more hope than certainty.", "exampleZh": "她回答問題時，希望多過把握。"}], "reading": [{"q": "How did Jia-hao feel at the beginning of the story?", "options": ["Excited and proud", "Nervous and afraid of failing", "Angry at his teacher", "Bored by the contest"], "answer": 1, "explain": "第一段描述 His hands were shaking, and the anxiety in his stomach felt like a stone，以及他說 I can't do this，故選 (B)。"}, {"q": "Why did Ms. Huang mention the first time Jia-hao read aloud?", "options": ["To remind him that he had improved through practice", "To show him that he still made many mistakes", "To explain why he should not enter the contest", "To compare him with the other students"], "answer": 0, "explain": "第二段老師提到他雖然曾經臉紅、難為情，但 you didn't stop. You came to every practice，目的是提醒他已靠努力進步，故選 (A)。"}, {"q": "What did Ms. Huang mean by 'They are listening. There is a difference.'?", "options": ["The audience cannot hear him clearly.", "The audience is there to judge his looks.", "The audience wants to hear his ideas, not to laugh at him.", "The audience is not paying attention."], "answer": 2, "explain": "老師把 watching（看）和 listening（聽）作對比，是要告訴他觀眾在意的是內容而非他的失誤，故選 (C)。"}, {"q": "The word \"content\" in the last paragraph is closest in meaning to ______.", "options": ["disappointed", "satisfied", "confused", "exhausted"], "answer": 1, "explain": "content 當形容詞時意思是「滿足的」，與 satisfied 意思最接近，故選 (B)。"}, {"q": "What can be inferred about Jia-hao's attitude toward the winner?", "options": ["He thought the judges were unfair.", "He was jealous of her story.", "He respected her performance.", "He did not listen to her speech."], "answer": 2, "explain": "最後一段說 Jia-hao felt a surprising admiration for her rather than envy，可推知他敬佩對方，故選 (C)。"}], "vocabQ": [{"q": "Little children are full of ____ and ask questions about everything they see.", "options": ["curiosity", "anxiety", "cruelty", "confusion"], "answer": 0, "explain": "句意為「小孩充滿好奇心，對看到的每樣東西都提問」，curiosity 好奇心。"}, {"q": "The coach's words of ____ helped the team calm down after the loss.", "options": ["despair", "disgust", "comfort", "ambition"], "answer": 2, "explain": "句意為「教練安慰的話幫助球隊在輸球後平靜下來」，comfort 安慰。"}, {"q": "Even heavy rain could not ____ the fans from waiting outside the stadium.", "options": ["amuse", "blush", "cherish", "discourage"], "answer": 3, "explain": "句意為「連大雨也無法讓球迷放棄在體育場外等候」，discourage 使氣餒。"}, {"q": "After months of practice, the young pianist played with great ____ on stage.", "options": ["depression", "confidence", "disapproval", "cruelty"], "answer": 1, "explain": "句意為「經過數月練習，年輕鋼琴家在台上充滿信心地演奏」，confidence 信心。"}, {"q": "My grandfather is always ____ in the morning, singing while he makes breakfast.", "options": ["ashamed", "anxious", "cheerful", "desperate"], "answer": 2, "explain": "句意為「我爺爺早上總是很開朗，一邊做早餐一邊唱歌」，cheerful 開朗的。"}]}, {"id": "I26", "level": "inter", "num": 26, "title": "Thank You for the Laughter: A Graduation Speech", "titleZh": "謝謝那些笑聲：一篇畢業演講", "theme": "Feelings & Emotions", "themeZh": "情緒與感受", "article": ["Good morning, teachers, parents, and fellow graduates. Three years ago, I walked through the front gate of this school as a nervous twelve-year-old who did not know a single person. I remember the loneliness of that first week clearly: eating lunch by myself and pretending to read. I would never have guessed that I would be standing here today, trying not to become too emotional in front of all of you.", "What changed everything was kindness, and it came from people in this room. Mr. Lai, our homeroom teacher, noticed that I was eating alone and quietly asked two classmates to invite me to join their science project. Those two classmates, Mei-ling and Daniel, are now my closest friends. Their enthusiasm for building a small robot was so contagious that I became fascinated by engineering, a subject I had never cared about. I am eager to study it in senior high, and that dream began with a single invitation.", "I am also grateful for the laughter. Nobody will forget the day the sports fair was rained out and the whole grade had a dance contest in the hallway instead. Our teachers, who might have frowned at the noise, joined in. I think that is my deepest impression of this school: adults who treated us with patience when we were impatient, and with encouragement when we were frustrated.", "So, on behalf of the graduating class, I want to express our gratitude. To our parents, thank you for the early-morning breakfasts and the late-night rides home. To our teachers, thank you for believing in us before we believed in ourselves. We leave this school hopeful, a little sentimental, and very, very thankful. Congratulations, everyone."], "translation": ["各位老師、家長和畢業生同學，早安。三年前，我走進這所學校的大門時，是一個緊張的十二歲孩子，一個人也不認識。我清楚記得第一週的孤單：自己一個人吃午餐，假裝在看書。我從來沒想過，今天會站在這裡，努力不在各位面前太激動。", "改變一切的是善意，而它來自這個禮堂裡的人。我們的導師賴老師注意到我一個人吃飯，便悄悄請兩位同學邀我加入他們的科學專題。那兩位同學，美玲和 Daniel，現在是我最要好的朋友。他們對製作小機器人的熱情很有感染力，讓我對工程這個我以前從不在乎的科目著了迷。我迫不及待想在高中繼續學習它，而這個夢想，始於一句簡單的邀請。", "我也感謝那些笑聲。沒有人會忘記運動會因雨取消、全年級改在走廊舉辦舞蹈比賽的那一天。本來可能會對吵鬧聲皺眉頭的老師們，也一起加入了。我想，這就是這所學校給我最深刻的印象：當我們不耐煩時，大人們以耐心對待我們；當我們受挫時，他們給予鼓勵。", "所以，我要代表全體畢業生表達我們的感謝。謝謝我們的父母，謝謝那些清晨的早餐和深夜的接送。謝謝我們的老師，在我們相信自己之前就先相信了我們。我們帶著希望、一點點感傷，以及滿滿的感激離開這所學校。恭喜大家。"], "vocab": [{"word": "loneliness", "pos": "n.", "zh": "孤單；寂寞", "example": "Moving to a new city brought him a sense of loneliness.", "exampleZh": "搬到新城市讓他感到一陣孤單。"}, {"word": "emotional", "pos": "adj.", "zh": "情緒激動的；情感的", "example": "The farewell at the airport was very emotional.", "exampleZh": "機場的道別場面非常令人動容。"}, {"word": "kindness", "pos": "n.", "zh": "善意；仁慈", "example": "A stranger's kindness helped me find my way in Tokyo.", "exampleZh": "一位陌生人的善意幫助我在東京找到路。"}, {"word": "enthusiasm", "pos": "n.", "zh": "熱情", "example": "The new coach brought a lot of enthusiasm to the team.", "exampleZh": "新教練為球隊帶來了許多熱情。"}, {"word": "fascinated", "pos": "adj.", "zh": "著迷的", "example": "The children were fascinated by the magician's tricks.", "exampleZh": "孩子們被魔術師的把戲深深吸引。"}, {"word": "eager", "pos": "adj.", "zh": "渴望的；熱切的", "example": "The puppy was eager to go outside and play.", "exampleZh": "小狗迫不及待想出去玩。"}, {"word": "grateful", "pos": "adj.", "zh": "感激的", "example": "I am grateful for all the help you gave me this year.", "exampleZh": "我很感激你今年給我的一切幫助。"}, {"word": "laughter", "pos": "n.", "zh": "笑聲", "example": "Laughter filled the room when the baby made a funny face.", "exampleZh": "嬰兒做鬼臉時，房間裡充滿了笑聲。"}, {"word": "impression", "pos": "n.", "zh": "印象", "example": "The clean streets of Kyoto left a deep impression on me.", "exampleZh": "京都乾淨的街道給我留下深刻的印象。"}, {"word": "gratitude", "pos": "n.", "zh": "感激之情", "example": "She wrote a card to show her gratitude to the doctor.", "exampleZh": "她寫了一張卡片向醫生表達感激之情。"}], "phrases": [{"phrase": "on behalf of", "zh": "代表", "example": "The captain accepted the trophy on behalf of the team.", "exampleZh": "隊長代表球隊接受獎盃。"}, {"phrase": "join in", "zh": "加入；參與", "example": "Everyone was invited to join in the singing.", "exampleZh": "大家都被邀請一起加入歌唱。"}, {"phrase": "believe in", "zh": "相信；信任", "example": "My parents always believed in me, even when I failed.", "exampleZh": "即使我失敗了，父母也始終相信我。"}], "grammar": [{"pattern": "What + S + V ... + was / is + N", "explain": "what 引導的名詞子句可以當主詞，意思是「…的事物」，用來強調句子後半的重點。文中 What changed everything was kindness 把「改變一切的東西」放在句首，再揭曉答案是善意。", "example": "What I need most now is a good night's sleep.", "exampleZh": "我現在最需要的是好好睡一覺。"}, {"pattern": "S + might have + p.p.", "explain": "might have + 過去分詞用來推測過去「可能發生但實際上沒有發生」的事。文中 who might have frowned at the noise 表示老師們原本可能會皺眉，但實際上他們反而加入了。", "example": "Without your help, I might have missed the last train.", "exampleZh": "沒有你的幫忙，我可能就錯過末班車了。"}], "reading": [{"q": "What is the speaker's main purpose in giving this speech?", "options": ["To complain about the school's rules", "To thank the people who shaped his school years", "To introduce the school's robot team", "To explain why he was lonely in the first week"], "answer": 1, "explain": "演講最後一段明確表示 I want to express our gratitude，全文都在感謝老師、家長與同學，故選 (B)。"}, {"q": "How did Mr. Lai help the speaker?", "options": ["He gave him extra lessons in science.", "He ate lunch with him every day.", "He asked two students to invite him to their project.", "He told him to stop reading at lunch."], "answer": 2, "explain": "第二段提到 Mr. Lai ... quietly asked two classmates to invite me to join their science project，故選 (C)。"}, {"q": "The word \"contagious\" in paragraph 2 is closest in meaning to ______.", "options": ["dangerous", "easily spread to others", "difficult to understand", "quickly forgotten"], "answer": 1, "explain": "contagious 原指會傳染的，文中形容熱情「有感染力、會傳給別人」，故選 (B)。"}, {"q": "What happened on the day of the sports fair?", "options": ["The teachers cancelled all classes.", "The students held a dance contest indoors because of rain.", "The speaker won a prize for dancing.", "The whole grade went home early."], "answer": 1, "explain": "第三段說 the sports fair was rained out and the whole grade had a dance contest in the hallway instead，故選 (B)。"}, {"q": "Which word best describes the tone of the last paragraph?", "options": ["Thankful", "Angry", "Humorous", "Doubtful"], "answer": 0, "explain": "最後一段連續向父母和老師說 thank you，並以 very, very thankful 作結，語氣充滿感激，故選 (A)。"}], "vocabQ": [{"q": "The audience showed great ____ for the band and sang along to every song.", "options": ["loneliness", "enthusiasm", "grief", "guilt"], "answer": 1, "explain": "句意為「觀眾對樂團表現出極大的熱情，每首歌都跟著唱」，enthusiasm 熱情。"}, {"q": "We are ____ to the volunteers who cleaned the beach after the typhoon.", "options": ["furious", "envious", "grateful", "impatient"], "answer": 2, "explain": "句意為「我們很感激颱風過後清理海灘的志工」，grateful 感激的。"}, {"q": "Wear something neat for the interview; you only get one chance to make a good first ____.", "options": ["impression", "excitement", "hatred", "laughter"], "answer": 0, "explain": "句意為「面試穿整齊一點，給人好的第一印象只有一次機會」，impression 印象。"}, {"q": "The old man said that a small act of ____ can change someone's whole day.", "options": ["horror", "fright", "jealousy", "kindness"], "answer": 3, "explain": "句意為「老人說一個小小的善舉能改變某人的一整天」，kindness 善意。"}, {"q": "The students were ____ to hear the results and crowded around the notice board.", "options": ["dreadful", "eager", "emotional", "frightened"], "answer": 1, "explain": "句意為「學生們迫不及待想知道結果，擠在公布欄前」，eager 渴望的。"}]}, {"id": "I27", "level": "inter", "num": 27, "title": "Four Ways to Beat Exam Pressure", "titleZh": "戰勝考試壓力的四個方法", "theme": "Feelings & Emotions", "themeZh": "情緒與感受", "article": ["Exam week is coming, and if you are like most senior high students in Taiwan, you probably feel the pressure building already. Your shoulders are tense, you lie awake at night, and the thought of the mock test is turning into a nightmare. The good news is that stress itself is not your enemy; too much of it is. Here are four ways to keep it under control.", "First, make a plan you can actually follow. Students often panic because the amount of material looks endless. Break each subject into thirty-minute blocks and tick them off one by one. The sense of satisfaction from finishing a block is a stronger motivation than any scary warning from a teacher. Second, protect your sleep. A restless night does more harm than an extra hour of cramming, and a tired brain is a pessimistic brain that sees every question as impossible.", "Third, move your body. A twenty-minute walk around the block, a few stretches between chapters, or even dancing to one song will relax muscles that have been tight for hours. Many students report an immediate sense of relief after exercise, and the improved mood usually lasts into the next study session.", "Finally, talk to someone. If you feel miserable or find yourself losing your temper over small things, tell a friend, a parent, or a counselor. A sympathetic listener cannot take the exam for you, but sharing a worry often cuts it in half. Remember that your worth is not measured by a single score. Be patient with yourself, treat your mind with the same warmth you would offer a friend, and the pressure will become something you can carry, not something that carries you."], "translation": ["考試週就要到了，如果你和臺灣大多數高中生一樣，大概已經感覺到壓力在累積。你的肩膀很緊繃，晚上躺著睡不著，一想到模擬考就像一場惡夢。好消息是，壓力本身不是你的敵人；過多的壓力才是。以下是四個讓壓力受控的方法。", "第一，訂一個你真的做得到的計畫。學生常常恐慌，是因為要讀的東西看起來沒完沒了。把每一科切成三十分鐘的區塊，一塊一塊打勾完成。完成一個區塊帶來的滿足感，比老師任何可怕的警告都更能激發動力。第二，保護你的睡眠。一個輾轉難眠的夜晚，比多熬一小時死背造成的傷害更大；疲倦的大腦是悲觀的大腦，會覺得每一題都不可能。", "第三，動一動身體。繞著街區走二十分鐘、讀完一章後做幾個伸展，甚至隨著一首歌跳舞，都能放鬆緊繃了好幾小時的肌肉。許多學生表示運動後立刻感到如釋重負，而變好的心情通常能延續到下一段讀書時間。", "最後，找人聊聊。如果你覺得很痛苦，或發現自己因為小事就發脾氣，告訴朋友、家長或輔導老師。一個有同理心的傾聽者無法替你考試，但把煩惱說出來往往能讓它減半。記住，你的價值不是由一個分數決定的。對自己有耐心，用你會給朋友的那份溫暖來對待自己的心，壓力就會變成你扛得起的東西，而不是把你壓垮的東西。"], "vocab": [{"word": "pressure", "pos": "n.", "zh": "壓力", "example": "Athletes often perform well under pressure.", "exampleZh": "運動員在壓力下常常表現得很好。"}, {"word": "tense", "pos": "adj.", "zh": "緊繃的；緊張的", "example": "The room was tense as the judges announced the winner.", "exampleZh": "評審宣布得獎者時，房間裡氣氛緊張。"}, {"word": "nightmare", "pos": "n.", "zh": "惡夢", "example": "Getting lost in the typhoon was a nightmare for the hikers.", "exampleZh": "在颱風中迷路對登山客來說是一場惡夢。"}, {"word": "panic", "pos": "v.", "zh": "恐慌", "example": "Don't panic if the fire alarm rings; walk calmly to the exit.", "exampleZh": "火災警報響時別慌，冷靜走向出口。"}, {"word": "satisfaction", "pos": "n.", "zh": "滿足感", "example": "Finishing the puzzle gave her a deep sense of satisfaction.", "exampleZh": "完成拼圖讓她有深深的滿足感。"}, {"word": "motivation", "pos": "n.", "zh": "動力；動機", "example": "Winning a scholarship was his main motivation for studying hard.", "exampleZh": "拿獎學金是他用功讀書的主要動力。"}, {"word": "restless", "pos": "adj.", "zh": "坐立不安的；睡不安穩的", "example": "The children grew restless after waiting for an hour.", "exampleZh": "等了一小時後，孩子們開始坐立不安。"}, {"word": "pessimistic", "pos": "adj.", "zh": "悲觀的", "example": "Try not to be so pessimistic about the result.", "exampleZh": "別對結果那麼悲觀。"}, {"word": "relief", "pos": "n.", "zh": "寬慰；解脫", "example": "It was a relief to hear that everyone was safe.", "exampleZh": "聽到大家都平安，真是鬆了一口氣。"}, {"word": "sympathetic", "pos": "adj.", "zh": "有同情心的；體諒的", "example": "The sympathetic doctor listened to every worry I had.", "exampleZh": "那位體貼的醫生聽我說完每一個擔憂。"}], "phrases": [{"phrase": "under control", "zh": "受到控制", "example": "The firefighters soon had the fire under control.", "exampleZh": "消防員很快就控制住了火勢。"}, {"phrase": "one by one", "zh": "一個接一個", "example": "The students entered the exam room one by one.", "exampleZh": "學生一個接一個走進考場。"}, {"phrase": "lose one's temper", "zh": "發脾氣", "example": "Dad rarely loses his temper, even in traffic jams.", "exampleZh": "爸爸很少發脾氣，就算塞車也一樣。"}], "grammar": [{"pattern": "If + S + V (現在式), (please) + 原形動詞 ...", "explain": "條件句中 if 子句用現在式表示未來可能的情況，主要子句用祈使句給予建議或指示。文中 If you feel miserable ..., tell a friend 是典型的「如果…，就…」建議句型。", "example": "If you feel sick during the test, raise your hand.", "exampleZh": "如果考試時覺得不舒服，就舉手。"}, {"pattern": "V-ing + (O) + V (單數) ...", "explain": "動名詞片語可以當句子的主詞，視為單數，後面動詞用單數。文中 sharing a worry often cuts it in half 以「分享煩惱」這個動作當主詞。", "example": "Walking to school every day keeps me healthy.", "exampleZh": "每天走路上學讓我保持健康。"}], "reading": [{"q": "Who is this article mainly written for?", "options": ["Teachers who give mock tests", "Parents of young children", "Students facing exam stress", "Doctors who treat sleep problems"], "answer": 2, "explain": "第一段 if you are like most senior high students in Taiwan 直接對學生說話，全文提供考試壓力的應對方法，故選 (C)。"}, {"q": "According to the writer, why do students often panic?", "options": ["Their teachers give scary warnings.", "The amount of material seems endless.", "They exercise too much before exams.", "They sleep too many hours."], "answer": 1, "explain": "第二段說 Students often panic because the amount of material looks endless，故選 (B)。"}, {"q": "What does the writer say about sleep?", "options": ["An extra hour of study is better than sleep.", "A poor night's sleep makes the brain pessimistic.", "Students should sleep less during exam week.", "Sleep has no effect on exam results."], "answer": 1, "explain": "第二段提到 A restless night does more harm than an extra hour of cramming, and a tired brain is a pessimistic brain，故選 (B)。"}, {"q": "The word \"cramming\" in paragraph 2 is closest in meaning to ______.", "options": ["exercising hard", "studying a lot in a short time", "eating too much", "sleeping late"], "answer": 1, "explain": "cramming 指考前「臨時抱佛腳、死背」，即短時間內大量讀書，故選 (B)。"}, {"q": "What is the writer's attitude in the final paragraph?", "options": ["Caring and encouraging", "Strict and critical", "Humorous and playful", "Cold and scientific"], "answer": 0, "explain": "最後一段要讀者 Be patient with yourself，並說 your worth is not measured by a single score，語氣關懷且鼓勵，故選 (A)。"}], "vocabQ": [{"q": "Shoppers began to ____ when the lights in the mall suddenly went out.", "options": ["relax", "panic", "sob", "tolerate"], "answer": 1, "explain": "句意為「商場燈光突然熄滅時，購物者開始恐慌」，panic 恐慌。"}, {"q": "What a ____ to find my wallet on the MRT seat where I had left it!", "options": ["relief", "rage", "terror", "shame"], "answer": 0, "explain": "句意為「在我忘在捷運座位上的地方找到皮夾，真是鬆了一口氣」，relief 寬慰。"}, {"q": "The baby had a ____ night and woke up crying several times.", "options": ["merry", "restless", "tragic", "thankful"], "answer": 1, "explain": "句意為「寶寶一夜睡不安穩，哭醒了好幾次」，restless 睡不安穩的。"}, {"q": "He is so ____ that he expects it to rain every time we plan a picnic.", "options": ["sympathetic", "suspicious", "pessimistic", "reluctant"], "answer": 2, "explain": "句意為「他太悲觀了，每次計畫野餐都預期會下雨」，pessimistic 悲觀的。"}, {"q": "Without clear goals, many students lose their ____ halfway through the year.", "options": ["pressure", "nightmare", "sorrow", "motivation"], "answer": 3, "explain": "句意為「沒有明確目標，很多學生讀到一半就失去動力」，motivation 動力。"}]}, {"id": "I28", "level": "inter", "num": 28, "title": "The Student Judge at the Science Fair", "titleZh": "科展上的學生評審", "theme": "Thinking & Knowledge", "themeZh": "思考與知識", "article": ["At the Kang Ming Junior High science fair, Pei-yu was given a job she had not asked for. As the winner of last year's contest, she was invited to join the teachers as a student judge and evaluate twelve projects in the ninth-grade section. 'Look at every aspect,' Mr. Tsai told her, 'not just the posters. A good experiment is one that another person could repeat.'", "Most projects were easy to score. Then she reached Table 9, where a boy named Kai-wen had tested whether plants grew faster when music was played to them. His poster was beautiful, and his conclusion was bold: plants that listened to classical music grew exactly twice as tall as the others. Pei-yu was doubtful. In her experience, living things never behaved that neatly. She asked him to demonstrate how he had measured the plants, and he hesitated for a moment before picking up a ruler.", "Rather than accuse him, Pei-yu devised a quick test. She asked to see his daily notebook and made a comparison between the raw numbers and the chart on the poster. The notebook told a different story. The music plants were taller, but only by about twenty percent, and on two rainy days they had actually grown less. Kai-wen's face turned red. 'The real numbers looked boring,' he admitted. 'I thought nobody would detect the change.' Apparently, his expectation was that judges only read the posters.", "Pei-yu did not report him for cheating. Instead, she noted that the experiment itself was well designed and offered an alternative: present the honest data and explain why a twenty percent difference still mattered. Kai-wen redid his poster that afternoon. He did not win, but Mr. Tsai later told Pei-yu that she had made the fairest decision of the day. 'Judging,' he said, 'means concentrating on what is actually there, not on what you were promised.'"], "translation": ["在康明國中的科展上，佩瑜被指派了一項她沒有要求過的工作。身為去年比賽的優勝者，她受邀和老師們一起擔任學生評審，評估九年級組的十二件作品。蔡老師告訴她：「要看每一個面向，不只是海報。好的實驗，是別人也能重複做出來的實驗。」", "大多數作品都很容易評分。接著她來到第九桌，一個叫凱文的男生測試的是植物聽音樂是否會長得比較快。他的海報很漂亮，結論也很大膽：聽古典音樂的植物長得剛好是其他植物的兩倍高。佩瑜起了疑心。依她的經驗，生物從來不會表現得這麼整齊。她請他示範是怎麼量植物的，他遲疑了一下才拿起尺。", "佩瑜沒有指控他，而是設計了一個快速的檢驗。她要求看他每天的記錄本，把原始數據和海報上的圖表做比較。記錄本說的是另一個故事。聽音樂的植物確實比較高，但只高了大約百分之二十，而且有兩個雨天它們反而長得比較少。凱文的臉紅了。「真實的數字看起來很無聊，」他承認，「我以為沒有人會發現這個改動。」顯然，他預期評審只會看海報。", "佩瑜沒有舉報他作弊。她反而在評分表上註明這個實驗本身設計得很好，並提供另一個選擇：呈現誠實的數據，並解釋為什麼百分之二十的差異仍然很重要。凱文當天下午就重做了海報。他沒有得獎，但蔡老師後來告訴佩瑜，她做出了當天最公正的判斷。他說：「評審，就是專注在實際存在的東西上，而不是別人向你承諾的東西。」"], "vocab": [{"word": "evaluate", "pos": "v.", "zh": "評估", "example": "The teacher will evaluate our projects based on creativity and effort.", "exampleZh": "老師會根據創意和努力來評估我們的作品。"}, {"word": "aspect", "pos": "n.", "zh": "方面；層面", "example": "We discussed every aspect of the plan before voting.", "exampleZh": "投票前我們討論了計畫的每一個層面。"}, {"word": "demonstrate", "pos": "v.", "zh": "示範；證明", "example": "The chef demonstrated how to fold a dumpling in three steps.", "exampleZh": "廚師示範了如何用三個步驟包水餃。"}, {"word": "doubtful", "pos": "adj.", "zh": "懷疑的；不確定的", "example": "I am doubtful that the shop will still be open at midnight.", "exampleZh": "我懷疑那家店午夜是否還開著。"}, {"word": "conclusion", "pos": "n.", "zh": "結論", "example": "After reading both reports, she came to a different conclusion.", "exampleZh": "讀完兩份報告後，她得出了不同的結論。"}, {"word": "devise", "pos": "v.", "zh": "設計；想出", "example": "The students devised a game to help them remember new words.", "exampleZh": "學生們想出一個遊戲來幫助記憶新單字。"}, {"word": "comparison", "pos": "n.", "zh": "比較", "example": "In comparison with last year, the summer was much hotter.", "exampleZh": "和去年相比，今年夏天熱得多。"}, {"word": "detect", "pos": "v.", "zh": "察覺；偵測", "example": "Dogs can detect smells that humans cannot notice.", "exampleZh": "狗能察覺到人類無法注意到的氣味。"}, {"word": "alternative", "pos": "n.", "zh": "替代方案；另一個選擇", "example": "If the MRT is closed, taking a bus is a good alternative.", "exampleZh": "如果捷運停駛，搭公車是不錯的替代方案。"}, {"word": "expectation", "pos": "n.", "zh": "期望；預期", "example": "The movie did not live up to my expectations.", "exampleZh": "這部電影沒有達到我的期望。"}], "phrases": [{"phrase": "twice as + adj. + as", "zh": "是…的兩倍", "example": "This bag is twice as heavy as mine.", "exampleZh": "這個袋子的重量是我的兩倍。"}, {"phrase": "turn red", "zh": "臉紅", "example": "His face turned red when everyone sang happy birthday to him.", "exampleZh": "大家為他唱生日快樂歌時，他的臉紅了。"}, {"phrase": "concentrate on", "zh": "專注於", "example": "Turn off the TV so you can concentrate on your homework.", "exampleZh": "把電視關掉，這樣你才能專心寫作業。"}], "grammar": [{"pattern": "Rather than + V / V-ing, S + V", "explain": "rather than 意思是「而不是」，放在句首時後面接動詞原形或動名詞，表示「沒有做 A，而是做 B」。文中 Rather than accuse him, Pei-yu devised a quick test 表示她沒有指控對方，而是設計了檢驗。", "example": "Rather than wait for the elevator, we took the stairs.", "exampleZh": "我們沒有等電梯，而是走樓梯。"}, {"pattern": "S + V + 倍數 + as + adj. + as + N", "explain": "倍數（twice、three times 等）加上 as ... as 用來表示「是…的幾倍」，是比較句型的常見變化。文中 grew exactly twice as tall as the others 表示長得剛好是其他植物的兩倍高。", "example": "Taipei 101 is three times as tall as our school building.", "exampleZh": "臺北 101 的高度是我們學校大樓的三倍。"}], "reading": [{"q": "Why was Pei-yu chosen as a student judge?", "options": ["She was the oldest student at the fair.", "She had won the contest the year before.", "She was Kai-wen's classmate.", "She had designed the score sheets."], "answer": 1, "explain": "第一段說 As the winner of last year's contest, she was invited to join the teachers as a student judge，故選 (B)。"}, {"q": "What first made Pei-yu doubtful about Kai-wen's project?", "options": ["His poster was poorly drawn.", "He refused to show his notebook.", "His result was too neat to be believable.", "His plants had died."], "answer": 2, "explain": "第二段說結論是植物剛好長到兩倍高，而 In her experience, living things never behaved that neatly，故選 (C)。"}, {"q": "What did the notebook show?", "options": ["The music plants were only about twenty percent taller.", "The music plants grew exactly twice as tall.", "All the plants grew the same amount.", "The plants grew more on rainy days."], "answer": 0, "explain": "第三段說 The music plants were taller, but only by about twenty percent，故選 (A)。"}, {"q": "The word \"bold\" in paragraph 2 is closest in meaning to ______.", "options": ["careful", "daring", "boring", "hidden"], "answer": 1, "explain": "bold 在此形容結論「大膽的」，與 daring 意思最接近，故選 (B)。"}, {"q": "What can be inferred about Pei-yu's decision at the end?", "options": ["She wanted Kai-wen to be punished severely.", "She thought the experiment was worthless.", "She valued honesty but also recognized good work.", "She disagreed with Mr. Tsai's advice."], "answer": 2, "explain": "最後一段她沒有舉報作弊，卻指出實驗設計良好並要求呈現誠實數據，老師也稱讚這是最公正的決定，故選 (C)。"}], "vocabQ": [{"q": "Smoke alarms can ____ a fire long before people smell anything.", "options": ["approve", "detect", "foresee", "acquire"], "answer": 1, "explain": "句意為「煙霧警報器能在人聞到味道之前就偵測到火災」，detect 偵測。"}, {"q": "The engineers had to ____ a new way to cool the building without air conditioning.", "options": ["devise", "hesitate", "disagree", "conclude"], "answer": 0, "explain": "句意為「工程師得想出一個不用冷氣就能讓大樓降溫的新方法」，devise 設計、想出。"}, {"q": "Health is only one ____ of happiness; friendship and purpose matter too.", "options": ["clue", "faith", "aspect", "contrast"], "answer": 2, "explain": "句意為「健康只是幸福的一個面向，友誼和目標也很重要」，aspect 方面。"}, {"q": "Judges will ____ each dish on taste, appearance, and originality.", "options": ["identify", "concentrate", "evaluate", "distinguish"], "answer": 2, "explain": "句意為「評審將依味道、外觀和原創性評估每道菜」，evaluate 評估。"}, {"q": "After hours of discussion, the committee finally reached a ____.", "options": ["conclusion", "consideration", "demonstration", "distinction"], "answer": 0, "explain": "句意為「經過數小時討論，委員會終於得出結論」，conclusion 結論。"}]}, {"id": "I29", "level": "inter", "num": 29, "title": "The Thinking Club Wants You", "titleZh": "思考社招募新血", "theme": "Thinking & Knowledge", "themeZh": "思考與知識", "article": ["ANNOUNCEMENT: The Thinking Club Is Looking for New Members. Do you ever lie awake wondering whether the blue you see is the same blue your friend sees? Do you enjoy questions more than answers? If so, the Thinking Club, the school's only philosophy society, invites you to join us this semester. No previous knowledge of philosophers is required, only curiosity and a willingness to be wrong.", "What we do: Every Wednesday at 4:30 in Room 305, we take one big question and spend an hour pulling it apart. Recent topics have included 'Can a computer have intelligence?' and 'Is a prediction still useful if it turns out to be wrong?' Members learn to build a logical outline of an argument, to infer what a speaker really intends, and to tell the difference between an objective fact and a strong opinion. We also observe how the same problem looks from different cultures, from ancient Greece to the Confucian classics.", "Why join: Universities and employers increasingly value people who can resolve disagreements with reason rather than volume. Our former members say the club sharpened their wit, improved their essays for the writing section of the college entrance exam, and, most importantly, taught them that being unaware of your own mistakes is the biggest mystery of all. One graduate, now a law student, recalls that the club gave her 'the wisdom to say I don't know.'", "How to apply: Pick up an application form outside the library or scan the QR code on this poster. The selection is simple: write one paragraph about a question you cannot stop thinking about. Space is limited to twenty new members, so do not suppose there will be room next month. The first meeting is on September 17. Bring your questions; leave your certainty at the door."], "translation": ["公告：思考社招募新社員。你是否曾經躺在床上睡不著，想著你看到的藍色和朋友看到的藍色是不是同一種藍？你喜歡問題勝過答案嗎？如果是，學校唯一的哲學社團「思考社」邀請你這學期加入我們。不需要先具備哲學家的知識，只需要好奇心，以及願意承認自己錯了的心。", "我們做什麼：每週三下午四點半在 305 教室，我們挑一個大問題，花一個小時把它拆解開來。最近的主題包括「電腦可以有智慧嗎？」和「如果預測最後是錯的，它還有用嗎？」社員學習建立論證的邏輯大綱、推論說話者真正的意圖，以及分辨客觀事實和強烈意見之間的差別。我們也觀察同一個問題從不同文化看起來有何不同，從古希臘到儒家經典。", "為什麼要加入：大學和雇主越來越重視能用理性而非音量來化解分歧的人。我們的前社員說，社團磨利了他們的機智，提升了他們學測寫作的程度，而最重要的是，社團教會他們：對自己的錯誤毫無察覺，才是最大的謎。一位現在就讀法律系的畢業社員回憶，社團給了她「說出『我不知道』的智慧」。", "如何申請：到圖書館外領取申請表，或掃描海報上的 QR code。甄選方式很簡單：寫一段關於一個你無法停止思考的問題。名額只有二十位新社員，所以別以為下個月還會有位子。第一次聚會在 9 月 17 日。帶著你的問題來；把你的「確定」留在門外。"], "vocab": [{"word": "philosophy", "pos": "n.", "zh": "哲學", "example": "Her philosophy of life is simple: work hard and be kind.", "exampleZh": "她的人生哲學很簡單：努力工作、待人和善。"}, {"word": "intelligence", "pos": "n.", "zh": "智慧；智力", "example": "Dolphins are known for their high intelligence.", "exampleZh": "海豚以高智力聞名。"}, {"word": "prediction", "pos": "n.", "zh": "預測", "example": "The weather prediction for the weekend is sunny and hot.", "exampleZh": "週末的天氣預測是晴朗炎熱。"}, {"word": "logical", "pos": "adj.", "zh": "合乎邏輯的", "example": "It is logical to bring an umbrella when the sky is dark.", "exampleZh": "天色很暗時帶把傘是合理的。"}, {"word": "infer", "pos": "v.", "zh": "推論", "example": "From her smile, I inferred that she had passed the test.", "exampleZh": "從她的笑容，我推論她通過了考試。"}, {"word": "intend", "pos": "v.", "zh": "打算；意圖", "example": "We intend to visit Tainan during the winter vacation.", "exampleZh": "我們打算寒假去臺南。"}, {"word": "objective", "pos": "adj.", "zh": "客觀的", "example": "A good judge must stay objective during the trial.", "exampleZh": "好的法官在審判中必須保持客觀。"}, {"word": "resolve", "pos": "v.", "zh": "解決；化解", "example": "The two neighbors resolved their argument over tea.", "exampleZh": "兩位鄰居邊喝茶邊化解了他們的爭執。"}, {"word": "unaware", "pos": "adj.", "zh": "未察覺的", "example": "He was unaware that the shop had already closed.", "exampleZh": "他沒有察覺到商店已經關門了。"}, {"word": "wisdom", "pos": "n.", "zh": "智慧", "example": "My grandmother's wisdom comes from eighty years of experience.", "exampleZh": "我奶奶的智慧來自八十年的人生經驗。"}], "phrases": [{"phrase": "pull apart", "zh": "拆解；仔細分析", "example": "The critics pulled the movie apart scene by scene.", "exampleZh": "評論家把這部電影一幕一幕地拆解分析。"}, {"phrase": "tell the difference between A and B", "zh": "分辨 A 與 B 的差別", "example": "Can you tell the difference between real and fake pearls?", "exampleZh": "你能分辨真珍珠和假珍珠的差別嗎？"}, {"phrase": "be limited to", "zh": "限於；僅限", "example": "The free tickets are limited to the first one hundred visitors.", "exampleZh": "免費票僅限前一百名訪客。"}], "grammar": [{"pattern": "S + V + whether + S + V ...", "explain": "whether 引導名詞子句，意思是「是否…」，常接在 wonder、ask、know 等動詞之後。文中 wondering whether the blue you see is the same blue your friend sees 即為此用法。", "example": "I wonder whether the night market is open on rainy days.", "exampleZh": "我想知道夜市在下雨天有沒有營業。"}, {"pattern": "S + V + sb + to + V, to + V, and to + V", "explain": "當同一個動詞後面接多個不定詞時，可用對等連接詞 and 連接，形成平行結構，每個 to V 的形式要一致。文中 learn to build ..., to infer ..., and to tell ... 就是三個平行的不定詞片語。", "example": "The course teaches students to read, to write, and to speak with confidence.", "exampleZh": "這門課教學生有自信地閱讀、寫作和說話。"}], "reading": [{"q": "What is the purpose of this announcement?", "options": ["To sell tickets to a philosophy lecture", "To invite students to join a school club", "To explain the rules of the college entrance exam", "To introduce a new law school"], "answer": 1, "explain": "開頭即說 The Thinking Club Is Looking for New Members，並說明活動內容與申請方式，故選 (B)。"}, {"q": "What do members need in order to join?", "options": ["High grades in every subject", "Experience reading ancient Greek", "Curiosity and the willingness to be wrong", "A recommendation from a teacher"], "answer": 2, "explain": "第一段說 No previous knowledge of philosophers is required, only curiosity and a willingness to be wrong，故選 (C)。"}, {"q": "Which of the following is NOT mentioned as something members learn?", "options": ["How to outline an argument", "How to infer a speaker's true intention", "How to tell facts from opinions", "How to write computer programs"], "answer": 3, "explain": "第二段提到大綱、推論意圖、分辨事實與意見，但沒有提到寫程式，故選 (D)。"}, {"q": "The word \"volume\" in paragraph 3 is closest in meaning to ______.", "options": ["the loudness of a voice", "the size of a book", "the amount of water", "a large number"], "answer": 0, "explain": "with reason rather than volume 指用理性而非「音量、大聲嚷嚷」來解決分歧，故選 (A)。"}, {"q": "Why should interested students apply soon?", "options": ["The library closes at the end of the month.", "Only twenty new members will be accepted.", "The application costs more after September 17.", "The QR code will stop working next week."], "answer": 1, "explain": "最後一段說 Space is limited to twenty new members, so do not suppose there will be room next month，故選 (B)。"}], "vocabQ": [{"q": "The scientist's ____ that the volcano would erupt within a year turned out to be correct.", "options": ["prediction", "reality", "option", "reminder"], "answer": 0, "explain": "句意為「科學家預測火山會在一年內爆發，結果證明是對的」，prediction 預測。"}, {"q": "A news reporter should remain ____ and not take sides in a debate.", "options": ["intellectual", "objective", "supposed", "probable"], "answer": 1, "explain": "句意為「新聞記者應保持客觀，不在辯論中選邊站」，objective 客觀的。"}, {"q": "The driver was ____ that the road ahead had been closed by a landslide.", "options": ["unknown", "learned", "informed", "unaware"], "answer": 3, "explain": "句意為「駕駛沒有察覺前方道路已因山崩封閉」，unaware 未察覺的。"}, {"q": "We can ____ from the empty plates that the guests enjoyed the dinner.", "options": ["recall", "infer", "intend", "relate"], "answer": 1, "explain": "句意為「從空盤子我們可以推論客人很享受這頓晚餐」，infer 推論。"}, {"q": "The two sides met for hours but could not ____ their differences.", "options": ["suppose", "observe", "resolve", "predict"], "answer": 2, "explain": "句意為「雙方會談數小時，仍無法化解歧見」，resolve 解決、化解。"}]}, {"id": "I30", "level": "inter", "num": 30, "title": "Why Does Everyone in Taiwan Sound a Little Different?", "titleZh": "為什麼臺灣每個人的口音都有點不一樣？", "theme": "Language & Expression", "themeZh": "語言與表達", "article": ["If you take the train from Taipei to Kaohsiung, you will hear Mandarin spoken with a slightly different accent at almost every stop. A friend from Tainan may stretch a vowel that a Taipei speaker cuts short, and a grandmother in Yilan might slip in a word from the Taiwanese dialect that her grandchildren only half understand. Linguists define a dialect as a form of a language shared by a particular group, while an accent refers only to the way words are pronounced. The two are often confused, so the distinction is worth clarifying.", "Neither an accent nor a dialect is 'wrong.' Each one conveys information about where a speaker grew up, who raised them, and sometimes even which television programs they watched as a child. Problems arise only when people criticize a way of speaking they do not share. A student who is told that her southern accent sounds 'funny' may stop speaking in class altogether. Consequently, she loses the chance to practice the very skill she is being judged on.", "Context also matters. The same expression can be a compliment in one town and a joke in another, and a farewell that sounds warm in Hakka may seem abrupt when translated directly into Mandarin. Good communicators learn to pay attention to these signals instead of exaggerating the differences. When a misunderstanding happens, a short explanation, or even a simple apology, usually clears the air faster than an argument about who is 'correct.'", "The next time you chat with someone whose speech sounds unfamiliar, listen for the consonants they soften and the words they emphasize. You might discover that the person you were about to criticize is giving you a free lesson in the history of the island. Language is not only a tool for conveying ideas; it is also a map of where we have all come from."], "translation": ["如果你搭火車從臺北到高雄，幾乎每一站都會聽到帶著些微不同口音的國語。來自臺南的朋友可能會把臺北人說得很短的母音拉長，而宜蘭的阿嬤可能會夾進一個孫子們只聽得懂一半的臺語詞。語言學家把「方言」定義為某個特定群體共用的一種語言形式，而「口音」只指字詞的發音方式。這兩者常被混淆，所以值得把差別說清楚。", "口音或方言都沒有「錯」。每一種都傳達了說話者在哪裡長大、由誰撫養，有時甚至透露他小時候看哪些電視節目的訊息。只有當人們批評自己不熟悉的說話方式時，問題才會出現。一個被說「南部口音聽起來很好笑」的學生，可能會乾脆在課堂上不再開口。結果，她失去了練習的機會，而那正是她被評斷的那項能力。", "語境也很重要。同一句話在一個鎮上是讚美，在另一個鎮上卻可能是玩笑；一句在客家話裡聽起來溫暖的道別，直接翻成國語可能顯得唐突。善於溝通的人會學著留意這些訊號，而不是誇大差異。當誤會發生時，一句簡短的解釋，甚至一句簡單的道歉，通常比爭論誰才「正確」更能快速化解尷尬。", "下次你和說話方式聽起來陌生的人聊天時，留意他們放輕的子音和強調的字詞。你可能會發現，你本來要批評的那個人，正在免費為你上一堂這座島嶼的歷史課。語言不只是傳達想法的工具；它也是一張地圖，標示著我們每個人從哪裡來。"], "vocab": [{"word": "accent", "pos": "n.", "zh": "口音", "example": "The tour guide speaks English with a strong French accent.", "exampleZh": "那位導遊說英文帶有濃濃的法國口音。"}, {"word": "dialect", "pos": "n.", "zh": "方言", "example": "My grandfather speaks a dialect that few young people understand.", "exampleZh": "我爺爺說的方言，很少年輕人聽得懂。"}, {"word": "define", "pos": "v.", "zh": "定義", "example": "The dictionary defines 'courage' as the ability to face fear.", "exampleZh": "字典把「勇氣」定義為面對恐懼的能力。"}, {"word": "clarify", "pos": "v.", "zh": "澄清；說清楚", "example": "Could you clarify what you mean by 'soon'?", "exampleZh": "你能說清楚你說的「很快」是什麼意思嗎？"}, {"word": "convey", "pos": "v.", "zh": "傳達", "example": "A picture can convey feelings that words cannot.", "exampleZh": "一張圖片能傳達文字無法表達的感受。"}, {"word": "criticize", "pos": "v.", "zh": "批評", "example": "It is easy to criticize, but hard to do better.", "exampleZh": "批評很容易，但要做得更好很難。"}, {"word": "consequently", "pos": "adv.", "zh": "因此；結果", "example": "He missed the bus and, consequently, arrived late for the exam.", "exampleZh": "他錯過公車，因此考試遲到了。"}, {"word": "context", "pos": "n.", "zh": "上下文；語境", "example": "You can often guess a word's meaning from its context.", "exampleZh": "你通常可以從上下文猜出一個字的意思。"}, {"word": "compliment", "pos": "n.", "zh": "讚美", "example": "She received many compliments on her new haircut.", "exampleZh": "她的新髮型得到許多讚美。"}, {"word": "exaggerate", "pos": "v.", "zh": "誇大", "example": "My brother always exaggerates how big the fish he caught was.", "exampleZh": "我哥總是誇大他釣到的魚有多大。"}], "phrases": [{"phrase": "slip in", "zh": "不經意地加入（話語）", "example": "The speaker slipped in a joke to wake up the audience.", "exampleZh": "講者不經意地加了一個笑話來喚醒聽眾。"}, {"phrase": "pay attention to", "zh": "注意", "example": "Please pay attention to the announcements on the MRT.", "exampleZh": "請注意捷運上的廣播。"}, {"phrase": "clear the air", "zh": "消除誤會；化解尷尬", "example": "A frank talk helped the two friends clear the air.", "exampleZh": "一次坦誠的談話幫助兩位朋友消除了誤會。"}], "grammar": [{"pattern": "Neither + A + nor + B + V (單數)", "explain": "neither A nor B 意思是「A 和 B 都不…」，動詞的單複數依最接近的 B 決定。文中 Neither an accent nor a dialect is wrong 表示兩者都沒有錯。", "example": "Neither my sister nor my brother likes spicy food.", "exampleZh": "我姊姊和我弟弟都不喜歡吃辣。"}, {"pattern": "the way (that / in which) + S + V", "explain": "the way 後面接子句，表示「…的方式」，that 或 in which 常省略。文中 the way words are pronounced 指「字詞被發音的方式」。", "example": "I like the way she explains difficult ideas.", "exampleZh": "我喜歡她解釋困難概念的方式。"}], "reading": [{"q": "What is the main idea of the article?", "options": ["Mandarin should be spoken the same way everywhere in Taiwan.", "Differences in accent and dialect are natural and worth respecting.", "Hakka is the most difficult language to learn in Taiwan.", "Students should avoid speaking in class if they have an accent."], "answer": 1, "explain": "全文說明口音與方言都沒有「錯」，並呼籲以理解取代批評，故選 (B)。"}, {"q": "According to the article, what is the difference between a dialect and an accent?", "options": ["A dialect is older than an accent.", "A dialect is used only by grandparents.", "An accent refers only to pronunciation, while a dialect is a form of a language.", "An accent is correct, but a dialect is not."], "answer": 2, "explain": "第一段說 a dialect is a form of a language shared by a particular group, while an accent refers only to the way words are pronounced，故選 (C)。"}, {"q": "What may happen to a student whose accent is called 'funny'?", "options": ["She may stop speaking in class.", "She may move to another city.", "She may learn Hakka instead.", "She may get better grades."], "answer": 0, "explain": "第二段說 A student who is told that her southern accent sounds 'funny' may stop speaking in class altogether，故選 (A)。"}, {"q": "The word \"abrupt\" in paragraph 3 is closest in meaning to ______.", "options": ["friendly", "sudden and rude", "very long", "difficult to hear"], "answer": 1, "explain": "abrupt 指「突然而顯得無禮的、唐突的」，與 sudden and rude 意思最接近，故選 (B)。"}, {"q": "What does the writer suggest doing when a misunderstanding happens?", "options": ["Argue until the other person agrees", "Translate everything into Mandarin", "Give a short explanation or apology", "Stop talking to the person"], "answer": 2, "explain": "第三段說 a short explanation, or even a simple apology, usually clears the air faster than an argument，故選 (C)。"}], "vocabQ": [{"q": "Even after ten years abroad, she still speaks with a Taiwanese ____.", "options": ["accent", "caption", "argument", "definition"], "answer": 0, "explain": "句意為「即使在國外十年，她說話仍帶著臺灣口音」，accent 口音。"}, {"q": "The teacher asked him to ____ his answer because nobody understood it.", "options": ["boast", "clarify", "deceive", "curse"], "answer": 1, "explain": "句意為「老師要他把答案說清楚，因為沒人聽懂」，clarify 澄清、說清楚。"}, {"q": "Don't ____ the story; the fish was only thirty centimeters long, not a meter.", "options": ["congratulate", "confess", "exaggerate", "bless"], "answer": 2, "explain": "句意為「別誇大這個故事，那條魚只有三十公分，不是一公尺」，exaggerate 誇大。"}, {"q": "The road was flooded; ____, all the buses were delayed for two hours.", "options": ["anyhow", "concerning", "consequently", "farewell"], "answer": 2, "explain": "句意為「道路淹水，因此所有公車延誤兩小時」，consequently 因此。"}, {"q": "The word 'cool' can mean different things depending on the ____.", "options": ["dialect", "apology", "criticism", "context"], "answer": 3, "explain": "句意為「cool 這個字依語境不同可以有不同意思」，context 語境、上下文。"}]}, {"id": "I31", "level": "inter", "num": 31, "title": "Feedback on My First English Speech", "titleZh": "我第一次英語演講的回饋", "theme": "Language & Expression", "themeZh": "語言與表達", "article": ["Dear Kevin, Thank you for sending me the video of your speech, \"Why Teenagers Ought to Sleep More.\" I watched it twice last night, and I am writing to give you some feedback before the city contest on Saturday. First of all, your introduction was excellent. You greeted the judges warmly, mentioned your nickname, \"Sleepy Kevin,\" and made everyone laugh. A good greeting like this makes the audience want to listen, so keep it.", "Your English was fluent, and your grammar was almost perfect. However, there are two things that could mislead your listeners. In the second paragraph, you used the idiom \"hit the sack,\" but you did not explain it. Some judges may misunderstand you and think you are talking about a bag! Furthermore, when you said \"studies show that,\" you did not say which studies. A persuasive speaker always informs the audience where the facts come from; otherwise, people may think you are talking nonsense.", "Nevertheless, I was impressed by the way you tried to persuade the audience with real examples instead of empty phrases. The story about your sister falling asleep on the MRT was obviously the best part. Moreover, your voice was clear, and you did not murmur even once, which is a great improvement.", "Here is one more suggestion. Near the end, you said, \"Parents never understand.\" This phrase may imply that all parents are the enemy, and some judges might interpret it as an insult. Change it to \"Parents do not always understand,\" and you will sound polite and persuasive at the same time. I believe you will do well. Please inquire at the office if you need a quiet room to practice. Indeed, I am proud of you. Best wishes, Ms. Lin"], "translation": ["親愛的 Kevin：謝謝你把你的演講影片「為什麼青少年應該多睡一點」寄給我。我昨晚看了兩遍，現在寫信給你，想在星期六的市賽前給你一些回饋。首先，你的開場非常出色。你親切地向評審問好，提到你的綽號「愛睏 Kevin」，逗得大家都笑了。像這樣好的問候會讓觀眾想聽下去，所以要保留。", "你的英語很流利，文法也幾乎完美。不過，有兩個地方可能會誤導聽眾。在第二段，你用了慣用語「hit the sack」（上床睡覺），卻沒有解釋。有些評審可能會誤解你，以為你在講一個袋子！此外，你說「研究顯示」的時候，並沒有說是哪些研究。有說服力的講者一定會告訴聽眾事實的出處；否則，大家可能會覺得你在胡說。", "儘管如此，你試著用真實例子而不是空洞的詞句來說服觀眾，這一點讓我印象深刻。你妹妹在捷運上睡著的故事顯然是最精彩的部分。而且，你的聲音清楚，一次也沒有含糊不清，這是很大的進步。", "還有一個建議。接近結尾時，你說「父母永遠不懂」。這句話可能暗示所有父母都是敵人，有些評審可能會把它解讀成一種侮辱。把它改成「父母並不總是了解」，你聽起來就會既有禮貌又有說服力。我相信你會表現得很好。如果你需要安靜的房間練習，請到辦公室詢問。我真的以你為榮。祝好，林老師"], "vocab": [{"word": "feedback", "pos": "n.", "zh": "回饋；意見", "example": "The teacher gave us useful feedback on our essays.", "exampleZh": "老師針對我們的作文給了有用的回饋。"}, {"word": "fluent", "pos": "adj.", "zh": "流利的", "example": "After a year in Canada, she became fluent in English.", "exampleZh": "在加拿大住了一年後，她的英語變得很流利。"}, {"word": "grammar", "pos": "n.", "zh": "文法", "example": "English grammar is not as hard as many students think.", "exampleZh": "英文文法沒有許多學生想的那麼難。"}, {"word": "mislead", "pos": "v.", "zh": "誤導", "example": "The advertisement misled customers about the price.", "exampleZh": "那則廣告在價格上誤導了顧客。"}, {"word": "idiom", "pos": "n.", "zh": "慣用語；成語", "example": "\"Break a leg\" is an idiom that means \"good luck.\"", "exampleZh": "「Break a leg」是一個意思是「祝好運」的慣用語。"}, {"word": "misunderstand", "pos": "v.", "zh": "誤解", "example": "I think you misunderstood what I said about the test.", "exampleZh": "我想你誤解了我關於考試所說的話。"}, {"word": "furthermore", "pos": "adv.", "zh": "此外；再者", "example": "The hotel is cheap; furthermore, it is close to the MRT station.", "exampleZh": "這家飯店很便宜；此外，它離捷運站很近。"}, {"word": "persuasive", "pos": "adj.", "zh": "有說服力的", "example": "Her argument was so persuasive that everyone agreed.", "exampleZh": "她的論點非常有說服力，大家都同意了。"}, {"word": "nevertheless", "pos": "adv.", "zh": "儘管如此", "example": "It was raining; nevertheless, we went hiking.", "exampleZh": "當時在下雨；儘管如此，我們還是去健行了。"}, {"word": "interpret", "pos": "v.", "zh": "解讀；詮釋", "example": "People may interpret the same poem in different ways.", "exampleZh": "人們可能用不同的方式解讀同一首詩。"}], "phrases": [{"phrase": "first of all", "zh": "首先", "example": "First of all, let me thank everyone for coming.", "exampleZh": "首先，讓我感謝大家的到來。"}, {"phrase": "be impressed by", "zh": "對……印象深刻", "example": "We were impressed by his clear pronunciation.", "exampleZh": "我們對他清楚的發音印象深刻。"}, {"phrase": "instead of", "zh": "而不是", "example": "Use real examples instead of empty words.", "exampleZh": "用真實的例子，而不是空洞的話。"}], "grammar": [{"pattern": "S + V ..., which + V ...（非限定關係子句補充說明前面整句）", "explain": "逗號後的 which 可以代替前面整個句子的內容，用來補充說明或評論。文中 you did not murmur even once, which is a great improvement 的 which 指的是「你一次也沒有含糊不清」這件事。", "example": "He finished the race, which surprised everyone.", "exampleZh": "他跑完了比賽，這讓大家都很驚訝。"}, {"pattern": "祈使句, and + S + will + V", "explain": "「做某事，你就會……」。前半是祈使句，後面用 and 連接表示結果；若用 or 則表示「否則」。文中 Change it to ..., and you will sound polite 就是這個句型。", "example": "Practice every day, and you will become fluent.", "exampleZh": "每天練習，你就會變得流利。"}], "reading": [{"q": "What is the main purpose of this email?", "options": ["To invite Kevin to a speech contest", "To give Kevin advice before his contest", "To explain why teenagers need more sleep", "To ask Kevin to practice in the office"], "answer": 1, "explain": "第一段提到 I am writing to give you some feedback before the city contest，全文都是對演講的建議，故選 (B)。"}, {"q": "Why might some judges misunderstand the idiom \"hit the sack\"?", "options": ["Because Kevin said it too fast", "Because the idiom is too old", "Because Kevin did not explain it", "Because the judges do not like idioms"], "answer": 2, "explain": "第二段說 you used the idiom \"hit the sack,\" but you did not explain it，故選 (C)。"}, {"q": "The word \"murmur\" in paragraph 3 is closest in meaning to ______.", "options": ["speak unclearly in a low voice", "shout at the audience", "forget the words", "laugh nervously"], "answer": 0, "explain": "murmur 是「低聲含糊地說」，與 your voice was clear 形成對比，故選 (A)。"}, {"q": "Why does Ms. Lin want Kevin to change the sentence \"Parents never understand\"?", "options": ["It is grammatically wrong.", "It is too long for the speech.", "It does not fit the topic.", "It may sound rude to some judges."], "answer": 3, "explain": "第四段提到這句話 may imply that all parents are the enemy，評審可能 interpret it as an insult，故選 (D)。"}, {"q": "According to Ms. Lin, which part of the speech was the best?", "options": ["The greeting to the judges", "The story about Kevin's sister", "The part about studies", "The ending about parents"], "answer": 1, "explain": "第三段說 The story about your sister falling asleep on the MRT was obviously the best part，故選 (B)。"}], "vocabQ": [{"q": "My cousin is ____ in three languages, so she works as a tour guide.", "options": ["fluent", "silent", "nervous", "similar"], "answer": 0, "explain": "句意為「我表姊三種語言都很流利，所以她當導遊」，fluent 流利的。"}, {"q": "We need more ____ from the students before we change the lunch menu.", "options": ["grammar", "feedback", "furniture", "weather"], "answer": 1, "explain": "句意為「在更改午餐菜單前，我們需要學生更多的回饋意見」，feedback 回饋。"}, {"q": "Old maps can easily ____ hikers, so always check the trail signs too.", "options": ["inform", "impress", "mislead", "interpret"], "answer": 2, "explain": "句意為「舊地圖很容易誤導登山客，所以也要看步道指標」，mislead 誤導。"}, {"q": "The ticket was expensive; ____, the concert was worth every dollar.", "options": ["otherwise", "namely", "moreover", "nevertheless"], "answer": 3, "explain": "前後句意相反（票很貴，但演唱會值得），需用 nevertheless 儘管如此。"}, {"q": "Her speech was so ____ that the whole class agreed to clean the beach.", "options": ["offensive", "persuasive", "misleading", "oral"], "answer": 1, "explain": "句意為「她的演講非常有說服力，全班都同意去淨灘」，persuasive 有說服力的。"}]}, {"id": "I32", "level": "inter", "num": 32, "title": "Five Tricks to Fix Your Pronunciation", "titleZh": "改善發音的五個訣竅", "theme": "Language & Expression", "themeZh": "語言與表達", "article": ["Many students in Taiwan can read an English text well but feel nervous when they open their mouths. If your teacher has ever warned you that nobody could understand your \"comfortable\" or \"vegetable,\" do not feel bad. Pronunciation is a skill, and like any skill, it can be trained. Here are five tricks that I recommend to my students.", "First, count the syllables. English words have a rhythm, and most mistakes happen when learners add or drop a syllable. \"Chocolate,\" for example, has two syllables in everyday usage, not three. Clap your hands once for each syllable while you say the word, and you will surely hear the difference. Second, pay attention to vowels. The vowel in \"ship\" is short, but the vowel in \"sheep\" is long. Unless you can hear the difference, you cannot produce it, so listen to the two words again and again before you repeat them.", "Third, learn verbs and nouns in pairs. The verb \"record\" and the noun \"record\" are spelled the same, but the stress is different. Fourth, recite short poems or song lines that rhyme. Rhyme forces your mouth to make the same sounds repeatedly, and the tune helps you remember the correct tone. Avoid slang at the beginning, because slang changes quickly and is often pronounced in unusual ways. Finally, whisper. When you whisper a sentence, you cannot rely on your voice, so your lips and tongue must do all the work. Unfortunately, most learners skip this step because it feels silly.", "To summarize, good pronunciation does not come from a dictionary alone. It comes from your ears, your mouth, and daily practice. Try these tricks for a month, and then record yourself. The result will reveal how far you have come."], "translation": ["台灣有許多學生能把英文文章讀得很好，卻在一開口時感到緊張。如果老師曾經警告你，沒有人聽得懂你說的「comfortable」或「vegetable」，不要難過。發音是一種技能，而且像任何技能一樣，是可以訓練的。以下是我推薦給學生的五個訣竅。", "第一，數音節。英文單字有節奏，而大多數錯誤都發生在學習者多加或少掉一個音節的時候。例如「chocolate」在日常用法中有兩個音節，不是三個。說這個字的時候，每個音節拍一次手，你一定會聽出差別。第二，注意母音。「ship」的母音是短的，而「sheep」的母音是長的。除非你能聽出差別，否則你無法發出來，所以在跟讀之前，先一遍又一遍地聽這兩個字。", "第三，把動詞和名詞成對學。動詞「record」和名詞「record」拼法相同，但重音不同。第四，朗誦押韻的短詩或歌詞。押韻迫使你的嘴巴反覆發出相同的音，而曲調會幫助你記住正確的語調。一開始要避免俚語，因為俚語變化很快，而且常常用不尋常的方式發音。最後，用耳語說。當你用耳語說一個句子時，你無法依靠嗓音，所以嘴唇和舌頭必須做所有的工作。可惜的是，大多數學習者都跳過這一步，因為感覺很傻。", "總結來說，好的發音不是光靠字典就能得到的。它來自你的耳朵、你的嘴巴和每天的練習。試試這些訣竅一個月，然後把自己錄下來。結果會顯示你進步了多少。"], "vocab": [{"word": "pronunciation", "pos": "n.", "zh": "發音", "example": "His pronunciation improved after he joined the drama club.", "exampleZh": "他加入戲劇社後，發音進步了。"}, {"word": "syllable", "pos": "n.", "zh": "音節", "example": "The word \"banana\" has three syllables.", "exampleZh": "「banana」這個字有三個音節。"}, {"word": "vowel", "pos": "n.", "zh": "母音", "example": "There are five vowel letters in the English alphabet.", "exampleZh": "英文字母中有五個母音字母。"}, {"word": "recite", "pos": "v.", "zh": "朗誦；背誦", "example": "Each student had to recite a poem in front of the class.", "exampleZh": "每個學生都必須在全班面前朗誦一首詩。"}, {"word": "rhyme", "pos": "v.", "zh": "押韻", "example": "\"Cat\" rhymes with \"hat.\"", "exampleZh": "「cat」和「hat」押韻。"}, {"word": "tone", "pos": "n.", "zh": "語調；語氣", "example": "Her tone was friendly, so nobody felt nervous.", "exampleZh": "她的語氣很友善，所以沒有人感到緊張。"}, {"word": "slang", "pos": "n.", "zh": "俚語", "example": "Teenagers often use slang that their parents do not understand.", "exampleZh": "青少年常用父母聽不懂的俚語。"}, {"word": "whisper", "pos": "v.", "zh": "低聲說；耳語", "example": "Please whisper in the library.", "exampleZh": "在圖書館裡請小聲說話。"}, {"word": "summarize", "pos": "v.", "zh": "總結；摘要", "example": "Can you summarize the story in three sentences?", "exampleZh": "你能用三句話總結這個故事嗎？"}, {"word": "unless", "pos": "conj.", "zh": "除非", "example": "You will not pass the test unless you study.", "exampleZh": "除非你讀書，否則你不會通過考試。"}], "phrases": [{"phrase": "pay attention to", "zh": "注意", "example": "Pay attention to the stress of each word.", "exampleZh": "注意每個字的重音。"}, {"phrase": "rely on", "zh": "依靠", "example": "Do not rely on translation apps all the time.", "exampleZh": "不要一直依賴翻譯軟體。"}, {"phrase": "again and again", "zh": "一遍又一遍", "example": "She listened to the song again and again.", "exampleZh": "她一遍又一遍地聽那首歌。"}], "grammar": [{"pattern": "Unless + S + V, S + V（除非……否則……）", "explain": "unless 等於 if ... not，引導條件子句，表示「除非」。文中 Unless you can hear the difference, you cannot produce it 意思是「除非你聽得出差別，否則發不出來」。", "example": "Unless it rains, we will practice outside.", "exampleZh": "除非下雨，否則我們會在戶外練習。"}, {"pattern": "S + can/must + be + p.p.（含情態動詞的被動語態）", "explain": "情態動詞後接 be + 過去分詞，表示「可以被／必須被……」。文中 it can be trained 表示「發音是可以被訓練的」。", "example": "This word can be pronounced in two ways.", "exampleZh": "這個字可以用兩種方式發音。"}], "reading": [{"q": "What is the passage mainly about?", "options": ["Why English spelling is difficult", "How to memorize new vocabulary", "Practical ways to improve English pronunciation", "The differences between verbs and nouns"], "answer": 2, "explain": "全文介紹五個改善發音的訣竅，第一段最後說 Here are five tricks，故選 (C)。"}, {"q": "According to the writer, how many syllables does \"chocolate\" usually have?", "options": ["Two", "Three", "Four", "One"], "answer": 0, "explain": "第二段說 \"Chocolate\" has two syllables in everyday usage, not three，故選 (A)。"}, {"q": "The phrase \"rely on\" in paragraph 3 is closest in meaning to ______.", "options": ["give up", "look for", "turn off", "depend on"], "answer": 3, "explain": "rely on 意為「依靠」，與 depend on 同義，故選 (D)。"}, {"q": "Why does the writer suggest avoiding slang at the beginning?", "options": ["Slang is rude.", "Slang changes fast and sounds unusual.", "Slang has too many syllables.", "Slang is not in the dictionary."], "answer": 1, "explain": "第三段說 slang changes quickly and is often pronounced in unusual ways，故選 (B)。"}, {"q": "What is the purpose of whispering, according to the passage?", "options": ["To avoid disturbing others", "To make the lesson more fun", "To make the lips and tongue work harder", "To help learners remember words"], "answer": 2, "explain": "第三段說 you cannot rely on your voice, so your lips and tongue must do all the work，故選 (C)。"}], "vocabQ": [{"q": "Her ____ is so clear that even foreigners can understand her easily.", "options": ["pronunciation", "signature", "translation", "proposal"], "answer": 0, "explain": "句意為「她的發音非常清楚，連外國人都能輕易聽懂」，pronunciation 發音。"}, {"q": "The word \"cat\" has only one ____, but \"banana\" has three.", "options": ["slogan", "syllable", "sentence", "summary"], "answer": 1, "explain": "句意為「cat 只有一個音節，但 banana 有三個」，syllable 音節。"}, {"q": "The twins had to ____ a long poem at the school festival.", "options": ["recite", "refuse", "scold", "warn"], "answer": 0, "explain": "句意為「雙胞胎必須在校慶朗誦一首長詩」，recite 朗誦。"}, {"q": "The baby was sleeping, so Mom could only ____ to us.", "options": ["yell", "swear", "whisper", "respond"], "answer": 2, "explain": "句意為「寶寶在睡覺，所以媽媽只能低聲對我們說話」，whisper 低聲說。"}, {"q": "We will not go to the beach ____ the typhoon leaves Taiwan.", "options": ["unless", "regarding", "surely", "sincerely"], "answer": 0, "explain": "句意為「除非颱風離開台灣，否則我們不會去海邊」，unless 除非。"}]}, {"id": "I33", "level": "inter", "num": 33, "title": "The Boy Who Hated Cram School", "titleZh": "討厭補習班的男孩", "theme": "Education & School", "themeZh": "教育與學校", "article": ["When Jason entered senior high school as a freshman, his mother enrolled him in a cram school near Taipei Main Station. Three nights a week, after eight hours in his own classroom, he sat through another lecture on math or English. His academic record was average, and his mother believed that a tutor could change that. Jason believed something else: that he was wasting his life.", "The cram school's discipline was strict. Every student had to register at the door, and an absence meant a phone call home. The teacher assigned pages from a thick workbook every night and instructed students to memorize fifty words before each quiz. Jason copied, memorized, and forgot. His comprehension did not improve, and his essays stayed short and dull.", "Everything changed when a new adviser, Mr. Kao, joined the center. Instead of lecturing, he asked Jason what he actually wanted to learn. Jason, surprised, said he liked building model planes. Mr. Kao brought in an English reference book about flight and told Jason to read one page a day and write three questions about it. For the first time, Jason wanted to look up words. The words he learned for the quiz began to appear in his reading, and his revision at home no longer felt like punishment.", "By the end of the year, Jason had moved from the intermediate class to the advanced one. He later graduated with a certificate of excellence in English, which the headmaster handed him at graduation in front of the whole school. Years later, as a scholar at a university in Hsinchu, he still remembered Mr. Kao's guidance: \"A learner who asks questions will always go further than one who only memorizes answers.\""], "translation": ["Jason 進入高中成為新生時，媽媽幫他在台北車站附近的補習班報了名。每週三個晚上，在自己的教室待了八小時之後，他還要再坐著聽一堂數學或英文課。他的學業成績普通，媽媽相信家教老師可以改變這一點。Jason 則相信另一件事：他正在浪費人生。", "補習班的紀律很嚴格。每個學生進門都必須登記，缺席一次就代表會打電話回家。老師每晚從厚厚的習作本指派頁數，並指示學生在每次小考前背五十個單字。Jason 抄寫、背誦，然後忘記。他的理解力沒有進步，作文也一直又短又乏味。", "一位新的輔導老師高老師加入補習班後，一切都改變了。他不是講課，而是問 Jason 真正想學什麼。Jason 很驚訝，說他喜歡做模型飛機。高老師帶來一本關於飛行的英文參考書，叫 Jason 每天讀一頁，並寫下三個問題。Jason 第一次主動想查單字。他為小考背的單字開始出現在他的閱讀裡，在家複習也不再像是處罰。", "到了年底，Jason 已經從中級班升到高級班。後來他畢業時拿到英文優秀證書，是校長在畢業典禮上當著全校的面交給他的。多年後，身為新竹一所大學的學者，他仍然記得高老師的指引：「會問問題的學習者，永遠比只會背答案的人走得更遠。」"], "vocab": [{"word": "cram", "pos": "v.", "zh": "填鴨式死記；(cram school) 補習班", "example": "Many students cram for exams the night before.", "exampleZh": "許多學生在考試前一晚臨時抱佛腳死背。"}, {"word": "enroll", "pos": "v.", "zh": "註冊；報名", "example": "She enrolled in a summer art course.", "exampleZh": "她報名了一門暑期美術課程。"}, {"word": "tutor", "pos": "n.", "zh": "家教；導師", "example": "My tutor comes to our house every Tuesday.", "exampleZh": "我的家教每週二都來我們家。"}, {"word": "academic", "pos": "adj.", "zh": "學業的；學術的", "example": "The school is proud of its academic results.", "exampleZh": "這所學校以它的學業成績為榮。"}, {"word": "memorize", "pos": "v.", "zh": "記住；背誦", "example": "It took me an hour to memorize the poem.", "exampleZh": "我花了一小時把這首詩背起來。"}, {"word": "discipline", "pos": "n.", "zh": "紀律", "example": "Good discipline is important in a large class.", "exampleZh": "在大班級裡，良好的紀律很重要。"}, {"word": "guidance", "pos": "n.", "zh": "指導；引導", "example": "With her teacher's guidance, she chose the right major.", "exampleZh": "在老師的指導下，她選擇了合適的科系。"}, {"word": "graduate", "pos": "v.", "zh": "畢業", "example": "My brother will graduate from university next June.", "exampleZh": "我哥哥明年六月將從大學畢業。"}, {"word": "lecture", "pos": "n.", "zh": "講課；演講", "example": "The professor's lecture on history lasted two hours.", "exampleZh": "教授的歷史課講了兩個小時。"}, {"word": "freshman", "pos": "n.", "zh": "（高中或大學）一年級新生", "example": "As a freshman, he did not know anyone at school.", "exampleZh": "身為新生，他在學校誰都不認識。"}], "phrases": [{"phrase": "sit through", "zh": "耐著性子聽完（坐到結束）", "example": "We had to sit through a three-hour meeting.", "exampleZh": "我們必須耐著性子坐完三小時的會議。"}, {"phrase": "look up", "zh": "查閱（字典、資料）", "example": "Look up the word if you do not know it.", "exampleZh": "如果你不認識這個字，就查一下。"}, {"phrase": "for the first time", "zh": "第一次", "example": "For the first time, she enjoyed reading in English.", "exampleZh": "她第一次享受用英文閱讀。"}], "grammar": [{"pattern": "By + 過去時間, S + had + p.p.（過去完成式）", "explain": "表示在過去某個時間點之前已經完成的動作。文中 By the end of the year, Jason had moved from ... 表示「到年底時，Jason 已經升班了」。", "example": "By the time the bell rang, we had finished the test.", "exampleZh": "鐘響時，我們已經寫完考卷了。"}, {"pattern": "Instead of + V-ing, S + V", "explain": "「不是做……，而是……」。instead of 後面接動名詞或名詞。文中 Instead of lecturing, he asked Jason ... 表示高老師不講課，反而問問題。", "example": "Instead of watching TV, he read a book.", "exampleZh": "他沒有看電視，而是看書。"}], "reading": [{"q": "Why did Jason's mother send him to a cram school?", "options": ["She thought a tutor could improve his average grades.", "Jason asked to go there with his friends.", "The school required all freshmen to attend.", "She wanted him to learn how to build planes."], "answer": 0, "explain": "第一段說 His academic record was average, and his mother believed that a tutor could change that，故選 (A)。"}, {"q": "What happened if a student was absent from the cram school?", "options": ["He had to copy the workbook twice.", "He was moved to a lower class.", "He had to memorize one hundred words.", "The school called his family."], "answer": 3, "explain": "第二段說 an absence meant a phone call home，故選 (D)。"}, {"q": "How was Mr. Kao different from the other teachers?", "options": ["He gave more homework.", "He asked Jason what he wanted to learn.", "He taught only advanced students.", "He was the headmaster of the school."], "answer": 1, "explain": "第三段說 Instead of lecturing, he asked Jason what he actually wanted to learn，故選 (B)。"}, {"q": "The word \"dull\" in paragraph 2 is closest in meaning to ______.", "options": ["difficult", "long", "boring", "careful"], "answer": 2, "explain": "dull 意為「乏味的」，與 short and dull 的語境相符，故選 (C)。"}, {"q": "What is the main message of the story?", "options": ["Asking questions leads to real learning.", "Cram schools are a waste of money.", "Students should study only what they like.", "Memorizing words is the key to success."], "answer": 0, "explain": "最後一段高老師的話 A learner who asks questions will always go further 點出全文主旨，故選 (A)。"}], "vocabQ": [{"q": "Students who want to ____ in the computer class must sign up by Friday.", "options": ["graduate", "enroll", "instruct", "assign"], "answer": 1, "explain": "句意為「想報名電腦課的學生必須在星期五前登記」，enroll 報名。"}, {"q": "My parents hired a math ____ to help me before the big exam.", "options": ["tutor", "learner", "scholar", "examiner"], "answer": 0, "explain": "句意為「大考前父母請了一位數學家教來幫我」，tutor 家教。"}, {"q": "Actors have to ____ hundreds of lines before the play opens.", "options": ["register", "educate", "memorize", "graduate"], "answer": 2, "explain": "句意為「演員在開演前必須背下數百句台詞」，memorize 記住。"}, {"q": "Without ____, the children ran around the classroom and shouted.", "options": ["guidance", "absence", "revision", "discipline"], "answer": 3, "explain": "句意為「沒有紀律，孩子們在教室裡跑來跑去大叫」，discipline 紀律。"}, {"q": "Her ____ performance was excellent, so she won a scholarship.", "options": ["elementary", "academic", "educational", "intermediate"], "answer": 1, "explain": "句意為「她的學業表現優異，所以獲得獎學金」，academic 學業的。"}]}, {"id": "I34", "level": "inter", "num": 34, "title": "Student Artists Light Up an Old Train Station", "titleZh": "學生藝術家點亮老火車站", "theme": "Arts & Culture", "themeZh": "藝術與文化", "article": ["TAICHUNG, May 12 -- An old train station that stood empty for ten years has been turned into a gallery for young artists. The exhibition, titled \"Tracks of Imagination,\" opened on Saturday with a short ceremony attended by the mayor, several art critics, and more than two hundred students and parents.", "The show presents works created by senior high school students from across central Taiwan. Visitors who walk through the main hall first see a huge canvas painted by a group of students from Taichung Girls' Senior High School. It shows the goddess Mazu riding a high-speed train, a creative mix of folk belief and contemporary life. Nearby, wooden figures carved by students at a vocational school tell a fable about a greedy fox, and each figure wears a tiny costume made of recycled cloth.", "The organizers said the idea came from a simple question: where do teenagers find inspiration? \"Most of them told us that their inspiration comes from daily life, not from museums,\" explained Ms. Chen Yu-ting, the art teacher who organized the event. \"So we asked them to exhibit what they see every day.\" The result includes illustrations of night markets, a fantasy comic about a dancer who lives inside the MRT, and a short animated film with a surprising ending.", "Critics have praised the station's architecture as the perfect setting. \"The high ceiling and the old iron beams make every drawing look alive,\" wrote one reviewer in a local newspaper. The best piece, chosen by visitors, will receive an award of NT$10,000 at the closing ceremony on June 30. The exhibition is open daily from 10 a.m. to 6 p.m., and admission is free for students."], "translation": ["台中，5 月 12 日訊——一座閒置十年的老火車站已被改造成年輕藝術家的藝廊。這場名為「想像的軌道」的展覽於星期六開幕，開幕典禮簡短，市長、數位藝術評論家以及兩百多名學生和家長出席。", "展覽呈現的是來自中台灣各地高中生的作品。走進主廳的參觀者首先會看到一幅由台中女中一群學生繪製的巨大畫布。畫中媽祖女神搭著高鐵，是民間信仰與當代生活富有創意的結合。附近，一所高職學生雕刻的木頭人偶講述一則貪心狐狸的寓言，每個人偶都穿著用回收布料做的小戲服。", "主辦單位表示，這個構想來自一個簡單的問題：青少年從哪裡找到靈感？籌辦這次活動的美術老師陳昱婷解釋：「他們大多數告訴我們，靈感來自日常生活，而不是博物館。所以我們請他們展出每天看到的東西。」成果包括夜市的插畫、一部關於住在捷運裡的舞者的奇幻漫畫，以及一部結局出人意料的動畫短片。", "評論家稱讚這座車站的建築是完美的場地。一位評論者在地方報紙上寫道：「挑高的天花板和老舊的鐵樑讓每一幅畫都活了起來。」由參觀者選出的最佳作品，將在 6 月 30 日的閉幕典禮上獲得新台幣一萬元的獎金。展覽每天上午十點至下午六點開放，學生免費入場。"], "vocab": [{"word": "exhibition", "pos": "n.", "zh": "展覽", "example": "The photo exhibition will last until the end of July.", "exampleZh": "這場攝影展將持續到七月底。"}, {"word": "gallery", "pos": "n.", "zh": "藝廊；畫廊", "example": "The gallery shows paintings by local artists.", "exampleZh": "這間藝廊展出本地藝術家的畫作。"}, {"word": "ceremony", "pos": "n.", "zh": "典禮；儀式", "example": "The opening ceremony began with a drum performance.", "exampleZh": "開幕典禮以一場鼓樂表演揭開序幕。"}, {"word": "canvas", "pos": "n.", "zh": "畫布", "example": "The artist stared at the empty canvas for an hour.", "exampleZh": "那位藝術家盯著空白的畫布看了一個小時。"}, {"word": "carve", "pos": "v.", "zh": "雕刻", "example": "The old man carved a small bird out of wood.", "exampleZh": "老先生用木頭雕了一隻小鳥。"}, {"word": "contemporary", "pos": "adj.", "zh": "當代的；現代的", "example": "The museum is famous for its contemporary art collection.", "exampleZh": "這間博物館以當代藝術收藏聞名。"}, {"word": "fable", "pos": "n.", "zh": "寓言", "example": "\"The Tortoise and the Hare\" is a famous fable.", "exampleZh": "《龜兔賽跑》是一則著名的寓言。"}, {"word": "inspiration", "pos": "n.", "zh": "靈感", "example": "Nature is a great source of inspiration for poets.", "exampleZh": "大自然是詩人很好的靈感來源。"}, {"word": "illustration", "pos": "n.", "zh": "插畫；圖解", "example": "The children's book is full of colorful illustrations.", "exampleZh": "這本童書充滿了色彩豐富的插畫。"}, {"word": "critic", "pos": "n.", "zh": "評論家", "example": "The film critic gave the movie five stars.", "exampleZh": "影評人給這部電影五顆星。"}], "phrases": [{"phrase": "be turned into", "zh": "被改造成", "example": "The old factory was turned into a bookstore.", "exampleZh": "那座舊工廠被改造成了書店。"}, {"phrase": "a mix of", "zh": "……的混合", "example": "The dish is a mix of Taiwanese and Japanese flavors.", "exampleZh": "這道菜是台式和日式口味的混合。"}, {"phrase": "be praised as", "zh": "被稱讚為", "example": "The young singer was praised as the voice of her generation.", "exampleZh": "這位年輕歌手被稱讚為她那一代的代表聲音。"}], "grammar": [{"pattern": "S + have/has + been + p.p.（現在完成式被動語態）", "explain": "表示「到目前為止已經被……」。文中 An old train station ... has been turned into a gallery 表示車站已被改造成藝廊，強調結果持續到現在。", "example": "The park has been cleaned by volunteers.", "exampleZh": "公園已經被志工清理乾淨了。"}, {"pattern": "N + p.p. 片語（過去分詞當形容詞修飾名詞）", "explain": "過去分詞片語放在名詞後面，相當於被動的關係子句。文中 works created by students = works which were created by students；a canvas painted by ... = a canvas which was painted by ...。", "example": "The cake made by my aunt was delicious.", "exampleZh": "我阿姨做的蛋糕很好吃。"}], "reading": [{"q": "What is this news report mainly about?", "options": ["A new high-speed train station in Taichung", "A student art exhibition held in an old train station", "A famous painting of the goddess Mazu", "A contest for the best art teacher"], "answer": 1, "explain": "第一段指出老車站 has been turned into a gallery，全文報導學生展覽，故選 (B)。"}, {"q": "According to Ms. Chen, where did most students say their inspiration came from?", "options": ["From museums", "From their teachers", "From daily life", "From famous critics"], "answer": 2, "explain": "第三段引述 their inspiration comes from daily life, not from museums，故選 (C)。"}, {"q": "What is special about the huge canvas in the main hall?", "options": ["It was painted by a famous artist.", "It tells a fable about a fox.", "It shows a night market at night.", "It combines a folk goddess with modern life."], "answer": 3, "explain": "第二段說畫中媽祖搭高鐵，是 a creative mix of folk belief and contemporary life，故選 (D)。"}, {"q": "The word \"setting\" in paragraph 4 is closest in meaning to ______.", "options": ["place", "price", "painting", "reason"], "answer": 0, "explain": "setting 指「場地、背景」，critics 稱讚車站建築是完美的場地，故選 (A)。"}, {"q": "What will happen on June 30?", "options": ["The mayor will give a speech.", "Students will paint a new canvas.", "The best piece will receive a prize.", "The station will be closed forever."], "answer": 2, "explain": "第四段說 The best piece ... will receive an award of NT$10,000 at the closing ceremony on June 30，故選 (C)。"}], "vocabQ": [{"q": "The science ____ at the museum attracts thousands of visitors every month.", "options": ["ceremony", "exhibition", "costume", "creation"], "answer": 1, "explain": "句意為「博物館的科學展覽每月吸引數千名參觀者」，exhibition 展覽。"}, {"q": "My grandfather can ____ beautiful dragons out of bamboo.", "options": ["compose", "exhibit", "carve", "award"], "answer": 2, "explain": "句意為「我爺爺能用竹子雕出美麗的龍」，carve 雕刻。"}, {"q": "The building looks very ____ with its glass walls and strange shapes.", "options": ["contemporary", "cultural", "folk", "fairy"], "answer": 0, "explain": "句意為「這棟建築有玻璃牆和奇特的形狀，看起來非常現代」，contemporary 當代的。"}, {"q": "The singer found her ____ for the new song while walking by the sea.", "options": ["illustration", "inspiration", "architecture", "exhibition"], "answer": 1, "explain": "句意為「歌手在海邊散步時找到新歌的靈感」，inspiration 靈感。"}, {"q": "Every ____ who saw the play said the acting was wonderful.", "options": ["dancer", "author", "composer", "critic"], "answer": 3, "explain": "句意為「每位看過這齣戲的評論家都說演技精彩」，critic 評論家。"}]}, {"id": "I35", "level": "inter", "num": 35, "title": "Diary of a Nervous Violinist", "titleZh": "一位緊張小提琴手的日記", "theme": "Arts & Culture", "themeZh": "藝術與文化", "article": ["Monday, October 6. Our school orchestra has only two weeks left before the autumn concert, and tonight's rehearsal was a disaster. We are playing the second movement of Dvorak's \"New World\" Symphony, which our conductor, Mr. Huang, calls a masterpiece. I know the melody by heart, but when the pianist sped up, I lost the rhythm completely and came in two bars late. Mr. Huang did not yell. He just looked at me, which was worse. On the way home I kept humming the tune on the MRT until a little girl stared at me.", "Thursday, October 9. Better today. I rehearsed alone in the small studio behind the music room for an hour before everyone arrived, and this time I counted silently through the hard part. Lily, our best violinist, sat beside me and told me the secret: do not listen to yourself; listen to the cellos. The posters for the performance went up in the hallway this afternoon. My name is on them, in very small letters, but it is there. Grandma says she will come even though she usually only likes opera.", "Saturday, October 18. We performed tonight. The hall was full, and in the first verse of the opening piece my hands were shaking so badly that I could barely hold the bow. Then the theme of the second movement began, slow and warm, and somehow I forgot to be afraid. The sound of sixty students playing together felt like one voice. Afterwards, Grandma hugged me and said it was the best lullaby she had ever heard, which made everyone laugh. Mr. Huang finally smiled. I think I will remember that smile longer than the applause."], "translation": ["10 月 6 日，星期一。我們學校管弦樂團距離秋季音樂會只剩兩週，而今晚的排練是一場災難。我們要演奏德弗札克《新世界》交響曲的第二樂章，指揮黃老師稱它為傑作。我已經把旋律背得滾瓜爛熟，但鋼琴手加快速度時，我完全失去節奏，晚了兩小節才進來。黃老師沒有大吼。他只是看著我，那更糟。回家的路上，我在捷運上一直哼著那段曲調，直到一個小女孩盯著我看。", "10 月 9 日，星期四。今天好一些。大家到之前，我先在音樂教室後面的小練習室獨自練了一小時，這次我在困難的段落默數拍子。我們最厲害的小提琴手 Lily 坐在我旁邊，告訴我祕訣：不要聽自己，要聽大提琴。演出的海報今天下午貼在走廊上了。我的名字在上面，字很小，但確實在那裡。奶奶說她會來，雖然她平常只喜歡歌劇。", "10 月 18 日，星期六。我們今晚演出了。音樂廳坐滿了人，開場曲的第一段，我的手抖得厲害，幾乎握不住琴弓。然後第二樂章的主題開始了，緩慢而溫暖，不知怎麼地我忘了害怕。六十個學生一起演奏的聲音，感覺像是同一個聲音。之後奶奶抱著我，說這是她聽過最好聽的搖籃曲，逗得大家都笑了。黃老師終於笑了。我想我會記得那個微笑，比記得掌聲更久。"], "vocab": [{"word": "rehearsal", "pos": "n.", "zh": "排練；彩排", "example": "The final rehearsal for the play is on Friday.", "exampleZh": "這齣戲的最後一次彩排在星期五。"}, {"word": "orchestra", "pos": "n.", "zh": "管弦樂團", "example": "She plays the cello in the city orchestra.", "exampleZh": "她在市立管弦樂團拉大提琴。"}, {"word": "symphony", "pos": "n.", "zh": "交響曲", "example": "Beethoven wrote nine symphonies.", "exampleZh": "貝多芬寫了九首交響曲。"}, {"word": "masterpiece", "pos": "n.", "zh": "傑作", "example": "The Mona Lisa is considered a masterpiece.", "exampleZh": "《蒙娜麗莎》被視為一件傑作。"}, {"word": "melody", "pos": "n.", "zh": "旋律", "example": "The melody of the song is easy to remember.", "exampleZh": "這首歌的旋律很容易記住。"}, {"word": "rhythm", "pos": "n.", "zh": "節奏", "example": "The drummer kept a steady rhythm.", "exampleZh": "鼓手保持穩定的節奏。"}, {"word": "tune", "pos": "n.", "zh": "曲調", "example": "Grandpa whistled an old tune while cooking.", "exampleZh": "爺爺一邊做菜一邊吹著一首老曲調。"}, {"word": "studio", "pos": "n.", "zh": "工作室；錄音室；練習室", "example": "The band recorded their album in a small studio.", "exampleZh": "樂團在一間小錄音室錄製他們的專輯。"}, {"word": "poster", "pos": "n.", "zh": "海報", "example": "There is a poster of the concert on the wall.", "exampleZh": "牆上有一張音樂會的海報。"}, {"word": "performance", "pos": "n.", "zh": "表演；演出", "example": "Her performance at the talent show was amazing.", "exampleZh": "她在才藝表演上的演出令人驚豔。"}], "phrases": [{"phrase": "by heart", "zh": "熟記；背下來", "example": "I know all the words of this song by heart.", "exampleZh": "這首歌的歌詞我全都背下來了。"}, {"phrase": "on the way home", "zh": "在回家路上", "example": "We bought bubble tea on the way home.", "exampleZh": "我們在回家路上買了珍珠奶茶。"}, {"phrase": "even though", "zh": "雖然；即使", "example": "He came to practice even though he was sick.", "exampleZh": "即使生病了，他還是來練習。"}], "grammar": [{"pattern": "S + V + so + adj./adv. + that + S + V", "explain": "「如此……以至於……」，so 後接形容詞或副詞，that 子句說明結果。文中 my hands were shaking so badly that I could barely hold the bow 表示手抖得厲害到幾乎握不住琴弓。", "example": "The music was so loud that we could not talk.", "exampleZh": "音樂大聲到我們無法交談。"}, {"pattern": "the + 最高級 + N + (that) + S + have/had ever + p.p.", "explain": "「某人曾經……過最……的」，用最高級加上完成式的 ever 來強調。文中 the best lullaby she had ever heard 表示「她聽過最好聽的搖籃曲」。", "example": "This is the most beautiful song I have ever heard.", "exampleZh": "這是我聽過最美的歌。"}], "reading": [{"q": "What went wrong at the rehearsal on October 6?", "options": ["The pianist forgot the melody.", "Mr. Huang yelled at the orchestra.", "The writer lost the rhythm and came in late.", "The writer forgot to bring the bow."], "answer": 2, "explain": "第一段說 I lost the rhythm completely and came in two bars late，故選 (C)。"}, {"q": "What advice did Lily give the writer?", "options": ["Listen to the cellos instead of yourself.", "Practice alone in the studio every day.", "Count the beats out loud.", "Ask Mr. Huang for extra lessons."], "answer": 0, "explain": "第二段 Lily 說 do not listen to yourself; listen to the cellos，故選 (A)。"}, {"q": "Why does the writer say Mr. Huang's look \"was worse\"?", "options": ["Mr. Huang looked tired.", "Silence made the writer feel guiltier than shouting would.", "Mr. Huang decided to remove the writer from the concert.", "The writer could not see Mr. Huang clearly."], "answer": 1, "explain": "第一段 He did not yell. He just looked at me, which was worse 暗示老師不說話的眼神比罵人更讓作者難受，故選 (B)。"}, {"q": "The word \"barely\" in paragraph 3 is closest in meaning to ______.", "options": ["easily", "always", "finally", "hardly"], "answer": 3, "explain": "barely 意為「幾乎不」，與 hardly 同義，故選 (D)。"}, {"q": "How did the writer feel at the end of the concert?", "options": ["Proud and moved", "Angry at the pianist", "Disappointed with Grandma", "Bored by the applause"], "answer": 0, "explain": "最後一段提到大家笑了、老師終於微笑，作者說會記得那個微笑比掌聲更久，表達感動與自豪，故選 (A)。"}], "vocabQ": [{"q": "The actors will have their last ____ the night before the show opens.", "options": ["rehearsal", "portrait", "sculpture", "statue"], "answer": 0, "explain": "句意為「演員在開演前一晚會做最後一次排練」，rehearsal 排練。"}, {"q": "More than eighty musicians play in the national ____.", "options": ["parade", "orchestra", "studio", "poster"], "answer": 1, "explain": "句意為「八十多位音樂家在國家管弦樂團演奏」，orchestra 管弦樂團。"}, {"q": "I cannot remember the words, but I can hum the ____.", "options": ["plot", "verse", "melody", "theme"], "answer": 2, "explain": "句意為「我記不得歌詞，但可以哼出旋律」，melody 旋律。"}, {"q": "Dancers must follow the ____ of the music carefully.", "options": ["poetry", "portrait", "literature", "rhythm"], "answer": 3, "explain": "句意為「舞者必須仔細跟著音樂的節奏」，rhythm 節奏。"}, {"q": "We put up a ____ in the hallway to tell students about the concert.", "options": ["poster", "pottery", "sketch", "tune"], "answer": 0, "explain": "句意為「我們在走廊貼了一張海報，告訴學生音樂會的消息」，poster 海報。"}]}, {"id": "I36", "level": "inter", "num": 36, "title": "The Night the Clown Went Live", "titleZh": "小丑現場直播之夜", "theme": "Entertainment & Media", "themeZh": "娛樂與媒體", "article": ["\"Are you sure this is a good idea?\" my cousin Mei-ling asked, pulling her red nose into place. It was the opening night of Dream Circus in Kaohsiung, and a television producer had just told her that the show would be televised live.", "Mei-ling had been a clown for only six months. Before that, she had worked as a newscaster at a small radio station, reading bulletins about traffic and weather. \"I wanted to entertain people, not inform them,\" she told me when she quit. Her parents thought she had gone crazy, but I had seen her make a whole bus laugh, so I believed in her.", "\"The preview went well yesterday,\" I said. \"The comedian who performed before you said you were the best entertainer he had seen all year.\" \"He was being kind,\" she whispered. \"Tonight there are cameras.\" At that moment the producer waved. \"Thirty seconds! And remember, do not look at the lens.\" Mei-ling took a deep breath and ran into the ring.", "What happened next became a headline the following morning. Halfway through her act, a firework meant for the finale went off early, and the ring filled with pink smoke. Instead of freezing, Mei-ling pretended to look for the firework, crawling under the elephant stand and sneezing loudly. The audience exploded with applause. The newspaper published a photo of her covered in pink powder, and the story was shared thousands of times online. The circus had never had such publicity. \"So,\" I asked her afterward, \"was it a good idea?\" She grinned under the paint. \"The best idea I have ever had. Next time, though, I want to know where the fireworks are.\""], "translation": ["「你確定這是個好主意嗎？」我表姊美玲一邊把紅鼻子戴正一邊問。那是夢想馬戲團在高雄的開幕之夜，一位電視製作人剛剛告訴她，演出將會現場直播。", "美玲當小丑才六個月。在那之前，她在一家小廣播電台當新聞播報員，播報交通和天氣的簡訊。她辭職時告訴我：「我想娛樂大家，而不是告知大家。」她的父母覺得她瘋了，但我曾看過她逗得整台公車的人大笑，所以我相信她。", "「昨天的預演很順利，」我說。「在你之前表演的那位喜劇演員說，你是他今年看過最棒的表演者。」「他只是客氣，」她小聲說。「今晚有攝影機。」就在那時，製作人揮了揮手。「三十秒！記住，不要看鏡頭。」美玲深吸一口氣，跑進了表演場。", "接下來發生的事成了隔天早上的頭條。她的表演進行到一半時，一枚原本要留到壓軸的煙火提早施放，整個表演場充滿粉紅色的煙霧。美玲沒有愣住，反而假裝在找那枚煙火，爬到大象的台子底下，還大聲打噴嚏。觀眾爆出如雷的掌聲。報紙刊登了她全身沾滿粉紅色粉末的照片，這則故事在網路上被分享了數千次。馬戲團從來沒有得到過這樣的宣傳。「所以，」事後我問她，「這是個好主意嗎？」她在妝容下咧嘴笑了。「我這輩子最好的主意。不過，下次我想先知道煙火在哪裡。」"], "vocab": [{"word": "entertain", "pos": "v.", "zh": "娛樂；使歡樂", "example": "The magician entertained the children for an hour.", "exampleZh": "魔術師逗孩子們開心了一個小時。"}, {"word": "clown", "pos": "n.", "zh": "小丑", "example": "The clown at the party made balloon animals.", "exampleZh": "派對上的小丑做了氣球動物。"}, {"word": "producer", "pos": "n.", "zh": "製作人", "example": "The producer decided to film the show in Tainan.", "exampleZh": "製作人決定在台南拍攝這個節目。"}, {"word": "televise", "pos": "v.", "zh": "電視轉播", "example": "The baseball final will be televised nationwide.", "exampleZh": "棒球決賽將在全國電視轉播。"}, {"word": "bulletin", "pos": "n.", "zh": "簡報；公告", "example": "The weather bulletin warned of heavy rain tonight.", "exampleZh": "天氣簡報警告今晚有大雨。"}, {"word": "preview", "pos": "n.", "zh": "預演；預告", "example": "We watched a preview of the new movie online.", "exampleZh": "我們在網路上看了新電影的預告。"}, {"word": "comedian", "pos": "n.", "zh": "喜劇演員", "example": "The comedian's jokes made the whole room laugh.", "exampleZh": "那位喜劇演員的笑話讓全場大笑。"}, {"word": "headline", "pos": "n.", "zh": "頭條新聞；標題", "example": "The earthquake was the headline in every newspaper.", "exampleZh": "那場地震是每家報紙的頭條。"}, {"word": "applause", "pos": "n.", "zh": "掌聲", "example": "The singer bowed as the applause grew louder.", "exampleZh": "掌聲越來越大時，歌手鞠了躬。"}, {"word": "publicity", "pos": "n.", "zh": "宣傳；知名度", "example": "The new restaurant got a lot of publicity from the news report.", "exampleZh": "那家新餐廳因新聞報導得到很多宣傳。"}], "phrases": [{"phrase": "take a deep breath", "zh": "深吸一口氣", "example": "Take a deep breath before you walk on stage.", "exampleZh": "上台前先深吸一口氣。"}, {"phrase": "go off", "zh": "（煙火、炸彈等）爆開；（鬧鐘）響", "example": "The fireworks went off at exactly midnight.", "exampleZh": "煙火在午夜整點施放。"}, {"phrase": "believe in", "zh": "相信（某人的能力）", "example": "My coach always believed in me.", "exampleZh": "我的教練一直相信我。"}], "grammar": [{"pattern": "S + V ..., V-ing ...（分詞構句表示同時進行的動作）", "explain": "用現在分詞片語補充說明主詞同時在做的另一個動作，兩個動作的主詞相同。文中 Mei-ling asked, pulling her red nose into place 表示她一邊問一邊戴正鼻子。", "example": "She walked into the room, carrying a big box.", "exampleZh": "她抱著一個大箱子走進房間。"}, {"pattern": "What + V ... + V（what 引導的名詞子句當主詞）", "explain": "what 子句可以當整句的主詞，意思是「……的事情」。文中 What happened next became a headline 的主詞是 What happened next（接下來發生的事）。", "example": "What she said surprised everyone.", "exampleZh": "她說的話讓大家都很驚訝。"}], "reading": [{"q": "What did Mei-ling do before she became a clown?", "options": ["She was a comedian in a circus.", "She was a television producer.", "She sold tickets at a cinema.", "She read news bulletins on the radio."], "answer": 3, "explain": "第二段說 she had worked as a newscaster at a small radio station, reading bulletins，故選 (D)。"}, {"q": "What did the producer tell Mei-ling to remember?", "options": ["To smile at the audience", "To avoid looking at the camera", "To run into the ring quickly", "To wait for the fireworks"], "answer": 1, "explain": "第三段製作人說 do not look at the lens，故選 (B)。"}, {"q": "What went wrong during Mei-ling's act?", "options": ["A firework went off too early.", "An elephant ran into the ring.", "The cameras stopped working.", "She forgot her lines."], "answer": 0, "explain": "第四段說 a firework meant for the finale went off early，故選 (A)。"}, {"q": "The word \"freezing\" in paragraph 4 is closest in meaning to ______.", "options": ["feeling cold", "crying loudly", "standing still in shock", "running away"], "answer": 2, "explain": "此處 freezing 指「嚇得僵住不動」，與後面假裝找煙火的動作相對，故選 (C)。"}, {"q": "How did Mei-ling feel about the night afterward?", "options": ["She regretted joining the circus.", "She was happy but wanted to be better prepared.", "She was angry with the producer.", "She decided to go back to radio."], "answer": 1, "explain": "最後她說 The best idea I have ever had，但又說下次想先知道煙火在哪，表示滿意但希望更有準備，故選 (B)。"}], "vocabQ": [{"q": "Grandpa likes to ____ the kids with funny stories about his childhood.", "options": ["entertain", "publish", "televise", "applaud"], "answer": 0, "explain": "句意為「爺爺喜歡用他童年的趣事逗孩子們開心」，entertain 娛樂。"}, {"q": "The ____ of the show asked the singer to change her costume.", "options": ["newscaster", "producer", "publisher", "idol"], "answer": 1, "explain": "句意為「節目製作人要求歌手換服裝」，producer 製作人。"}, {"q": "The ____ on the front page said that the typhoon had changed direction.", "options": ["journal", "edition", "headline", "circus"], "answer": 2, "explain": "句意為「頭版的頭條說颱風改變了方向」，headline 頭條。"}, {"q": "After the final song, the ____ lasted for almost five minutes.", "options": ["preview", "bulletin", "firework", "applause"], "answer": 3, "explain": "句意為「最後一首歌之後，掌聲持續了將近五分鐘」，applause 掌聲。"}, {"q": "The movie received so much ____ that tickets sold out in one day.", "options": ["publicity", "comedy", "entertainment", "cinema"], "answer": 0, "explain": "句意為「這部電影得到大量宣傳，票一天內就賣光」，publicity 宣傳。"}]}, {"id": "I37", "level": "inter", "num": 37, "title": "More Than a Race: Taiwan's Marathon Fever", "titleZh": "不只是比賽：台灣的馬拉松熱", "theme": "Sports & Leisure", "themeZh": "運動與休閒", "article": ["Twenty years ago, running was something most people in Taiwan did only in PE class. Today, on almost every weekend from October to March, thousands of runners gather before dawn for a marathon somewhere on the island. From the Taipei Marathon, which starts outside the city stadium, to small races along the east coast, the sport has become one of the most popular forms of recreation in the country.", "What makes these events special is that most competitors are amateurs. A typical race includes a few professional athletes who compete for the title of champion and a medal, but behind them run office workers, grandmothers, students, and sometimes a man dressed as a bubble tea cup. Many of them do not care about their opponents at all. Their only competition is with themselves: to finish, or to run a little faster than last year.", "The spectators are part of the show. Along the route, families hand out water and sliced oranges, temple volunteers beat drums, and elementary school children hold signs that say \"Keep going, uncle!\" In Taitung, where the race passes rice fields and the Pacific Ocean, some runners stop to take photos, as if the event were an adventure rather than a race.", "Doctors point out that this kind of outdoor leisure brings more than fitness. Training for a marathon gives people a goal, a reason to sleep early, and a group of friends who share the same early-morning suffering. \"Running is my relaxation,\" says a 52-year-old climber and hiker from Hualien who finished her tenth marathon last winter. \"For four hours, nobody can call me about work.\" For a growing number of people, that may be the best prize of all."], "translation": ["二十年前，跑步是大多數台灣人只在體育課才做的事。如今，從十月到三月幾乎每個週末，都有數千名跑者在天亮前聚集，參加島上某處的馬拉松。從在市立體育場外起跑的台北馬拉松，到東海岸的小型賽事，這項運動已成為全國最受歡迎的休閒活動之一。", "讓這些活動特別的地方，在於大多數參賽者都是業餘選手。典型的比賽包括少數為冠軍頭銜和獎牌而競爭的職業運動員，但跟在他們後面跑的是上班族、奶奶、學生，有時還有一位打扮成珍珠奶茶杯的男子。他們很多人根本不在乎對手。他們唯一的競爭是和自己：跑完全程，或是比去年跑快一點。", "觀眾也是這場秀的一部分。沿途，家家戶戶發放水和切片柳丁，廟宇的志工敲鑼打鼓，國小學童舉著寫有「加油，叔叔！」的牌子。在台東，賽道經過稻田和太平洋，有些跑者會停下來拍照，彷彿這場活動是一場冒險而不是比賽。", "醫生指出，這種戶外休閒帶來的不只是體能。為馬拉松訓練給人一個目標、一個早睡的理由，以及一群分擔同樣清晨之苦的朋友。「跑步是我的放鬆方式，」一位 52 歲、來自花蓮的登山客兼健行者說，她去年冬天完成了第十場馬拉松。「四個小時裡，沒有人可以打電話找我談工作。」對越來越多的人來說，這或許才是最好的獎品。"], "vocab": [{"word": "marathon", "pos": "n.", "zh": "馬拉松", "example": "My uncle finished his first marathon in five hours.", "exampleZh": "我叔叔花五小時跑完他的第一場馬拉松。"}, {"word": "stadium", "pos": "n.", "zh": "體育場", "example": "The new stadium can hold forty thousand fans.", "exampleZh": "新體育場可以容納四萬名球迷。"}, {"word": "recreation", "pos": "n.", "zh": "休閒活動；娛樂", "example": "The park offers many kinds of recreation for families.", "exampleZh": "這座公園為家庭提供許多種休閒活動。"}, {"word": "competitor", "pos": "n.", "zh": "參賽者；競爭者", "example": "Over a thousand competitors joined the swimming race.", "exampleZh": "一千多名參賽者參加了游泳比賽。"}, {"word": "amateur", "pos": "n.", "zh": "業餘愛好者", "example": "The photo contest is open to amateurs only.", "exampleZh": "這場攝影比賽只開放給業餘愛好者參加。"}, {"word": "athlete", "pos": "n.", "zh": "運動員", "example": "The athlete trains six hours a day.", "exampleZh": "這位運動員每天訓練六小時。"}, {"word": "champion", "pos": "n.", "zh": "冠軍", "example": "She became the national table tennis champion at sixteen.", "exampleZh": "她十六歲就成為全國桌球冠軍。"}, {"word": "medal", "pos": "n.", "zh": "獎牌", "example": "Taiwan won two gold medals at the games.", "exampleZh": "台灣在這次運動會贏得兩面金牌。"}, {"word": "opponent", "pos": "n.", "zh": "對手", "example": "He shook hands with his opponent after the match.", "exampleZh": "比賽後他和對手握手。"}, {"word": "spectator", "pos": "n.", "zh": "觀眾", "example": "Thousands of spectators cheered in the rain.", "exampleZh": "數千名觀眾在雨中歡呼。"}], "phrases": [{"phrase": "hand out", "zh": "分發", "example": "Volunteers handed out water to the runners.", "exampleZh": "志工發水給跑者。"}, {"phrase": "point out", "zh": "指出", "example": "The coach pointed out that rest is as important as training.", "exampleZh": "教練指出休息和訓練一樣重要。"}, {"phrase": "rather than", "zh": "而不是", "example": "I prefer hiking rather than shopping on weekends.", "exampleZh": "週末我比較喜歡健行而不是逛街。"}], "grammar": [{"pattern": "as if + S + were/過去式 V（與現在事實相反的假設）", "explain": "as if 表示「彷彿」，後面用過去式（be 動詞用 were）表示與事實不符的想像。文中 as if the event were an adventure 表示比賽其實不是冒險，只是看起來像。", "example": "He talks as if he were the champion.", "exampleZh": "他說話的樣子彷彿他是冠軍一樣。"}, {"pattern": "one of the + 最高級 + 複數名詞", "explain": "「最……之一」，最高級後面的名詞要用複數。文中 one of the most popular forms of recreation 表示「最受歡迎的休閒活動之一」。", "example": "Jade Mountain is one of the highest mountains in East Asia.", "exampleZh": "玉山是東亞最高的山之一。"}], "reading": [{"q": "What is the passage mainly about?", "options": ["How marathons have become a popular leisure activity in Taiwan", "How to train for the Taipei Marathon", "Why professional athletes love Taitung", "The history of the city stadium"], "answer": 0, "explain": "全文說明馬拉松在台灣成為受歡迎的休閒活動，以及參賽者和觀眾的情況，故選 (A)。"}, {"q": "According to paragraph 2, who are most of the competitors?", "options": ["Professional athletes", "Doctors and nurses", "Ordinary people who run for fun", "Foreign visitors"], "answer": 2, "explain": "第二段說 most competitors are amateurs，並舉出上班族、奶奶、學生等例子，故選 (C)。"}, {"q": "The word \"route\" in paragraph 3 is closest in meaning to ______.", "options": ["river", "path", "rule", "prize"], "answer": 1, "explain": "route 指「路線」，後文描述沿途觀眾的行為，故選 (B)。"}, {"q": "Which of the following do spectators do, according to the passage?", "options": ["Take photos of the ocean", "Run with the athletes", "Give medals to the winners", "Beat drums and hold signs"], "answer": 3, "explain": "第三段提到 temple volunteers beat drums 以及 children hold signs，故選 (D)。"}, {"q": "What does the 52-year-old runner mean by \"nobody can call me about work\"?", "options": ["She lost her phone during the race.", "She has no job.", "Running gives her a break from work pressure.", "Her office is closed on weekends."], "answer": 2, "explain": "她說 Running is my relaxation，四小時內沒人能找她談工作，表示跑步讓她暫時擺脫工作壓力，故選 (C)。"}], "vocabQ": [{"q": "Although he is only an ____, his paintings sell very well.", "options": ["opponent", "amateur", "athlete", "examiner"], "answer": 1, "explain": "句意為「雖然他只是業餘愛好者，他的畫卻賣得很好」，amateur 業餘者。"}, {"q": "Every ____ must have a health check before the Olympic Games.", "options": ["athlete", "spectator", "champion", "climber"], "answer": 0, "explain": "句意為「每位運動員在奧運前都必須做健康檢查」，athlete 運動員。"}, {"q": "Every ____ stood up and cheered when the home team scored.", "options": ["competitor", "opponent", "spectator", "medal"], "answer": 2, "explain": "句意為「主隊得分時，每位觀眾都起立歡呼」，spectator 觀眾。"}, {"q": "After winning three games in a row, she was named the ____ of the tournament.", "options": ["stadium", "spectator", "hiker", "champion"], "answer": 3, "explain": "句意為「連贏三場後，她被封為這次錦標賽的冠軍」，champion 冠軍。"}, {"q": "Our ____ in the final is a team from Kaohsiung that has never lost.", "options": ["opponent", "recreation", "marathon", "leisure"], "answer": 0, "explain": "句意為「我們決賽的對手是一支從未輸過的高雄隊伍」，opponent 對手。"}]}, {"id": "I38", "level": "inter", "num": 38, "title": "Inside My Grandfather's Hardware Shop", "titleZh": "走進爺爺的五金行", "theme": "Materials & Objects", "themeZh": "材料與物品", "article": ["My grandfather's hardware shop sits at the corner of a narrow lane in Sanchong, between a breakfast stand and a temple. From the outside, it looks like a dark cave filled with dirt and old boxes. Inside, however, every object has its place, and Grandpa can find any of them with his eyes closed.", "The walls are covered with hooks, and from each hook hangs something different: coils of copper wire, rubber hoses, elastic cords, and chains of every thickness. Along the left side stand barrels of nails and screws, sorted by size into plastic containers with hand-written labels. On the shelves above them sit jars of brass clips, boxes of drill bits, and a few bags of cement and clay that the neighbors buy for small repairs. Near the counter, Grandpa keeps his most expensive equipment: electric drills, a small crane for lifting engines, and a cutting machine that throws out sparks like tiny flames.", "What I love most are the strange things that no one seems to buy. There is an old wooden bow with three arrows, an ax with a cracked handle, a walking cane made of bamboo, and a glass jar of crystal beads that Grandma used to make bracelets. Grandpa says every piece has a story. The bow, for instance, belonged to a customer who could not pay his bill in 1985, so he left it as a gift instead.", "People often ask why Grandpa does not sell the shop, since the land is worth a lot of money now. He always gives the same answer. \"A hardware shop is like a doctor's office,\" he says, wiping his hands on an oily cloth. \"When something breaks at midnight, people need to know where to go.\" Then he hands me a booklet of prices, and I go back to counting screws."], "translation": ["我爺爺的五金行坐落在三重一條窄巷的轉角，夾在早餐店和廟之間。從外面看，它像一個堆滿灰塵和舊箱子的黑暗洞穴。然而在裡面，每樣東西都有它的位置，爺爺閉著眼睛也能找到任何一樣。", "牆上掛滿了掛鉤，每個掛鉤上都吊著不同的東西：一圈圈的銅線、橡膠水管、彈性繩，還有各種粗細的鏈條。左側立著一桶桶的釘子和螺絲，依大小分裝在貼有手寫標籤的塑膠容器裡。上方的架子上放著一罐罐黃銅夾子、一盒盒鑽頭，還有幾袋鄰居買來做小修繕的水泥和黏土。櫃檯附近，爺爺放著他最貴的設備：電鑽、一台吊引擎用的小型起重機，以及一台噴出火花像小火焰的切割機。", "我最喜歡的是那些似乎沒有人會買的奇怪東西。有一把舊木弓配三支箭、一把握柄裂開的斧頭、一根竹子做的拐杖，還有一玻璃罐奶奶以前用來做手鍊的水晶珠子。爺爺說每一件都有故事。例如那把弓，原本屬於一位 1985 年付不出帳單的客人，所以他把它留下來當作禮物。", "人們常問爺爺為什麼不把店賣掉，因為那塊地現在值很多錢。他總是給同樣的答案。「五金行就像診所，」他一邊說，一邊用一塊油膩的布擦手。「半夜東西壞掉的時候，大家得知道該去哪裡。」然後他遞給我一本價目小冊子，我又回去數螺絲了。"], "vocab": [{"word": "hardware", "pos": "n.", "zh": "五金；硬體", "example": "You can buy nails and locks at the hardware store.", "exampleZh": "你可以在五金行買釘子和鎖。"}, {"word": "hook", "pos": "n.", "zh": "掛鉤", "example": "Hang your coat on the hook behind the door.", "exampleZh": "把你的外套掛在門後的掛鉤上。"}, {"word": "copper", "pos": "n.", "zh": "銅", "example": "Copper is used in many electric wires.", "exampleZh": "銅被用在許多電線裡。"}, {"word": "elastic", "pos": "adj.", "zh": "有彈性的", "example": "The waist of these pants is elastic.", "exampleZh": "這條褲子的腰是有彈性的。"}, {"word": "barrel", "pos": "n.", "zh": "桶", "example": "The farmer stored rainwater in a big barrel.", "exampleZh": "農夫把雨水儲存在一個大桶裡。"}, {"word": "container", "pos": "n.", "zh": "容器", "example": "Put the leftovers in a plastic container.", "exampleZh": "把剩菜放進塑膠容器裡。"}, {"word": "cement", "pos": "n.", "zh": "水泥", "example": "The workers mixed cement to build the wall.", "exampleZh": "工人攪拌水泥來砌牆。"}, {"word": "equipment", "pos": "n.", "zh": "設備；裝備", "example": "The school bought new equipment for the science lab.", "exampleZh": "學校為科學實驗室買了新設備。"}, {"word": "crane", "pos": "n.", "zh": "起重機", "example": "A crane lifted the heavy steel beams onto the roof.", "exampleZh": "一台起重機把沉重的鋼樑吊到屋頂上。"}, {"word": "cloth", "pos": "n.", "zh": "布", "example": "Wipe the table with a wet cloth.", "exampleZh": "用濕布擦桌子。"}], "phrases": [{"phrase": "be covered with", "zh": "被……覆蓋；布滿", "example": "The ground was covered with fallen leaves.", "exampleZh": "地上布滿了落葉。"}, {"phrase": "for instance", "zh": "例如", "example": "Some tools, for instance drills, are dangerous for children.", "exampleZh": "有些工具，例如電鑽，對兒童是危險的。"}, {"phrase": "be worth", "zh": "值……", "example": "This old coin is worth a lot of money.", "exampleZh": "這枚舊硬幣值很多錢。"}], "grammar": [{"pattern": "地方副詞片語 + V + S（地方副詞倒裝句）", "explain": "把表示地點的介系詞片語放在句首時，主詞和動詞要倒裝，常用於描寫景物。文中 from each hook hangs something different、Along the left side stand barrels ... 都是這種倒裝。", "example": "On the table lies an old map.", "exampleZh": "桌上放著一張舊地圖。"}, {"pattern": "S + V ..., since + S + V（since 表示「因為」）", "explain": "since 除了「自從」，也可以當「因為」，用來說明大家已知的理由。文中 since the land is worth a lot of money now 說明為什麼大家問爺爺為何不賣店。", "example": "Since it was late, we took a taxi home.", "exampleZh": "因為時間很晚了，我們搭計程車回家。"}], "reading": [{"q": "Where is the grandfather's shop located?", "options": ["Next to a train station", "Between a breakfast stand and a temple", "Inside a dark cave", "On the main road of Sanchong"], "answer": 1, "explain": "第一段說 between a breakfast stand and a temple，故選 (B)。"}, {"q": "What does Grandpa keep near the counter?", "options": ["Bags of cement and clay", "Jars of brass clips", "Barrels of nails and screws", "His most expensive equipment"], "answer": 3, "explain": "第二段說 Near the counter, Grandpa keeps his most expensive equipment，故選 (D)。"}, {"q": "How did the wooden bow come to the shop?", "options": ["A customer left it because he could not pay.", "Grandpa bought it in 1985.", "Grandma made it for the children.", "A neighbor gave it in exchange for cement."], "answer": 0, "explain": "第三段說弓 belonged to a customer who could not pay his bill in 1985, so he left it as a gift，故選 (A)。"}, {"q": "The word \"sorted\" in paragraph 2 is closest in meaning to ______.", "options": ["sold", "hidden", "arranged", "mixed"], "answer": 2, "explain": "sorted by size 意為「依大小分類整理」，與 arranged 意思最接近，故選 (C)。"}, {"q": "Why does Grandpa refuse to sell the shop?", "options": ["The land is not worth much.", "He believes people need the shop in emergencies.", "He wants the writer to run it one day.", "He cannot find a buyer."], "answer": 1, "explain": "第四段爺爺說五金行像診所，When something breaks at midnight, people need to know where to go，故選 (B)。"}], "vocabQ": [{"q": "Dad went to the ____ store to buy a new lock for the front door.", "options": ["hardware", "jewel", "handbag", "fuel"], "answer": 0, "explain": "句意為「爸爸去五金行買大門的新鎖」，hardware 五金。"}, {"q": "The old pot is made of ____, so it turns green when it gets wet.", "options": ["cloth", "foam", "ivory", "copper"], "answer": 3, "explain": "句意為「這個舊鍋子是銅做的，所以遇水會變綠」，copper 銅（銅鏽為綠色）。"}, {"q": "The fishermen kept the day's catch in a large wooden ____.", "options": ["collar", "barrel", "column", "bracelet"], "answer": 1, "explain": "句意為「漁夫把當天的漁獲放在一個大木桶裡」，barrel 桶。"}, {"q": "Please put the cookies in an airtight ____ so they stay fresh.", "options": ["cane", "frame", "container", "chain"], "answer": 2, "explain": "句意為「請把餅乾放進密封容器裡保持新鮮」，container 容器。"}, {"q": "The hospital received new medical ____ from the government.", "options": ["equipment", "cement", "dirt", "coal"], "answer": 0, "explain": "句意為「醫院收到政府提供的新醫療設備」，equipment 設備。"}]}, {"id": "I39", "level": "inter", "num": 39, "title": "My Honest Review of a Camping Kit", "titleZh": "一組露營套件的誠實評測", "theme": "Materials & Objects", "themeZh": "材料與物品", "article": ["Last month I bought the \"Mountain Buddy Camping Kit\" online for NT$1,990, and several readers have asked whether it is worth the money. After two weekends at Wuling Farm, here is my honest review.", "First, the good news. The tent poles are made of steel instead of cheap plastic, so they did not bend in the strong wind on the first night. The nylon ropes are thick, and the metal stakes went into the hard ground without a problem. I also liked the small lantern, which runs on a battery and gives enough light to read by. The kit comes with a leather pouch for scissors, a can opener, and a tiny saw. All of these are real tools, not toys.", "Now the bad news. The sleeping pad is only one layer thick, so I could feel every log and stone under my back. The torch stopped working on the second day because a wire inside had come loose. The wrapping around the tent was a thin plastic bag that tore before I even reached the campsite, and the label on the box says \"waterproof,\" but the tent floor was wet after a light rain. The instruction booklet is half in Japanese, and the English notes in the margin are too small to read without a torch, which, as I said, was broken.", "My verdict: this kit is good for beginners who camp two or three times a year, but serious campers will replace half of its stuff within a season. If you buy it, bring your own sleeping pad and a roll of string for repairs. And keep the box; the plastic bags inside make great junk bags for packing up your trash. Four stars for the poles, two for the rest."], "translation": ["上個月我在網路上花新台幣 1,990 元買了「山友露營套件」，有幾位讀者問我它值不值得這個價錢。在武陵農場度過兩個週末之後，以下是我的誠實評測。", "先說好消息。帳篷的桿子是鋼製而不是廉價塑膠做的，所以第一晚的強風中沒有彎掉。尼龍繩很粗，金屬營釘毫無問題地釘進了堅硬的地面。我也喜歡那盞小燈籠，它用電池運作，光線足以用來看書。套件附有一個皮革小袋，裝著剪刀、開罐器和一把小鋸子。這些都是真正的工具，不是玩具。", "接著是壞消息。睡墊只有一層厚，所以我背後每一根木頭和石頭都感覺得到。手電筒第二天就不亮了，因為裡面的一條電線鬆脫了。帳篷外的包裝是一個薄塑膠袋，我還沒到營地就破了；盒子上的標籤寫著「防水」，但一場小雨過後帳篷地板就濕了。說明小冊子有一半是日文，頁邊空白處的英文註解小到沒有手電筒就看不清——而手電筒，如我所說，已經壞了。", "我的結論：這組套件適合一年露營兩三次的新手，但認真的露營者在一季內就會換掉一半的東西。如果你要買，請自備睡墊和一捲繩子以備修補。還有，把盒子留著；裡面的塑膠袋很適合當垃圾袋來收拾垃圾。桿子四顆星，其餘兩顆星。"], "vocab": [{"word": "kit", "pos": "n.", "zh": "成套工具；套件", "example": "Every car should carry a first-aid kit.", "exampleZh": "每輛車都應該備有急救箱。"}, {"word": "steel", "pos": "n.", "zh": "鋼", "example": "The bridge is made of steel and concrete.", "exampleZh": "這座橋是用鋼和混凝土建造的。"}, {"word": "nylon", "pos": "n.", "zh": "尼龍", "example": "These socks are made of nylon and cotton.", "exampleZh": "這些襪子是尼龍和棉做的。"}, {"word": "stake", "pos": "n.", "zh": "樁；營釘", "example": "We hammered the stakes into the ground to hold the tent.", "exampleZh": "我們把營釘敲進地裡固定帳篷。"}, {"word": "lantern", "pos": "n.", "zh": "燈籠；提燈", "example": "Red lanterns hung along the street during the festival.", "exampleZh": "節慶期間街上掛滿了紅燈籠。"}, {"word": "leather", "pos": "n.", "zh": "皮革", "example": "My father's leather wallet is twenty years old.", "exampleZh": "我爸爸的皮夾已經二十年了。"}, {"word": "pad", "pos": "n.", "zh": "墊子；便條本", "example": "Put a soft pad under the laptop to protect the table.", "exampleZh": "在筆電下放一塊軟墊來保護桌子。"}, {"word": "torch", "pos": "n.", "zh": "手電筒；火把", "example": "Bring a torch in case the lights go out.", "exampleZh": "帶支手電筒，以防停電。"}, {"word": "wire", "pos": "n.", "zh": "電線；金屬線", "example": "Do not touch the broken wire.", "exampleZh": "不要碰那條斷掉的電線。"}, {"word": "label", "pos": "n.", "zh": "標籤", "example": "Read the label before you take the medicine.", "exampleZh": "吃藥前先看標籤。"}], "phrases": [{"phrase": "be made of", "zh": "由……製成", "example": "The table is made of solid wood.", "exampleZh": "這張桌子是實木做的。"}, {"phrase": "come loose", "zh": "鬆脫", "example": "One of the screws on the chair has come loose.", "exampleZh": "椅子上有一顆螺絲鬆脫了。"}, {"phrase": "run on", "zh": "以……為動力運作", "example": "This clock runs on two small batteries.", "exampleZh": "這個時鐘用兩顆小電池運作。"}], "grammar": [{"pattern": "S + be + too + adj. + to + V", "explain": "「太……而不能……」。文中 the English notes ... are too small to read 表示字太小而無法閱讀。注意 to 後面的動詞不再加受詞，因為主詞就是受詞。", "example": "The box is too heavy to carry.", "exampleZh": "這個箱子太重，搬不動。"}, {"pattern": "S + V + whether + S + V（whether 引導的名詞子句）", "explain": "whether 意為「是否」，引導名詞子句當動詞的受詞。文中 asked whether it is worth the money 表示「問它是否值得」。", "example": "I wonder whether the shop is open today.", "exampleZh": "我想知道那家店今天是否有開。"}], "reading": [{"q": "What is the purpose of this passage?", "options": ["To teach readers how to set up a tent", "To describe a trip to Wuling Farm", "To advertise a new camping product", "To tell readers whether a camping kit is worth buying"], "answer": 3, "explain": "第一段說讀者問 whether it is worth the money，作者因此寫下評測，故選 (D)。"}, {"q": "Why did the writer like the tent poles?", "options": ["They were strong enough for strong wind.", "They were made of light plastic.", "They came in many colors.", "They were easy to fold."], "answer": 0, "explain": "第二段說桿子是鋼製的，so they did not bend in the strong wind，故選 (A)。"}, {"q": "What happened to the torch?", "options": ["It was lost at the campsite.", "It got wet in the rain.", "A wire inside came loose.", "Its battery was missing."], "answer": 2, "explain": "第三段說 The torch stopped working ... because a wire inside had come loose，故選 (C)。"}, {"q": "The word \"verdict\" in paragraph 4 is closest in meaning to ______.", "options": ["price", "final opinion", "warning", "complaint"], "answer": 1, "explain": "verdict 原指「判決」，此處指作者的最終評價，故選 (B)。"}, {"q": "Who does the writer think should buy this kit?", "options": ["People who camp only a few times a year", "Serious campers who go out every weekend", "Readers who already own a good tent", "People who need a good torch"], "answer": 0, "explain": "第四段說 this kit is good for beginners who camp two or three times a year，故選 (A)。"}], "vocabQ": [{"q": "The nurse opened the first-aid ____ and took out a bandage.", "options": ["kit", "vase", "sack", "tray"], "answer": 0, "explain": "句意為「護士打開急救箱拿出繃帶」，kit 成套工具。"}, {"q": "The knife is made of ____, so it will not rust easily.", "options": ["wool", "silk", "steel", "linen"], "answer": 2, "explain": "句意為「這把刀是鋼做的，所以不容易生鏽」，steel 鋼。"}, {"q": "Grandpa's ____ shoes still look new after ten years.", "options": ["plastic", "leather", "marble", "nylon"], "answer": 1, "explain": "句意為「爺爺的皮鞋十年後看起來還像新的」，leather 皮革。"}, {"q": "Check the ____ on the bottle to see how much sugar the drink has.", "options": ["knot", "loop", "ribbon", "label"], "answer": 3, "explain": "句意為「看瓶子上的標籤，了解飲料含多少糖」，label 標籤。"}, {"q": "When the power went out, Dad found a ____ and led us to the door.", "options": ["torch", "shovel", "ladder", "razor"], "answer": 0, "explain": "句意為「停電時，爸爸找到一支手電筒帶我們走到門口」，torch 手電筒。"}]}, {"id": "I40", "level": "inter", "num": 40, "title": "Escape from the Flooded Basement", "titleZh": "逃出淹水的地下室", "theme": "Actions & Movement", "themeZh": "動作與移動", "article": ["I had never seen rain like that before. Typhoon Haikui was approaching Yilan faster than the weather bureau had predicted, and by three in the afternoon the street outside our family's bookstore had turned into a brown river. My father and I were in the basement, attempting to carry boxes of new books upstairs, when the lights went out with a loud bang.", "\"Leave the books,\" Dad said. \"We're abandoning the basement.\" But as we climbed, water began to pour down the stairs, and the old wooden shelf beside the entry collapsed, blocking our way. For a second I just stood there, blinking in the dark. Then I heard Dad cough, and I understood that we had to cope with this ourselves. I fastened my phone inside a plastic bag, switched on its light, and crawled under the fallen shelf. The gap was small, and a nail cracked the screen, but I emerged on the other side and started dragging the shelf aside.", "Dad could not fit through, so we tried another way. He bent the thin metal pole of a lamp, and I used it to assist him in pushing the shelf while I pulled. The water was now up to my knees, cold and smelling of mud. After several attempts, the shelf shifted just enough, and Dad crept through. We dashed up the last steps and burst into the shop, where my mother was waiting with towels and a very loud voice.", "The books in the basement were destroyed, and we spent a week dumping wet paper into trucks. But my father did not look sad. \"Possessions can be replaced,\" he said, adjusting his glasses with a shaking hand. \"The important thing is that we encountered the flood together and escaped together.\" I did not say anything. I just held the towel tighter."], "translation": ["我從來沒見過那樣的雨。海葵颱風逼近宜蘭的速度比氣象局預測的還快，到了下午三點，我們家書店外的街道已經變成一條棕色的河。我和爸爸在地下室，正試著把一箱箱新書搬上樓，這時燈「砰」的一聲熄滅了。", "「書別管了，」爸爸說。「我們放棄地下室。」但我們往上爬時，水開始沿著樓梯灌下來，入口旁邊那座老舊的木書架倒了，擋住我們的路。有那麼一秒，我只是站在那裡，在黑暗中眨著眼睛。然後我聽到爸爸咳嗽，我明白我們必須自己應付這個狀況。我把手機固定在塑膠袋裡，打開手機的燈，從倒下的書架底下爬過去。縫隙很小，一根釘子把螢幕刮裂了，但我從另一邊鑽了出來，開始把書架拖到一旁。", "爸爸鑽不過去，所以我們試了另一個方法。他把一盞檯燈細細的金屬桿折彎，我用它協助他推書架，同時我在這邊拉。水現在已經淹到我的膝蓋，又冷又帶著泥巴味。試了幾次之後，書架剛好移開了足夠的距離，爸爸慢慢爬了過來。我們衝上最後幾階，闖進店裡，媽媽正拿著毛巾、用很大的嗓門在那裡等著。", "地下室的書全毀了，我們花了一個星期把濕掉的紙倒進卡車。但爸爸看起來並不難過。「財物可以再買，」他一邊說，一邊用顫抖的手扶正眼鏡。「重要的是，我們一起遇上了這場水災，也一起逃了出來。」我什麼也沒說。我只是把毛巾握得更緊。"], "vocab": [{"word": "approach", "pos": "v.", "zh": "接近；逼近", "example": "A typhoon is approaching the east coast of Taiwan.", "exampleZh": "一個颱風正逼近台灣東海岸。"}, {"word": "attempt", "pos": "v.", "zh": "試圖；嘗試", "example": "He attempted to climb the wall but fell.", "exampleZh": "他試圖爬牆，卻摔了下來。"}, {"word": "abandon", "pos": "v.", "zh": "放棄；遺棄", "example": "The sailors had to abandon the sinking ship.", "exampleZh": "水手們必須棄船逃離正在下沉的船。"}, {"word": "collapse", "pos": "v.", "zh": "倒塌；崩潰", "example": "The old bridge collapsed during the earthquake.", "exampleZh": "那座舊橋在地震中倒塌了。"}, {"word": "cope", "pos": "v.", "zh": "應付；處理", "example": "She learned to cope with stress by running.", "exampleZh": "她學會用跑步來應付壓力。"}, {"word": "fasten", "pos": "v.", "zh": "繫緊；固定", "example": "Please fasten your seat belt before the bus moves.", "exampleZh": "公車開動前請繫好安全帶。"}, {"word": "crawl", "pos": "v.", "zh": "爬行", "example": "The baby crawled across the floor to her mother.", "exampleZh": "寶寶爬過地板到媽媽身邊。"}, {"word": "emerge", "pos": "v.", "zh": "出現；浮現", "example": "The sun emerged from behind the clouds.", "exampleZh": "太陽從雲後露了出來。"}, {"word": "drag", "pos": "v.", "zh": "拖；拉", "example": "He dragged the heavy suitcase up the stairs.", "exampleZh": "他把沉重的行李箱拖上樓梯。"}, {"word": "escape", "pos": "v.", "zh": "逃離；逃脫", "example": "Two monkeys escaped from the zoo last night.", "exampleZh": "昨晚有兩隻猴子從動物園逃走了。"}], "phrases": [{"phrase": "cope with", "zh": "應付；處理", "example": "How do you cope with so much homework?", "exampleZh": "你怎麼應付這麼多功課？"}, {"phrase": "go out", "zh": "（燈、火）熄滅", "example": "All the lights went out during the storm.", "exampleZh": "暴風雨期間所有的燈都熄滅了。"}, {"phrase": "burst into", "zh": "衝進；突然……起來", "example": "The children burst into the room with excitement.", "exampleZh": "孩子們興奮地衝進房間。"}], "grammar": [{"pattern": "S + V ..., where + S + V（非限定關係副詞 where 補充說明地點）", "explain": "逗號後的 where 用來補充說明前面的地點名詞。文中 burst into the shop, where my mother was waiting 表示「衝進店裡，媽媽正在那裡等著」。", "example": "We visited Jiufen, where my grandmother grew up.", "exampleZh": "我們去了九份，我奶奶在那裡長大。"}, {"pattern": "The important thing is that + S + V（that 子句當主詞補語）", "explain": "that 引導的名詞子句放在 be 動詞後面，說明主詞的內容。文中 The important thing is that we encountered the flood together 表示「重要的是我們一起經歷了水災」。", "example": "The good news is that nobody was hurt.", "exampleZh": "好消息是沒有人受傷。"}], "reading": [{"q": "Where were the writer and his father when the lights went out?", "options": ["In the shop", "In the basement", "On the street", "On the stairs"], "answer": 1, "explain": "第一段說 My father and I were in the basement ... when the lights went out，故選 (B)。"}, {"q": "What blocked their way out of the basement?", "options": ["A locked door", "Boxes of new books", "A fallen wooden shelf", "A flooded truck"], "answer": 2, "explain": "第二段說 the old wooden shelf beside the entry collapsed, blocking our way，故選 (C)。"}, {"q": "The word \"shifted\" in paragraph 3 is closest in meaning to ______.", "options": ["moved", "broke", "fell", "floated"], "answer": 0, "explain": "shifted 意為「移動」，書架移開足夠的距離讓爸爸過去，故選 (A)。"}, {"q": "How did Dad finally get through?", "options": ["He crawled under the shelf like the writer.", "He waited for the water to go down.", "He broke the shelf with an ax.", "The writer pulled the shelf while Dad pushed with a bent pole."], "answer": 3, "explain": "第三段說爸爸折彎檯燈桿推書架，I used it to assist him in pushing the shelf while I pulled，故選 (D)。"}, {"q": "What does the father's last comment show about him?", "options": ["He was angry about losing the books.", "He blamed the weather bureau.", "He valued his family more than his possessions.", "He planned to close the bookstore."], "answer": 2, "explain": "爸爸說 Possessions can be replaced，重要的是一起經歷並逃出，顯示他看重家人勝過財物，故選 (C)。"}], "vocabQ": [{"q": "Drivers should slow down as they ____ the school zone.", "options": ["approach", "abandon", "attract", "assemble"], "answer": 0, "explain": "句意為「駕駛接近學校區域時應該減速」，approach 接近。"}, {"q": "The hikers had to ____ their plan to reach the top because of the snow.", "options": ["accomplish", "abandon", "adjust", "accompany"], "answer": 1, "explain": "句意為「因為下雪，登山客必須放棄攻頂的計畫」，abandon 放棄。"}, {"q": "Engineers worry that the old bridge may ____ in the next big earthquake.", "options": ["bounce", "blink", "collapse", "combine"], "answer": 2, "explain": "句意為「工程師擔心這座舊橋可能在下一次大地震中倒塌」，collapse 倒塌。"}, {"q": "It is hard for new students to ____ with so many tests in one week.", "options": ["crawl", "drag", "dash", "cope"], "answer": 3, "explain": "句意為「新生很難應付一週內這麼多考試」，cope with 應付。"}, {"q": "After the storm, the sun began to ____ from behind the dark clouds.", "options": ["emerge", "escape", "explode", "erase"], "answer": 0, "explain": "句意為「暴風雨過後，太陽開始從烏雲後露出來」，emerge 出現。"}]}, {"id": "I41", "level": "inter", "num": 41, "title": "The Night the Lights Went Out", "titleZh": "燈熄滅的那一夜", "theme": "Actions & Movement", "themeZh": "動作與移動", "article": ["Last Friday, a typhoon was pouring rain over Taipei when the lights in our cram school suddenly went out. Everything halted. For a second, nobody reacted; we just sat in the dark and gazed at the black screen where the teacher's slides had been. Then a few students giggled nervously, and someone whispered, \"Is this a test?\" Mr. Lin, who never seems to panic, told us to hush and to stay in our seats so that nobody would trip and get hurt.", "Since the emergency light overhead only gave a weak glow, Mr. Lin grabbed his phone and switched on the flashlight. Light flashed across the ceiling, and I caught a glimpse of my friend Wen-hao pretending to be a ghost, which made the girls behind us leap out of their chairs. Mr. Lin glanced at him and simply patted him on the shoulder. \"Nice try,\" he said with a grin. Then he asked me to fetch the candles that were kept in the drawer at the back of the room. I had to kneel on the floor and peer into the dark drawer, but I finally located them.", "What happened next was the best part of the evening. Instead of proceeding with the grammar lesson, Mr. Lin leaned against the desk and began to hum an old song, and the whole class joined in. Shadows floated on the walls as the candle flames danced. Nobody wanted to flee into the storm, so we told stories and laughed until the power came back. When it did, a few students actually groaned, and Wen-hao gave the candle a hug as if it were an old friend. I had always thought a blackout would be frightening, but that night, the darkness seemed to melt the usual distance between a teacher and his students."], "translation": ["上星期五，颱風把大雨傾盆倒在台北，我們補習班的燈突然熄了。一切都停了下來。有那麼一秒鐘，沒有人有反應；我們只是坐在黑暗中，凝視著原本放老師投影片的黑色螢幕。接著幾個學生緊張地咯咯笑了起來，有人小聲問：「這是在考我們嗎？」從來不會慌張的林老師叫我們安靜，待在座位上，免得有人絆倒受傷。", "由於頭頂上的緊急照明只發出微弱的光，林老師抓起手機，打開手電筒。光線閃過天花板，我瞥見我的朋友文豪正在裝鬼，嚇得我們後面的女生從椅子上跳了起來。林老師瞥了他一眼，只是拍拍他的肩膀。「不錯的嘗試。」他咧嘴一笑說。接著他要我去拿放在教室後面抽屜裡的蠟燭。我得跪在地上，往漆黑的抽屜裡細看，但最後還是找到了。", "接下來發生的事是那晚最棒的部分。林老師沒有繼續上文法課，而是靠在桌子上，開始哼一首老歌，全班也跟著唱了起來。燭火搖曳，影子在牆上飄動。沒有人想逃進暴風雨裡，所以我們說故事、大笑，直到電力恢復。電來的時候，有幾個學生竟然發出失望的呻吟，文豪還抱了抱那根蠟燭，好像它是老朋友一樣。我一直以為停電會很可怕，但那一晚，黑暗似乎融化了老師和學生之間平常的距離。"], "vocab": [{"word": "halt", "pos": "v.", "zh": "停止；停下", "example": "The train halted at the small station for only one minute.", "exampleZh": "火車在小站只停了一分鐘。"}, {"word": "gaze", "pos": "v.", "zh": "凝視；注視", "example": "She gazed at the stars until she fell asleep.", "exampleZh": "她凝視著星星，直到睡著。"}, {"word": "giggle", "pos": "v.", "zh": "咯咯笑", "example": "The children giggled when the clown fell down.", "exampleZh": "小丑跌倒時，孩子們咯咯地笑了。"}, {"word": "hush", "pos": "v.", "zh": "（使）安靜", "example": "The mother hushed the baby with a soft song.", "exampleZh": "媽媽用輕柔的歌聲讓寶寶安靜下來。"}, {"word": "glow", "pos": "n.", "zh": "微光；光輝", "example": "The glow of the sunset turned the river gold.", "exampleZh": "夕陽的光輝把河水染成金色。"}, {"word": "glimpse", "pos": "n.", "zh": "一瞥；一眼", "example": "We caught a glimpse of the singer as she left the hotel.", "exampleZh": "歌手離開飯店時，我們瞥見了她一眼。"}, {"word": "grin", "pos": "n.", "zh": "露齒的笑", "example": "He answered with a big grin on his face.", "exampleZh": "他回答時臉上帶著大大的笑容。"}, {"word": "fetch", "pos": "v.", "zh": "去拿來；取來", "example": "Could you fetch me the dictionary from the shelf?", "exampleZh": "你可以幫我從書架上拿字典來嗎？"}, {"word": "kneel", "pos": "v.", "zh": "跪下", "example": "The old man knelt down to pick up the coin.", "exampleZh": "老人跪下來撿硬幣。"}, {"word": "lean", "pos": "v.", "zh": "倚靠；傾斜", "example": "Don't lean against the door; it is not locked.", "exampleZh": "不要靠在門上，門沒有鎖。"}], "phrases": [{"phrase": "catch a glimpse of", "zh": "瞥見；看到一眼", "example": "I caught a glimpse of a deer in the forest.", "exampleZh": "我在森林裡瞥見一隻鹿。"}, {"phrase": "lean against", "zh": "靠著", "example": "The bike was leaning against the wall.", "exampleZh": "腳踏車靠在牆邊。"}, {"phrase": "join in", "zh": "加入；一起參與", "example": "Everyone joined in when the band played the last song.", "exampleZh": "樂團演奏最後一首歌時，大家都加入了。"}], "grammar": [{"pattern": "S + V ... so that + S + would / could + V", "explain": "so that 引導目的副詞子句，表示「以便…、為了讓…」，子句中常搭配 would、could、can 等助動詞。", "example": "Mr. Lin told us to stay in our seats so that nobody would trip.", "exampleZh": "林老師叫我們待在座位上，免得有人絆倒。"}, {"pattern": "S + V + as if + S + were / 過去式", "explain": "as if 後接過去式（be 動詞用 were）表示與事實相反的假設，意思是「彷彿…、好像…」。", "example": "He hugged the candle as if it were an old friend.", "exampleZh": "他抱著蠟燭，好像它是老朋友一樣。"}], "reading": [{"q": "What is the passage mainly about?", "options": ["Why typhoons often cause blackouts in Taipei", "How a blackout turned a class into a memorable evening", "How Mr. Lin teaches grammar in the dark", "Why students should bring candles to school"], "answer": 1, "explain": "全文描述停電那一晚，老師和學生一起唱歌、說故事，變成難忘的夜晚，故選 (B)。"}, {"q": "Why did Mr. Lin tell the students to stay in their seats?", "options": ["He wanted to finish the grammar lesson.", "He was afraid they would leave without paying.", "He did not want anyone to trip and get hurt.", "He needed to count the students."], "answer": 2, "explain": "第一段提到 so that nobody would trip and get hurt，故選 (C)。"}, {"q": "What did the writer have to do to get the candles?", "options": ["Kneel down and look into a dark drawer", "Walk to the office next door", "Borrow a flashlight from Wen-hao", "Climb onto a chair to reach a shelf"], "answer": 0, "explain": "第二段寫 I had to kneel on the floor and peer into the dark drawer，故選 (A)。"}, {"q": "The word \"proceeding\" in paragraph 3 is closest in meaning to ______.", "options": ["stopping", "arguing", "listening", "continuing"], "answer": 3, "explain": "proceeding with the grammar lesson 指「繼續上文法課」，與 continuing 意思最接近，故選 (D)。"}, {"q": "How did the writer most likely feel at the end of the evening?", "options": ["Angry that the lesson was wasted", "Closer to the teacher than before", "Afraid of the next typhoon", "Bored by the old song"], "answer": 1, "explain": "最後一句說黑暗融化了師生之間平常的距離，表示作者覺得和老師更親近了，故選 (B)。"}], "vocabQ": [{"q": "The guard raised his hand to ____ the traffic so the children could cross the road.", "options": ["fetch", "lean", "halt", "kneel"], "answer": 2, "explain": "句意為「警衛舉手讓車流停下，好讓孩子過馬路」，halt 停止。"}, {"q": "The baby began to ____ with joy when her father made a funny face.", "options": ["giggle", "hush", "gaze", "kneel"], "answer": 0, "explain": "句意為「爸爸做鬼臉時，寶寶開心地咯咯笑了起來」，giggle 咯咯笑。"}, {"q": "Can you ____ me a glass of water from the kitchen?", "options": ["hush", "kneel", "lean", "fetch"], "answer": 3, "explain": "句意為「你可以幫我從廚房拿一杯水來嗎」，fetch 去拿來。"}, {"q": "In the dark, we could see the soft ____ of the night-market lanterns far away.", "options": ["grin", "glow", "glimpse", "hum"], "answer": 1, "explain": "句意為「黑暗中，我們看得到遠處夜市燈籠柔和的光」，glow 微光。"}, {"q": "The teacher asked the noisy class to ____ before the test began.", "options": ["gaze", "lean", "hush", "fetch"], "answer": 2, "explain": "句意為「老師要吵鬧的班級在考試開始前安靜下來」，hush 安靜。"}]}, {"id": "I42", "level": "inter", "num": 42, "title": "Kitten Rescued After Students Refuse to Give Up", "titleZh": "學生不放棄，小貓獲救", "theme": "Actions & Movement", "themeZh": "動作與移動", "article": ["NEW TAIPEI CITY - A kitten that had been trapped in a storm drain for two days was rescued on Sunday afternoon by firefighters, after a group of junior high school students refused to give up on it. The students, who were wandering along the riverside path after school on Friday, heard a faint cry that seemed to vanish every time a car passed. Lin Yu-ting, 14, said, \"We stared at the drain for ten minutes before we saw a tiny paw. Then I screamed because it moved.\"", "The students tried to lift the heavy cover themselves, tugging at it wildly, but it would not shift. One boy even tried to sneak his hand through the narrow gap, only to scratch his arm on the rough edge. Finally, they tapped on the window of a nearby shop and asked the owner to call 119. When the firefighters arrived, they used a special tool to twist the cover loose, and one of them squeezed his shoulders into the opening. The kitten, trembling and soaked with mud, was gently wrapped in a towel and handed to the cheering crowd that surrounded the scene.", "Firefighter Chen Wei-lun shrugged off the praise. \"The kids did the hard part,\" he said with a sigh of relief. \"If they had tossed the problem aside, this little guy would not have made it.\" The kitten has since been transferred to an animal shelter in Banqiao, where volunteers scrubbed the mud from its fur and gave it a warm place to settle down. The shelter says the kitten is now stretching, playing, and splashing water out of its bowl, which is a good sign that it will recover. The students plan to visit next week, and if no owner is found, they hope the kitten can be reunited with the people who saved it, this time as a classmate's pet."], "translation": ["新北市訊——一隻被困在排水溝裡兩天的小貓，星期日下午被消防人員救出，起因是一群國中生不肯放棄牠。這群學生星期五放學後在河濱步道閒逛時，聽到一聲微弱的叫聲，每當有車經過，聲音似乎就消失了。十四歲的林郁婷說：「我們盯著排水溝看了十分鐘，才看到一隻小小的腳掌。然後我尖叫了，因為它動了。」", "學生們試著自己抬起沉重的蓋子，拚命地拉扯，但它動也不動。一個男孩甚至想把手從狹窄的縫隙偷偷伸進去，結果反而被粗糙的邊緣刮傷了手臂。最後，他們敲了敲附近一家商店的窗戶，請老闆打 119。消防人員抵達後，用特殊工具把蓋子轉鬆，其中一人把肩膀擠進開口。小貓渾身發抖、沾滿泥巴，被輕輕地用毛巾包起來，交給圍在現場歡呼的人群。", "消防員陳偉倫對讚美一笑置之。「困難的部分是孩子們做的，」他鬆了一口氣說。「如果他們把這個問題丟在一邊，這個小傢伙就撐不過去了。」小貓之後被轉送到板橋的一間動物收容所，志工刷掉牠毛上的泥巴，給牠一個溫暖的地方安頓下來。收容所表示，小貓現在會伸懶腰、玩耍，還會把水從碗裡潑出來，這是牠會康復的好徵兆。學生們打算下週去探望；如果找不到飼主，他們希望小貓能和救牠的人團聚——這次是以同學寵物的身分。"], "vocab": [{"word": "rescue", "pos": "v.", "zh": "拯救；營救", "example": "The lifeguard rescued a boy from the strong waves.", "exampleZh": "救生員從大浪中救出一個男孩。"}, {"word": "wander", "pos": "v.", "zh": "漫步；閒逛", "example": "We wandered around the old town without a map.", "exampleZh": "我們沒帶地圖就在老城裡閒逛。"}, {"word": "vanish", "pos": "v.", "zh": "消失", "example": "The fog vanished as soon as the sun came out.", "exampleZh": "太陽一出來，霧就消失了。"}, {"word": "stare", "pos": "v.", "zh": "盯著看；凝視", "example": "The little boy stared at the huge dinosaur model.", "exampleZh": "小男孩盯著巨大的恐龍模型看。"}, {"word": "tug", "pos": "v.", "zh": "用力拉；拖", "example": "The dog tugged at the rope with all its strength.", "exampleZh": "狗用盡全力拉那條繩子。"}, {"word": "squeeze", "pos": "v.", "zh": "擠；擠壓", "example": "She squeezed the lemon into the tea.", "exampleZh": "她把檸檬汁擠進茶裡。"}, {"word": "tremble", "pos": "v.", "zh": "發抖；顫抖", "example": "His hands trembled as he opened the letter.", "exampleZh": "他打開信的時候，雙手直發抖。"}, {"word": "wrap", "pos": "v.", "zh": "包；裹", "example": "Please wrap the gift in red paper.", "exampleZh": "請用紅色的紙把禮物包起來。"}, {"word": "transfer", "pos": "v.", "zh": "轉移；調動", "example": "The patient was transferred to a larger hospital.", "exampleZh": "病人被轉送到一家更大的醫院。"}, {"word": "reunite", "pos": "v.", "zh": "（使）團聚；重聚", "example": "The lost dog was reunited with its family after a week.", "exampleZh": "走失的狗一個星期後和家人團聚了。"}], "phrases": [{"phrase": "give up on", "zh": "放棄（某人／某事）", "example": "Her coach never gave up on her.", "exampleZh": "她的教練從未放棄她。"}, {"phrase": "shrug off", "zh": "對…不以為意；一笑置之", "example": "He shrugged off the criticism and kept working.", "exampleZh": "他對批評不以為意，繼續工作。"}, {"phrase": "settle down", "zh": "安頓下來；安定下來", "example": "It took the new puppy a few days to settle down.", "exampleZh": "新來的小狗花了幾天才安頓下來。"}], "grammar": [{"pattern": "S + V ..., only to + V", "explain": "only to + 原形動詞表示「結果卻…」，用來說明一個出乎意料或令人失望的結果。", "example": "He ran to the station, only to find that the last train had left.", "exampleZh": "他跑到車站，結果卻發現末班車已經開走了。"}, {"pattern": "If + S + had + p.p., S + would have + p.p.", "explain": "與過去事實相反的假設語氣：if 子句用過去完成式，主要子句用 would have + 過去分詞，表示「當時如果…，就會…」。", "example": "If they had tossed the problem aside, the kitten would not have survived.", "exampleZh": "如果他們當時把問題丟在一邊，小貓就活不下來了。"}], "reading": [{"q": "What is the news report mainly about?", "options": ["Students helped save a kitten trapped in a drain", "A shop owner who adopted a kitten", "How firefighters train for animal rescues", "A new animal shelter opening in Banqiao"], "answer": 0, "explain": "全文報導學生發現受困小貓並協助救援的經過，故選 (A)。"}, {"q": "Why did the students fail to free the kitten themselves?", "options": ["They were afraid of the kitten.", "The shop owner told them to stop.", "It was already dark outside.", "The drain cover was too heavy to move."], "answer": 3, "explain": "第二段提到他們拚命拉蓋子，but it would not shift，故選 (D)。"}, {"q": "Who finally called 119?", "options": ["Lin Yu-ting", "A shop owner", "A passing driver", "A volunteer from the shelter"], "answer": 1, "explain": "第二段寫學生敲店家的窗戶，asked the owner to call 119，故選 (B)。"}, {"q": "The phrase \"shrugged off\" in paragraph 3 is closest in meaning to ______.", "options": ["asked for", "was proud of", "did not take seriously", "was confused by"], "answer": 2, "explain": "消防員接著說「困難的部分是孩子們做的」，表示他不把讚美當一回事，故選 (C)。"}, {"q": "What can be inferred about the kitten's future?", "options": ["It will stay in the shelter forever.", "It may become the pet of one of the students.", "It will be returned to the drain.", "It will be sold by the shop owner."], "answer": 1, "explain": "最後一句說如果找不到飼主，學生希望小貓成為同學的寵物，故選 (B)。"}], "vocabQ": [{"q": "It took three firefighters to ____ the hikers from the steep cliff.", "options": ["punish", "remove", "release", "rescue"], "answer": 3, "explain": "句意為「三名消防員才把登山客從陡峭的懸崖救下來」，rescue 營救。"}, {"q": "The old man likes to ____ around the park with no particular place to go.", "options": ["wander", "tremble", "vanish", "squeeze"], "answer": 0, "explain": "句意為「老先生喜歡在公園裡漫無目的地閒逛」，wander 漫步。"}, {"q": "The magician made the coin ____ right in front of our eyes.", "options": ["stare", "tug", "vanish", "wrap"], "answer": 2, "explain": "句意為「魔術師讓硬幣在我們眼前消失」，vanish 消失。"}, {"q": "Please don't ____ at strangers on the MRT; it makes them uncomfortable.", "options": ["shrug", "stare", "sneak", "wander"], "answer": 1, "explain": "句意為「請不要在捷運上盯著陌生人看，那會讓他們不舒服」，stare 盯著看。"}, {"q": "After the typhoon, the school decided to ____ all classes to the online system.", "options": ["tremble", "reunite", "tug", "transfer"], "answer": 3, "explain": "句意為「颱風過後，學校決定把所有課程轉移到線上系統」，transfer 轉移。"}]}, {"id": "I43", "level": "inter", "num": 43, "title": "Grandma's Tea Shop Gets a Second Life", "titleZh": "奶奶的茶行重獲新生", "theme": "Time & Change", "themeZh": "時間與變化", "article": ["October 18, Saturday. Lately I have been thinking a lot about Grandma's tea shop in Dadaocheng. It has stood on the same street corner for more than six decades, and until last year, it opened punctually at eight every morning, just as it had when my great-grandfather ran it. But nowadays few young people stop by, and sales have declined year after year. The wooden door has begun to decay, and the red paint on the sign has faded. At dusk, the shop looks like something from a different era.", "This afternoon, my cousin Mei-ling, who studies design in Taichung, arrived with a surprising plan. Instead of letting the business cease, she wants to transform it gradually into a tea cafe where customers can taste traditional tea and also take photos for social media. Grandma's initial reaction was silence. Then she asked whether the old tea jars would remain. \"Of course,\" Mei-ling said. \"We will renew the space, but the origin of the shop will stay the same.\" Meanwhile, I was doing the math in my head: the renovation would be temporary, lasting about two months, and the shop could reopen in time for its sixty-fifth anniversary in January.", "Grandma did not say yes immediately. She said she needed to adapt to the idea first and asked us to postpone the decision for a week. Afterwards, while we were washing the cups, she admitted something I had never heard before: the shop has changed many times in her lifetime, from selling rice to selling tea, and every change seemed frightening at first. \"Nothing is permanent,\" she said, \"but the things we love can evolve.\" I think she will eventually agree. In the meantime, I am going to take photos of every corner of the shop, so that whatever happens, the memory of this version will not fade."], "translation": ["十月十八日，星期六。最近我常常想起奶奶在大稻埕的茶行。它在同一個街角矗立了六十多年，直到去年，每天早上八點都準時開門，就像曾祖父經營時一樣。但如今很少有年輕人會順道來看看，營業額年復一年地下滑。木門開始腐朽，招牌上的紅漆也褪色了。黃昏時，這家店看起來像是來自另一個時代的東西。", "今天下午，在台中讀設計的表姊美玲帶著一個令人驚訝的計畫來了。她不想讓生意就此結束，而是想把它逐漸改造成一間茶咖啡館，讓顧客能品嚐傳統茶，也能拍照放上社群媒體。奶奶最初的反應是沉默。接著她問，那些舊茶罐會不會留下來。「當然，」美玲說，「我們會把空間翻新，但這家店的本源會維持不變。」同時，我在心裡算了算：整修是暫時的，大約兩個月，店可以趕在一月的六十五週年紀念前重新開張。", "奶奶沒有馬上答應。她說她需要先適應這個想法，請我們把決定延後一個星期。之後，我們洗杯子的時候，她說了一件我從沒聽過的事：在她這一生中，這家店已經改變過很多次，從賣米到賣茶，每一次改變起初都令人害怕。「沒有什麼是永久的，」她說，「但我們所愛的事物可以演變。」我想她最後會同意的。在此期間，我要把店裡的每個角落都拍下來，這樣無論發生什麼事，這個版本的記憶都不會褪去。"], "vocab": [{"word": "decade", "pos": "n.", "zh": "十年", "example": "My parents have lived in Taipei for two decades.", "exampleZh": "我的父母在台北住了二十年。"}, {"word": "decline", "pos": "v.", "zh": "下降；衰退", "example": "The number of visitors declined sharply last winter.", "exampleZh": "去年冬天遊客人數大幅下降。"}, {"word": "decay", "pos": "v.", "zh": "腐爛；腐朽", "example": "The fallen leaves slowly decayed on the ground.", "exampleZh": "落葉在地上慢慢腐爛。"}, {"word": "fade", "pos": "v.", "zh": "褪色；逐漸消失", "example": "The colors of the old photo have faded.", "exampleZh": "這張舊照片的顏色已經褪了。"}, {"word": "transform", "pos": "v.", "zh": "改變；轉變", "example": "The factory was transformed into an art center.", "exampleZh": "這座工廠被改造成藝術中心。"}, {"word": "initial", "pos": "adj.", "zh": "最初的；開始的", "example": "My initial plan was to study abroad.", "exampleZh": "我最初的計畫是出國念書。"}, {"word": "renew", "pos": "v.", "zh": "更新；翻新", "example": "I need to renew my library card next month.", "exampleZh": "我下個月需要更新我的借書證。"}, {"word": "postpone", "pos": "v.", "zh": "延期；延後", "example": "The game was postponed because of the rain.", "exampleZh": "比賽因為下雨而延期。"}, {"word": "permanent", "pos": "adj.", "zh": "永久的", "example": "He finally got a permanent job at the bank.", "exampleZh": "他終於在銀行得到一份固定的工作。"}, {"word": "evolve", "pos": "v.", "zh": "演變；逐漸發展", "example": "The small blog evolved into a popular website.", "exampleZh": "這個小部落格演變成一個受歡迎的網站。"}], "phrases": [{"phrase": "stop by", "zh": "順道拜訪", "example": "Feel free to stop by my office anytime.", "exampleZh": "隨時歡迎順道來我的辦公室。"}, {"phrase": "year after year", "zh": "年復一年", "example": "The birds return to the island year after year.", "exampleZh": "這些鳥年復一年地回到島上。"}, {"phrase": "in the meantime", "zh": "在此期間；同時", "example": "The bus comes at six; in the meantime, let's get a drink.", "exampleZh": "公車六點來；在這期間，我們去買杯飲料吧。"}], "grammar": [{"pattern": "Instead of + V-ing / N, S + V", "explain": "instead of 是介系詞片語，後面接動名詞或名詞，表示「而不是…、代替…」。", "example": "Instead of taking the bus, we walked to the night market.", "exampleZh": "我們沒有搭公車，而是走路去夜市。"}, {"pattern": "S + ask / wonder + whether + S + V", "explain": "whether 引導名詞子句作為受詞，表示「是否…」，常用於間接問句，子句要用直述句的語序。", "example": "She asked whether the old tea jars would remain.", "exampleZh": "她問那些舊茶罐會不會留下來。"}], "reading": [{"q": "What kind of text is this passage?", "options": ["A news report", "A business letter", "A diary entry", "An advertisement"], "answer": 2, "explain": "文章開頭有日期，並以第一人稱記錄當天發生的事和感想，是日記，故選 (C)。"}, {"q": "What is Mei-ling's plan for the shop?", "options": ["To turn it into a tea cafe that still sells traditional tea", "To close it and open a design studio", "To move it to Taichung", "To sell rice instead of tea"], "answer": 0, "explain": "第二段提到她想把店改造成茶咖啡館，顧客可以品嚐傳統茶，故選 (A)。"}, {"q": "Why did Grandma ask to wait a week?", "options": ["She wanted to talk to the writer's great-grandfather.", "She was too busy with the anniversary.", "She did not trust Mei-ling.", "She needed time to get used to the idea."], "answer": 3, "explain": "第三段寫 she needed to adapt to the idea first，故選 (D)。"}, {"q": "The word \"cease\" in paragraph 2 is closest in meaning to ______.", "options": ["grow", "stop", "move", "change"], "answer": 1, "explain": "letting the business cease 指「讓生意結束／停止」，與 stop 意思最接近，故選 (B)。"}, {"q": "What does the writer think Grandma will do?", "options": ["Sell the shop to a stranger", "Refuse any change forever", "Agree to the plan in the end", "Move in with Mei-ling"], "answer": 2, "explain": "第三段寫 I think she will eventually agree，故選 (C)。"}], "vocabQ": [{"q": "It has been nearly a ____ since the new MRT line opened in 2017.", "options": ["week", "decade", "season", "minute"], "answer": 1, "explain": "句意為「自 2017 年新捷運線通車以來，已經快十年了」，decade 十年。"}, {"q": "The number of students in rural schools continues to ____ as families move to the cities.", "options": ["renew", "evolve", "postpone", "decline"], "answer": 3, "explain": "句意為「隨著家庭搬到都市，鄉村學校的學生人數持續下降」，decline 下降。"}, {"q": "If you don't brush your teeth, they will slowly ____.", "options": ["decay", "fade", "transform", "renew"], "answer": 0, "explain": "句意為「如果你不刷牙，牙齒會慢慢蛀壞」，decay 腐壞。"}, {"q": "Because of the heavy rain, the school had to ____ the sports day until next Friday.", "options": ["renew", "evolve", "postpone", "decay"], "answer": 2, "explain": "句意為「因為大雨，學校必須把運動會延到下星期五」，postpone 延期。"}, {"q": "The ____ cost of the trip was NT$3,000, but we ended up paying much more.", "options": ["permanent", "initial", "temporary", "gradual"], "answer": 1, "explain": "句意為「這趟旅行最初的費用是三千元，但我們最後付了更多」，initial 最初的。"}]}, {"id": "I44", "level": "inter", "num": 44, "title": "How Much Water Is in Your Lunch?", "titleZh": "你的午餐裡有多少水？", "theme": "Quantity, Size & Degree", "themeZh": "數量、大小與程度", "article": ["Have you ever wondered how much water it takes to make your lunch? Most of us think only of the glass of water beside the plate, but that is barely the beginning. Scientists use the term \"water footprint\" to describe the total amount of water used to produce something, and the numbers are often enormous. A single hamburger, for example, requires an estimated 2,400 liters of water, which is roughly equivalent to forty full bathtubs. To a considerable extent, this water is used to grow the grain that feeds the cattle, not to cook the meat itself.", "You can estimate your own water footprint in three simple steps. First, write down everything you eat on an average day, from the bunch of bananas at breakfast to the handful of candies after dinner. Second, look up the water footprint of each item on a reliable website; the gap between items may surprise you, since one cup of coffee uses about 130 liters while a cup of tea uses only 30. Third, add the numbers together. Do not worry about getting the total exactly right. Your goal is to understand the general size of your usage, not to produce a perfect figure.", "Why does this matter? Taiwan receives heavy rainfall, yet its steep mountains let most of it flow quickly into the sea, so the island's capacity to store water is highly limited. During the extreme drought of 2021, several reservoirs were nearly empty, and the water supply in some cities was inadequate for weeks. Globally, about two billion people lack adequate drinking water. Fully understanding our footprint will not solve the problem overnight, but it can greatly change our choices. Eating slightly less meat, for instance, reduces a family's water use by a surprising amount. Small changes, when extended across millions of people, expand into something gigantic."], "translation": ["你有沒有想過，做你的一頓午餐需要用掉多少水？我們大多數人只想到盤子旁邊那杯水，但那只不過是開始而已。科學家用「水足跡」一詞來描述生產某樣東西所使用的總水量，而這些數字往往大得驚人。例如，一個漢堡估計需要 2,400 公升的水，大約相當於四十個裝滿的浴缸。這些水在相當程度上是用來種植餵牛的穀物，而不是用來烹調肉本身。", "你可以用三個簡單的步驟估算自己的水足跡。第一，寫下你平常一天吃的所有東西，從早餐的一串香蕉到晚餐後的一小把糖果。第二，在可靠的網站上查閱每樣東西的水足跡；各項目之間的差距可能會讓你吃驚，因為一杯咖啡大約用掉 130 公升的水，而一杯茶只用 30 公升。第三，把數字加起來。不必擔心總數是否完全正確。你的目標是了解自己用水量的大致規模，而不是算出一個完美的數字。", "這為什麼重要？台灣雨量豐沛，但陡峭的山勢讓大部分雨水迅速流入海裡，所以這座島儲水的容量非常有限。在 2021 年的極端乾旱期間，好幾座水庫幾乎見底，有些城市的供水好幾個星期都不足。在全球，大約有二十億人缺乏足夠的飲用水。完全了解我們的水足跡不會一夜之間解決問題，但它能大大改變我們的選擇。例如，少吃一點肉，就能讓一個家庭的用水量減少驚人的幅度。小小的改變，當它延伸到數百萬人身上，就會擴大成巨大的力量。"], "vocab": [{"word": "barely", "pos": "adv.", "zh": "僅僅；幾乎不", "example": "He barely passed the math test.", "exampleZh": "他的數學考試勉強及格。"}, {"word": "enormous", "pos": "adj.", "zh": "巨大的", "example": "The whale was enormous, longer than a bus.", "exampleZh": "那隻鯨魚非常巨大，比公車還長。"}, {"word": "estimate", "pos": "v.", "zh": "估計；估算", "example": "We estimate that the trip will cost about NT$5,000.", "exampleZh": "我們估計這趟旅行大約要花五千元。"}, {"word": "equivalent", "pos": "adj.", "zh": "相等的；等同的", "example": "One U.S. dollar is equivalent to about thirty NT dollars.", "exampleZh": "一美元大約相當於三十元新台幣。"}, {"word": "considerable", "pos": "adj.", "zh": "相當大的；可觀的", "example": "The project took a considerable amount of time.", "exampleZh": "這個專案花了相當多的時間。"}, {"word": "handful", "pos": "n.", "zh": "一把；少數", "example": "Only a handful of students stayed after class.", "exampleZh": "只有少數幾個學生下課後留下來。"}, {"word": "gap", "pos": "n.", "zh": "差距；缺口", "example": "There is a big gap between the two teams' scores.", "exampleZh": "兩隊的分數有很大的差距。"}, {"word": "capacity", "pos": "n.", "zh": "容量；能力", "example": "The stadium has a capacity of 40,000 people.", "exampleZh": "這座體育場可容納四萬人。"}, {"word": "inadequate", "pos": "adj.", "zh": "不足的；不夠的", "example": "The food was inadequate for such a large group.", "exampleZh": "食物對這麼大的團體來說不夠。"}, {"word": "gigantic", "pos": "adj.", "zh": "巨大的；龐大的", "example": "A gigantic balloon floated over the stadium.", "exampleZh": "一個巨大的氣球飄在體育場上空。"}], "phrases": [{"phrase": "to a considerable extent", "zh": "在相當程度上", "example": "The success was, to a considerable extent, due to luck.", "exampleZh": "這次成功在相當程度上是靠運氣。"}, {"phrase": "look up", "zh": "查閱；查詢", "example": "You can look up the word in the dictionary.", "exampleZh": "你可以在字典裡查這個字。"}, {"phrase": "for instance", "zh": "例如", "example": "Many fruits, for instance mangoes, grow well in Taiwan.", "exampleZh": "很多水果，例如芒果，在台灣長得很好。"}], "grammar": [{"pattern": "It takes + 數量 / 時間 + to + V", "explain": "it 為虛主詞，take 表示「花費、需要」，後面接不定詞說明做某事需要多少時間或東西。", "example": "It takes about 2,400 liters of water to make one hamburger.", "exampleZh": "做一個漢堡大約需要 2,400 公升的水。"}, {"pattern": "S + V ..., while + S + V", "explain": "while 用來連接兩個互相對比的子句，意思是「而、然而」，強調兩者的不同。", "example": "A cup of coffee uses 130 liters, while a cup of tea uses only 30.", "exampleZh": "一杯咖啡用掉 130 公升的水，而一杯茶只用 30 公升。"}], "reading": [{"q": "What is the main purpose of the passage?", "options": ["To warn readers not to eat hamburgers", "To describe the drought of 2021", "To compare coffee and tea", "To explain what a water footprint is and how to estimate one"], "answer": 3, "explain": "第一段說明水足跡，第二段教讀者如何估算，第三段說明重要性，故選 (D)。"}, {"q": "According to paragraph 1, where does most of the water for a hamburger go?", "options": ["Growing grain to feed the cattle", "Cooking the meat", "Washing the dishes", "Filling the bathtubs"], "answer": 0, "explain": "第一段最後一句說水主要用來種植餵牛的穀物，故選 (A)。"}, {"q": "Which of the following is NOT one of the three steps?", "options": ["Write down what you eat in a day", "Look up each item's water footprint", "Compare your total with your classmates'", "Add all the numbers together"], "answer": 2, "explain": "第二段的三個步驟是記錄、查閱、加總，沒有提到和同學比較，故選 (C)。"}, {"q": "Why is Taiwan's ability to store water limited even though it rains a lot?", "options": ["The reservoirs are too old.", "Its steep mountains make the rain flow quickly into the sea.", "Most people waste water.", "The rain only falls in winter."], "answer": 1, "explain": "第三段提到 its steep mountains let most of it flow quickly into the sea，故選 (B)。"}, {"q": "The word \"overnight\" in paragraph 3 is closest in meaning to ______.", "options": ["very quickly", "during sleep", "at midnight", "forever"], "answer": 0, "explain": "will not solve the problem overnight 指「不會一夜之間／很快解決問題」，故選 (A)。"}], "vocabQ": [{"q": "The typhoon caused ____ damage to the farms along the east coast.", "options": ["slight", "tiny", "enormous", "little"], "answer": 2, "explain": "句意為「颱風對東海岸的農田造成巨大的損害」，enormous 巨大的。"}, {"q": "Experts ____ that the new MRT line will carry 200,000 passengers a day.", "options": ["expand", "estimate", "extend", "enlarge"], "answer": 1, "explain": "句意為「專家估計新捷運線每天將載運二十萬名乘客」，estimate 估計。"}, {"q": "There is a wide ____ between what the rich and the poor can afford.", "options": ["heap", "bunch", "handful", "gap"], "answer": 3, "explain": "句意為「富人和窮人負擔得起的東西之間有很大的差距」，gap 差距。"}, {"q": "The hall has a ____ of 500 people, so we cannot invite the whole school.", "options": ["capacity", "depth", "balance", "extension"], "answer": 0, "explain": "句意為「這個禮堂可容納五百人，所以我們不能邀請全校」，capacity 容量。"}, {"q": "The food supply was ____ for the hikers, so they had to turn back early.", "options": ["adequate", "equivalent", "inadequate", "extensive"], "answer": 2, "explain": "句意為「登山客的食物供給不足，所以他們必須提早折返」，inadequate 不足的。"}]}, {"id": "I45", "level": "inter", "num": 45, "title": "Survey: Teen Screen Time Reaches Record High", "titleZh": "調查：青少年螢幕時間創新高", "theme": "Quantity, Size & Degree", "themeZh": "數量、大小與程度", "article": ["TAIPEI - The majority of Taiwanese teenagers now spend more than four hours per day on their phones, according to a nationwide survey released on Monday by a youth research center. The survey, which included 3,200 students between the ages of 13 and 18, found that 62 percent of respondents use their phones mainly for short videos and messaging, while a mere 9 percent said they use them mostly for studying. Researchers described the trend as \"worldwide,\" but noted that the rate in Taiwan is relatively high compared with Japan and South Korea.", "The report also revealed a widespread shortage of sleep. Nearly half of the students reported sleeping less than seven hours on school nights, and the proportion rose to 58 percent among senior high school students. Multiple factors were mentioned, including homework, cram school schedules, and late-night scrolling. \"A slight increase in screen time may not seem serious,\" said Dr. Huang Shu-fen, who led the study, \"but when it is repeated every night, the quantity of lost sleep becomes tremendous.\"", "Not all the news was negative. The percentage of teenagers who said they had tried to reduce their screen time rose from 31 to 44 percent in a series of surveys over the past three years, and various schools have introduced \"phone-free\" lunch breaks. Students at one junior high school in Kaohsiung ranked among the best sleepers in the survey after their school shortened evening study sessions by thirty minutes. Dr. Huang suggested that parents set a reasonable minimum of eight hours of sleep and keep phones out of the bedroom. \"Plenty of teens want to change,\" she said. \"They simply need sufficient support, and a moderate, step-by-step reduction works far better than taking the phone away completely.\""], "translation": ["台北訊——根據一家青年研究中心星期一發布的全國性調查，台灣大多數青少年現在每天使用手機超過四小時。這項調查納入了 3,200 名十三到十八歲的學生，發現 62% 的受訪者主要用手機看短影片和傳訊息，而僅有 9% 表示主要用來讀書。研究人員形容這是「全球性」的趨勢，但指出台灣的比率與日本和南韓相比相對偏高。", "報告也揭露了普遍的睡眠不足問題。將近一半的學生表示上學日晚上睡不到七小時，在高中生當中，這個比例更升到 58%。報告提到多種因素，包括作業、補習班的時間表，以及深夜滑手機。「螢幕時間稍微增加看起來或許不嚴重，」主持這項研究的黃淑芬博士說，「但當它每晚重複發生，失去的睡眠量就會變得非常龐大。」", "消息並非全是負面的。在過去三年的一系列調查中，表示曾試著減少螢幕時間的青少年比例從 31% 升到 44%，而且各校陸續推出「無手機」午休。高雄一所國中在把晚自習縮短三十分鐘之後，學生名列調查中睡得最好的一群。黃博士建議家長訂出合理的最低睡眠時間八小時，並且不要把手機放在臥室裡。「很多青少年想要改變，」她說，「他們只是需要足夠的支持，而且溫和、循序漸進的減量，遠比完全沒收手機有效得多。」"], "vocab": [{"word": "majority", "pos": "n.", "zh": "大多數", "example": "The majority of my classmates take the MRT to school.", "exampleZh": "我大多數的同學搭捷運上學。"}, {"word": "mere", "pos": "adj.", "zh": "僅僅的；只不過的", "example": "The ticket costs a mere NT$50.", "exampleZh": "這張票只要五十元。"}, {"word": "relatively", "pos": "adv.", "zh": "相對地；比較上", "example": "The test was relatively easy this time.", "exampleZh": "這次的考試相對來說比較簡單。"}, {"word": "widespread", "pos": "adj.", "zh": "普遍的；廣泛的", "example": "The use of smartphones is widespread among teenagers.", "exampleZh": "智慧型手機的使用在青少年之間很普遍。"}, {"word": "shortage", "pos": "n.", "zh": "短缺；不足", "example": "There is a shortage of nurses in many hospitals.", "exampleZh": "許多醫院都有護理師短缺的問題。"}, {"word": "proportion", "pos": "n.", "zh": "比例", "example": "A large proportion of the money was spent on food.", "exampleZh": "這筆錢有很大的比例花在食物上。"}, {"word": "multiple", "pos": "adj.", "zh": "多個的；多種的", "example": "The player has won multiple awards this year.", "exampleZh": "這位球員今年贏得了多個獎項。"}, {"word": "tremendous", "pos": "adj.", "zh": "巨大的；驚人的", "example": "The concert was a tremendous success.", "exampleZh": "這場演唱會獲得巨大的成功。"}, {"word": "reduce", "pos": "v.", "zh": "減少；降低", "example": "We should reduce the amount of sugar we eat.", "exampleZh": "我們應該減少吃糖的量。"}, {"word": "sufficient", "pos": "adj.", "zh": "足夠的", "example": "Do we have sufficient time to finish the project?", "exampleZh": "我們有足夠的時間完成這個專案嗎？"}], "phrases": [{"phrase": "according to", "zh": "根據", "example": "According to the weather report, it will rain tomorrow.", "exampleZh": "根據氣象報告，明天會下雨。"}, {"phrase": "compared with", "zh": "與…相比", "example": "Compared with last year, the prices are much higher.", "exampleZh": "和去年相比，價格高了很多。"}, {"phrase": "rank among", "zh": "名列…之中", "example": "Taipei 101 once ranked among the tallest buildings in the world.", "exampleZh": "台北 101 曾名列世界最高建築之一。"}], "grammar": [{"pattern": "S, which + V ..., + V", "explain": "非限定用法的關係子句，用逗號隔開，對先行詞做補充說明；which 指事物，不可用 that 代替。", "example": "The survey, which included 3,200 students, found that most teens sleep too little.", "exampleZh": "這項納入 3,200 名學生的調查發現，大多數青少年睡眠不足。"}, {"pattern": "S + suggest + that + S + (should) + 原形V", "explain": "suggest（建議）後面的 that 子句中，動詞用原形（should 可省略），不隨主詞或時態變化。", "example": "Dr. Huang suggested that parents keep phones out of the bedroom.", "exampleZh": "黃博士建議家長不要把手機放在臥室裡。"}], "reading": [{"q": "What is the passage mainly about?", "options": ["How to study with a smartphone", "A survey showing teens' heavy phone use and lack of sleep", "Why Japanese teens sleep more than Taiwanese teens", "A new phone designed for students"], "answer": 1, "explain": "全文報導一項關於青少年手機使用時間與睡眠不足的調查結果，故選 (B)。"}, {"q": "What did 9 percent of the students say about their phones?", "options": ["They use them for more than four hours a day.", "They never use them at school.", "They use them mostly for studying.", "They want to give them up."], "answer": 2, "explain": "第一段提到 a mere 9 percent said they use them mostly for studying，故選 (C)。"}, {"q": "What helped the students in Kaohsiung sleep better?", "options": ["Their school shortened evening study sessions.", "Their parents took away their phones.", "They stopped going to cram school.", "They joined a sports team."], "answer": 0, "explain": "第三段提到該校把晚自習縮短三十分鐘後，學生名列睡得最好的一群，故選 (A)。"}, {"q": "The word \"tremendous\" in paragraph 2 is closest in meaning to ______.", "options": ["unimportant", "confusing", "temporary", "very large"], "answer": 3, "explain": "the quantity of lost sleep becomes tremendous 指失去的睡眠量變得非常大，故選 (D)。"}, {"q": "What is Dr. Huang's view on solving the problem?", "options": ["Phones should be banned completely.", "Teens do not really want to change.", "Gradual change works better than taking phones away.", "Schools should give more homework."], "answer": 2, "explain": "最後一句說溫和、循序漸進的減量遠比完全沒收手機有效，故選 (C)。"}], "vocabQ": [{"q": "The ____ of the class voted to hold the party at the night market.", "options": ["majority", "shortage", "proportion", "percentage"], "answer": 0, "explain": "句意為「班上大多數人投票決定在夜市辦派對」，majority 大多數。"}, {"q": "He finished the whole exam in a ____ twenty minutes, which surprised everyone.", "options": ["multiple", "sufficient", "tremendous", "mere"], "answer": 3, "explain": "句意為「他只用了短短二十分鐘就寫完整份考卷，讓大家很驚訝」，mere 僅僅的。"}, {"q": "Because of the dry weather, there was a ____ of water in the southern cities.", "options": ["proportion", "shortage", "majority", "quantity"], "answer": 1, "explain": "句意為「由於天氣乾燥，南部城市出現缺水」，shortage 短缺。"}, {"q": "The new policy aims to ____ the amount of plastic waste by half.", "options": ["rank", "shorten", "reduce", "rate"], "answer": 2, "explain": "句意為「新政策的目標是把塑膠垃圾的量減少一半」，reduce 減少。"}, {"q": "Make sure you have ____ time to get to the test center before 8:30.", "options": ["sufficient", "widespread", "multiple", "tremendous"], "answer": 0, "explain": "句意為「確定你有足夠的時間在八點半前到達考場」，sufficient 足夠的。"}]}, {"id": "I46", "level": "inter", "num": 46, "title": "Is This Painting Real?", "titleZh": "這幅畫是真的嗎？", "theme": "Quality & Description", "themeZh": "性質與描述", "article": ["On a casual Sunday afternoon, Ya-wen and her classmate Jun-jie wandered through the narrow streets of Ximending, where a street artist had set up a small stall. Dozens of paintings leaned against the wall: some were elegant watercolors of Taipei 101 at dusk, while others showed dramatic scenes of lightning over the sea. \"These are amazing,\" Ya-wen whispered. \"Look at the detailed brushwork on this one.\" Jun-jie, however, was not convinced. \"The colors are too consistent,\" he said. \"I think they're fake. Printed copies, not real paintings.\"", "The artist, an old man in baggy jeans and a dusty cap, overheard them and grinned. \"A fair question,\" he said. \"It's apparent you have good eyes, young man. Some sellers do pass off printed copies as originals. But feel this.\" He handed Jun-jie a delicate sheet of paper. Its surface was uneven, with small ridges where the paint had dried thickly. \"Artificial prints are perfectly smooth,\" the artist explained. \"Real watercolor leaves evidence of the brush.\" Jun-jie turned red; it was an awkward moment, but the artist seemed more amused than annoyed.", "Then he showed them something astonishing. Taking out a brush, he painted a complete scene of the Red House in less than three minutes, his hand moving in an efficient rhythm that looked effortless. \"Thirty years of practice,\" he said. \"What looks simple is often the most complex.\" Ya-wen bought a small painting of a night market for her mother, and Jun-jie, now a little embarrassed but fascinated, asked whether he could watch for a while longer. \"Of course,\" said the artist. \"The essential feature of an artist is not talent. It is the willingness to keep looking.\""], "translation": ["一個悠閒的星期天下午，雅雯和同學俊傑在西門町的小巷裡閒逛，那裡有一位街頭畫家擺了一個小攤。幾十幅畫靠在牆邊：有些是黃昏時台北 101 的優雅水彩畫，有些則是海上閃電的戲劇性場景。「這些太驚人了，」雅雯小聲說。「看看這幅細膩的筆觸。」不過俊傑並不信服。「顏色太均勻一致了，」他說。「我覺得是假的。是印刷的複製品，不是真正的畫。」", "那位畫家是個穿著寬鬆牛仔褲、戴著滿是灰塵帽子的老先生，他聽到了，咧嘴一笑。「問得好，」他說。「年輕人，很明顯你的眼力不錯。有些賣家確實會把印刷品冒充成原作。不過你摸摸這個。」他遞給俊傑一張細緻的紙。紙的表面凹凸不平，顏料乾得厚的地方留下小小的隆起。「人工印刷品是完全平滑的，」畫家解釋，「真正的水彩會留下筆刷的痕跡。」俊傑臉紅了；那是個尷尬的時刻，但畫家看起來覺得好笑多過於惱怒。", "接著他讓他們看了一件令人驚嘆的事。他拿出畫筆，不到三分鐘就畫出一幅完整的西門紅樓，手的動作有效率又有節奏，看起來毫不費力。「三十年的練習，」他說。「看起來簡單的，往往最複雜。」雅雯買了一幅小小的夜市畫送給媽媽，而俊傑雖然有點不好意思，卻深深著迷，問能不能再多看一會兒。「當然可以，」畫家說。「一個藝術家最基本的特質不是天分，而是願意一直看下去。」"], "vocab": [{"word": "casual", "pos": "adj.", "zh": "輕鬆的；隨意的", "example": "We had a casual chat over coffee.", "exampleZh": "我們邊喝咖啡邊輕鬆地聊天。"}, {"word": "elegant", "pos": "adj.", "zh": "優雅的", "example": "She wore an elegant black dress to the party.", "exampleZh": "她穿著一件優雅的黑色洋裝去參加派對。"}, {"word": "dramatic", "pos": "adj.", "zh": "戲劇性的；引人注目的", "example": "There was a dramatic change in the weather.", "exampleZh": "天氣出現了戲劇性的變化。"}, {"word": "consistent", "pos": "adj.", "zh": "一致的；始終如一的", "example": "His grades have been consistent all year.", "exampleZh": "他的成績一整年都很穩定。"}, {"word": "fake", "pos": "adj.", "zh": "假的；偽造的", "example": "The shop was caught selling fake designer bags.", "exampleZh": "這家店被抓到販賣假名牌包。"}, {"word": "apparent", "pos": "adj.", "zh": "明顯的", "example": "It was apparent that he had not slept.", "exampleZh": "很明顯他沒有睡覺。"}, {"word": "delicate", "pos": "adj.", "zh": "精緻的；易碎的", "example": "The delicate glass vase must be handled with care.", "exampleZh": "這個精緻的玻璃花瓶必須小心處理。"}, {"word": "artificial", "pos": "adj.", "zh": "人造的；人工的", "example": "The restaurant decorates its tables with artificial flowers.", "exampleZh": "這家餐廳用人造花裝飾桌子。"}, {"word": "awkward", "pos": "adj.", "zh": "尷尬的；笨拙的", "example": "There was an awkward silence after his joke.", "exampleZh": "他講完笑話後出現一陣尷尬的沉默。"}, {"word": "astonishing", "pos": "adj.", "zh": "令人驚訝的", "example": "The young pianist gave an astonishing performance.", "exampleZh": "這位年輕鋼琴家的表演令人驚嘆。"}], "phrases": [{"phrase": "pass off ... as", "zh": "把…冒充成", "example": "He tried to pass off the copy as an original.", "exampleZh": "他試圖把複製品冒充成原作。"}, {"phrase": "set up", "zh": "設立；擺設", "example": "The vendors set up their stalls before six o'clock.", "exampleZh": "攤販在六點前就擺好攤位。"}, {"phrase": "for a while", "zh": "一會兒；一段時間", "example": "Let's sit here for a while and rest.", "exampleZh": "我們在這裡坐一會兒休息吧。"}], "grammar": [{"pattern": "It is + adj. + (that) + S + V", "explain": "it 為虛主詞，真正的主詞是後面的 that 子句；用來表達「…是明顯的／重要的／可能的」等判斷。", "example": "It is apparent that you have good eyes.", "exampleZh": "很明顯你的眼力很好。"}, {"pattern": "V-ing ..., S + V（分詞構句）", "explain": "當兩個子句主詞相同時，可把其中一個改成現在分詞開頭的分詞構句，表示同時發生或先後發生的動作。", "example": "Taking out a brush, he painted a complete scene in three minutes.", "exampleZh": "他拿出畫筆，三分鐘內就畫出一幅完整的景色。"}], "reading": [{"q": "Why did Jun-jie think the paintings were fake?", "options": ["They were too cheap.", "The artist looked too old to paint.", "They were painted on thin paper.", "The colors looked too even and consistent."], "answer": 3, "explain": "第一段俊傑說 The colors are too consistent，所以認為是印刷品，故選 (D)。"}, {"q": "How did the artist prove that the paintings were real?", "options": ["He showed Jun-jie his art school certificate.", "He let Jun-jie feel the uneven surface of the paper.", "He asked Ya-wen to buy one.", "He told them the price of real paintings."], "answer": 1, "explain": "第二段寫畫家把一張紙遞給俊傑摸，表面凹凸不平，證明是真正的水彩，故選 (B)。"}, {"q": "How did the artist react to Jun-jie's doubt?", "options": ["He found it funny rather than offensive.", "He became very angry.", "He refused to talk to them.", "He asked them to leave the stall."], "answer": 0, "explain": "第二段最後說 the artist seemed more amused than annoyed，故選 (A)。"}, {"q": "The word \"effortless\" in paragraph 3 is closest in meaning to ______.", "options": ["careless", "slow", "easy", "painful"], "answer": 2, "explain": "effortless 指「不費力的、看起來很輕鬆的」，與 easy 意思最接近，故選 (C)。"}, {"q": "According to the artist, what matters most for an artist?", "options": ["Natural talent", "The willingness to keep observing", "Thirty years of training", "Selling many paintings"], "answer": 1, "explain": "最後一句說藝術家最基本的特質不是天分，而是願意一直看下去，故選 (B)。"}], "vocabQ": [{"q": "The office has a ____ dress code, so you don't need to wear a suit.", "options": ["formal", "casual", "delicate", "dramatic"], "answer": 1, "explain": "句意為「這間公司的服裝規定很隨意，所以你不必穿西裝」，casual 隨意的。"}, {"q": "It was ____ from her tears that she had failed the exam.", "options": ["elegant", "fake", "apparent", "awkward"], "answer": 2, "explain": "句意為「從她的眼淚可以明顯看出她考試不及格」，apparent 明顯的。"}, {"q": "Her writing style is ____; every chapter has the same clear voice.", "options": ["consistent", "artificial", "astonishing", "baggy"], "answer": 0, "explain": "句意為「她的寫作風格很一致，每一章都有同樣清楚的語調」，consistent 一致的。"}, {"q": "Be careful with those glasses; they are very ____ and break easily.", "options": ["dramatic", "casual", "elegant", "delicate"], "answer": 3, "explain": "句意為「小心那些玻璃杯，它們很脆弱，容易破」，delicate 易碎的。"}, {"q": "The police found that the NT$1,000 bills were ____ and arrested the seller.", "options": ["elegant", "fake", "apparent", "astonishing"], "answer": 1, "explain": "句意為「警方發現那些千元鈔票是假的，逮捕了賣家」，fake 假的。"}]}, {"id": "I47", "level": "inter", "num": 47, "title": "A Night Among the Lanterns of Jiufen", "titleZh": "九份燈籠下的夜晚", "theme": "Quality & Description", "themeZh": "性質與描述", "article": ["If you take the bus from Ruifang up the winding mountain road, you will arrive at Jiufen, a historic gold-mining town that seems to hang on the hillside above the sea. During the day, the main street is messy and crowded, but at dusk something magical happens. Red lanterns are lit one after another along the narrow steps, and the whole town begins to glow. The fragrance of taro balls and grilled sausages drifts through the air, and the harsh noise of the day fades into a leisurely hum.", "The teahouses are the most impressive feature of the town. Their outer walls are made of dark wood that has been polished by decades of mist, while the inner rooms are filled with oval wooden tables, hidden corners, and windows that frame the magnificent view of the ocean. In one of them, I sat beside a window and watched the fishing boats, their lights scattered like stars on the water. The tea master moved with graceful precision, pouring hot water in a perfectly steady stream. It was a genuine moment of peace, the kind that is hard to find in a city.", "Of course, Jiufen is not ideal in every way. The steps are irregular and sometimes inconvenient for older visitors, and on weekends the crowds can be overwhelming. Yet the town's original charm remains obvious. The old buildings are not identical copies of each other; each one has an odd shape that tells its own story. As I walked back down to the bus stop, the lanterns behind me looked like a glorious river of light. Overall, it was a memorable night, and I left with the promising feeling that I would return, perhaps in the mysterious fog of winter, when the town seems to float above the clouds."], "translation": ["如果你從瑞芳搭公車沿著蜿蜒的山路往上走，就會抵達九份——一座歷史悠久的採金小鎮，彷彿懸掛在海邊的山坡上。白天，老街雜亂又擁擠，但到了黃昏，神奇的事情就發生了。狹窄的石階旁，紅燈籠一盞接一盞亮起，整座小鎮開始發光。芋圓和烤香腸的香氣在空氣中飄散，白天刺耳的喧鬧漸漸淡成悠閒的低語。", "茶樓是這座小鎮最令人印象深刻的特色。它們的外牆是深色木頭，被幾十年的霧氣磨得光亮，而內部的房間裡則擺滿橢圓形的木桌、隱密的角落，以及框出壯麗海景的窗戶。在其中一家，我坐在窗邊看著漁船，它們的燈火像星星一樣散落在水面上。茶師的動作優雅而精準，倒熱水時水流完全平穩。那是一個真實的寧靜時刻，是在城市裡很難找到的那種。", "當然，九份並非在各方面都很理想。石階不規則，有時對年長的遊客來說很不方便，週末的人潮也可能讓人吃不消。然而小鎮原始的魅力依然明顯。老建築不是一模一樣的複製品；每一棟都有奇特的形狀，訴說自己的故事。當我走回公車站時，身後的燈籠看起來像一條燦爛的光之河。整體而言，這是個難忘的夜晚，我帶著充滿希望的感覺離開：我一定會再回來，也許是在冬天神祕的霧裡，那時小鎮彷彿漂浮在雲端之上。"], "vocab": [{"word": "historic", "pos": "adj.", "zh": "歷史上著名的；有歷史意義的", "example": "Tainan is full of historic temples and streets.", "exampleZh": "台南到處都是有歷史意義的廟宇和街道。"}, {"word": "fragrance", "pos": "n.", "zh": "香味；芳香", "example": "The fragrance of the flowers filled the room.", "exampleZh": "花香充滿了整個房間。"}, {"word": "harsh", "pos": "adj.", "zh": "刺耳的；嚴酷的", "example": "The harsh sound of the alarm woke everyone up.", "exampleZh": "刺耳的警報聲把大家都吵醒了。"}, {"word": "leisurely", "pos": "adj.", "zh": "悠閒的；從容的", "example": "We took a leisurely walk along the river.", "exampleZh": "我們沿著河邊悠閒地散步。"}, {"word": "impressive", "pos": "adj.", "zh": "令人印象深刻的", "example": "Her speech was so impressive that everyone stood up.", "exampleZh": "她的演講令人印象深刻，大家都站了起來。"}, {"word": "magnificent", "pos": "adj.", "zh": "壯麗的；宏偉的", "example": "From the top of the mountain, we saw a magnificent sunrise.", "exampleZh": "我們在山頂看到壯麗的日出。"}, {"word": "graceful", "pos": "adj.", "zh": "優雅的", "example": "The swan moved across the lake in a graceful way.", "exampleZh": "天鵝優雅地划過湖面。"}, {"word": "genuine", "pos": "adj.", "zh": "真正的；真誠的", "example": "Is this bag made of genuine leather?", "exampleZh": "這個包包是真皮做的嗎？"}, {"word": "irregular", "pos": "adj.", "zh": "不規則的", "example": "The old street has irregular stone steps.", "exampleZh": "這條老街的石階不規則。"}, {"word": "memorable", "pos": "adj.", "zh": "難忘的", "example": "Graduation day was a memorable day for all of us.", "exampleZh": "畢業典禮那天對我們所有人來說都很難忘。"}], "phrases": [{"phrase": "one after another", "zh": "一個接一個", "example": "The students stood up one after another to speak.", "exampleZh": "學生一個接一個站起來發言。"}, {"phrase": "be filled with", "zh": "充滿", "example": "The box was filled with old letters.", "exampleZh": "箱子裡裝滿了舊信件。"}, {"phrase": "in every way", "zh": "在各方面", "example": "The new library is better in every way.", "exampleZh": "新圖書館在各方面都更好。"}], "grammar": [{"pattern": "If + S + V（現在式）, S + will + V", "explain": "表示未來可能發生的條件句：if 子句用現在式代替未來式，主要子句用 will + 原形動詞。", "example": "If you take the bus from Ruifang, you will arrive at Jiufen.", "exampleZh": "如果你從瑞芳搭公車，就會抵達九份。"}, {"pattern": "N + that / which + V ...（限定關係子句）", "explain": "關係代名詞 that 或 which 引導的形容詞子句，用來修飾前面的名詞，說明「哪一個」；指物時兩者皆可。", "example": "Jiufen is a historic town that seems to hang on the hillside.", "exampleZh": "九份是一座彷彿懸掛在山坡上的歷史小鎮。"}], "reading": [{"q": "What is the main purpose of the passage?", "options": ["To describe the atmosphere and charm of Jiufen at night", "To explain how gold was mined in Jiufen", "To compare Jiufen with Ruifang", "To complain about the crowds in Jiufen"], "answer": 0, "explain": "全文以描寫為主，描述九份入夜後的氣氛與魅力，故選 (A)。"}, {"q": "What happens in Jiufen at dusk, according to paragraph 1?", "options": ["The shops close and the street becomes empty.", "The buses stop running.", "The lanterns are lit and the town becomes calmer.", "It starts to rain heavily."], "answer": 2, "explain": "第一段提到燈籠一盞盞亮起，刺耳的喧鬧淡成悠閒的低語，故選 (C)。"}, {"q": "What does the writer say about the windows of the teahouses?", "options": ["They are made of dark wood.", "They are always closed because of the mist.", "They are oval in shape.", "They frame the view of the ocean."], "answer": 3, "explain": "第二段寫 windows that frame the magnificent view of the ocean，故選 (D)。"}, {"q": "The word \"overwhelming\" in paragraph 3 is closest in meaning to ______.", "options": ["friendly", "too much to handle", "very quiet", "well organized"], "answer": 1, "explain": "the crowds can be overwhelming 指人潮多到讓人吃不消，故選 (B)。"}, {"q": "What does the writer hope to do in the future?", "options": ["Open a teahouse in Jiufen", "Visit Jiufen on a summer weekend", "Return to Jiufen in the winter fog", "Take photos of the fishing boats"], "answer": 2, "explain": "最後一句寫作者希望再回來，也許是在冬天神祕的霧裡，故選 (C)。"}], "vocabQ": [{"q": "The ____ of fresh bread from the bakery made everyone hungry.", "options": ["noise", "shape", "color", "fragrance"], "answer": 3, "explain": "句意為「麵包店飄來的新鮮麵包香味讓大家都餓了」，fragrance 香味。"}, {"q": "The ____ weather conditions on the mountain forced the climbers to turn back.", "options": ["harsh", "leisurely", "graceful", "memorable"], "answer": 0, "explain": "句意為「山上嚴酷的天氣迫使登山者折返」，harsh 嚴酷的。"}, {"q": "The dancer's ____ movements made the audience forget she was only twelve.", "options": ["irregular", "harsh", "graceful", "historic"], "answer": 2, "explain": "句意為「舞者優雅的動作讓觀眾忘了她只有十二歲」，graceful 優雅的。"}, {"q": "Is this watch ____, or is it just a cheap copy?", "options": ["magnificent", "genuine", "impressive", "irregular"], "answer": 1, "explain": "句意為「這支錶是真品，還是只是便宜的仿冒品」，genuine 真正的。"}, {"q": "Our trip to Green Island was so ____ that we still talk about it years later.", "options": ["harsh", "irregular", "leisurely", "memorable"], "answer": 3, "explain": "句意為「我們的綠島之旅太難忘了，多年後仍常提起」，memorable 難忘的。"}]}, {"id": "I48", "level": "inter", "num": 48, "title": "Notice: Yangmingshan Hiking Trip Safety Guidelines", "titleZh": "公告：陽明山健行安全須知", "theme": "Quality & Description", "themeZh": "性質與描述", "article": ["To all Grade 9 students and parents: The annual school hiking trip to Yangmingshan will take place on Friday, November 21. Because the weather in the mountains is unpredictable, the following guidelines are vital for everyone's safety. Please read them in a thorough manner and sign the form at the rear of this notice. A specific list of what to bring is printed on the back.", "Clothing and equipment: Wear proper hiking shoes with a solid grip. Sneakers with worn soles are useless on the steep, slippery stone steps near Qixing Mountain, especially after rain. Bring a water-resistant jacket, as sudden showers are typical of the area in late autumn. A reliable flashlight and a whistle are required, even though we plan to return before dark. Backpacks should be tight and secure so that nothing swings when you walk. Do not bring sticky snacks or glass bottles; a sensible choice is a sandwich, fruit, and at least one liter of water.", "On the trail: Stay with your group at a steady pace, and keep the teacher in front of you visible at all times. Some sections are tricky, with stiff ropes to hold on to; use them properly and never run. If you feel unusually tired or notice a severe headache or dizziness, tell a teacher immediately; this is urgent and should never be hidden. Mobile phones often have no signal in the valley, so a vague plan like \"I'll call you\" is not acceptable. Students who leave the trail will be sent back with a teacher.", "Finally, remember why we go. The view from the top is splendid, the hot-spring steam rising from the valley is vivid and unforgettable, and the sense of achievement after a tough climb is well worth the effort. With careful preparation, this will be a safe and worthwhile day for all. For further questions, contact the Student Affairs Office before Wednesday."], "translation": ["致全體九年級學生與家長：一年一度的陽明山健行校外教學將於 11 月 21 日（星期五）舉行。由於山區天氣難以預測，以下的指引對每個人的安全都至關重要。請仔細讀完，並在本通知後面的回條上簽名。需要攜帶物品的詳細清單印在背面。", "服裝與裝備：請穿著抓地力佳的正規登山鞋。鞋底磨損的球鞋在七星山附近陡峭又濕滑的石階上毫無用處，尤其是在雨後。請帶防水外套，因為深秋時節突然的陣雨在這一帶很常見。手電筒和哨子是必備的，即使我們計畫在天黑前返回。背包要束緊、固定好，走路時才不會晃動。不要帶黏手的零食或玻璃瓶；合理的選擇是三明治、水果，以及至少一公升的水。", "步道上：以穩定的速度跟著自己的小組，並隨時讓前方的老師保持在視線內。有些路段比較棘手，需要抓著硬繩索；請正確使用，絕對不要奔跑。如果你覺得異常疲倦，或出現嚴重頭痛、頭暈，請立刻告訴老師；這是緊急狀況，絕不可隱瞞。手機在山谷裡常常沒有訊號，所以像「我再打給你」這種模糊的計畫是不被接受的。離開步道的學生將由老師帶回。", "最後，請記得我們為什麼要去。山頂的景色壯麗，山谷中升起的溫泉蒸氣鮮明而難忘，而艱辛攀登之後的成就感絕對值得付出。只要做好仔細的準備，這會是對所有人都安全又值得的一天。如有其他問題，請在星期三之前聯絡學務處。"], "vocab": [{"word": "vital", "pos": "adj.", "zh": "極重要的；不可或缺的", "example": "Sleep is vital for a healthy brain.", "exampleZh": "睡眠對健康的大腦極為重要。"}, {"word": "thorough", "pos": "adj.", "zh": "徹底的；仔細的", "example": "The police made a thorough search of the house.", "exampleZh": "警方徹底搜查了那棟房子。"}, {"word": "proper", "pos": "adj.", "zh": "適當的；正確的", "example": "You need proper tools to fix the bike.", "exampleZh": "你需要適當的工具來修腳踏車。"}, {"word": "slippery", "pos": "adj.", "zh": "滑的；容易滑倒的", "example": "The rocks by the waterfall are very slippery.", "exampleZh": "瀑布旁的石頭非常滑。"}, {"word": "typical", "pos": "adj.", "zh": "典型的；常見的", "example": "Afternoon thunderstorms are typical in summer.", "exampleZh": "午後雷陣雨在夏天很常見。"}, {"word": "reliable", "pos": "adj.", "zh": "可靠的", "example": "My old scooter is slow but reliable.", "exampleZh": "我的舊機車很慢，但很可靠。"}, {"word": "steady", "pos": "adj.", "zh": "穩定的；平穩的", "example": "Hold the ladder steady while I climb.", "exampleZh": "我爬的時候，把梯子扶穩。"}, {"word": "tricky", "pos": "adj.", "zh": "棘手的；需要技巧的", "example": "The last question on the test was really tricky.", "exampleZh": "考試的最後一題真的很棘手。"}, {"word": "severe", "pos": "adj.", "zh": "嚴重的；劇烈的", "example": "The city suffered severe flooding after the typhoon.", "exampleZh": "颱風過後，這座城市遭受嚴重的水患。"}, {"word": "worthwhile", "pos": "adj.", "zh": "值得的", "example": "Volunteering at the shelter was a worthwhile experience.", "exampleZh": "在收容所當志工是一次值得的經驗。"}], "phrases": [{"phrase": "take place", "zh": "舉行；發生", "example": "The school fair will take place next Saturday.", "exampleZh": "校慶園遊會將在下星期六舉行。"}, {"phrase": "hold on to", "zh": "抓住；握緊", "example": "Hold on to the rail when the bus turns.", "exampleZh": "公車轉彎時要抓好扶手。"}, {"phrase": "at all times", "zh": "隨時；始終", "example": "Keep your ID card with you at all times.", "exampleZh": "請隨時把身分證帶在身上。"}], "grammar": [{"pattern": "S + V ..., even though + S + V", "explain": "even though 引導讓步子句，意思是「即使、儘管」，語氣比 although 更強，表示儘管有某個事實，主要子句仍然成立。", "example": "A flashlight is required, even though we plan to return before dark.", "exampleZh": "即使我們計畫天黑前返回，仍然必須帶手電筒。"}, {"pattern": "Do not / Never + 原形V ...（否定祈使句）", "explain": "公告或規定中常用否定祈使句下指令，句首直接用 Do not 或 Never 加原形動詞，不需要主詞。", "example": "Never run on the wet stone steps.", "exampleZh": "絕對不要在濕的石階上奔跑。"}], "reading": [{"q": "What is the main purpose of this notice?", "options": ["To advertise a new hiking trail", "To describe the history of Yangmingshan", "To give safety rules for a school hiking trip", "To invite parents to join the trip"], "answer": 2, "explain": "公告列出校外健行的裝備、步道規定與安全注意事項，故選 (C)。"}, {"q": "Why are sneakers with worn soles not allowed?", "options": ["The stone steps are steep and slippery.", "They look untidy in photos.", "They are too heavy to carry.", "They get wet in the hot springs."], "answer": 0, "explain": "第二段說鞋底磨損的球鞋在陡峭又濕滑的石階上毫無用處，故選 (A)。"}, {"q": "What should a student do if he or she feels dizzy on the trail?", "options": ["Rest alone until it passes", "Call a parent on the phone", "Walk slowly to the top", "Tell a teacher right away"], "answer": 3, "explain": "第三段寫出現頭暈時 tell a teacher immediately，故選 (D)。"}, {"q": "The word \"vague\" in paragraph 3 is closest in meaning to ______.", "options": ["careful", "unclear", "expensive", "quick"], "answer": 1, "explain": "a vague plan 指「模糊、不清楚的計畫」，與 unclear 意思最接近，故選 (B)。"}, {"q": "Which of the following is true according to the notice?", "options": ["Students may bring glass bottles of juice.", "The trip will end after dark.", "Phones work well everywhere on the trail.", "The signed form is at the back of the notice."], "answer": 3, "explain": "第一段提到 sign the form at the rear of this notice，回條在公告後面，故選 (D)。"}], "vocabQ": [{"q": "Clean water is ____ to the survival of the village.", "options": ["vital", "vague", "tricky", "slippery"], "answer": 0, "explain": "句意為「乾淨的水對這個村子的生存極為重要」，vital 極重要的。"}, {"q": "The doctor gave him a ____ examination before allowing him to play again.", "options": ["typical", "steady", "thorough", "severe"], "answer": 2, "explain": "句意為「醫生在允許他重新上場前，幫他做了徹底的檢查」，thorough 徹底的。"}, {"q": "Without ____ training, a lifeguard cannot save anyone.", "options": ["worthwhile", "proper", "slippery", "vague"], "answer": 1, "explain": "句意為「沒有適當的訓練，救生員救不了任何人」，proper 適當的。"}, {"q": "The floor is ____ after mopping, so please walk slowly.", "options": ["steady", "reliable", "severe", "slippery"], "answer": 3, "explain": "句意為「拖過的地板很滑，請慢慢走」，slippery 滑的。"}, {"q": "Learning a new language takes years, but it is ____ in the end.", "options": ["worthwhile", "tricky", "typical", "severe"], "answer": 0, "explain": "句意為「學一種新語言要花好幾年，但最終是值得的」，worthwhile 值得的。"}]}, {"id": "I49", "level": "inter", "num": 49, "title": "A Letter to Next Year's Seniors", "titleZh": "給明年高三生的一封信", "theme": "Abstract & Other", "themeZh": "抽象與其他", "article": ["Dear students of Class 207, By the time you read this, I will already be a university student elsewhere, and you will be standing where I stood a year ago, with the entrance exam only months away. Your teacher asked me to write to you, and I agreed, despite knowing that advice from a stranger is easily forgotten. Still, I hope a few of these words will be a small contribution to your year.", "Let me be honest: the year will be a challenge, and there will be hardship. Amid endless practice tests and the burden of expectations, you may wonder whether all this effort is worth it. I felt the same. What enabled me to endure was not talent but a combination of two things: a clear commitment and a fairly simple routine. I promised myself to study three hours every evening, no exception, and I went to bed at the same time every night. Essentially, the routine became the foundation that held everything else together. On bad days, I did not have to decide whether to study; the decision had already been made.", "You will also meet circumstances you cannot control. A classmate of mine fell ill two weeks before the exam, and by coincidence, it was the same week her parents moved house. She did not blame fate. She simply adjusted her plan and did what she could. Fortunately, she passed, but even if she had not, she would have deserved respect for facing the situation with dignity.", "Finally, remember that your existence is not defined by a score. Fame and glory are not the point. Harmony between your effort and your health is. Treat yourself with the goodness you would show a good friend. You have been granted a year to grow, and whatever the consequence, that is a blessing. Good luck. Your senior, Chia-hao"], "translation": ["親愛的 207 班同學：當你們讀到這封信時，我已經在別處成為大學生，而你們正站在我一年前站過的地方，距離大學入學考試只剩幾個月。你們的老師請我寫信給你們，我答應了，儘管我知道陌生人的建議很容易被忘記。不過，我還是希望其中幾句話能對你們這一年有小小的貢獻。", "老實說：這一年會是一場挑戰，也會有艱苦。在無止盡的模擬考和期望的重擔之中，你可能會懷疑這一切努力是否值得。我也有過同樣的感覺。讓我撐下去的不是天分，而是兩樣東西的結合：明確的承諾，以及相當簡單的作息。我向自己承諾每天晚上讀書三小時，沒有例外，而且每晚同一時間上床睡覺。本質上，這個作息成了支撐其他一切的基礎。在糟糕的日子裡，我不必決定要不要讀書；決定早就做好了。", "你們也會遇到自己無法控制的情況。我的一位同學在考前兩週生病了，而且碰巧，那一週她的父母正好搬家。她沒有怪命運。她只是調整計畫，做自己能做的事。幸運的是，她考過了；但即使她沒有，她以尊嚴面對這個處境的態度也值得尊敬。", "最後，請記得你的存在不是由一個分數定義的。名聲和榮耀不是重點。你的努力和健康之間的和諧才是。用你對待好朋友的善意來對待自己。你被賜予了一年的時間成長，無論結果如何，那都是一種福氣。祝你們好運。學長 家豪"], "vocab": [{"word": "despite", "pos": "prep.", "zh": "儘管", "example": "Despite the rain, the game went on.", "exampleZh": "儘管下雨，比賽還是繼續進行。"}, {"word": "hardship", "pos": "n.", "zh": "艱難；困苦", "example": "The family went through great hardship during the war.", "exampleZh": "這個家庭在戰爭期間經歷了極大的苦難。"}, {"word": "burden", "pos": "n.", "zh": "負擔；重擔", "example": "The high rent is a heavy burden for the young couple.", "exampleZh": "高昂的房租對這對年輕夫妻來說是沉重的負擔。"}, {"word": "enable", "pos": "v.", "zh": "使能夠", "example": "The new app enables users to order food in seconds.", "exampleZh": "這個新應用程式讓使用者能在幾秒內點餐。"}, {"word": "endure", "pos": "v.", "zh": "忍受；撐過", "example": "The runners had to endure the heat for three hours.", "exampleZh": "跑者必須忍受三個小時的酷熱。"}, {"word": "commitment", "pos": "n.", "zh": "承諾；投入", "example": "Learning the piano requires a long-term commitment.", "exampleZh": "學鋼琴需要長期的投入。"}, {"word": "foundation", "pos": "n.", "zh": "基礎；根基", "example": "Reading is the foundation of all learning.", "exampleZh": "閱讀是所有學習的基礎。"}, {"word": "circumstance", "pos": "n.", "zh": "情況；環境", "example": "Under no circumstances should you open the door to strangers.", "exampleZh": "在任何情況下都不該為陌生人開門。"}, {"word": "coincidence", "pos": "n.", "zh": "巧合", "example": "What a coincidence! We are on the same flight.", "exampleZh": "真巧！我們搭同一班飛機。"}, {"word": "dignity", "pos": "n.", "zh": "尊嚴", "example": "The old soldier accepted defeat with dignity.", "exampleZh": "老兵有尊嚴地接受了失敗。"}], "phrases": [{"phrase": "by the time", "zh": "到…的時候", "example": "By the time we arrived, the movie had started.", "exampleZh": "我們到的時候，電影已經開始了。"}, {"phrase": "by coincidence", "zh": "碰巧；巧合地", "example": "By coincidence, we were born on the same day.", "exampleZh": "碰巧我們在同一天出生。"}, {"phrase": "worth it", "zh": "值得", "example": "The climb was hard, but the view was worth it.", "exampleZh": "攀登很辛苦，但那景色值得。"}], "grammar": [{"pattern": "By the time + S + V（現在式）, S + will + V", "explain": "by the time 表示「到…的時候」，描述未來時，時間子句用現在式，主要子句用未來式。", "example": "By the time you read this, I will already be a university student.", "exampleZh": "當你讀到這封信時，我已經是大學生了。"}, {"pattern": "What + S + V + is / was + not A but B", "explain": "what 引導的名詞子句當主詞，意思是「…的東西／事情」；搭配 not A but B 表示「不是 A 而是 B」。", "example": "What enabled me to endure was not talent but a simple routine.", "exampleZh": "讓我撐下去的不是天分，而是簡單的作息。"}], "reading": [{"q": "Who wrote this letter, and to whom?", "options": ["A teacher, to her students", "A former student, to next year's seniors", "A parent, to a school principal", "A university professor, to new students"], "answer": 1, "explain": "信末署名 Your senior，作者是已畢業的學長，寫給即將面對入學考試的學弟妹，故選 (B)。"}, {"q": "What did the writer say was the foundation of his year?", "options": ["Natural talent", "Help from his teacher", "Expensive cram schools", "A fixed daily routine"], "answer": 3, "explain": "第二段說 the routine became the foundation that held everything else together，故選 (D)。"}, {"q": "Why does the writer mention the classmate who fell ill?", "options": ["To show how to face events you cannot control", "To warn readers not to move house", "To prove that luck matters most", "To explain why she failed the exam"], "answer": 0, "explain": "第三段以同學生病又碰上搬家為例，說明如何面對無法控制的情況，故選 (A)。"}, {"q": "The word \"granted\" in paragraph 4 is closest in meaning to ______.", "options": ["sold", "refused", "given", "wasted"], "answer": 2, "explain": "You have been granted a year to grow 指「你被給予一年的時間成長」，故選 (C)。"}, {"q": "According to the writer, what matters most?", "options": ["Getting the highest score", "Becoming famous", "Studying more hours than others", "Balance between effort and health"], "answer": 3, "explain": "第四段說名聲和榮耀不是重點，努力和健康之間的和諧才是，故選 (D)。"}], "vocabQ": [{"q": "____ the heavy rain, thousands of fans waited outside the stadium.", "options": ["Although", "Because", "Despite", "Unless"], "answer": 2, "explain": "句意為「儘管下大雨，成千上萬的粉絲仍在體育場外等候」，despite 儘管，後接名詞。"}, {"q": "The scholarship will ____ her to study abroad without worrying about money.", "options": ["enable", "endure", "deserve", "burden"], "answer": 0, "explain": "句意為「這筆獎學金將使她能出國念書而不必擔心錢」，enable 使能夠。"}, {"q": "Caring for three children alone was a heavy ____ for the single mother.", "options": ["dignity", "coincidence", "foundation", "burden"], "answer": 3, "explain": "句意為「獨自照顧三個孩子對這位單親媽媽來說是沉重的負擔」，burden 負擔。"}, {"q": "People who live in the desert must ____ extreme heat every summer.", "options": ["enable", "endure", "found", "deserve"], "answer": 1, "explain": "句意為「住在沙漠的人每年夏天都必須忍受極端的高溫」，endure 忍受。"}, {"q": "It was a pure ____ that we both chose the same seat on the train.", "options": ["circumstance", "commitment", "coincidence", "hardship"], "answer": 2, "explain": "句意為「我們兩個在火車上選了同一個座位，純粹是巧合」，coincidence 巧合。"}]}, {"id": "I50", "level": "inter", "num": 50, "title": "The Climb to Grandpa's Hill", "titleZh": "爬上爺爺的那座山", "theme": "Abstract & Other", "themeZh": "抽象與其他", "article": ["Every year on Tomb Sweeping Day, the Chen family gathers on a hillside in Miaoli where their ancestors are buried. For Hsiao-an, a sixteen-year-old who would rather spend the holiday with her friends, the trip has always seemed a tiresome necessity. This year, however, an unexpected incident changed her view. Her eighty-two-year-old grandfather insisted on climbing the steep path to the tomb himself instead of waiting in the car, and no one in the family was able to stop him.", "The process of cleaning the tomb involves pulling weeds, repainting the faded characters on the stone, and offering food and prayers. Halfway up, Grandpa's legs began to shake, and Hsiao-an took his arm. \"Why do you insist on this?\" she asked. \"You could rely on us to do it.\" He was silent for a moment. Then he said, \"My father carried me up this hill when I was five. His presence is still here. If I stop coming, somehow a part of my identity goes with him.\" Hsiao-an did not fully understand, but she felt the significance of his words.", "At the tomb, the family worked together with a unity she had not noticed before. Her uncle, who usually argued with her father about every issue, passed him the brush. Her mother, who is not religious, bowed with the others. Grandpa explained that the ritual is not about religion alone; it is a spiritual reminder that each person represents a link in a long chain, and that the virtues of the people before us are an inheritance we should honor.", "On the way down, Hsiao-an realized that the trend among her friends of skipping family rituals for the sake of free time came with a hidden risk: the loss of knowing who you are. The outcome of the day was not a miracle, and she may still complain next year. But she now tends to see the climb differently, not as an obstacle to her weekend, but as a small sacrifice that keeps a family's story alive."], "translation": ["每年清明節，陳家人都會聚集在苗栗一處埋葬祖先的山坡上。對十六歲、寧願把假日拿來和朋友相處的曉安來說，這趟路一直像是件累人的必要之事。然而今年，一件意外的事件改變了她的看法。八十二歲的爺爺堅持要自己爬上通往墳墓的陡峭小路，而不是在車裡等，家裡沒有人能阻止他。", "掃墓的過程包括拔草、重新描上石碑上褪色的字，以及供奉食物和祈禱。爬到一半，爺爺的腿開始發抖，曉安扶住了他的手臂。「你為什麼堅持要這樣？」她問。「你可以靠我們來做啊。」他沉默了一會兒。然後他說：「我五歲的時候，我父親背著我爬上這座山。他的存在還在這裡。如果我不再來，不知怎的，我的一部分身分也會跟著他走。」曉安沒有完全懂，但她感受到這些話的重要性。", "在墓前，全家人以一種她從未注意過的團結一起工作。平常和她爸爸什麼事都要爭論的叔叔，把刷子遞給他。沒有宗教信仰的媽媽，也和大家一起鞠躬。爺爺解釋，這個儀式不只關乎宗教；它是一種心靈上的提醒，提醒每個人都代表一條長鏈中的一環，而前人的美德是我們應當尊崇的傳承。", "下山的路上，曉安明白了朋友之間為了自由時間而略過家族儀式的風氣，其實帶著隱藏的風險：失去對自己是誰的認識。這一天的結果不是什麼奇蹟，她明年大概還是會抱怨。但她現在傾向用不同的眼光看待這段爬坡：不是週末的阻礙，而是讓一個家族的故事延續下去的小小犧牲。"], "vocab": [{"word": "necessity", "pos": "n.", "zh": "必需品；必要", "example": "In Taiwan, an umbrella is a daily necessity.", "exampleZh": "在台灣，雨傘是日常必需品。"}, {"word": "incident", "pos": "n.", "zh": "事件", "example": "The teacher reported the incident to the principal.", "exampleZh": "老師把這起事件報告給校長。"}, {"word": "involve", "pos": "v.", "zh": "包含；牽涉", "example": "The job involves a lot of traveling.", "exampleZh": "這份工作需要經常出差。"}, {"word": "rely", "pos": "v.", "zh": "依靠；信賴", "example": "You can rely on him to keep a secret.", "exampleZh": "你可以信賴他會保守祕密。"}, {"word": "identity", "pos": "n.", "zh": "身分；認同", "example": "The police are trying to find out the man's identity.", "exampleZh": "警方正試圖查出那名男子的身分。"}, {"word": "significance", "pos": "n.", "zh": "重要性；意義", "example": "The teacher explained the significance of the festival.", "exampleZh": "老師解釋了這個節日的意義。"}, {"word": "unity", "pos": "n.", "zh": "團結；一致", "example": "The coach asked the team to show unity on the field.", "exampleZh": "教練要求球隊在場上展現團結。"}, {"word": "spiritual", "pos": "adj.", "zh": "心靈的；精神上的", "example": "Many people visit temples for spiritual peace.", "exampleZh": "許多人到廟裡尋求心靈的平靜。"}, {"word": "sacrifice", "pos": "n.", "zh": "犧牲", "example": "Her parents made many sacrifices so she could study abroad.", "exampleZh": "她的父母做了許多犧牲，好讓她能出國念書。"}, {"word": "obstacle", "pos": "n.", "zh": "障礙；阻礙", "example": "Lack of money was the biggest obstacle to his dream.", "exampleZh": "缺錢是他夢想的最大障礙。"}], "phrases": [{"phrase": "would rather", "zh": "寧願", "example": "I would rather stay home than go shopping.", "exampleZh": "我寧願待在家也不要去逛街。"}, {"phrase": "for the sake of", "zh": "為了", "example": "He gave up smoking for the sake of his health.", "exampleZh": "他為了健康戒菸了。"}, {"phrase": "on the way", "zh": "在途中", "example": "We stopped for breakfast on the way to school.", "exampleZh": "我們在上學途中停下來吃早餐。"}], "grammar": [{"pattern": "S + insist on + V-ing / N", "explain": "insist on 表示「堅持」，後面接動名詞或名詞，說明堅持要做的事情。", "example": "Grandpa insisted on climbing the hill himself.", "exampleZh": "爺爺堅持要自己爬上那座山。"}, {"pattern": "not A but B", "explain": "not A but B 表示「不是 A 而是 B」，A 和 B 必須是相同的詞性或結構（例如都是名詞片語或介系詞片語）。", "example": "She sees the climb not as an obstacle but as a small sacrifice.", "exampleZh": "她把這段爬坡看成不是阻礙，而是小小的犧牲。"}], "reading": [{"q": "How did Hsiao-an feel about the trip before this year?", "options": ["She saw it as a boring duty.", "She looked forward to it every year.", "She was afraid of the steep path.", "She enjoyed cleaning the tomb."], "answer": 0, "explain": "第一段說這趟路對她來說一直是 a tiresome necessity（累人的必要之事），故選 (A)。"}, {"q": "Why did Grandpa insist on climbing the hill himself?", "options": ["He wanted to prove he was still strong.", "He did not trust the younger family members.", "It keeps him connected to his father and to who he is.", "The car could not park near the tomb."], "answer": 2, "explain": "第二段爺爺說父親的存在還在那裡，不再來的話，一部分的身分會跟著消失，故選 (C)。"}, {"q": "According to Grandpa, what is the ritual mainly about?", "options": ["Religion only", "Reminding each person that he or she is a link in a long chain", "Showing respect to the uncle", "Teaching children to pull weeds"], "answer": 1, "explain": "第三段寫儀式是 a spiritual reminder that each person represents a link in a long chain，故選 (B)。"}, {"q": "The word \"ritual\" in paragraph 3 is closest in meaning to ______.", "options": ["argument", "holiday", "journey", "ceremony"], "answer": 3, "explain": "ritual 指掃墓這類固定進行的儀式，與 ceremony 意思最接近，故選 (D)。"}, {"q": "What can be inferred about Hsiao-an at the end of the story?", "options": ["She will never complain about the trip again.", "She plans to skip the trip next year.", "She still may complain but now understands its meaning.", "She has decided to become religious."], "answer": 2, "explain": "最後一段說她明年大概還是會抱怨，但已經用不同的眼光看待這段爬坡，故選 (C)。"}], "vocabQ": [{"q": "A smartphone has become a ____ for most students, not a luxury.", "options": ["sacrifice", "necessity", "obstacle", "unity"], "answer": 1, "explain": "句意為「對大多數學生來說，智慧型手機已成為必需品，而不是奢侈品」，necessity 必需品。"}, {"q": "The police are investigating a strange ____ that happened at the station last night.", "options": ["identity", "significance", "unity", "incident"], "answer": 3, "explain": "句意為「警方正在調查昨晚發生在車站的一起奇怪事件」，incident 事件。"}, {"q": "The new project will ____ students from three different schools.", "options": ["involve", "rely", "honor", "represent"], "answer": 0, "explain": "句意為「這個新專案將包含來自三所不同學校的學生」，involve 包含、牽涉。"}, {"q": "You can always ____ on Grandma to remember everyone's birthday.", "options": ["involve", "honor", "rely", "sacrifice"], "answer": 2, "explain": "句意為「你永遠可以指望奶奶記得每個人的生日」，rely on 依靠。"}, {"q": "The lack of money was the biggest ____ to opening the restaurant.", "options": ["identity", "obstacle", "necessity", "significance"], "answer": 1, "explain": "句意為「缺錢是開餐廳最大的障礙」，obstacle 障礙。"}]}];